@Composable
fun FoodOrderScreen(viewModel: AppViewModel, onBack: () -> Unit, modifier: Modifier = Modifier) {
    var vegOnly by remember { mutableStateOf(false) }
    var selectedCategory by remember { mutableStateOf("All Food") }
    val foodCart by viewModel.foodCartItems.collectAsState()

    var selectedFoodDetailPage by remember { mutableStateOf<FoodItem?>(null) }

    if (selectedFoodDetailPage != null) {
        RestaurantAndDishDetailsScreen(
            selectedFood = selectedFoodDetailPage!!,
            onBack = { selectedFoodDetailPage = null },
            viewModel = viewModel,
            onSelectFood = { selectedFoodDetailPage = it }
        )
    } else {
        val categories = listOf("All Food", "North Indian", "Chinese", "Italian", "Fast Food", "Punjabi", "Desserts", "Burgers")

        Column(modifier = modifier.fillMaxSize().background(lightBg)) {
        // App Bar
        Box(
            modifier = Modifier
                .fillMaxWidth()
                .background(
                    Brush.verticalGradient(
                        colors = listOf(Color(0xFF1A3BBF), Color(0xFF1A56DB))
                    )
                )
                .padding(horizontal = 16.dp, vertical = 14.dp)
        ) {
            Row(
                verticalAlignment = Alignment.CenterVertically
            ) {
                IconButton(onClick = onBack, modifier = Modifier.testTag("food_back")) {
                    Icon(Icons.AutoMirrored.Filled.ArrowBack, "Back", tint = Color.White)
                }
                Text("Food Order 🍽️", color = Color.White, fontWeight = FontWeight.Bold, fontSize = 18.sp, modifier = Modifier.weight(1f))
                Row(verticalAlignment = Alignment.CenterVertically) {
                    Text("Veg Only", color = Color.White, fontSize = 12.sp, fontWeight = FontWeight.Bold)
                    Switch(
                        checked = vegOnly,
                        onCheckedChange = { vegOnly = it },
                        modifier = Modifier.scale(0.8f).testTag("veg_only_switch"),
                        colors = SwitchDefaults.colors(checkedThumbColor = Color.Green)
                    )
                }
            }
        }

        // Horizontal Category Row
        Row(
            modifier = Modifier.fillMaxWidth().horizontalScroll(rememberScrollState()).padding(8.dp),
            horizontalArrangement = Arrangement.spacedBy(8.dp)
        ) {
            categories.forEach { cat ->
                FilterChip(
                    selected = selectedCategory == cat,
                    onClick = { selectedCategory = cat },
                    label = { Text(cat) },
                    modifier = Modifier.testTag("food_chip_$cat")
                )
            }
        }

        // Grid of 6 hardcoded food items
        val filtered = viewModel.foodProducts.filter { item ->
            val matchesVeg = !vegOnly || item.isVeg
            val matchesCat = selectedCategory == "All Food" || item.cuisines.contains(selectedCategory)
            matchesVeg && matchesCat
        }

        if (filtered.isEmpty()) {
            Box(Modifier.fillMaxSize(), contentAlignment = Alignment.Center) {
                Text("No matching dishes found.", color = Color(0xFF687280))
            }
        } else {
            LazyVerticalGrid(
                columns = GridCells.Fixed(2),
                modifier = Modifier.fillMaxSize().padding(horizontal = 12.dp),
                horizontalArrangement = Arrangement.spacedBy(10.dp),
                verticalArrangement = Arrangement.spacedBy(10.dp)
            ) {
                // Horizontal big food dishes box (Featured special - Burger Seigneur, same-to-same)
                item(span = { GridItemSpan(2) }) {
                    val context = LocalContext.current
                    Column(modifier = Modifier.fillMaxWidth().padding(bottom = 12.dp)) {
                        Text(
                            text = "Featured Gourmet Specials ⭐",
                            fontSize = 16.sp,
                            fontWeight = FontWeight.Bold,
                            color = Color(0xFF0F172A),
                            modifier = Modifier.padding(vertical = 8.dp)
                        )
                        
                        Column(
                            modifier = Modifier.fillMaxWidth(),
                            verticalArrangement = Arrangement.spacedBy(16.dp)
                        ) {
                            val featuredDishes = listOf(
                                FeaturedDish("f4", "Burger Seigneur", 115, "4.4", "0.8 km", "American • Continental", "15-20 min", "20% OFF", "🍔", true),
                                FeaturedDish("f2", "Margherita Seigneur", 199, "4.5", "1.2 km", "Italian • Continental", "18-22 min", "30% OFF", "🍕", true),
                                FeaturedDish("f1", "Paneer Butter Seigneur", 249, "4.7", "1.5 km", "Punjabi • North Indian", "12-15 min", "25% OFF", "🍛", true)
                            )
                            
                            featuredDishes.forEach { dish ->
                                Card(
                                    modifier = Modifier
                                        .fillMaxWidth()
                                        .padding(bottom = 6.dp)
                                        .clickable { 
                                            selectedFoodDetailPage = viewModel.foodProducts.find { it.id == dish.id } ?: viewModel.foodProducts.first()
                                        }
                                        .testTag("featured_dish_${dish.id}"),
                                    colors = CardDefaults.cardColors(containerColor = Color.White),
                                    shape = RoundedCornerShape(18.dp),
                                    border = BorderStroke(1.dp, Color(0xFFE2E8F0))
                                ) {
                                    Column {
                                        Box(
                                            modifier = Modifier
                                                .fillMaxWidth()
                                                .height(180.dp)
                                                .background(Color(0xFF1E1E1E)),
                                            contentAlignment = Alignment.Center
                                        ) {
                                            Text(dish.emoji, fontSize = 64.sp)
                                            
                                            // Yellow price tag Top-Left
                                            Box(
                                                modifier = Modifier
                                                    .align(Alignment.TopStart)
                                                    .background(
                                                        Color(0xFFFBBF24),
                                                        RoundedCornerShape(bottomEnd = 12.dp, topStart = 18.dp)
                                                    )
                                                    .padding(horizontal = 14.dp, vertical = 6.dp)
                                            ) {
                                                Text("₹${dish.price}", color = Color.Black, fontWeight = FontWeight.Bold, fontSize = 13.sp)
                                            }
                                            
                                            // Top-Right Icons
                                            Row(
                                                modifier = Modifier
                                                    .align(Alignment.TopEnd)
                                                    .padding(8.dp),
                                                horizontalArrangement = Arrangement.spacedBy(6.dp),
                                                verticalAlignment = Alignment.CenterVertically
                                            ) {
                                                Icon(
                                                    imageVector = Icons.Default.Favorite,
                                                    contentDescription = "Favorite",
                                                    tint = Color.White,
                                                    modifier = Modifier.size(18.dp)
                                                )
                                                Icon(
                                                    imageVector = Icons.Default.MoreVert,
                                                    contentDescription = "Options",
                                                    tint = Color.White,
                                                    modifier = Modifier.size(18.dp)
                                                )
                                            }
                                            
                                            // 5 dots bottom-left
                                            Row(
                                                modifier = Modifier
                                                    .align(Alignment.BottomStart)
                                                    .padding(10.dp),
                                                horizontalArrangement = Arrangement.spacedBy(4.dp)
                                            ) {
                                                repeat(5) { dIndex ->
                                                    Box(
                                                        modifier = Modifier
                                                            .size(5.dp)
                                                            .background(
                                                                color = if (dIndex == 0) Color.White else Color.White.copy(alpha = 0.4f),
                                                                shape = CircleShape
                                                            )
                                                    )
                                                }
                                            }
                                            
                                            // Time pill bottom-right
                                            Box(
                                                modifier = Modifier
                                                    .align(Alignment.BottomEnd)
                                                    .padding(10.dp)
                                                    .background(Color.White, RoundedCornerShape(10.dp))
                                                    .padding(horizontal = 8.dp, vertical = 3.dp)
                                            ) {
                                                Text(dish.deliveryTime, color = Color.Black, fontWeight = FontWeight.Bold, fontSize = 10.sp)
                                            }
                                        }
                                        
                                        Column(modifier = Modifier.padding(12.dp)) {
                                            Text(dish.name, fontWeight = FontWeight.Black, fontSize = 15.sp, color = Color(0xFF0F172A))
                                            Spacer(modifier = Modifier.height(8.dp))
                                            
                                            Row(verticalAlignment = Alignment.CenterVertically) {
                                                Box(
                                                    modifier = Modifier
                                                        .size(14.dp)
                                                        .background(Color(0xFF22C55E), CircleShape),
                                                    contentAlignment = Alignment.Center
                                                ) {
                                                    Icon(
                                                        imageVector = Icons.Default.Star,
                                                        contentDescription = "Star",
                                                        tint = Color.White,
                                                        modifier = Modifier.size(8.dp)
                                                    )
                                                }
                                                Spacer(modifier = Modifier.width(4.dp))
                                                Text("${dish.rating} • ${dish.distance}", fontSize = 11.sp, fontWeight = FontWeight.Bold, color = Color(0xFF475569))
                                            }
                                            Spacer(modifier = Modifier.height(2.dp))
                                            Text(dish.cuisines, fontSize = 10.sp, color = Color(0xFF687280), maxLines = 1, overflow = TextOverflow.Ellipsis)
                                            Spacer(modifier = Modifier.height(8.dp))
                                            
                                            // Offer Banner (20% OFF | FAST DELIVERY) without "free delivery" per instruction
                                            Row(
                                                modifier = Modifier
                                                    .fillMaxWidth()
                                                    .background(Color(0xFF136B31), RoundedCornerShape(10.dp))
                                                    .padding(horizontal = 8.dp, vertical = 5.dp),
                                                verticalAlignment = Alignment.CenterVertically,
                                                horizontalArrangement = Arrangement.Center
                                            ) {
                                                Box(
                                                    modifier = Modifier
                                                        .size(12.dp)
                                                        .background(Color.White, CircleShape),
                                                    contentAlignment = Alignment.Center
                                                ) {
                                                    Icon(
                                                        imageVector = Icons.Default.Check,
                                                        contentDescription = "Success",
                                                        tint = Color(0xFF136B31),
                                                        modifier = Modifier.size(8.dp)
                                                    )
                                                }
                                                Spacer(modifier = Modifier.width(4.dp))
                                                Text(
                                                    text = "${dish.discount} | 🚚 FAST DELIVERY 🚚",
                                                    color = Color.White,
                                                    fontWeight = FontWeight.Bold,
                                                    fontSize = 10.sp
                                                )
                                            }
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
                
                // Header for regular dishes nearby
                item(span = { GridItemSpan(2) }) {
                    Text(
                        text = "All Dishes Nearby 🍽️",
                        fontSize = 16.sp,
                        fontWeight = FontWeight.Bold,
                        color = Color(0xFF0F172A),
                        modifier = Modifier.padding(top = 16.dp, bottom = 8.dp)
                    )
                }

                items(filtered) { item ->
                    val qty = foodCart[item.id] ?: 0
                    Card(
                        modifier = Modifier.fillMaxWidth().clickable { selectedFoodDetailPage = item }.testTag("food_item_${item.id}"),
                        colors = CardDefaults.cardColors(containerColor = Color.White)
                    ) {
                        Column {
                            Box(modifier = Modifier.fillMaxWidth().height(100.dp).background(Color(0xFFF1F5F9)), contentAlignment = Alignment.Center) {
                                Text(item.emoji, fontSize = 48.sp)
                                // Indicators overlay
                                Row(modifier = Modifier.fillMaxWidth().align(Alignment.TopStart).padding(6.dp), horizontalArrangement = Arrangement.SpaceBetween) {
                                    Box(modifier = Modifier.background(Color(0xFFFBBF24), RoundedCornerShape(4.dp)).padding(horizontal = 6.dp, vertical = 2.dp)) {
                                        Text("₹${item.price.toInt()}", fontSize = 10.sp, fontWeight = FontWeight.Bold)
                                    }
                                    Box(modifier = Modifier.background(crowmixAccent, RoundedCornerShape(4.dp)).padding(horizontal = 6.dp, vertical = 2.dp)) {
                                        Text("${item.discountPercent}% OFF", fontSize = 8.sp, fontWeight = FontWeight.Bold, color = Color.White)
                                    }
                                }
                            }
                            Column(modifier = Modifier.padding(12.dp)) {
                                Row(verticalAlignment = Alignment.CenterVertically) {
                                    Box(modifier = Modifier.size(8.dp).background(if (item.isVeg) Color.Green else Color.Red, CircleShape))
                                    Spacer(modifier = Modifier.width(4.dp))
                                    Text(item.name, fontWeight = FontWeight.Bold, fontSize = 12.sp, maxLines = 1, overflow = TextOverflow.Ellipsis)
                                }
                                Text(item.cuisines.joinToString(", "), fontSize = 10.sp, color = Color(0xFF687280), maxLines = 1)
                                Row(modifier = Modifier.fillMaxWidth().padding(top = 8.dp), horizontalArrangement = Arrangement.SpaceBetween, verticalAlignment = Alignment.CenterVertically) {
                                    Column {
                                        Text("⭐ ${item.rating}", fontSize = 10.sp, fontWeight = FontWeight.Bold)
                                        Text(item.deliveryTime, fontSize = 8.sp, color = Color(0xFF687280))
                                    }
                                    if (qty == 0) {
                                        Button(
                                            onClick = { viewModel.addFoodToCart(item.id) },
                                            modifier = Modifier.height(28.dp).testTag("add_food_${item.id}"),
                                            colors = ButtonDefaults.buttonColors(containerColor = crowmixBlue),
                                            contentPadding = PaddingValues(horizontal = 12.dp)
                                        ) {
                                            Text("ADD", fontSize = 10.sp, color = Color.White)
                                        }
                                    } else {
                                        Row(verticalAlignment = Alignment.CenterVertically, modifier = Modifier.background(Color.White, RoundedCornerShape(4.dp)).border(1.dp, crowmixBlue, RoundedCornerShape(4.dp))) {
                                            Text("-", modifier = Modifier.clickable { viewModel.removeFoodFromCart(item.id) }.padding(horizontal = 8.dp, vertical = 2.dp).testTag("dec_food_${item.id}"), fontWeight = FontWeight.Bold, color = crowmixBlue)
                                            Text(qty.toString(), modifier = Modifier.padding(horizontal = 4.dp), fontSize = 11.sp, fontWeight = FontWeight.Bold)
                                            Text("+", modifier = Modifier.clickable { viewModel.addFoodToCart(item.id) }.padding(horizontal = 8.dp, vertical = 2.dp).testTag("inc_food_${item.id}"), fontWeight = FontWeight.Bold, color = crowmixBlue)
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }
    }
}
