@Composable
fun RestaurantAndDishDetailsScreen(
    selectedFood: FoodItem,
    onBack: () -> Unit,
    viewModel: AppViewModel,
    onSelectFood: (FoodItem) -> Unit = {}
) {
    val foodCart by viewModel.foodCartItems.collectAsState()
    val context = LocalContext.current
    var searchQuery by remember { mutableStateOf("") }
    var selectedFilter by remember { mutableStateOf("All") }
    var showMenuPopup by remember { mutableStateOf(false) }
    
    val recommendedItems = listOf(
        RecommendedDish("f3", "Deluxe Thali", 190, "A wholesome full meal with dal, sabzi, rice, roti, salad, papad, and sweets...", "🍱", true, "Highly Reordered", listOf("Popular", "Highly Reordered")),
        RecommendedDish("f1", "Paneer Tikka Masala", 190, "Tender cubes of cottage cheese grilled to perfection with signature spiced gravy.", "🍛", true, "Chef's Pick", listOf("Spicy", "Chef's Pick")),
        RecommendedDish("f2", "Paneer Masala", 160, "Fresh paneer in robust, tangy masala gravy bursting with local aromatic spices.", "🧀", true, "Highly Reordered", listOf("Highly Reordered", "Popular")),
        RecommendedDish("f4", "Dal Tadka", 140, "Classic yellow lentils tempered with red chilies, garlic, cumin, and coriander.", "🍲", true, "Bestseller", listOf("Light", "Comfort Food")),
        RecommendedDish("f5", "Dal Khichdi", 100, "A traditional one-pot comforting rice and lentil dish cooked with turmeric and ghee.", "🍚", true, "Bestseller", listOf("Light", "Comfort Food")),
        RecommendedDish("f6", "Jeera Rice", 80, "Fragrant long-grain basmati rice tempered with cumin seeds and fresh ghee.", "🍚", true, "Comfort", listOf("Side", "Light"))
    )

    val filteredRecommended = recommendedItems.filter { dish ->
        val matchesSearch = dish.name.contains(searchQuery, ignoreCase = true) || dish.desc.contains(searchQuery, ignoreCase = true)
        val matchesFilter = when (selectedFilter) {
            "All" -> true
            "Highly Reordered" -> dish.badge == "Highly Reordered" || dish.tags.contains("Highly Reordered")
            "Spicy" -> dish.tags.contains("Spicy")
            "Thali" -> dish.name.contains("Thali") || dish.tags.contains("Thali")
            else -> true
        }
        matchesSearch && matchesFilter
    }

    Box(modifier = Modifier.fillMaxSize().background(Color.White)) {
        Column(modifier = Modifier.fillMaxSize().verticalScroll(rememberScrollState())) {
            
            Box(
                modifier = Modifier
                    .fillMaxWidth()
                    .background(Color(0xFFFCFDFE))
                    .padding(horizontal = 16.dp, vertical = 12.dp)
            ) {
                Column {
                    Row(
                        modifier = Modifier.fillMaxWidth(),
                        horizontalArrangement = Arrangement.SpaceBetween,
                        verticalAlignment = Alignment.CenterVertically
                    ) {
                        IconButton(onClick = onBack, modifier = Modifier.testTag("details_back_btn")) {
                            Icon(Icons.AutoMirrored.Filled.ArrowBack, contentDescription = "Back", tint = Color.Black)
                        }
                        
                        Row(
                            modifier = Modifier
                                .background(Color(0xE6E8F5E9), RoundedCornerShape(12.dp))
                                .border(1.dp, Color(0xFF2E7D32), RoundedCornerShape(12.dp))
                                .padding(horizontal = 10.dp, vertical = 4.dp),
                            verticalAlignment = Alignment.CenterVertically
                        ) {
                            Box(
                                modifier = Modifier
                                    .size(8.dp)
                                    .background(Color(0xFF2E7D32), CircleShape)
                            )
                            Spacer(modifier = Modifier.width(6.dp))
                            Text("Pure Veg", color = Color(0xFF2E7D32), fontWeight = FontWeight.Bold, fontSize = 11.sp)
                        }
                    }
                    
                    Spacer(modifier = Modifier.height(16.dp))
                    
                    Text(
                        text = "Rasoi Ghar Bhojnalay",
                        fontSize = 24.sp,
                        fontWeight = FontWeight.Black,
                        color = Color(0xFF1E293B)
                    )
                    
                    Spacer(modifier = Modifier.height(8.dp))
                    
                    Row(
                        verticalAlignment = Alignment.CenterVertically,
                        horizontalArrangement = Arrangement.spacedBy(8.dp),
                        modifier = Modifier.fillMaxWidth()
                    ) {
                        Row(
                            modifier = Modifier
                                .background(Color(0xFF1B5E20), RoundedCornerShape(6.dp))
                                .padding(horizontal = 6.dp, vertical = 2.dp),
