data class RecommendedDish(
    val id: String,
    val name: String,
    val price: Int,
    val desc: String,
    val emoji: String,
    val isVeg: Boolean,
    val badge: String,
    val tags: List<String>
)

data class HorizontalDish(
    val id: String,
    val name: String,
    val price: Int,
    val badge: String,
    val emoji: String
)

// --------------------------------------------------------------------------
// TAXI SCREEN
// --------------------------------------------------------------------------
@Composable
fun TaxiAutoScreen(onBack: () -> Unit, modifier: Modifier = Modifier) {
    var activeTab by remember { mutableStateOf("Auto") } // Auto, Cab, Bus, Ambulance
    var phase by remember { mutableStateOf(1) }
    var pickup by remember { mutableStateOf("Sector 62, Noida (crowmix Hub)") }
    var drop by remember { mutableStateOf("") }
    var bookingRef by remember { mutableStateOf("") }
    var selectedVehicle by remember { mutableStateOf("") }
    var selectedFare by remember { mutableStateOf(40) }
    var tripStep by remember { mutableStateOf(1) }
    var promoCode by remember { mutableStateOf("") }
    var promoDiscount by remember { mutableStateOf(0) }
    var isPromoApplied by remember { mutableStateOf(false) }
    var selectedPaymentMethod by remember { mutableStateOf("UPI (GPay / PhonePe)") }
    var isScheduleBooking by remember { mutableStateOf(false) }
    var scheduleTime by remember { mutableStateOf("Now") }

    LaunchedEffect(phase) {
        if (phase == 4) {
            tripStep = 1
            while (tripStep < 4) {
                delay(4000)
                tripStep++
            }
        }
    }

    // Dynamic coloring from design guide
    val themeColor = when (activeTab) {
        "Ambulance" -> Color(0xFFEF4444)
        "Bus" -> Color(0xFF6366F1)
        else -> Color(0xFFCA8A04) // Taxi / Auto -> Yellow/Amber
    }

    Column(modifier = modifier.fillMaxSize().background(lightBg)) {
        // Adaptable Header
        Row(
            modifier = Modifier
                .fillMaxWidth()
                .background(themeColor)
                .padding(14.dp),
            verticalAlignment = Alignment.CenterVertically
        ) {
            IconButton(onClick = onBack, modifier = Modifier.testTag("taxi_back")) {
                Icon(Icons.AutoMirrored.Filled.ArrowBack, "Back", tint = Color.White)
            }
            Text(
                text = when (activeTab) {
                    "Ambulance" -> "🚑 Emergency Dispatch"
                    "Bus" -> "🚌 Bus Terminal"
                    "Cab" -> "🚕 High-Speed Cabs"
                    else -> "🛺 Eco Auto & Rickshaws"
                },
                color = Color.White,
                fontWeight = FontWeight.Black,
                fontSize = 18.sp
            )
        }

        // Pill / Tab Selector at standard position
        Row(
            modifier = Modifier
                .fillMaxWidth()
                .background(Color.White)
                .padding(vertical = 10.dp, horizontal = 12.dp)
                .horizontalScroll(rememberScrollState()),
            horizontalArrangement = Arrangement.spacedBy(8.dp)
        ) {
            listOf("Auto", "Cab", "Bus", "Ambulance").forEach { tab ->
                val isSelected = activeTab == tab
                val itemColor = when (tab) {
                    "Ambulance" -> Color(0xFFEF4444)
                    "Bus" -> Color(0xFF6366F1)
                    else -> Color(0xFFCA8A04)
                }
                Box(
                    modifier = Modifier
                        .clip(RoundedCornerShape(20.dp))
                        .background(if (isSelected) itemColor else Color(0xFFF1F5F9))
                        .clickable { 
                            activeTab = tab 
                            phase = 1
                            drop = ""
                            selectedVehicle = ""
                            isPromoApplied = false
                            promoDiscount = 0
                        }
                        .padding(horizontal = 14.dp, vertical = 8.dp),
                    contentAlignment = Alignment.Center
                ) {
                    Row(verticalAlignment = Alignment.CenterVertically) {
                        Text(
                            text = when (tab) {
                                "Auto" -> "🛺 Auto"
                                "Cab" -> "🚕 Taxi"
                                "Bus" -> "🚌 Bus"
                                else -> "🚑 Ambulance"
                            },
                            color = if (isSelected) Color.White else Color(0xFF475569),
                            fontWeight = FontWeight.Bold,
                            fontSize = 12.sp
                        )
                    }
                }
            }
        }

        when (activeTab) {
            "Ambulance" -> {
                // REDIRECT TO EMBEDDED AMBULANCE BOOKING FORM
                AmbulanceScreenContent(onBack = { activeTab = "Auto" })
            }
            "Bus" -> {
                // REDIRECT / BRIEF INFO FOR BUS BOOKING
                Column(
                    modifier = Modifier
                        .padding(16.dp)
                        .fillMaxSize()
                        .verticalScroll(rememberScrollState()),
                    horizontalAlignment = Alignment.CenterHorizontally,
                    verticalArrangement = Arrangement.Center
                ) {
                    Text("🚌 Bus Ticketing Terminal", fontWeight = FontWeight.Black, fontSize = 20.sp, color = Color(0xFF1E293B))
                    Spacer(modifier = Modifier.height(8.dp))
                    Text(
                        "Book intra-city or inter-state long route transit tickets instantly with verified private operators & roadways services.",
                        textAlign = TextAlign.Center,
                        fontSize = 12.sp,
                        color = Color(0xFF687280)
                    )
                    Spacer(modifier = Modifier.height(24.dp))
                    Button(
                        onClick = { onBack() },
                        colors = ButtonDefaults.buttonColors(containerColor = Color(0xFF6366F1)),
                        shape = RoundedCornerShape(20.dp),
                        modifier = Modifier.fillMaxWidth().height(48.dp)
                    ) {
                        Text("Back to main menu", fontWeight = FontWeight.Bold, color = Color.White)
                    }
                }
            }
            else -> {
                // TAXI / AUTO FLOWS
                when (phase) {
                    1 -> {
                        Column(modifier = Modifier.padding(16.dp).verticalScroll(rememberScrollState())) {
                            Text("Setup Transit Destination", fontWeight = FontWeight.Black, fontSize = 16.sp, color = Color(0xFF0F172A))
                            Text("Get instant matchings with verified dynamic riders in Sector 62", fontSize = 11.sp, color = Color(0xFF687280))
                            Spacer(modifier = Modifier.height(16.dp))
                            
                            OutlinedTextField(
                                value = pickup,
                                onValueChange = { pickup = it },
                                leadingIcon = { Icon(Icons.Default.LocationOn, "Pickup", tint = Color(0xFF10B981)) },
                                label = { Text("Pickup Location") },
                                modifier = Modifier.fillMaxWidth().testTag("pickup_field"),
                                shape = RoundedCornerShape(12.dp)
                            )
                            Spacer(modifier = Modifier.height(8.dp))
                            OutlinedTextField(
                                value = drop,
                                onValueChange = { drop = it },
                                leadingIcon = { Icon(Icons.Default.Search, "Drop Pin", tint = themeColor) },
                                label = { Text("Drop Location") },
                                placeholder = { Text("Search city, metro, office landmarks...") },
                                modifier = Modifier.fillMaxWidth().testTag("drop_field"),
                                shape = RoundedCornerShape(12.dp)
                            )
                            Spacer(modifier = Modifier.height(16.dp))

                            Text("🏠 Pick Saved Places for Quick Booking:", fontSize = 12.sp, fontWeight = FontWeight.ExtraBold, color = Color(0xFF334155))
                            Spacer(modifier = Modifier.height(8.dp))
                            Row(
                                modifier = Modifier.fillMaxWidth().horizontalScroll(rememberScrollState()),
                                horizontalArrangement = Arrangement.spacedBy(8.dp)
                            ) {
                                listOf(
                                    "Work 💼" to "Sector 62 Technopark Noida",
                                    "Home 🏠" to "Sector 15 Main Road Noida",
                                    "Airport ✈️" to "IGI Airport Terminal 3 Delhi",
                                    "Metro 🚇" to "Sector 52 Blue Line Platform"
                                ).forEach { (label, loc) ->
                                    Box(
                                        modifier = Modifier
                                            .clip(RoundedCornerShape(10.dp))
                                            .background(Color.White)
                                            .border(1.dp, Color(0xFFE2E8F0), RoundedCornerShape(10.dp))
                                            .clickable { drop = loc }
                                            .padding(horizontal = 12.dp, vertical = 10.dp)
                                    ) {
                                        Text(label, fontSize = 11.sp, fontWeight = FontWeight.Bold, color = Color(0xFF1E293B))
                                    }
                                }
                            }
                            Spacer(modifier = Modifier.height(16.dp))
                            Text("Recent Searches:", fontSize = 11.sp, fontWeight = FontWeight.SemiBold, color = Color(0xFF687280))
                            listOf("Grand Venice Mall Gr. Noida 🛍️", "Fortis Hospital Sec 62 🏥", "Noida City Centre Gate 1 🚇").forEach { dest ->
                                Row(
                                    modifier = Modifier
                                        .fillMaxWidth()
                                        .clickable { drop = dest.substringBeforeLast(" ") }
                                        .padding(vertical = 8.dp),
                                    verticalAlignment = Alignment.CenterVertically
                                ) {
                                    Icon(Icons.Default.LocationOn, null, modifier = Modifier.size(14.dp), tint = Color(0xFF9CA3AF))
                                    Spacer(modifier = Modifier.width(8.dp))
                                    Text(dest, fontSize = 12.sp, color = Color(0xFF475569))
                                }
                            }

                            Spacer(modifier = Modifier.height(24.dp))
                            Button(
                                onClick = { if (drop.isNotBlank()) phase = 2 },
                                modifier = Modifier
                                    .fillMaxWidth()
                                    .height(48.dp)
                                    .testTag("find_rides_btn"),
                                colors = ButtonDefaults.buttonColors(containerColor = themeColor),
                                shape = RoundedCornerShape(20.dp)
                            ) {
                                Text("Find Available Rides", color = Color.White, fontWeight = FontWeight.Bold)
                            }
                        }
                    }
                    2 -> {
                        Column(modifier = Modifier.fillMaxSize()) {
                            Box(
                                modifier = Modifier
                                    .fillMaxWidth()
                                    .background(Color(0xFFFEF3C7))
                                    .padding(10.dp)
                            ) {
                                Row(verticalAlignment = Alignment.CenterVertically) {
                                    Icon(Icons.Default.CheckCircle, "Route Set", tint = themeColor, modifier = Modifier.size(16.dp))
                                    Spacer(modifier = Modifier.width(8.dp))
                                    Text("Route set from $pickup to $drop", fontSize = 11.sp, color = Color(0xFF92400E), fontWeight = FontWeight.Bold, maxLines = 1, overflow = TextOverflow.Ellipsis)
                                }
                            }

                            Column(modifier = Modifier.padding(16.dp).weight(1f).verticalScroll(rememberScrollState())) {
                                Text("Select Preferred Ride Option:", fontWeight = FontWeight.Black, fontSize = 14.sp, color = Color(0xFF0F172A))
                                Spacer(modifier = Modifier.height(8.dp))

                                val vehicleList = if (activeTab == "Auto") {
                                    listOf(
                                        Triple("Auto Rickshaw (Eco-Savings)", 64, "🛺 • Rajinder Pal (UP 16 ER 9123) • ⭐4.7"),
                                        Triple("E-Rickshaw (Short-Local)", 36, "🛺 • Satish Kumar (UP 16 AT 4482) • ⭐4.5")
                                    )
                                } else {
                                    listOf(
                                        Triple("Standard Hatchback (Fast)", 90, "🚗 • Sanjay Yadav (UP 16 CT 1124) • ⭐4.8"),
                                        Triple("Spacious Prime Sedan", 132, "🚗 • Manpreet Singh (HR 26 DT 5521) • ⭐4.9"),
                                        Triple("Suv Cruiser / Ertiga", 210, "🚙 • Nafees Ahmed (DL 3C AW 8891) • ⭐4.9")
                                    )
                                }

                                vehicleList.forEach { (v, fare, desc) ->
                                    Card(
                                        modifier = Modifier
                                            .fillMaxWidth()
                                            .padding(bottom = 10.dp)
                                            .clickable { 
                                                selectedVehicle = v 
                                                selectedFare = fare 
                                                bookingRef = (if (activeTab == "Auto") "AUT-" else "TAX-") + (10000..99999).random()
                                                phase = 3 
                                            }
                                            .testTag("select_$v"),
                                        colors = CardDefaults.cardColors(containerColor = Color.White),
                                        border = BorderStroke(1.dp, Color(0xFFE2E8F0))
                                    ) {
                                        Row(modifier = Modifier.padding(14.dp), verticalAlignment = Alignment.CenterVertically) {
                                            Text(if (v.contains("Suv") || v.contains("SUV")) "🚙" else if (v.contains("Rickshaw")) "🛺" else "🚗", fontSize = 34.sp)
                                            Spacer(modifier = Modifier.width(14.dp))
                                            Column(modifier = Modifier.weight(1f)) {
                                                Text(v, fontWeight = FontWeight.ExtraBold, fontSize = 14.sp, color = Color(0xFF1E293B))
                                                Text(desc, fontSize = 11.sp, color = Color(0xFF687280))
                                                Text("ETA: 3 mins away", fontSize = 10.sp, color = Color(0xFF10B981), fontWeight = FontWeight.Bold)
                                            }
                                            Text("₹$fare", fontWeight = FontWeight.Black, fontSize = 16.sp, color = Color(0xFF1E293B))
                                        }
                                    }
                                }
                            }
                        }
                    }
                    3 -> {
                        val ctx = LocalContext.current
                        Column(modifier = Modifier.padding(16.dp).verticalScroll(rememberScrollState())) {
                            Card(
                                modifier = Modifier.fillMaxWidth(),
                                colors = CardDefaults.cardColors(containerColor = Color.White),
                                border = BorderStroke(1.dp, Color(0xFFE2E8F0))
                            ) {
                                Column(modifier = Modifier.padding(16.dp)) {
                                    Row(modifier = Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.SpaceBetween) {
                                        Text("BOOKING OFFER CONFIRMATION", fontWeight = FontWeight.Black, color = themeColor, fontSize = 12.sp)
                                        Text(bookingRef, fontWeight = FontWeight.Bold, fontSize = 11.sp, color = Color(0xFF687280))
                                    }
                                    HorizontalDivider(modifier = Modifier.padding(vertical = 12.dp))
                                    Row(verticalAlignment = Alignment.CenterVertically) {
                                        Text("Vehicle Chosen:", fontWeight = FontWeight.SemiBold, fontSize = 13.sp)
                                        Spacer(modifier = Modifier.width(8.dp))
                                        Text(selectedVehicle, fontWeight = FontWeight.Bold, fontSize = 14.sp)
                                    }
                                    Spacer(modifier = Modifier.height(16.dp))
                                    Text("Fare breakdown summary:", fontWeight = FontWeight.ExtraBold, fontSize = 11.sp, color = Color(0xFF687280))
                                    Spacer(modifier = Modifier.height(8.dp))
                                    Row(modifier = Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.SpaceBetween) {
                                        Text("Estimated Fare", fontSize = 12.sp, color = Color.DarkGray)
                                        Text("₹$selectedFare", fontSize = 12.sp, fontWeight = FontWeight.Bold)
                                    }
                                    Row(modifier = Modifier.fillMaxWidth().padding(top = 4.dp), horizontalArrangement = Arrangement.SpaceBetween) {
                                        Text("Rider Care & Booking fee", fontSize = 12.sp, color = Color.DarkGray)
                                        Text("₹4", fontSize = 12.sp, fontWeight = FontWeight.Bold)
                                    }
                                    if (isPromoApplied) {
                                        Row(modifier = Modifier.fillMaxWidth().padding(top = 4.dp), horizontalArrangement = Arrangement.SpaceBetween) {
                                            Text("Coupon Discount Applied (FREEUP)", fontSize = 12.sp, color = Color(0xFFEF4444))
                                            Text("-₹$promoDiscount", fontSize = 12.sp, color = Color(0xFFEF4444), fontWeight = FontWeight.Bold)
                                        }
                                    }
                                    HorizontalDivider(modifier = Modifier.padding(vertical = 8.dp))
                                    Row(
                                        modifier = Modifier
                                            .fillMaxWidth()
                                            .background(Color(0xFFFFFAEB))
                                            .padding(8.dp),
                                        horizontalArrangement = Arrangement.SpaceBetween
                                    ) {
                                        Text("Total Grand Bill", fontWeight = FontWeight.ExtraBold, color = Color(0xFF92400E))
                                        val totalCost = (selectedFare + 4 - promoDiscount).coerceAtLeast(0)
                                        Text("₹$totalCost", fontWeight = FontWeight.Black, color = Color(0xFF92400E), fontSize = 16.sp)
                                    }
                                }
                            }

                            Spacer(modifier = Modifier.height(16.dp))
                            
                            // Promo Code Box
                            Row(
                                modifier = Modifier.fillMaxWidth(),
                                verticalAlignment = Alignment.CenterVertically
                            ) {
                                OutlinedTextField(
                                    value = promoCode,
                                    onValueChange = { promoCode = it },
                                    label = { Text("Have a Coupon code?") },
                                    placeholder = { Text("Enter FREEUP to save ₹30") },
                                    modifier = Modifier.weight(1f),
                                    singleLine = true,
                                    shape = RoundedCornerShape(12.dp)
                                )
                                Spacer(modifier = Modifier.width(8.dp))
                                Button(
                                    onClick = {
                                        if (promoCode.uppercase().trim() == "FREEUP") {
                                            promoDiscount = 30
                                            isPromoApplied = true
                                            Toast.makeText(ctx, "SUCCESS 🎉: Coupon FREEUP Applied. ₹30 Saved!", Toast.LENGTH_SHORT).show()
                                        } else {
                                            Toast.makeText(ctx, "INVALID CODE. Enter 'FREEUP'", Toast.LENGTH_SHORT).show()
                                        }
                                    },
                                    colors = ButtonDefaults.buttonColors(containerColor = Color(0xFF1E293B)),
                                    shape = RoundedCornerShape(12.dp)
                                ) {
                                    Text("Apply", color = Color.White)
                                }
                            }

                            Spacer(modifier = Modifier.height(16.dp))
                            Text("Select Payment Option:", fontWeight = FontWeight.Bold, fontSize = 12.sp, color = Color(0xFF687280))
                            Spacer(modifier = Modifier.height(8.dp))
                            Row(modifier = Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.spacedBy(8.dp)) {
                                listOf("UPI (GPay / PhonePe)", "Cash On Board").forEach { method ->
                                    val isSelected = selectedPaymentMethod == method
                                    Box(
                                        modifier = Modifier
                                            .weight(1f)
                                            .clip(RoundedCornerShape(10.dp))
                                            .background(if (isSelected) themeColor.copy(alpha = 0.15f) else Color.White)
                                            .border(1.dp, if (isSelected) themeColor else Color(0xFFE2E8F0), RoundedCornerShape(10.dp))
                                            .clickable { selectedPaymentMethod = method }
                                            .padding(12.dp),
                                        contentAlignment = Alignment.Center
                                    ) {
                                        Text(method, fontSize = 11.sp, fontWeight = FontWeight.Bold, color = if (isSelected) themeColor else Color.DarkGray)
                                    }
                                }
                            }

                            Spacer(modifier = Modifier.height(16.dp))

                            // Date and Time Scheduler Checkbox
                            Row(verticalAlignment = Alignment.CenterVertically, modifier = Modifier.fillMaxWidth()) {
                                Checkbox(checked = isScheduleBooking, onCheckedChange = { isScheduleBooking = it })
                                Text("Schedule ride for later / medical transfer", fontSize = 12.sp, fontWeight = FontWeight.SemiBold)
                            }

                            if (isScheduleBooking) {
                                Row(
                                    modifier = Modifier.fillMaxWidth().padding(top = 8.dp),
                                    horizontalArrangement = Arrangement.spacedBy(8.dp)
                                ) {
                                    listOf("In 30 Mins", "In 1 Hour", "Tomorrow Morning").forEach { time ->
                                        val isSel = scheduleTime == time
                                        Box(
                                            modifier = Modifier
                                                .weight(1f)
                                                .clip(RoundedCornerShape(8.dp))
                                                .background(if (isSel) Color.DarkGray else Color.White)
                                                .clickable { scheduleTime = time }
                                                .padding(6.dp),
                                            contentAlignment = Alignment.Center
                                        ) {
                                            Text(time, fontSize = 10.sp, color = if (isSel) Color.White else Color.DarkGray)
                                        }
                                    }
                                }
                            }

                            Spacer(modifier = Modifier.height(24.dp))
                            Button(
                                onClick = { phase = 4 },
                                modifier = Modifier
                                    .fillMaxWidth()
                                    .height(48.dp)
                                    .testTag("track_ride_btn"),
                                colors = ButtonDefaults.buttonColors(containerColor = themeColor),
                                shape = RoundedCornerShape(20.dp) // standard visual corner radius as requested!
                            ) {
                                Text("Book Now & Track Ride", color = Color.White, fontWeight = FontWeight.Bold)
                            }
                        }
                    }
                    4 -> {
                        Column(modifier = Modifier.padding(16.dp), horizontalAlignment = Alignment.CenterHorizontally) {
                            Text("Live Trip Progress Tracker", fontWeight = FontWeight.Black, fontSize = 18.sp, color = Color(0xFF0F172A))
                            Text("Your ride with Satish Yadav (Eco-Savings) is live in Sector 62", fontSize = 11.sp, color = Color(0xFF687280))
                            Spacer(modifier = Modifier.height(16.dp))
                            
                            // Map Simulated Box
                            Box(
                                modifier = Modifier
                                    .fillMaxWidth()
                                    .height(130.dp)
                                    .clip(RoundedCornerShape(16.dp))
                                    .background(Color(0xFFE2E8F0))
                                    .border(1.dp, Color(0xFFCBD5E1), RoundedCornerShape(16.dp)),
                                contentAlignment = Alignment.Center
                            ) {
                                Canvas(modifier = Modifier.fillMaxSize()) {
                                    // Simulated maps route drawing
                                    drawCircle(color = Color(0xFF10B981), radius = 12f, center = center.copy(x = center.x - 100f, y = center.y + 30f))
                                    drawCircle(color = Color(0xFFEF4444), radius = 12f, center = center.copy(x = center.x + 100f, y = center.y - 30f))
                                }
                                Column(horizontalAlignment = Alignment.CenterHorizontally) {
                                    Text("🗺️ Live Route Simulation Map", fontWeight = FontWeight.Bold, fontSize = 12.sp, color = Color(0xFF334155))
                                    Text("From: $pickup -> $drop", fontSize = 10.sp, color = Color(0xFF687280))
                                    Text("Driver is arriving in 2 mins!", fontWeight = FontWeight.Bold, fontSize = 11.sp, color = Color(0xFF2563EB))
                                }
                            }

                            Spacer(modifier = Modifier.height(24.dp))
                            listOf(
                                "Rider Dispatched & Routed 🔵" to 1,
                                "Driver Arriving in 2m 🟡" to 2,
                                "In Route Transit 🟠" to 3,
                                "Completed Billed & Confirmed ✅" to 4
                            ).forEach { (step, idx) ->
                                val active = tripStep >= idx
                                Row(
                                    modifier = Modifier
                                        .fillMaxWidth()
                                        .padding(vertical = 8.dp),
                                    verticalAlignment = Alignment.CenterVertically
                                ) {
                                    Box(
                                        modifier = Modifier
                                            .size(16.dp)
                                            .background(if (active) themeColor else Color(0xFF9CA3AF), CircleShape)
                                    )
                                    Spacer(modifier = Modifier.width(12.dp))
                                    Text(
                                        text = step,
                                        fontWeight = if (active) FontWeight.Bold else FontWeight.Normal,
                                        color = if (active) Color(0xFF1E293B) else Color(0xFF687280),
                                        fontSize = 12.sp
                                    )
                                }
                            }
                            Spacer(modifier = Modifier.height(24.dp))
                            Button(
                                onClick = { phase = 1 },
                                colors = ButtonDefaults.buttonColors(containerColor = Color.Red),
                                shape = RoundedCornerShape(20.dp),
                                modifier = Modifier
                                    .fillMaxWidth()
                                    .testTag("cancel_ride")
                            ) {
                                Text("Cancel Ride / Back To Setup", color = Color.White, fontWeight = FontWeight.Bold)
                            }
                        }
                    }
                }
            }
        }
    }
}

// --------------------------------------------------------------------------
// AMBULANCE SCREEN
// --------------------------------------------------------------------------
@Composable
fun AmbulanceScreen(onBack: () -> Unit, modifier: Modifier = Modifier) {
    Column(modifier = modifier.fillMaxSize().background(lightBg)) {
        Row(
            modifier = Modifier.fillMaxWidth().background(Color(0xFFEF4444)).padding(14.dp),
            verticalAlignment = Alignment.CenterVertically
        ) {
            IconButton(onClick = onBack, modifier = Modifier.testTag("ambulance_back")) {
                Icon(Icons.AutoMirrored.Filled.ArrowBack, "Back", tint = Color.White)
            }
            Text("🚨 EMERGENCY SIREN DISPATCH", color = Color.White, fontWeight = FontWeight.Black, fontSize = 16.sp)
        }
        AmbulanceScreenContent(onBack = onBack)
    }
}

@Composable
fun AmbulanceScreenContent(onBack: () -> Unit) {
    var phase by remember { mutableStateOf(1) }
    var selectedType by remember { mutableStateOf("Basic Life Support (BLS) — ₹500 flat") }
    var patientName by remember { mutableStateOf("") }
    var pickupAddress by remember { mutableStateOf("Sector 62, Noida") }
    var selectedHospital by remember { mutableStateOf("Fortis Hospital, Sector 62 Noida") }
    var contactNumber by remember { mutableStateOf("") }
    var bookingRef by remember { mutableStateOf("AMB-10293") }
    var dispatchStep by remember { mutableStateOf(1) }
    var emergencyMode by remember { mutableStateOf(true) }
    var medicalSymptom by remember { mutableStateOf("Cardiac / Heart Symptoms ❤️") }

    LaunchedEffect(phase) {
        if (phase == 2) {
            dispatchStep = 1
            while (dispatchStep < 4) {
                delay(3000)
                dispatchStep++
            }
        }
    }

    when (phase) {
        1 -> {
            Column(
                modifier = Modifier
                    .fillMaxSize()
                    .verticalScroll(rememberScrollState())
                    .padding(16.dp)
            ) {
                Text(
                    "EMERGENCY VEHICLE TYPE", 
                    fontWeight = FontWeight.Black, 
                    fontSize = 11.sp, 
                    color = Color(0xFF687280),
                    letterSpacing = 1.sp
                )
                Spacer(modifier = Modifier.height(8.dp))
                listOf(
                    "Basic Life Support (BLS) — ₹500 flat" to "Standard trauma medical transport",
                    "Advanced Life Support (ALS / ICU) — ₹1200 flat" to "Critical cardiac ICU unit with ventilator",
                    "Paediatric Response Unit — ₹800 flat" to "Specialized newborn/child care equipment"
                ).forEach { (type, desc) ->
                    val isChosen = selectedType == type
                    Box(
                        modifier = Modifier
                            .fillMaxWidth()
                            .padding(bottom = 8.dp)
                            .clip(RoundedCornerShape(12.dp))
                            .background(if (isChosen) Color(0xFFFEF2F2) else Color.White)
                            .border(1.dp, if (isChosen) Color(0xFFEF4444) else Color(0xFFE2E8F0), RoundedCornerShape(12.dp))
                            .clickable { selectedType = type }
                            .padding(12.dp)
                    ) {
                        Row(verticalAlignment = Alignment.CenterVertically) {
                            RadioButton(
                                selected = isChosen,
                                onClick = { selectedType = type },
                                colors = RadioButtonDefaults.colors(selectedColor = Color(0xFFEF4444))
                            )
                            Spacer(modifier = Modifier.width(8.dp))
                            Column {
                                Text(type, fontWeight = FontWeight.Bold, fontSize = 13.sp, color = if (isChosen) Color(0xFF991B1B) else Color(0xFF1E293B))
                                Text(desc, fontSize = 10.sp, color = Color(0xFF687280))
                            }
                        }
                    }
                }

                Spacer(modifier = Modifier.height(16.dp))
                Text(
                    "PATIENT DETAILS", 
                    fontWeight = FontWeight.Black, 
                    fontSize = 11.sp, 
                    color = Color(0xFF687280),
                    letterSpacing = 1.sp
                )
                Spacer(modifier = Modifier.height(8.dp))
                
                OutlinedTextField(
                    value = patientName,
                    onValueChange = { patientName = it },
                    leadingIcon = { Icon(Icons.Default.Person, null, tint = Color(0xFF687280)) },
                    label = { Text("Patient Full Name") },
                    placeholder = { Text("E.g. Ramesh Kumar") },
                    modifier = Modifier.fillMaxWidth().testTag("patient_field"),
                    shape = RoundedCornerShape(12.dp)
                )
                
                Spacer(modifier = Modifier.height(8.dp))
                
                OutlinedTextField(
                    value = pickupAddress,
                    onValueChange = { pickupAddress = it },
                    leadingIcon = { Icon(Icons.Default.LocationOn, null, tint = Color(0xFFEF4444)) },
                    label = { Text("Emergency Pickup Location") },
                    modifier = Modifier.fillMaxWidth().testTag("amb_pickup_field"),
                    shape = RoundedCornerShape(12.dp)
                )

                Spacer(modifier = Modifier.height(16.dp))
                Text(
                    "DESTINATION EMERGENCY RECEIVING CENTER", 
                    fontWeight = FontWeight.Black, 
                    fontSize = 11.sp, 
                    color = Color(0xFF687280),
                    letterSpacing = 1.sp
                )
                Spacer(modifier = Modifier.height(8.dp))
                listOf(
                    "Fortis Hospital, Sector 62 Noida", 
                    "Jaypee Hospital, Sector 128 Noida", 
                    "Max Super Speciality, Sector 19 Noida", 
                    "Apollo Hospital, Sector 26 Noida"
                ).forEach { hospital ->
                    val isChosen = selectedHospital == hospital
                    Box(
                        modifier = Modifier
                            .fillMaxWidth()
                            .padding(bottom = 6.dp)
                            .clip(RoundedCornerShape(8.dp))
                            .background(if (isChosen) Color(0xFFFEF2F2) else Color.White)
                            .border(1.dp, if (isChosen) Color(0xFFEF4444) else Color(0xFFE2E8F0), RoundedCornerShape(8.dp))
                            .clickable { selectedHospital = hospital }
                            .padding(10.dp)
                    ) {
                        Row(verticalAlignment = Alignment.CenterVertically) {
                            Icon(
                                Icons.Default.LocalHospital, 
                                null, 
                                tint = if (isChosen) Color(0xFFEF4444) else Color(0xFF687280),
                                modifier = Modifier.size(16.dp)
                            )
                            Spacer(modifier = Modifier.width(10.dp))
                            Text(
                                text = hospital, 
                                fontSize = 12.sp, 
                                fontWeight = if (isChosen) FontWeight.Bold else FontWeight.Medium,
                                color = if (isChosen) Color(0xFF991B1B) else Color(0xFF1E293B)
                            )
                        }
                    }
                }

                Spacer(modifier = Modifier.height(16.dp))
                OutlinedTextField(
                    value = contactNumber,
                    onValueChange = { contactNumber = it },
                    leadingIcon = { Icon(Icons.Default.Call, null, tint = Color(0xFF687280)) },
                    label = { Text("Alternative Dispatch Contact Number") },
                    placeholder = { Text("E.g. +91 998811XXXX") },
                    modifier = Modifier.fillMaxWidth().testTag("contact_field"),
                    shape = RoundedCornerShape(12.dp)
                )

                Spacer(modifier = Modifier.height(16.dp))

                // Emergency Flash Glow Mode Switch
                Box(
                    modifier = Modifier
                        .fillMaxWidth()
                        .clip(RoundedCornerShape(12.dp))
                        .background(if (emergencyMode) Color(0xFFFFF1F2) else Color(0xFFF1F5F9))
                        .border(1.dp, if (emergencyMode) Color(0xFFFDA4AF) else Color.Transparent, RoundedCornerShape(12.dp))
                        .padding(12.dp)
                ) {
                    Row(verticalAlignment = Alignment.CenterVertically) {
                        Box(
                            modifier = Modifier
                                .size(10.dp)
                                .background(if (emergencyMode) Color.Red else Color(0xFF687280), CircleShape)
                        )
                        Spacer(modifier = Modifier.width(10.dp))
                        Column(modifier = Modifier.weight(1f)) {
                            Text("🚨 CRITICAL DISPATCH OVERRIDE", fontSize = 11.sp, fontWeight = FontWeight.Bold, color = if (emergencyMode) Color(0xFF9F1239) else Color.DarkGray)
                            Text("Fast-track with sirens and bypass transit signals directly", fontSize = 9.sp, color = Color(0xFF687280))
                        }
                        Switch(
                            checked = emergencyMode,
                            onCheckedChange = { emergencyMode = it },
                            colors = SwitchDefaults.colors(checkedThumbColor = Color.Red, checkedTrackColor = Color(0xFFFECDD3))
                        )
                    }
                }

                Spacer(modifier = Modifier.height(24.dp))
                
                Button(
                    onClick = {
                        if (patientName.isNotBlank() && contactNumber.isNotBlank()) {
                            bookingRef = "AMB-" + (10000..99999).random()
                            phase = 2
                        }
                    },
                    modifier = Modifier
                        .fillMaxWidth()
                        .height(52.dp)
                        .testTag("dispatch_ambulance_btn"),
                    colors = ButtonDefaults.buttonColors(containerColor = Color(0xFFEF4444)),
                    shape = RoundedCornerShape(20.dp) // rounded visual corner radius as requested!
                ) {
                    Text("DISPATCH SIREN RECOVERY AMBULANCE", fontWeight = FontWeight.Black, color = Color.White, fontSize = 13.sp)
                }
            }
        }
        2 -> {
            Column(modifier = Modifier.padding(16.dp), horizontalAlignment = Alignment.CenterHorizontally) {
                Card(
                    modifier = Modifier.fillMaxWidth(), 
                    colors = CardDefaults.cardColors(containerColor = Color.White),
                    border = BorderStroke(1.dp, Color(0xFFEF4444).copy(alpha = 0.3f))
                ) {
                    Column(modifier = Modifier.padding(16.dp)) {
                        Row(modifier = Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.SpaceBetween) {
                            Text("SIREN SIREN DISPATCH LIVE", fontWeight = FontWeight.Black, color = Color(0xFFEF4444), fontSize = 12.sp)
                            Text(bookingRef, fontWeight = FontWeight.Bold, fontSize = 11.sp, color = Color(0xFF687280))
                        }
                        HorizontalDivider(modifier = Modifier.padding(vertical = 12.dp))
                        Text("Destination Hospital: $selectedHospital", fontSize = 12.sp, fontWeight = FontWeight.Bold)
                        Text("Ventilation Class: $selectedType", fontSize = 12.sp, color = Color.DarkGray)
                        Text("Patient: $patientName", fontSize = 12.sp, color = Color.DarkGray)
                        
                        Text("Assigned Urgent Personnel Rescue Team:", fontWeight = FontWeight.Bold, fontSize = 11.sp, modifier = Modifier.padding(top = 10.dp), color = Color(0xFF687280))
                        val driver = if (selectedType.contains("ALS")) "Dr. Rahul Agrawal & Driver Vivek — Vehicle: UP 16 G 9904 [ICU Ventilator]" else "Paramedic Sonu Dev — Vehicle: UP 16 G 3312 [AMB Speed]"
                        Text(driver, fontSize = 11.sp, color = Color(0xFF991B1B), fontWeight = FontWeight.Bold)
                    }
                }
                
                Spacer(modifier = Modifier.height(24.dp))
                Text("Emergency Dispatch Status Feed (Est ~4 mins)", fontWeight = FontWeight.Black, fontSize = 14.sp, color = Color(0xFF1E293B))
                Spacer(modifier = Modifier.height(16.dp))
                listOf(
                    "Medical Crew Assembly Dispatched 🔵" to 1,
                    "Enroute to $pickupAddress 🟡" to 2,
                    "Stabilizing Emergency Patient 🟠" to 3,
                    "Full Siren Transit to Receiving Room ✅" to 4
                ).forEach { (step, idx) ->
                    val active = dispatchStep >= idx
                    Row(
                        modifier = Modifier
                            .fillMaxWidth()
                            .padding(vertical = 8.dp),
                        verticalAlignment = Alignment.CenterVertically
                    ) {
                        Box(
                            modifier = Modifier
                                .size(16.dp)
                                .background(if (active) Color(0xFFEF4444) else Color(0xFF9CA3AF), CircleShape)
                        )
                        Spacer(modifier = Modifier.width(12.dp))
                        Text(
                            text = step, 
                            fontWeight = if (active) FontWeight.Bold else FontWeight.Normal,
                            color = if (active) Color(0xFF1E293B) else Color(0xFF687280),
                            fontSize = 12.sp
                        )
                    }
                }
                
                Spacer(modifier = Modifier.height(30.dp))
                Button(
                    onClick = { phase = 1 }, 
                    colors = ButtonDefaults.buttonColors(containerColor = Color.DarkGray), 
                    shape = RoundedCornerShape(20.dp),
                    modifier = Modifier
                        .fillMaxWidth()
                        .testTag("retire_ambulance")
                ) {
                    Text("Dismiss Siren & Return", color = Color.White, fontWeight = FontWeight.Bold)
                }
            }
        }
    }
}

// --------------------------------------------------------------------------
// CUSTOM CANVAS BOOKMARK COMPOSABLE (100% COMPILE SAFE)
// --------------------------------------------------------------------------
@Composable
fun BookmarkIcon(modifier: Modifier = Modifier, isBookmarked: Boolean, tint: Color) {
    Canvas(modifier = modifier) {
        val path = androidx.compose.ui.graphics.Path().apply {
            moveTo(size.width * 0.25f, size.height * 0.15f)
            lineTo(size.width * 0.75f, size.height * 0.15f)
            lineTo(size.width * 0.75f, size.height * 0.85f)
            lineTo(size.width * 0.5f, size.height * 0.65f)
            lineTo(size.width * 0.25f, size.height * 0.85f)
            close()
        }
        if (isBookmarked) {
            drawPath(path = path, color = tint, style = androidx.compose.ui.graphics.drawscope.Fill)
        } else {
            drawPath(path = path, color = tint, style = androidx.compose.ui.graphics.drawscope.Stroke(width = 2.dp.toPx()))
        }
    }
}

