                        listOf("Mon", "Wed", "Fri"), listOf("8:30 AM", "12:00 PM", "3:30 PM"),
                        "https://images.unsplash.com/photo-1612349317150-e413f6a5b16d?w=500&auto=format&fit=crop&q=80"
                    )
                )

                val filteredDoctors = premiumDoctors.filter { doc ->
                    if (selectedHospName.contains("Fortis")) doc.id.startsWith("f_")
                    else if (selectedHospName.contains("Jaypee")) doc.id.startsWith("j_")
                    else if (selectedHospName.contains("Max")) doc.id.startsWith("m_")
                    else doc.id.startsWith("a_")
                }

                Column(modifier = Modifier.padding(16.dp).verticalScroll(rememberScrollState())) {
                    Row(
                        modifier = Modifier.fillMaxWidth(),
                        horizontalArrangement = Arrangement.SpaceBetween,
                        verticalAlignment = Alignment.CenterVertically
                    ) {
                        Column {
                            Text("Active OPD Medics", fontWeight = FontWeight.Black, fontSize = 15.sp, color = Color(0xFF1E293B))
                            Text("at $selectedHospName", fontSize = 11.sp, color = Color(0xFF687280))
                        }
                    }
                    Spacer(modifier = Modifier.height(16.dp))

                    var doctorBookmarks by remember { mutableStateOf(setOf<String>()) }
                    val context = LocalContext.current

                    filteredDoctors.forEach { doc ->
                        val isBookmarked = doctorBookmarks.contains(doc.id)
                        val isExpanded = expandedAvailabilities.contains(doc.id)
                        Card(
                            modifier = Modifier
                                .fillMaxWidth()
                                .padding(bottom = 16.dp),
                            shape = RoundedCornerShape(24.dp),
                            colors = CardDefaults.cardColors(containerColor = Color.White),
                            border = BorderStroke(1.dp, Color(0xFFEFF1F4))
                        ) {
                            Column(modifier = Modifier.padding(14.dp)) {
                                // Centered square doctor image with rounded corners
                                Box(
                                    modifier = Modifier
                                        .fillMaxWidth()
                                        .height(180.dp)
                                        .clip(RoundedCornerShape(20.dp))
                                ) {
                                    AsyncImage(
                                        model = doc.imageUrl,
                                        contentDescription = doc.name,
                                        contentScale = ContentScale.Crop,
                                        modifier = Modifier.fillMaxSize()
                                    )
                                    
                                    // Bookmark button overlay in the top right corner
                                    Box(
                                        modifier = Modifier
                                            .align(Alignment.TopEnd)
                                            .padding(10.dp)
                                            .size(36.dp)
                                            .clip(CircleShape)
                                            .background(Color.White.copy(alpha = 0.9f))
                                            .clickable {
                                                doctorBookmarks = if (isBookmarked) {
                                                    doctorBookmarks - doc.id
                                                } else {
                                                    doctorBookmarks + doc.id
                                                }
                                                val msg = if (isBookmarked) "Removed bookmark for ${doc.name}" else "Bookmarked ${doc.name}!"
                                                Toast.makeText(context, msg, Toast.LENGTH_SHORT).show()
                                            },
                                        contentAlignment = Alignment.Center
                                    ) {
                                        BookmarkIcon(
                                            modifier = Modifier.size(18.dp),
                                            isBookmarked = isBookmarked,
                                            tint = if (isBookmarked) Color(0xFFE01D75) else Color.DarkGray
                                        )
                                    }
                                }
                                
                                Spacer(modifier = Modifier.height(16.dp))

                                // Doctor Name and verified ticks
                                Row(
                                    verticalAlignment = Alignment.CenterVertically,
                                    horizontalArrangement = Arrangement.spacedBy(4.dp)
                                ) {
                                    Text(
                                        text = doc.name,
                                        fontWeight = FontWeight.Bold,
                                        fontSize = 16.sp,
                                        color = Color(0xFF0F172A)
                                    )
                                    Box(
                                        modifier = Modifier
                                            .size(14.dp)
                                            .clip(CircleShape)
                                            .background(Color(0xFF3B82F6)),
                                        contentAlignment = Alignment.Center
                                    ) {
                                        Icon(
                                            imageVector = Icons.Default.Check,
                                            contentDescription = "Verified",
                                            tint = Color.White,
                                            modifier = Modifier.size(10.dp)
                                        )
                                    }
                                }
                                
                                Text(
                                    text = "${doc.speciality} • ${doc.experience}",
                                    fontSize = 12.sp,
                                    color = Color(0xFF687280)
                                )
                                
                                Spacer(modifier = Modifier.height(16.dp))
                                HorizontalDivider(color = Color(0xFFF1F5F9))
                                Spacer(modifier = Modifier.height(8.dp))

                                // Three Columns (Rating, Available on button, Rate)
                                Row(
                                    modifier = Modifier.fillMaxWidth(),
                                    horizontalArrangement = Arrangement.SpaceEvenly,
                                    verticalAlignment = Alignment.CenterVertically
                                ) {
                                    // Column 1: Rating
                                    Column(horizontalAlignment = Alignment.CenterHorizontally) {
                                        Text(
                                            text = "⭐ ${doc.rating}",
                                            fontWeight = FontWeight.ExtraBold,
                                            fontSize = 13.sp,
                                            color = Color(0xFF0F172A)
                                        )
                                        Spacer(modifier = Modifier.height(2.dp))
                                        Text(
                                            text = "Rating",
                                            fontSize = 10.sp,
                                            color = Color(0xFF687280),
                                            fontWeight = FontWeight.Bold
                                        )
                                    }
                                    
                                    // Divider
                                    Box(
                                        modifier = Modifier
                                            .width(1.dp)
                                            .height(24.dp)
                                            .background(Color(0xFFE2E8F0))
                                    )

                                    // Column 2: Available on Button
                                    val isExpanded = expandedAvailabilities.contains(doc.id)
                                    Column(horizontalAlignment = Alignment.CenterHorizontally) {
                                        Box(
                                            modifier = Modifier
                                                .clip(RoundedCornerShape(8.dp))
                                                .background(Color(0xFFF1F5F9))
                                                .clickable {
                                                    expandedAvailabilities = if (isExpanded) {
                                                        expandedAvailabilities - doc.id
                                                    } else {
                                                        expandedAvailabilities + doc.id
                                                    }
                                                }
                                                .padding(horizontal = 10.dp, vertical = 6.dp)
                                        ) {
                                            Row(
                                                verticalAlignment = Alignment.CenterVertically,
                                                horizontalArrangement = Arrangement.spacedBy(2.dp)
                                            ) {
                                                Text(
                                                    text = "Available on",
                                                    fontSize = 11.sp,
                                                    fontWeight = FontWeight.ExtraBold,
                                                    color = themeColor
                                                )
                                                Icon(
                                                    imageVector = if (isExpanded) Icons.Default.KeyboardArrowUp else Icons.Default.KeyboardArrowDown,
                                                    contentDescription = null,
                                                    modifier = Modifier.size(12.dp),
                                                    tint = themeColor
                                                )
                                            }
                                        }
                                        Spacer(modifier = Modifier.height(2.dp))
                                        Text(
                                            text = "Schedule",
                                            fontSize = 10.sp,
                                            color = Color(0xFF687280),
                                            fontWeight = FontWeight.Bold
                                        )
                                    }

                                    // Divider
                                    Box(
                                        modifier = Modifier
                                            .width(1.dp)
                                            .height(24.dp)
                                            .background(Color(0xFFE2E8F0))
                                    )

                                    // Column 3: Rate per Checkup
                                    Column(horizontalAlignment = Alignment.CenterHorizontally) {
                                        Text(
                                            text = "₹${doc.fee}",
                                            fontWeight = FontWeight.ExtraBold,
                                            fontSize = 13.sp,
                                            color = Color(0xFF0F172A)
                                        )
                                        Spacer(modifier = Modifier.height(2.dp))
                                        Text(
                                            text = "Rate/checkup",
                                            fontSize = 10.sp,
                                            color = Color(0xFF687280),
                                            fontWeight = FontWeight.Bold
                                        )
                                    }
                                }

                                // 7 Weeks (Days of Week) Schedule row with glass green highlight
                                AnimatedVisibility(
                                    visible = isExpanded,
                                    enter = expandVertically() + fadeIn(),
                                    exit = shrinkVertically() + fadeOut()
                                ) {
                                    Column(
                                        modifier = Modifier
                                            .fillMaxWidth()
                                            .padding(top = 12.dp)
                                            .background(Color(0xFFF8FAFC), RoundedCornerShape(12.dp))
                                            .border(1.dp, Color(0xFFF1F5F9), RoundedCornerShape(12.dp))
                                            .padding(10.dp)
                                    ) {
                                        Text(
                                            text = "Op Doctor Weekly Schedule:",
                                            fontSize = 11.sp,
                                            fontWeight = FontWeight.Bold,
                                            color = Color(0xFF64748B),
                                            modifier = Modifier.padding(bottom = 6.dp)
                                        )
                                        Row(
                                            modifier = Modifier.fillMaxWidth(),
                                            horizontalArrangement = Arrangement.SpaceBetween,
                                            verticalAlignment = Alignment.CenterVertically
                                        ) {
                                            listOf("Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun").forEach { day ->
                                                val isAvailable = doc.daysAvailable.contains(day)
                                                if (isAvailable) {
                                                    // Glass green highlights
                                                    Box(
                                                        modifier = Modifier
                                                            .weight(1f)
                                                            .padding(horizontal = 2.dp)
                                                            .clip(RoundedCornerShape(8.dp))
                                                            .background(Color(0x3310B981)) // translucent/glass green
                                                            .border(1.2.dp, Color(0xFF10B981), RoundedCornerShape(8.dp))
                                                            .padding(vertical = 6.dp),
                                                        contentAlignment = Alignment.Center
                                                    ) {
                                                        Text(
                                                            text = day,
                                                            fontSize = 11.sp,
                                                            fontWeight = FontWeight.ExtraBold,
                                                            color = Color(0xFF047857) // solid deep green
                                                        )
                                                    }
                                                } else {
                                                    // Faded layout
                                                    Box(
                                                        modifier = Modifier
                                                            .weight(1f)
                                                            .padding(horizontal = 2.dp)
                                                            .clip(RoundedCornerShape(8.dp))
                                                            .background(Color(0xFFE2E8F0))
                                                            .padding(vertical = 6.dp),
                                                        contentAlignment = Alignment.Center
                                                    ) {
                                                        Text(
                                                            text = day,
                                                            fontSize = 11.sp,
                                                            fontWeight = FontWeight.Normal,
                                                            color = Color(0xFF94A3B8)
                                                        )
                                                    }
                                                }
                                            }
                                        }
                                    }
                                }

                                Spacer(modifier = Modifier.height(16.dp))
                                Text(
                                    text = "Select Consultation Timing Slot:",
                                    fontSize = 10.sp,
                                    fontWeight = FontWeight.Black,
                                    color = Color(0xFF687280)
                                )
                                Spacer(modifier = Modifier.height(8.dp))

                                Row(
                                    modifier = Modifier.horizontalScroll(rememberScrollState()),
                                    horizontalArrangement = Arrangement.spacedBy(6.dp)
                                ) {
                                    doc.slots.forEach { slot ->
                                        val isChosen = selectedDoctorName == doc.name && selectedSlot == slot
                                        Box(
                                            modifier = Modifier
                                                .clip(RoundedCornerShape(8.dp))
                                                .background(if (isChosen) themeColor else Color(0xFFF1F5F9))
                                                .clickable {
                                                    selectedDoctorName = doc.name
                                                    selectedSpecialty = doc.speciality
                                                    selectedPrice = doc.fee
                                                    selectedSlot = slot
                                                }
                                                .padding(horizontal = 12.dp, vertical = 8.dp)
                                                .testTag("slot_${doc.name}_${slot}")
                                        ) {
                                            Text(
                                                text = slot,
                                                fontSize = 11.sp,
                                                fontWeight = FontWeight.Bold,
                                                color = if (isChosen) Color.White else Color.DarkGray
                                            )
                                        }
                                    }
                                }

                                Spacer(modifier = Modifier.height(16.dp))

                                // Charcoal primary request booking button (matching B's grey select button)
                                Button(
                                    onClick = {
                                        if (selectedDoctorName == doc.name && selectedSlot.isNotBlank()) {
                                            phase = 3
                                        } else {
                                            Toast.makeText(context, "Please select an available timing slot first!", Toast.LENGTH_SHORT).show()
                                        }
                                    },
                                    modifier = Modifier
                                        .fillMaxWidth()
                                        .height(46.dp)
                                        .testTag("book_slot_${doc.id}"),
                                    colors = ButtonDefaults.buttonColors(containerColor = Color(0xFF475569)),
                                    shape = RoundedCornerShape(12.dp)
                                ) {
                                    Text(
                                        text = "Book Consultation",
                                        color = Color.White,
                                        fontWeight = FontWeight.Bold,
                                        fontSize = 13.sp
                                    )
                                }
                            }
                        }
                    }
                }
            }
            3 -> {
                Column(modifier = Modifier.padding(16.dp).verticalScroll(rememberScrollState())) {
                    Text("Patient File Demographics", fontWeight = FontWeight.Black, fontSize = 15.sp, color = Color(0xFF1E293B))
                    Text("Your slot will be registered directly into $selectedHospName OPD logs", fontSize = 11.sp, color = Color(0xFF687280))
                    Spacer(modifier = Modifier.height(16.dp))
                    
                    OutlinedTextField(
                        value = patientName, 
                        onValueChange = { patientName = it }, 
                        leadingIcon = { Icon(Icons.Default.Person, null, tint = Color(0xFF687280)) },
                        label = { Text("Patient Full Name") }, 
                        placeholder = { Text("As on Passport or Aadhaar") },
                        modifier = Modifier.fillMaxWidth().testTag("app_patient_name"),
                        shape = RoundedCornerShape(12.dp)
                    )
                    Spacer(modifier = Modifier.height(8.dp))
                    OutlinedTextField(
                        value = patientAge, 
                        onValueChange = { patientAge = it }, 
                        label = { Text("Patient Age (Years)") }, 
                        placeholder = { Text("E.g. 34") },
                        modifier = Modifier.fillMaxWidth(),
                        shape = RoundedCornerShape(12.dp)
                    )
                    Spacer(modifier = Modifier.height(16.dp))
                    
                    Text("Select Gender Classification:", fontSize = 11.sp, fontWeight = FontWeight.Bold, color = Color(0xFF687280))
                    Spacer(modifier = Modifier.height(8.dp))
                    Row(modifier = Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.spacedBy(8.dp)) {
                        listOf("Male", "Female", "Other").forEach { g ->
                            val isChosen = patientGender == g
                            Box(
                                modifier = Modifier
                                    .weight(1f)
                                    .clip(RoundedCornerShape(8.dp))
                                    .background(if (isChosen) themeColor.copy(alpha = 0.15f) else Color.White)
                                    .border(1.dp, if (isChosen) themeColor else Color(0xFFE2E8F0), RoundedCornerShape(8.dp))
                                    .clickable { patientGender = g }
                                    .padding(vertical = 10.dp),
                                contentAlignment = Alignment.Center
                            ) {
                                Text(g, fontSize = 11.sp, fontWeight = FontWeight.Bold, color = if (isChosen) themeColor else Color.DarkGray)
                            }
                        }
                    }
                    
                    Spacer(modifier = Modifier.height(16.dp))
                    OutlinedTextField(
                        value = symptoms, 
                        onValueChange = { symptoms = it }, 
                        label = { Text("Brief Symptoms Description") }, 
                        placeholder = { Text("Fever since 2 days, chest tightness, routine care...") },
                        modifier = Modifier
                            .fillMaxWidth()
                            .height(90.dp),
                        shape = RoundedCornerShape(12.dp)
                    )
                    Spacer(modifier = Modifier.height(16.dp))
                    
                    Row(verticalAlignment = Alignment.CenterVertically) {
                        Checkbox(checked = someoneElse, onCheckedChange = { someoneElse = it })
                        Text("Registering slot for my family member", fontSize = 12.sp, fontWeight = FontWeight.SemiBold)
                    }
                    Spacer(modifier = Modifier.height(24.dp))
                    
                    Button(
                        onClick = {
                            if (patientName.isNotBlank() && patientAge.isNotBlank()) {
                                tokenRef = "APT-" + (100000..999999).random()
                                phase = 4
                            }
                        },
                        colors = ButtonDefaults.buttonColors(containerColor = themeColor),
                        shape = RoundedCornerShape(20.dp),
                        modifier = Modifier
                            .fillMaxWidth()
                            .height(48.dp)
                            .testTag("confirm_appt_booking")
                    ) {
                        Text("Book Free OPD Token slot", color = Color.White, fontWeight = FontWeight.Bold)
                    }
                }
            }
            4 -> {
                Column(modifier = Modifier.padding(16.dp).verticalScroll(rememberScrollState()), horizontalAlignment = Alignment.CenterHorizontally) {
                    Card(
                        modifier = Modifier.fillMaxWidth(), 
                        colors = CardDefaults.cardColors(containerColor = Color.White),
                        border = BorderStroke(1.dp, Color(0xFFEFF1F4))
                    ) {
                        Column(modifier = Modifier.padding(16.dp), horizontalAlignment = Alignment.CenterHorizontally) {
                            Text("Official Slot Registered! ✅", fontWeight = FontWeight.Black, fontSize = 18.sp, color = Color(0xFF10B981))
                            Spacer(modifier = Modifier.height(8.dp))
                            Text("Please carry this reference card to skip wait times", fontSize = 11.sp, color = Color(0xFF687280))
                            
                            Spacer(modifier = Modifier.height(16.dp))
                            Text("FREE OPD TOKEN REF COPIED", fontWeight = FontWeight.Bold, fontSize = 10.sp, color = themeColor)
                            Text(tokenRef, fontWeight = FontWeight.Black, color = themeColor, fontSize = 22.sp, letterSpacing = 1.sp)
                            
                            HorizontalDivider(modifier = Modifier.padding(vertical = 12.dp))
                            
                            Row(modifier = Modifier.fillMaxWidth().padding(bottom = 6.dp), horizontalArrangement = Arrangement.SpaceBetween) {
                                Text("Hospital Center", fontSize = 12.sp, color = Color(0xFF687280))
                                Text(selectedHospName, fontSize = 12.sp, fontWeight = FontWeight.Bold, color = Color(0xFF1E293B))
                            }
                            Row(modifier = Modifier.fillMaxWidth().padding(bottom = 6.dp), horizontalArrangement = Arrangement.SpaceBetween) {
                                Text("Specialist Medic", fontSize = 12.sp, color = Color(0xFF687280))
                                Text("$selectedDoctorName ($selectedSpecialty)", fontSize = 12.sp, fontWeight = FontWeight.Bold, color = Color(0xFF1E293B))
                            }
                            Row(modifier = Modifier.fillMaxWidth().padding(bottom = 6.dp), horizontalArrangement = Arrangement.SpaceBetween) {
                                Text("Allocated Session", fontSize = 12.sp, color = Color(0xFF687280))
                                Text("Today, $selectedSlot", fontSize = 12.sp, color = themeColor, fontWeight = FontWeight.Bold)
                            }
                            Row(modifier = Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.SpaceBetween) {
                                Text("Patient", fontSize = 12.sp, color = Color(0xFF687280))
                                Text("$patientName (Age: $patientAge, $patientGender)", fontSize = 12.sp, fontWeight = FontWeight.Bold)
                            }
                            
                            HorizontalDivider(modifier = Modifier.padding(vertical = 12.dp))
                            
                            // Visual simulated barcode for skip-lines checkout lines
                            Canvas(modifier = Modifier.fillMaxWidth().height(40.dp)) {
                                val barcodeWidth = size.width
                                val totalBars = 36
                                var currentX = 0f
                                val barWidth = barcodeWidth / totalBars
                                for (i in 0 until totalBars) {
                                    val isColor = (i * 17) % 3 != 0
                                    if (isColor) {
                                        drawRect(
                                            color = Color.Black,
                                            topLeft = androidx.compose.ui.geometry.Offset(currentX, 0f),
                                            size = androidx.compose.ui.geometry.Size(barWidth - 2f, 30f)
                                        )
                                    }
                                    currentX += barWidth
                                }
                            }
                            Spacer(modifier = Modifier.height(8.dp))
                            Text("SIMULATED BARCODE SCANNER ID", fontSize = 8.sp, color = Color(0xFF687280), fontWeight = FontWeight.Bold)
                        }
                    }
                    
                    Spacer(modifier = Modifier.height(24.dp))
                    Button(
                        onClick = { phase = 1 }, 
                        colors = ButtonDefaults.buttonColors(containerColor = themeColor),
                        shape = RoundedCornerShape(20.dp),
                        modifier = Modifier
                            .fillMaxWidth()
                            .height(48.dp)
                            .testTag("book_another_appt")
                    ) {
                        Text("Register Another Slot", color = Color.White, fontWeight = FontWeight.Bold)
                    }
                    Spacer(modifier = Modifier.height(8.dp))
                    OutlinedButton(
                        onClick = onGoHome, 
                        shape = RoundedCornerShape(20.dp),
                        modifier = Modifier
                            .fillMaxWidth()
                            .height(48.dp)
                            .testTag("go_home_appt")
                    ) {
                        Text("Return to Hub Home", fontWeight = FontWeight.Bold)
                    }
                }
            }
        }
    }
}

// --------------------------------------------------------------------------
// PRINT SCREEN
// --------------------------------------------------------------------------
@Composable
fun PrintDocsScreen(onBack: () -> Unit, onGoHome: () -> Unit, modifier: Modifier = Modifier) {
    var phase by remember { mutableStateOf(1) }
    var fileList by remember { mutableStateOf(mutableListOf("Resume_Final.pdf", "Marksheet_Verified.pdf")) }
    var expandedAdd by remember { mutableStateOf(false) }
    var customFilename by remember { mutableStateOf("") }
    var showCustomInput by remember { mutableStateOf(false) }

    var copies by remember { mutableStateOf(1) }
    var colorMode by remember { mutableStateOf("B&W") }
    var paperSize by remember { mutableStateOf("A4") }
    var isDoubleSided by remember { mutableStateOf(true) }
    var bindingType by remember { mutableStateOf("None") }

    var couponCode by remember { mutableStateOf("") }
    var discountApplied by remember { mutableStateOf(0.0) }
    var showInvoiceDialog by remember { mutableStateOf(false) }
    var orderIdRef by remember { mutableStateOf("PRT-992104") }
    var trackingProgress by remember { mutableStateOf(1) }

    LaunchedEffect(phase) {
        if (phase == 2) {
            trackingProgress = 1
            while (trackingProgress < 4) {
                delay(5000)
                trackingProgress++
            }
        }
    }

    val ctx = LocalContext.current
    val themeColor = Color(0xFFA855F7) // Royal Purple Zepto Style

    fun calculatePageCost(): Int {
        return when {
            colorMode == "B&W" && paperSize == "A4" -> 2
            colorMode == "B&W" && paperSize == "A3" -> 4
            colorMode == "Color" && paperSize == "A4" -> 10
            else -> 18
        }
    }

    fun calculateBindingCost(): Int {
        return when (bindingType) {
            "Staple (+₹5)" -> 5
            "Spiral (+₹30)" -> 30
            else -> 0
        }
    }

    val subtotal = (fileList.size * 3 * copies * calculatePageCost()) + calculateBindingCost()
    val finalTotal = (subtotal - discountApplied).coerceAtLeast(0.0)

    Column(modifier = modifier.fillMaxSize().background(lightBg)) {
        // Adaptable Header
        Row(
            modifier = Modifier
                .fillMaxWidth()
                .background(themeColor)
                .padding(14.dp),
            verticalAlignment = Alignment.CenterVertically
        ) {
            IconButton(onClick = onBack, modifier = Modifier.testTag("print_back")) {
                Icon(Icons.AutoMirrored.Filled.ArrowBack, "Back", tint = Color.White)
            }
            Text("🔮 crowmix SuperPrint Hub", color = Color.White, fontWeight = FontWeight.Black, fontSize = 18.sp)
        }

        when (phase) {
            1 -> {
                Column(modifier = Modifier.padding(16.dp).verticalScroll(rememberScrollState())) {
                    Text("Select PDF/Docs to Print", fontWeight = FontWeight.Black, fontSize = 15.sp, color = Color(0xFF1E293B))
                    Text("Flash instant delivery to Sector 62 Noida in under 20 mins", fontSize = 11.sp, color = Color(0xFF687280))
                    Spacer(modifier = Modifier.height(16.dp))

                    // Simulated Cloud Upload Box with dashed borders representation
                    Box(
                        modifier = Modifier
                            .fillMaxWidth()
                            .clip(RoundedCornerShape(12.dp))
                            .background(Color(0xFFFAF5FF))
                            .border(BorderStroke(1.dp, themeColor), RoundedCornerShape(12.dp))
                            .clickable { expandedAdd = true }
                            .padding(20.dp),
                        contentAlignment = Alignment.Center
                    ) {
                        Column(horizontalAlignment = Alignment.CenterHorizontally) {
                            Text("☁️", fontSize = 38.sp)
                            Spacer(modifier = Modifier.height(8.dp))
                            Text("Click to select files from device", fontWeight = FontWeight.Bold, fontSize = 13.sp, color = themeColor)
                            Text("Supports PDF, DOCX, JPEG up to 40 MB", fontSize = 10.sp, color = Color(0xFF687280))
                            Spacer(modifier = Modifier.height(8.dp))
                            Box(
                                modifier = Modifier
                                    .clip(RoundedCornerShape(20.dp))
                                    .background(themeColor)
                                    .padding(horizontal = 14.dp, vertical = 6.dp)
                            ) {
                                Text("+ Select Documents", fontWeight = FontWeight.Bold, fontSize = 11.sp, color = Color.White)
                            }
                        }
                    }

                    // Native drop down overlay simulation triggers
                    DropdownMenu(expanded = expandedAdd, onDismissRequest = { expandedAdd = false }) {
                        listOf("Aadhar_Card_Front_Back.pdf", "PAN_Card_Verified.pdf", "College_Marksheet_S6.pdf", "Resume_Final_2026.pdf", "Passport_Photo_Digital.png", "Custom filename...").forEach { opt ->
                            DropdownMenuItem(
                                text = { Text(opt, fontSize = 12.sp, fontWeight = FontWeight.Medium) }, 
                                onClick = {
                                    expandedAdd = false
                                    if (opt == "Custom filename...") {
                                        showCustomInput = true
                                    } else {
                                        if (!fileList.contains(opt)) {
                                            fileList.add(opt)
                                            fileList = fileList.toMutableList()
                                        }
                                    }
                                }
                            )
                        }
                    }

                    if (showCustomInput) {
                        Spacer(modifier = Modifier.height(8.dp))
                        Row(modifier = Modifier.fillMaxWidth(), verticalAlignment = Alignment.CenterVertically) {
                            OutlinedTextField(
                                value = customFilename, 
                                onValueChange = { customFilename = it }, 
                                label = { Text("Enter manual filename.pdf") }, 
                                modifier = Modifier.weight(1f).testTag("custom_filename_field"),
                                shape = RoundedCornerShape(12.dp)
                            )
                            Spacer(modifier = Modifier.width(8.dp))
                            Button(
                                onClick = {
                                    if (customFilename.isNotBlank()) {
                                        val fn = if (customFilename.contains(".pdf") || customFilename.contains(".png")) customFilename else "$customFilename.pdf"
                                        fileList.add(fn)
                                        fileList = fileList.toMutableList()
                                        customFilename = ""
                                        showCustomInput = false
                                    }
                                },
                                colors = ButtonDefaults.buttonColors(containerColor = themeColor),
                                shape = RoundedCornerShape(12.dp)
                            ) {
                                Text("Add", color = Color.White)
                            }
                        }
                    }

                    Spacer(modifier = Modifier.height(16.dp))
                    Text("DOCUMENTS LIST READY TO PRINT (${fileList.size})", fontWeight = FontWeight.Black, fontSize = 10.sp, color = Color(0xFF687280))
                    Spacer(modifier = Modifier.height(8.dp))

                    if (fileList.isEmpty()) {
                        Text("No files added yet. Please upload above.", fontSize = 11.sp, color = Color.Red, fontWeight = FontWeight.Bold)
                    }

                    fileList.forEach { f ->
                        Card(
                            modifier = Modifier
                                .fillMaxWidth()
                                .padding(bottom = 6.dp),
                            colors = CardDefaults.cardColors(containerColor = Color.White),
                            border = BorderStroke(1.dp, Color(0xFFF1F5F9))
                        ) {
                            Row(
                                modifier = Modifier.padding(10.dp), 
                                verticalAlignment = Alignment.CenterVertically
                            ) {
                                Text(if (f.endsWith(".png") || f.endsWith(".jpg")) "🖼️" else "📄", fontSize = 22.sp)
                                Spacer(modifier = Modifier.width(10.dp))
                                Column(modifier = Modifier.weight(1f)) {
                                    Text(f, fontSize = 12.sp, fontWeight = FontWeight.Bold, color = Color(0xFF1E293B), maxLines = 1, overflow = TextOverflow.Ellipsis)
                                    Text("Ready to Print • A4 standard 3 pages", fontSize = 10.sp, color = Color(0xFF10B981), fontWeight = FontWeight.Medium)
                                }
                                IconButton(onClick = { 
                                    fileList.remove(f)
                                    fileList = fileList.toMutableList() 
                                }) {
                                    Icon(Icons.Default.Close, "Remove document", tint = Color.Red, modifier = Modifier.size(16.dp))
                                }
                            }
                        }
                    }

                    Spacer(modifier = Modifier.height(16.dp))
                    Text("💡 QUICK PACK PRESETS", fontWeight = FontWeight.Black, fontSize = 10.sp, color = Color(0xFF687280))
                    Spacer(modifier = Modifier.height(8.dp))
                    Row(
                        modifier = Modifier.fillMaxWidth().horizontalScroll(rememberScrollState()),
                        horizontalArrangement = Arrangement.spacedBy(8.dp)
                    ) {
                        listOf(
                            Triple("Thesis Print pack 📚", "B&W / A4", { copies = 1; colorMode = "B&W"; paperSize = "A4"; isDoubleSided = true; bindingType = "Spiral (+₹30)" }),
                            Triple("Identity copy 🪪", "Color / Single-sided", { copies = 1; colorMode = "Color"; paperSize = "A4"; isDoubleSided = false; bindingType = "None" }),
                            Triple("Resume Batch 💼", "Color / Premium", { copies = 5; colorMode = "Color"; paperSize = "A4"; isDoubleSided = true; bindingType = "Staple (+₹5)" })
                        ).forEach { (label, sub, action) ->
                            Box(
                                modifier = Modifier
                                    .clip(RoundedCornerShape(12.dp))
                                    .background(Color.White)
                                    .border(1.dp, Color(0xFFE2E8F0), RoundedCornerShape(12.dp))
                                    .clickable { action() }
                                    .padding(horizontal = 12.dp, vertical = 8.dp)
                            ) {
                                Column {
                                    Text(label, fontSize = 11.sp, fontWeight = FontWeight.Bold, color = Color(0xFF1E293B))
                                    Text(sub, fontSize = 9.sp, color = Color(0xFF687280))
                                }
                            }
                        }
                    }

                    Spacer(modifier = Modifier.height(16.dp))
                    Text("PRINT CONFIGURATION OPTIONS", fontWeight = FontWeight.Black, fontSize = 10.sp, color = Color(0xFF687280))
                    Spacer(modifier = Modifier.height(8.dp))

                    // Copies Stepper Selector
                    Row(
                        verticalAlignment = Alignment.CenterVertically, 
                        modifier = Modifier.fillMaxWidth().background(Color.White).padding(10.dp).clip(RoundedCornerShape(8.dp)), 
                        horizontalArrangement = Arrangement.SpaceBetween
                    ) {
                        Text("Print Copies Size:", fontSize = 12.sp, fontWeight = FontWeight.Bold, color = Color.DarkGray)
                        Row(verticalAlignment = Alignment.CenterVertically) {
                            IconButton(onClick = { if (copies > 1) copies-- }) {
                                Text("-", fontWeight = FontWeight.Black, fontSize = 24.sp, color = themeColor)
                            }
                            Text(copies.toString(), modifier = Modifier.padding(horizontal = 16.dp), fontWeight = FontWeight.Black, fontSize = 16.sp, color = Color.Black)
                            IconButton(onClick = { copies++ }) {
                                Text("+", fontWeight = FontWeight.Black, fontSize = 20.sp, color = themeColor)
                            }
                        }
                    }

                    Spacer(modifier = Modifier.height(8.dp))
                    // Color scheme row selector options
                    Row(modifier = Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.spacedBy(8.dp)) {
                        listOf("B&W", "Color").forEach { mode ->
                            val active = colorMode == mode
                            Box(
                                modifier = Modifier
                                    .weight(1f)
                                    .clip(RoundedCornerShape(10.dp))
                                    .background(if (active) themeColor.copy(alpha = 0.15f) else Color.White)
                                    .border(1.dp, if (active) themeColor else Color(0xFFE2E8F0), RoundedCornerShape(10.dp))
                                    .clickable { colorMode = mode }
                                    .padding(12.dp),
                                contentAlignment = Alignment.Center
                            ) {
                                Text(if (mode == "Color") "🌈 Colour premium" else "🩶 Black & White", fontSize = 12.sp, fontWeight = FontWeight.Bold, color = if (active) themeColor else Color.DarkGray)
                            }
                        }
                    }

                    Spacer(modifier = Modifier.height(8.dp))
                    // Paper sizes selection
                    Row(modifier = Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.spacedBy(8.dp)) {
                        listOf("A4", "A3").forEach { size ->
                            val active = paperSize == size
                            Box(
                                modifier = Modifier
                                    .weight(1f)
                                    .clip(RoundedCornerShape(10.dp))
                                    .background(if (active) themeColor.copy(alpha = 0.15f) else Color.White)
                                    .border(1.dp, if (active) themeColor else Color(0xFFE2E8F0), RoundedCornerShape(10.dp))
                                    .clickable { paperSize = size }
                                    .padding(10.dp),
                                contentAlignment = Alignment.Center
                            ) {
                                Text("Paper Size: $size", fontSize = 11.sp, fontWeight = FontWeight.Bold, color = if (active) themeColor else Color.DarkGray)
                            }
                        }
                    }

                    Spacer(modifier = Modifier.height(8.dp))
                    // Single vs Double sided page configurations
                    Row(modifier = Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.spacedBy(8.dp)) {
                        listOf("Double-sided", "Single-sided").forEach { side ->
                            val selectedVal = isDoubleSided == (side == "Double-sided")
                            Box(
                                modifier = Modifier
                                    .weight(1f)
                                    .clip(RoundedCornerShape(10.dp))
                                    .background(if (selectedVal) themeColor.copy(alpha = 0.15f) else Color.White)
                                    .border(1.dp, if (selectedVal) themeColor else Color(0xFFE2E8F0), RoundedCornerShape(10.dp))
                                    .clickable { isDoubleSided = (side == "Double-sided") }
                                    .padding(10.dp),
                                contentAlignment = Alignment.Center
                            ) {
                                Text(if (side == "Double-sided") "🔄 Front & Back" else "📄 Single Side", fontSize = 11.sp, fontWeight = FontWeight.Bold, color = if (selectedVal) themeColor else Color.DarkGray)
                            }
                        }
                    }

                    Spacer(modifier = Modifier.height(16.dp))
                    Text("BINDING REQUIREMENT", fontWeight = FontWeight.Black, fontSize = 10.sp, color = Color(0xFF687280))
                    Spacer(modifier = Modifier.height(8.dp))
                    Row(modifier = Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.spacedBy(6.dp)) {
                        listOf("None", "Staple (+₹5)", "Spiral (+₹30)").forEach { binding ->
                            val active = bindingType == binding
                            Box(
                                modifier = Modifier
                                    .weight(1f)
                                    .clip(RoundedCornerShape(8.dp))
                                    .background(if (active) themeColor.copy(alpha = 0.15f) else Color.White)
                                    .border(1.dp, if (active) themeColor else Color(0xFFE2E8F0), RoundedCornerShape(8.dp))
                                    .clickable { bindingType = binding }
                                    .padding(10.dp),
                                contentAlignment = Alignment.Center
                            ) {
                                Text(binding, fontSize = 10.sp, fontWeight = FontWeight.Bold, color = if (active) themeColor else Color.DarkGray)
                            }
                        }
                    }

                    Spacer(modifier = Modifier.height(16.dp))

                    // Coupon codes input
                    Row(modifier = Modifier.fillMaxWidth(), verticalAlignment = Alignment.CenterVertically) {
                        OutlinedTextField(
                            value = couponCode, 
                            onValueChange = { couponCode = it }, 
                            label = { Text("Have a Printing Coupon?") }, 
                            placeholder = { Text("E.g. PRINT20 to save ₹20") },
                            modifier = Modifier.weight(1f).testTag("print_coupon"),
                            shape = RoundedCornerShape(12.dp)
                        )
                        Spacer(modifier = Modifier.width(8.dp))
                        Button(
                            onClick = {
                                val cleanCode = couponCode.uppercase().trim()
                                if (cleanCode == "PRINT20") {
                                    discountApplied = 20.0
                                    Toast.makeText(ctx, "Coupon PRINT20 applied. Saving ₹20!", Toast.LENGTH_SHORT).show()
                                } else if (cleanCode == "DOCS15") {
                                    discountApplied = 15.0
                                    Toast.makeText(ctx, "Coupon DOCS15 applied. Saving ₹15!", Toast.LENGTH_SHORT).show()
                                } else {
                                    discountApplied = 0.0
                                    Toast.makeText(ctx, "Invalid Coupon! Try: PRINT20 or DOCS15", Toast.LENGTH_SHORT).show()
                                }
                            },
                            colors = ButtonDefaults.buttonColors(containerColor = Color(0xFF1E293B)),
                            shape = RoundedCornerShape(12.dp)
                        ) {
                            Text("Apply", color = Color.White)
                        }
                    }

                    Spacer(modifier = Modifier.height(16.dp))
                    // Summary billing estimates Card
                    Card(
                        modifier = Modifier.fillMaxWidth(), 
                        colors = CardDefaults.cardColors(containerColor = Color.White),
                        border = BorderStroke(1.dp, Color(0xFFF1F5F9))
                    ) {
                        Column(modifier = Modifier.padding(16.dp)) {
                            Text("DETAILED COST ESTIMATE", fontWeight = FontWeight.Black, fontSize = 11.sp, color = Color(0xFF687280))
                            HorizontalDivider(modifier = Modifier.padding(vertical = 10.dp))
                            
                            Row(modifier = Modifier.fillMaxWidth().padding(bottom = 4.dp), horizontalArrangement = Arrangement.SpaceBetween) {
                                Text("Page Printing subtotal (${fileList.size} files, $copies copies)", fontSize = 11.sp, color = Color.DarkGray)
                                Text("₹${(fileList.size * 3 * copies * calculatePageCost())}", fontSize = 11.sp, fontWeight = FontWeight.Bold)
                            }
                            Row(modifier = Modifier.fillMaxWidth().padding(bottom = 4.dp), horizontalArrangement = Arrangement.SpaceBetween) {
                                Text("Finishing Binding style cost ($bindingType)", fontSize = 11.sp, color = Color.DarkGray)
                                Text("₹${calculateBindingCost()}", fontSize = 11.sp, fontWeight = FontWeight.Bold)
                            }
                            if (discountApplied > 0) {
                                Row(modifier = Modifier.fillMaxWidth().padding(bottom = 4.dp), horizontalArrangement = Arrangement.SpaceBetween) {
                                    Text("Printing Promo voucher savings", fontSize = 11.sp, color = Color(0xFFEF4444))
                                    Text("-₹$discountApplied", fontSize = 11.sp, color = Color(0xFFEF4444), fontWeight = FontWeight.Bold)
                                }
                            }
                            HorizontalDivider(modifier = Modifier.padding(vertical = 8.dp))
                            Row(
                                modifier = Modifier
                                    .fillMaxWidth()
                                    .background(Color(0xFFFAF5FF))
                                    .padding(10.dp), 
                                horizontalArrangement = Arrangement.SpaceBetween,
                                verticalAlignment = Alignment.CenterVertically
                            ) {
                                Text("Total Calculated Estimate GST incl", fontWeight = FontWeight.ExtraBold, color = themeColor, fontSize = 13.sp)
                                Text("₹$finalTotal", fontWeight = FontWeight.Black, fontSize = 18.sp, color = themeColor)
                            }
                        }
                    }

                    Spacer(modifier = Modifier.height(24.dp))
                    Button(
                        onClick = { 
                            if (fileList.isNotEmpty()) {
                                orderIdRef = "PRT-" + (100000..999999).random()
                                phase = 2 
                            } else {
                                Toast.makeText(ctx, "Please add at least one file to print", Toast.LENGTH_SHORT).show()
                            }
                        },
                        modifier = Modifier
                            .fillMaxWidth()
                            .height(52.dp)
                            .testTag("place_print_btn"),
                        shape = RoundedCornerShape(14.dp),
                        colors = ButtonDefaults.buttonColors(containerColor = Color.Transparent),
                        contentPadding = PaddingValues(0.dp)
                    ) {
                        Box(
                            modifier = Modifier
                                .fillMaxSize()
                                .background(Brush.horizontalGradient(listOf(Color(0xFF7C3AED), Color(0xFFA855F7)))),
                            contentAlignment = Alignment.Center
                        ) {
                            Text("PLACE INSTANT PRINT ORDER", color = Color.White, fontWeight = FontWeight.Black, fontSize = 13.sp)
                        }
                    }
                }
            }
            2 -> {
                // Tracking page same like Zepto
                Column(modifier = Modifier.padding(16.dp).verticalScroll(rememberScrollState()), horizontalAlignment = Alignment.CenterHorizontally) {
                    Card(
                        modifier = Modifier.fillMaxWidth(), 
                        colors = CardDefaults.cardColors(containerColor = Color.White),
                        border = BorderStroke(1.dp, Color(0xFFFAF5FF))
                    ) {
                        Column(modifier = Modifier.padding(16.dp)) {
                            Row(
                                modifier = Modifier.fillMaxWidth(),
                                horizontalArrangement = Arrangement.SpaceBetween,
                                verticalAlignment = Alignment.CenterVertically
                            ) {
                                Column {
                                    Text("⚡ SUPERPRINT IN TRANSIT", fontWeight = FontWeight.Black, color = themeColor, fontSize = 12.sp)
                                    Text("Arriving in Sector 62 Noida in 12 mins", fontSize = 11.sp, color = Color(0xFF687280))
                                }
                                Box(
                                    modifier = Modifier
                                        .clip(RoundedCornerShape(8.dp))
                                        .background(Color(0xFFFFFAEB))
                                        .padding(horizontal = 8.dp, vertical = 4.dp)
                                ) {
                                    Text(orderIdRef, fontWeight = FontWeight.Bold, fontSize = 10.sp, color = Color(0xFFD97706))
                                }
                            }
                            HorizontalDivider(modifier = Modifier.padding(vertical = 12.dp))
                            Text("Print documents package details:", fontSize = 11.sp, fontWeight = FontWeight.Black, color = Color(0xFF687280))
                            Text("Files: ${fileList.joinToString(", ")}", fontSize = 12.sp, color = Color.DarkGray, fontWeight = FontWeight.Bold)
                            Text("Layout specs: Color is $colorMode ($paperSize paper size)", fontSize = 11.sp, color = Color.DarkGray)
                            Text("Finishing Bind style: $bindingType", fontSize = 11.sp, color = Color.DarkGray)
                            
                            Spacer(modifier = Modifier.height(16.dp))
                            
                            // Download Detailed Tax Bill Button (Explicitly requested!)
                            Button(
                                onClick = { showInvoiceDialog = true },
                                colors = ButtonDefaults.buttonColors(containerColor = Color(0xFF1E293B)),
                                modifier = Modifier.fillMaxWidth(),
                                shape = RoundedCornerShape(12.dp)
                            ) {
                                Text("📄 Download & View Detailed Bill", fontWeight = FontWeight.Bold, fontSize = 12.sp, color = Color.White)
                            }
                        }
                    }

                    Spacer(modifier = Modifier.height(24.dp))
                    Text("CROWMIX DELIVERY STATUS TRACKING FEED", fontWeight = FontWeight.Black, fontSize = 13.sp, color = Color(0xFF1E293B))
                    Spacer(modifier = Modifier.height(16.dp))
                    
                    listOf(
                        "Order Received & Verified 🔵" to 1,
                        "Laser Jet Printing in progress 🟡" to 2,
                        "In spiral finishing room 🟠" to 3,
                        "Out for instant delivery with crowmix Rider ✅" to 4
                    ).forEach { (step, idx) ->
                        val active = trackingProgress >= idx
                        Row(
                            modifier = Modifier
                                .fillMaxWidth()
                                .padding(vertical = 8.dp),
                            verticalAlignment = Alignment.CenterVertically
                        ) {
                            Box(
                                modifier = Modifier
                                    .size(16.dp)
                                    .background(if (active) themeColor else Color(0xFF9CA3AF), CircleShape)
                            )
                            Spacer(modifier = Modifier.width(12.dp))
                            Text(
                                text = step, 
                                fontWeight = if (active) FontWeight.Bold else FontWeight.Normal,
                                color = if (active) Color(0xFF1E293B) else Color(0xFF687280),
                                fontSize = 12.sp
                            )
                        }
                    }

                    Spacer(modifier = Modifier.height(30.dp))
                    Button(
                        onClick = { phase = 1 }, 
                        modifier = Modifier
                            .fillMaxWidth()
                            .height(52.dp)
                            .testTag("print_again_btn"),
                        shape = RoundedCornerShape(14.dp),
                        colors = ButtonDefaults.buttonColors(containerColor = Color.Transparent),
                        contentPadding = PaddingValues(0.dp)
                    ) {
                        Box(
                            modifier = Modifier
                                .fillMaxSize()
                                .background(Brush.horizontalGradient(listOf(Color(0xFF7C3AED), Color(0xFFA855F7)))),
                            contentAlignment = Alignment.Center
                        ) {
                            Text("Print Another Batch", color = Color.White, fontWeight = FontWeight.Bold)
                        }
                    }
                    Spacer(modifier = Modifier.height(8.dp))
                    OutlinedButton(
                        onClick = onGoHome, 
                        modifier = Modifier
                            .fillMaxWidth()
                            .height(48.dp)
                            .testTag("go_home_print"),
                        shape = RoundedCornerShape(20.dp)
                    ) {
                        Text("Return to Hub Home", fontWeight = FontWeight.Bold)
                    }
                }
            }
        }
    }

    // TAX BILL DETAILED INVOICE OVERLAY DIALOGUE
    if (showInvoiceDialog) {
        AlertDialog(
            onDismissRequest = { showInvoiceDialog = false },
            title = {
                Row(verticalAlignment = Alignment.CenterVertically) {
                    Text("🧾 OFFICIAL TAX INVOICE", fontWeight = FontWeight.ExtraBold, fontSize = 14.sp, color = Color.Black)
                }
            },
            text = {
                Column(modifier = Modifier.fillMaxWidth().verticalScroll(rememberScrollState())) {
                    Text("CROWMIX QUICK-PRINT PRIVATE LTD.", fontWeight = FontWeight.Bold, fontSize = 12.sp)
                    Text("GSTIN: 09AAPCZ1293K1Z2", fontSize = 10.sp, color = Color(0xFF687280))
                    Text("Sector 62 Cluster hub warehouse Noida", fontSize = 10.sp, color = Color(0xFF687280))
                    Text("Order Date: 11th June 2026", fontSize = 10.sp, color = Color(0xFF687280))
                    Text("Order Ref: $orderIdRef", fontSize = 10.sp, color = Color(0xFF687280))
                    
                    HorizontalDivider(modifier = Modifier.padding(vertical = 10.dp))
                    
                    fileList.forEach { fl ->
                        Row(modifier = Modifier.fillMaxWidth().padding(vertical = 2.dp), horizontalArrangement = Arrangement.SpaceBetween) {
                            Text(fl, fontSize = 10.sp, modifier = Modifier.weight(1f), maxLines = 1, overflow = TextOverflow.Ellipsis)
                            Text("3 pages x $copies c", fontSize = 10.sp, color = Color(0xFF687280))
                        }
                    }
                    
                    Row(modifier = Modifier.fillMaxWidth().padding(vertical = 2.dp), horizontalArrangement = Arrangement.SpaceBetween) {
                        Text("Finishing Class: $bindingType", fontSize = 10.sp)
                        Text("₹${calculateBindingCost()}", fontSize = 10.sp, fontWeight = FontWeight.Bold)
                    }

                    HorizontalDivider(modifier = Modifier.padding(vertical = 8.dp))
                    
                    Row(modifier = Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.SpaceBetween) {
                        Text("Subtotal:", fontSize = 11.sp, color = Color.DarkGray)
                        Text("₹$subtotal", fontSize = 11.sp, fontWeight = FontWeight.SemiBold)
                    }
                    Row(modifier = Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.SpaceBetween) {
                        Text("Packs Coupon savings:", fontSize = 11.sp, color = Color(0xFFEF4444))
                        Text("-₹$discountApplied", fontSize = 11.sp, color = Color(0xFFEF4444))
                    }
                    Row(modifier = Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.SpaceBetween) {
                        Text("CGST @ 9%:", fontSize = 10.sp, color = Color(0xFF687280))
                        val cgst = finalTotal * 0.09
                        Text("₹%.2f".format(cgst), fontSize = 10.sp, color = Color(0xFF687280))
                    }
                    Row(modifier = Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.SpaceBetween) {
                        Text("SGST @ 9%:", fontSize = 10.sp, color = Color(0xFF687280))
                        val sgst = finalTotal * 0.09
                        Text("₹%.2f".format(sgst), fontSize = 10.sp, color = Color(0xFF687280))
                    }
                    
                    HorizontalDivider(modifier = Modifier.padding(vertical = 8.dp))
                    
                    Row(
                        modifier = Modifier
                            .fillMaxWidth()
                            .background(Color(0xFFF1F5F9))
                            .padding(6.dp),
                        horizontalArrangement = Arrangement.SpaceBetween
                    ) {
                        Text("Net Billed (GST Incl):", fontWeight = FontWeight.Black, fontSize = 12.sp, color = Color.Black)
                        Text("₹$finalTotal", fontWeight = FontWeight.Black, fontSize = 13.sp, color = themeColor)
                    }
                }
            },
            confirmButton = {
                Button(
                    onClick = {
                        showInvoiceDialog = false
                        Toast.makeText(ctx, "📥 Invoice PDF has been exported of size 42kb inside /Downloads/Invoice_$orderIdRef.pdf", Toast.LENGTH_LONG).show()
                    },
                    modifier = Modifier.height(48.dp),
                    shape = RoundedCornerShape(14.dp),
                    colors = ButtonDefaults.buttonColors(containerColor = Color.Transparent),
                    contentPadding = PaddingValues(0.dp)
                ) {
                    Box(
                        modifier = Modifier
                            .fillMaxHeight()
                            .background(Brush.horizontalGradient(listOf(Color(0xFF7C3AED), Color(0xFFA855F7))))
                            .padding(horizontal = 16.dp),
                        contentAlignment = Alignment.Center
                    ) {
                        Text("Download PDF Invoice", color = Color.White, fontWeight = FontWeight.Bold)
                    }
                }
            },
            dismissButton = {
                TextButton(onClick = { showInvoiceDialog = false }) {
                    Text("Close", color = Color.DarkGray)
                }
            }
        )
    }
}

// --------------------------------------------------------------------------
// BUS TICKET SCREEN
// --------------------------------------------------------------------------
@Composable
fun BusTicketScreen(onBack: () -> Unit, onGoHome: () -> Unit, modifier: Modifier = Modifier) {
    var phase by remember { mutableStateOf(1) }
    var fromCity by remember { mutableStateOf("Delhi NCR") }
    var toCity by remember { mutableStateOf("Jaipur") }
    var dateVal by remember { mutableStateOf("15-06-2026") }

    var selectedBusName by remember { mutableStateOf("") }
    var selectedSeats = remember { mutableStateListOf<String>() }
    var boardingPoint by remember { mutableStateOf("Noida Sector 62 Bus Stand — 05:45 AM") }
    var droppingPoint by remember { mutableStateOf("Sindhi Camp (Main Bus Stand) — 12:10 PM") }
    var seatStep by remember { mutableStateOf("Seats") } // Seats | Stops | Passengers

    val passengerNames = remember { mutableStateMapOf<String, String>() }
    val passengerAges = remember { mutableStateMapOf<String, String>() }
    val passengerGenders = remember { mutableStateMapOf<String, String>() }

    var ticketRef by remember { mutableStateOf("") }
    val context = LocalContext.current

    Column(modifier = modifier.fillMaxSize().background(lightBg)) {
        Box(
            modifier = Modifier
                .fillMaxWidth()
                .background(
                    Brush.verticalGradient(
                        colors = listOf(Color(0xFF1A3BBF), Color(0xFF1A56DB))
                    )
                )
                .padding(horizontal = 16.dp, vertical = 14.dp)
        ) {
            Row(verticalAlignment = Alignment.CenterVertically) {
                IconButton(onClick = onBack, modifier = Modifier.testTag("bus_back")) {
                    Icon(Icons.AutoMirrored.Filled.ArrowBack, "Back", tint = Color.White)
                }
                Text("Book Bus Ticket 🎟️", color = Color.White, fontWeight = FontWeight.Bold, fontSize = 18.sp)
            }
        }

        when (phase) {
            1 -> {
                Column(modifier = Modifier.padding(16.dp).verticalScroll(rememberScrollState())) {
                    Text("Search Bus Options", fontWeight = FontWeight.Bold)
                    Spacer(modifier = Modifier.height(8.dp))
                    OutlinedTextField(value = fromCity, onValueChange = { fromCity = it }, label = { Text("From") }, modifier = Modifier.fillMaxWidth().testTag("bus_from"))
                    IconButton(onClick = { val tmp = fromCity; fromCity = toCity; toCity = tmp }, modifier = Modifier.align(Alignment.CenterHorizontally)) {
                        Text("⇄", fontSize = 24.sp, fontWeight = FontWeight.Bold)
                    }
                    OutlinedTextField(value = toCity, onValueChange = { toCity = it }, label = { Text("To") }, modifier = Modifier.fillMaxWidth().testTag("bus_to"))
                    Spacer(modifier = Modifier.height(8.dp))
                    OutlinedTextField(value = dateVal, onValueChange = { dateVal = it }, label = { Text("Date") }, modifier = Modifier.fillMaxWidth())

                    Spacer(modifier = Modifier.height(24.dp))
                    Button(onClick = { phase = 2 }, modifier = Modifier.fillMaxWidth().height(48.dp).testTag("search_buses"), colors = ButtonDefaults.buttonColors(containerColor = crowmixBlue)) {
                        Text("Search Buses", color = Color.White)
                    }
                }
            }
            2 -> {
                if (selectedBusName.isBlank()) {
                    Column(modifier = Modifier.padding(16.dp).verticalScroll(rememberScrollState())) {
                        Text("Buses from $fromCity to $toCity", fontWeight = FontWeight.Bold)
                        Spacer(modifier = Modifier.height(16.dp))
                        listOf(
                            Triple("Rajasthan Roadways Express", 650, "Sleeper AC • ⭐ 4.5 • Dep: 06:00 AM"),
                            Triple("VRL Travels Volvo", 450, "Semi-Sleeper • ⭐ 4.3 • Dep: 09:15 AM"),
                            Triple("IntrCity SmartBus", 380, "Sleeper Non-AC • ⭐ 4.1 • Dep: 11:30 PM")
                        ).forEach { (b, fare, d) ->
                            Card(modifier = Modifier.fillMaxWidth().padding(bottom = 10.dp).clickable { selectedBusName = b }.testTag("bus_card_${b.substringBefore(" ")}"), colors = CardDefaults.cardColors(containerColor = Color.White)) {
                                Column(modifier = Modifier.padding(12.dp)) {
                                    Text(b, fontWeight = FontWeight.Bold)
                                    Text(d, fontSize = 11.sp, color = Color(0xFF687280))
                                    Text("Fare: ₹$fare / seat", fontWeight = FontWeight.Bold, color = crowmixBlue, fontSize = 12.sp)
                                }
                            }
                        }
                    }
                } else {
                    // Config deck, boarding details
                    Column(modifier = Modifier.fillMaxSize()) {
                        TabRow(selectedTabIndex = if (seatStep == "Seats") 0 else if (seatStep == "Stops") 1 else 2) {
                            Tab(selected = seatStep == "Seats", onClick = { seatStep = "Seats" }, text = { Text("Seats") })
                            Tab(selected = seatStep == "Stops", onClick = { seatStep = "Stops" }, text = { Text("Stops") })
                            Tab(selected = seatStep == "Passengers", onClick = { seatStep = "Passengers" }, text = { Text("Passengers") })
                        }
                        Column(modifier = Modifier.padding(16.dp).weight(1f).verticalScroll(rememberScrollState())) {
                            when (seatStep) {
                                "Seats" -> {
                                    Text("Choose Deck Seats (Max 6):", fontWeight = FontWeight.Bold)
                                    Spacer(modifier = Modifier.height(8.dp))
                                    // 5x4 Grid Simulation
                                    Column(verticalArrangement = Arrangement.spacedBy(8.dp)) {
                                        for (row in 1..5) {
                                            Row(horizontalArrangement = Arrangement.spacedBy(8.dp)) {
                                                for (col in 1..4) {
                                                    val seatName = "${'A' + (row - 1)}$col"
                                                    val isSelected = selectedSeats.contains(seatName)
                                                    val isBooked = (row == 2 && col == 1) || (row == 4 && col == 3) // Fake Booked
                                                    val isLadies = (row == 3 && col == 2) // Ladies reserved
                                                    Box(
                                                        modifier = Modifier
                                                            .size(36.dp)
                                                            .clip(RoundedCornerShape(6.dp))
                                                            .background(if (isBooked) Color(0xFF687280) else if (isSelected) Color.Green else if (isLadies) Color(0xFFF472B6) else Color.White)
                                                            .border(1.dp, Color(0xFF9CA3AF))
                                                            .clickable(enabled = !isBooked) {
                                                                if (isSelected) {
                                                                    selectedSeats.remove(seatName)
                                                                } else {
                                                                    if (selectedSeats.size < 6) selectedSeats.add(seatName)
                                                                }
                                                            }
                                                            .testTag("seat_$seatName"),
                                                        contentAlignment = Alignment.Center
                                                    ) {
                                                        Text(seatName, fontSize = 10.sp, fontWeight = FontWeight.Bold, color = if (isBooked || isSelected || isLadies) Color.White else Color.Black)
                                                    }
                                                }
                                            }
                                        }
                                    }
                                    Spacer(modifier = Modifier.height(16.dp))
                                    Text("Seats Selected: ${selectedSeats.joinToString(", ")}", fontWeight = FontWeight.Bold)
                                    Button(onClick = { if (selectedSeats.isNotEmpty()) seatStep = "Stops" }, modifier = Modifier.fillMaxWidth().testTag("next_stops")) {
                                        Text("Next: Choose Stops →")
                                    }
                                }
                                "Stops" -> {
                                    Text("Boarding Point:", fontWeight = FontWeight.Bold)
                                    listOf("Noida Sector 62 Bus Stand — 05:45 AM", "Noida City Center Metro — 05:55 AM", "Mayur Vihar Phase 1 — 06:10 AM").forEach { boarding ->
                                        Row(modifier = Modifier.fillMaxWidth().clickable { boardingPoint = boarding }.padding(8.dp), verticalAlignment = Alignment.CenterVertically) {
                                            RadioButton(selected = boardingPoint == boarding, onClick = { boardingPoint = boarding })
                                            Text(boarding, fontSize = 12.sp)
                                        }
                                    }
                                    Spacer(modifier = Modifier.height(16.dp))
                                    Text("Dropping Point:", fontWeight = FontWeight.Bold)
                                    listOf("Sindhi Camp (Main Bus Stand) — 12:10 PM", "Jaipur Railway Station — 12:20 PM", "Malviya Nagar Depot — 12:35 PM").forEach { dropping ->
                                        Row(modifier = Modifier.fillMaxWidth().clickable { droppingPoint = dropping }.padding(8.dp), verticalAlignment = Alignment.CenterVertically) {
                                            RadioButton(selected = droppingPoint == dropping, onClick = { droppingPoint = dropping })
                                            Text(dropping, fontSize = 12.sp)
                                        }
                                    }
                                    Spacer(modifier = Modifier.height(16.dp))
                                    Button(onClick = { seatStep = "Passengers" }, modifier = Modifier.fillMaxWidth().testTag("next_passengers")) {
                                        Text("Next: Passenger Details →")
                                    }
                                }
                                "Passengers" -> {
                                    Text("Passenger Details", fontWeight = FontWeight.Bold)
                                    selectedSeats.forEach { seat ->
                                        Card(modifier = Modifier.fillMaxWidth().padding(top = 8.dp), colors = CardDefaults.cardColors(containerColor = Color.White)) {
                                            Column(modifier = Modifier.padding(10.dp)) {
                                                Text("Seat $seat Passenger Details", fontWeight = FontWeight.Bold, color = crowmixBlue, fontSize = 12.sp)
                                                OutlinedTextField(
                                                    value = passengerNames[seat] ?: "",
                                                    onValueChange = { passengerNames[seat] = it },
                                                    label = { Text("Passenger Name") },
                                                    modifier = Modifier.fillMaxWidth().testTag("passenger_name_$seat")
                                                )
                                                OutlinedTextField(
                                                    value = passengerAges[seat] ?: "",
                                                    onValueChange = { passengerAges[seat] = it },
                                                    label = { Text("Passenger Age") },
                                                    modifier = Modifier.fillMaxWidth()
                                                )
                                            }
                                        }
                                    }
                                    Spacer(modifier = Modifier.height(16.dp))
                                    Button(
                                        onClick = { if (selectedSeats.all { passengerNames[it]?.isNotBlank() == true }) phase = 3 },
                                        modifier = Modifier.fillMaxWidth().testTag("go_to_confirm_pay"),
                                        colors = ButtonDefaults.buttonColors(containerColor = crowmixBlue)
                                    ) {
                                        Text("Proceed to Confirm →")
                                    }
                                }
                            }
                        }
                    }
                }
            }
            3 -> {
                // Confirm full fare details
                val rate = if (selectedBusName.contains("Roadways")) 650 else if (selectedBusName.contains("VRL")) 450 else 380
                val priceTotal = selectedSeats.size * rate
                Column(modifier = Modifier.padding(16.dp).verticalScroll(rememberScrollState())) {
                    Text("Review Booking Summary", fontWeight = FontWeight.Bold, fontSize = 16.sp)
                    Card(modifier = Modifier.fillMaxWidth().padding(top = 10.dp), colors = CardDefaults.cardColors(containerColor = Color.White)) {
                        Column(modifier = Modifier.padding(14.dp)) {
                            Text(selectedBusName, fontWeight = FontWeight.Bold, color = crowmixBlue)
                            Text("Seats Saved: ${selectedSeats.joinToString(", ")}", fontSize = 12.sp)
                            Text("Boarding: $boardingPoint", fontSize = 11.sp)
                            Text("Dropping: $droppingPoint", fontSize = 11.sp)
                            Text("Journey Date: $dateVal", fontSize = 12.sp, fontWeight = FontWeight.Bold)
                            Spacer(modifier = Modifier.height(8.dp))
                            Text("Passengers registered:", fontWeight = FontWeight.Bold, fontSize = 12.sp)
                            selectedSeats.forEach { s ->
                                Text("• Seat $s: ${passengerNames[s]} (${passengerAges[s]} yrs)", fontSize = 11.sp)
                            }
                            HorizontalDivider(modifier = Modifier.padding(vertical = 12.dp))
                            Row(modifier = Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.SpaceBetween) {
                                Text("Total Fare Payable", fontWeight = FontWeight.Bold)
                                Text("₹$priceTotal", fontWeight = FontWeight.Bold, color = Color.Green, fontSize = 16.sp)
                            }
                        }
                    }
                    Spacer(modifier = Modifier.height(24.dp))
                    Button(
                        onClick = { ticketRef = "BUS-" + (100000..999999).random(); phase = 4 },
                        modifier = Modifier.fillMaxWidth().height(48.dp).testTag("confirm_bus_pay_btn"),
                        colors = ButtonDefaults.buttonColors(containerColor = crowmixBlue)
                    ) {
                        Text("Confirm & Pay ₹$priceTotal", color = Color.White)
                    }
                }
            }
            4 -> {
                Column(modifier = Modifier.padding(16.dp), horizontalAlignment = Alignment.CenterHorizontally) {
                    Card(modifier = Modifier.fillMaxWidth(), colors = CardDefaults.cardColors(containerColor = Color.White)) {
                        Column(modifier = Modifier.padding(16.dp)) {
                            Text("Receipt Ticket Success! ✅", fontWeight = FontWeight.Bold, color = Color.Green, fontSize = 16.sp)
                            Text("PNR: $ticketRef", fontWeight = FontWeight.Black, fontSize = 14.sp)
                            Spacer(modifier = Modifier.height(8.dp))
                            Text("Bus details: $selectedBusName", fontSize = 12.sp)
                            Text("Seats: ${selectedSeats.joinToString(", ")}", fontSize = 12.sp, fontWeight = FontWeight.Bold)
                            Text("Departs at: $boardingPoint", fontSize = 12.sp)
                            Text("Arrives at: $droppingPoint", fontSize = 12.sp)
                            Text("Passengers: ${selectedSeats.map { passengerNames[it] }.joinToString(", ")}", fontSize = 12.sp)
                        }
                    }
                    Spacer(modifier = Modifier.height(16.dp))
                    Button(
                        onClick = { Toast.makeText(context, "Ticket saved to Downloads Successfully!", Toast.LENGTH_SHORT).show() },
                        modifier = Modifier.fillMaxWidth().testTag("download_ticket_btn")
                    ) {
                        Text("Download Ticket Wallet")
                    }
                    Spacer(modifier = Modifier.height(8.dp))
                    Button(onClick = { selectedBusName = ""; selectedSeats.clear(); seatStep = "Seats"; phase = 1 }, modifier = Modifier.fillMaxWidth()) {
                        Text("Book Another")
                    }
                    Spacer(modifier = Modifier.height(8.dp))
                    OutlinedButton(onClick = onGoHome, modifier = Modifier.fillMaxWidth().testTag("go_home_bus")) {
                        Text("Go Home")
                    }
                }
            }
        }
    }
}

// --------------------------------------------------------------------------
// DOXA AI SCREEN (6 TABS CHAT)
// --------------------------------------------------------------------------
@Composable
fun DoxaAIScreen(onBack: () -> Unit, modifier: Modifier = Modifier) {
    var activeDoxaTab by remember { mutableStateOf("Chats") }
    val doxaTabs = listOf("Chats", "Projects")

    val coroutineScope = rememberCoroutineScope()
    var isHistorySidebarOpen by remember { mutableStateOf(false) }

    // Chat Session structure
    class ChatSession(
        val id: String,
        var title: String,
        val messages: SnapshotStateList<Pair<String, String>>, // "user" or "ai"
        var isStarred: Boolean = false
    )

    // Chat sessions list
    val sessions = remember {
        mutableStateListOf(
            ChatSession(
                "c1",
                "Building local AI agents",
                messages = mutableStateListOf(
                    "user" to "How can I build secure local AI agents?",
                    "ai" to "Building secure local agents involves quantized models inside sandboxed contexts. By keeping embeddings local, customer data is never serialized outward.\n\n1. Use 3B-parameter quantized model files\n2. Expose weights via relative fetches only\n3. Compute matches inside a Web Worker thread"
                ),
                isStarred = true
            ),
            ChatSession(
                "c2",
                "Q-commerce routing protocols",
                messages = mutableStateListOf(
                    "user" to "Synthesize Q-commerce routing protocols for dark-stores.",
                    "ai" to "In quick commerce, routing is driven by micro-dispatch loops. Automation integrates packing queues with rider GPS so bags are matched with electric bikes instantly. Over 90% of delays happen in the first 5-minute sorting window."
                ),
                isStarred = false
            )
        )
    }

    var activeSessionId by remember { mutableStateOf("c1") }
    val activeSession = sessions.find { it.id == activeSessionId } ?: (if (sessions.isNotEmpty()) sessions[0] else null)

    // SOS Mode State
    var sosActive by remember { mutableStateOf(false) }
    var sosLevel by remember { mutableStateOf(0) }
    val sosLog = remember { mutableStateListOf<Pair<String, String>>() }
    var sosLocationAcquired by remember { mutableStateOf(false) }
    var sosLocationCoordinates by remember { mutableStateOf("") }
    var sosFamilyNumberInput by remember { mutableStateOf("") }
    var sosAlertSentToDb by remember { mutableStateOf(false) }

    // Chat message input
    var selectedModel by remember { mutableStateOf("Doxa 4.6 Pro (Low Latency)") }
    var chatMessageInput by remember { mutableStateOf("") }
    var compilingResponse by remember { mutableStateOf(false) }

    // Custom instructions tab
    var customInstruction by remember { mutableStateOf("Act as DOXA AI, an advanced local intelligence model designed for context-aware Q-commerce insights and high-performance frontend engineering tasks.") }
    var checkedThinking by remember { mutableStateOf(false) }
    var checkedVoice by remember { mutableStateOf(false) }

    // Projects list
    val projects = remember {
        mutableStateListOf(
            "Noida Dark Store Optimization" to "Created: 2 days ago • Model: Doxa 4.6 Pro",
            "Local Cuisine Demand Forecast" to "Created: 5 days ago • Model: Doxa 4.6 Ultra",
            "E-Commerce Re-architecture" to "Created: Just now • Upgrading state management and zero-latency dark-store dispatch indexers."
        )
    }
    var showProjectCreator by remember { mutableStateOf(false) }
    var newPTitle by remember { mutableStateOf("") }
    var newPDesc by remember { mutableStateOf("") }

    // Side screen search
    var sideSearchQuery by remember { mutableStateOf("") }

    // Bouncing dots animation value
    val infiniteTransition = rememberInfiniteTransition(label = "dots")
    val dotAlpha1 by infiniteTransition.animateFloat(
        initialValue = 0.2f,
        targetValue = 1f,
        animationSpec = infiniteRepeatable(
            animation = tween(600, easing = LinearEasing),
            repeatMode = RepeatMode.Reverse
        ),
        label = "dot1"
    )
    val dotAlpha2 by infiniteTransition.animateFloat(
        initialValue = 0.2f,
        targetValue = 1f,
        animationSpec = infiniteRepeatable(
            animation = tween(600, delayMillis = 200, easing = LinearEasing),
            repeatMode = RepeatMode.Reverse
        ),
        label = "dot2"
    )
    val dotAlpha3 by infiniteTransition.animateFloat(
        initialValue = 0.2f,
        targetValue = 1f,
        animationSpec = infiniteRepeatable(
            animation = tween(600, delayMillis = 400, easing = LinearEasing),
            repeatMode = RepeatMode.Reverse
        ),
        label = "dot3"
    )

    // Handle SOS progression with delays
    LaunchedEffect(sosActive) {
        if (sosActive) {
            val ts = java.text.SimpleDateFormat("hh:mm a", java.util.Locale.getDefault()).format(java.util.Date())
            if (sosLog.isEmpty()) {
                sosLog.add(Pair(ts, "🚨 SOS activated. AI is in emergency mode. Noida Dispatch Sector 62 is tracking."))
            }
            delay(12000L)
            if (sosActive && sosLevel == 1) {
                sosLevel = 2
                val currentTs = java.text.SimpleDateFormat("hh:mm a", java.util.Locale.getDefault()).format(java.util.Date())
                sosLog.add(0, Pair(currentTs, "📞 Level 2: Auto-calling your registered phone number."))
            }
            delay(12000L)
            if (sosActive && sosLevel == 2) {
                sosLevel = 3
                val currentTs = java.text.SimpleDateFormat("hh:mm a", java.util.Locale.getDefault()).format(java.util.Date())
                sosLog.add(0, Pair(currentTs, "👨‍👩‍👧 Level 3: Family contacts notified via SMS + call."))
            }
            delay(12000L)
            if (sosActive && sosLevel == 3) {
                sosLevel = 4
                val currentTs = java.text.SimpleDateFormat("hh:mm a", java.util.Locale.getDefault()).format(java.util.Date())
                sosLog.add(0, Pair(currentTs, "🚔 Level 4: Case filed. Response team dispatched to Noida Sector 62."))
            }
        } else {
            sosLevel = 0
            sosLog.clear()
        }
    }

    // Function to execute messaging
    fun performSend(text: String) {
        if (text.isBlank() || compilingResponse || activeSession == null) return
        val currentInput = text.trim()
        chatMessageInput = ""

        activeSession.messages.add("user" to currentInput)
        val difficulty = DoxaAIService.getDifficulty(currentInput)

        if (difficulty == "sos" && !sosActive) {
            sosActive = true
            sosLevel = 1
            val ts = java.text.SimpleDateFormat("hh:mm a", java.util.Locale.getDefault()).format(java.util.Date())
            sosLog.add(Pair(ts, "🚨 SOS activated. AI is in emergency mode."))
        }

        // Auto update chat title if it's new
        if (activeSession.title == "New Chat") {
            activeSession.title = if (currentInput.length > 24) currentInput.substring(0, 22) + "..." else currentInput
        }

        compilingResponse = true

        coroutineScope.launch {
            try {
                val formattedMsgs = activeSession.messages.map {
                    DoxaAIService.Message(role = if (it.first == "user") "user" else "assistant", content = it.second)
                }

                val systemPrompt = buildString {
                    append("You are DOXA AI — Crowmix's intelligent assistant.\n\n")
                    append("CAPABILITIES:\n")
                    append("- Q-Commerce: Help users find products, purchase flow, manage cart, track delivery.\n")
                    append("- Code Writing: Provide clean high-performance snippets.\n")
                    append("- Design and Layout guidance: Help style UI with rich Material 3 themes.\n")
                    if (sosActive) {
                        append("- ⚠️ EMERGENCY MODE ACTIVE: Provide immediate clear instructions to the user. Location marker: Noida Sector 62. Ask them if they are safe, stay extremely reassuring and calm.\n")
                    }
                    append("\nCONTEXT: User=Abhi, Location=Noida Sector 62. Instructions: $customInstruction")
                }

                val reply = DoxaAIService.sendMessage(formattedMsgs, systemPrompt, difficulty)
                activeSession.messages.add("ai" to reply)
            } catch (e: Exception) {
                activeSession.messages.add("ai" to "⚠️ Service returned error: ${e.localizedMessage}. Please try again.")
            } finally {
                compilingResponse = false
            }
        }
    }

    fun triggerSOS() {
        sosActive = true
        sosLevel = 1
        sosLog.clear()
        val ts = java.text.SimpleDateFormat("hh:mm a", java.util.Locale.getDefault()).format(java.util.Date())
        sosLog.add(Pair(ts, "🚨 SOS activated. AI is in emergency mode. Noida Security tracking."))
        
        performSend("SOS I need emergency help immediately! Please guide me on what to do.")
    }

    Column(modifier = modifier.fillMaxSize().background(Color(0xFF141414))) {
        // High UI Header Bar
        Row(
            modifier = Modifier
                .fillMaxWidth()
                .background(Color(0xFF191919))
                .border(BorderStroke(0.5.dp, Color(0xFF2C2C2C)))
                .padding(horizontal = 12.dp, vertical = 8.dp),
            verticalAlignment = Alignment.CenterVertically
        ) {
            IconButton(onClick = onBack, modifier = Modifier.testTag("doxa_back")) {
                Icon(Icons.AutoMirrored.Filled.ArrowBack, "Back", tint = Color(0xFFF97316))
            }
            
            // Sidebar trigger
            IconButton(onClick = { isHistorySidebarOpen = !isHistorySidebarOpen }, modifier = Modifier.testTag("toggle_sidebar")) {
                Icon(Icons.Default.Menu, "History", tint = Color.White)
            }
            
            Spacer(modifier = Modifier.width(6.dp))
            
            Column(modifier = Modifier.weight(1f)) {
                Row(verticalAlignment = Alignment.CenterVertically) {
                    Text("DOXA AI", color = Color(0xFFF97316), fontWeight = FontWeight.Black, fontSize = 16.sp)
                    Spacer(modifier = Modifier.width(4.dp))
                    Box(modifier = Modifier.size(6.dp).background(if (sosActive) Color.Red else Color.Green, CircleShape))
                }
                Text(
                    text = if (sosActive) "Escalation Loop Active — Level $sosLevel" else "Crowmix Cloud Session",
                    color = if (sosActive) Color(0xFFEF4444) else Color(0xFF687280),
                    fontSize = 11.sp,
                    fontWeight = FontWeight.Bold
                )
            }

            // High Contrast Circular SOS Siren Switch
            IconButton(
                onClick = {
                    if (!sosActive) {
                        triggerSOS()
                    } else {
                        sosActive = false
                        sosLevel = 0
                        sosLog.clear()
                        sosLocationAcquired = false
                        sosLocationCoordinates = ""
                        sosFamilyNumberInput = ""
                        sosAlertSentToDb = false
                    }
                },
                modifier = Modifier
                    .size(38.dp)
                    .background(if (sosActive) Color(0xFF7F1D1D) else Color(0xFFB91C1C), CircleShape)
                    .border(BorderStroke(1.5.dp, if (sosActive) Color(0xFFEF4444) else Color(0xFFDC2626)), CircleShape)
            ) {
                Icon(
                    imageVector = Icons.Default.Warning,
                    contentDescription = "SOS Siren",
                    tint = Color.White,
                    modifier = Modifier.size(16.dp)
                )
            }
        }



        Row(modifier = Modifier.weight(1f)) {
            // Optional Collapsible Sidebar
            AnimatedVisibility(
                visible = isHistorySidebarOpen,
                enter = slideInHorizontally() + fadeIn(),
                exit = slideOutHorizontally() + fadeOut()
            ) {
                Column(
                    modifier = Modifier
                        .width(220.dp)
                        .fillMaxHeight()
                        .background(Color(0xFF191919))
                        .border(BorderStroke(1.dp, Color(0xFF2C2C2C)))
                ) {
                    // New chat button
                    Box(modifier = Modifier.padding(12.dp)) {
                        Column(verticalArrangement = Arrangement.spacedBy(8.dp)) {
                            Button(
                                onClick = {
                                    val id = "c_" + System.currentTimeMillis()
                                    val newSession = ChatSession(id, "New Chat", messages = mutableStateListOf<Pair<String, String>>(), isStarred = false)
                                    sessions.add(0, newSession)
                                    activeSessionId = id
                                    activeDoxaTab = "Chats"
                                },
                                colors = ButtonDefaults.buttonColors(containerColor = Color(0xFF2C2C2C)),
                                modifier = Modifier
                                    .fillMaxWidth()
                                    .height(48.dp)
                                    .testTag("new_chat_ai"),
                                shape = RoundedCornerShape(12.dp)
                            ) {
                                Icon(Icons.Default.Add, contentDescription = "Add", tint = Color.White, modifier = Modifier.size(16.dp))
                                Spacer(modifier = Modifier.width(8.dp))
                                Text("New chat", color = Color.White, fontSize = 12.sp, fontWeight = FontWeight.SemiBold)
                            }

                            // Chat and project buttons below new chat
                            Row(
                                modifier = Modifier.fillMaxWidth(),
                                horizontalArrangement = Arrangement.spacedBy(8.dp)
                            ) {
                                Button(
                                    onClick = { activeDoxaTab = "Chats" },
                                    colors = ButtonDefaults.buttonColors(
                                        containerColor = if (activeDoxaTab == "Chats") Color(0xFFF97316) else Color(0xFF1E1E1E)
                                    ),
                                    modifier = Modifier.weight(1f).height(38.dp),
                                    shape = RoundedCornerShape(10.dp),
                                    contentPadding = PaddingValues(0.dp)
                                ) {
                                    Text("Chats", color = Color.White, fontSize = 11.sp, fontWeight = FontWeight.Bold)
                                }
                                Button(
                                    onClick = { activeDoxaTab = "Projects" },
                                    colors = ButtonDefaults.buttonColors(
                                        containerColor = if (activeDoxaTab == "Projects") Color(0xFFF97316) else Color(0xFF1E1E1E)
                                    ),
                                    modifier = Modifier.weight(1f).height(38.dp),
                                    shape = RoundedCornerShape(10.dp),
                                    contentPadding = PaddingValues(0.dp)
                                ) {
                                    Text("Projects", color = Color.White, fontSize = 11.sp, fontWeight = FontWeight.Bold)
                                }
                            }
                        }
                    }

