                                            append("Click On Green Button")
                                        }
                                        append(" And Give Your ")
                                        withStyle(style = SpanStyle(fontWeight = FontWeight.Bold, color = Color.White)) {
                                            append("LIVE LOCATION")
                                        }
                                        append(".\n\nSecond Or Type And Send Your Live ")
                                        withStyle(style = SpanStyle(fontWeight = FontWeight.Bold, color = Color.White)) {
                                            append("LOCATION")
                                        }
                                        append(" With Any ")
                                        withStyle(style = SpanStyle(fontWeight = FontWeight.Bold, color = Color.White)) {
                                            append("LANDMARK")
                                        }
                                        append(" Example Water Tank, Billboard.")
