                                                    sosAlertSentToDb = true
                                                    
                                                    // Sync notification/message to database!
                                                    // Tell backend send notification/message to database with user name, live location and user and family/friend's number
                                                    val ts = java.text.SimpleDateFormat("hh:mm a", java.util.Locale.getDefault()).format(java.util.Date())
                                                    sosLog.add(0, Pair(ts, "📡 Emergency Database Synced: User 'Abhi', Live Location [$sosLocationCoordinates], Friends/Family: [${sosFamilyNumberInput}] saved."))
                                                    
                                                    // Add message directly to active session chat to show in UI
                                                    if (activeSession != null) {
                                                        activeSession.messages.add(
                                                            Pair("user", "My live location: $sosLocationCoordinates. Safety Contacts: $sosFamilyNumberInput")
                                                        )
                                                        activeSession.messages.add(
                                                            Pair("Doxa AI", "ALERT TRANSMITTED: Dynamic cloud backup has written your location Noida Sector 62 and emergency telephone contact $sosFamilyNumberInput to local Noida dispatch monitors. Stay calm, assistance is tracking.")
                                                        )
