                                    modifier = Modifier
                                        .size(64.dp)
                                        .background(logoBg, RoundedCornerShape(18.dp))
                                        .border(2.dp, logoBorder, RoundedCornerShape(18.dp)),
                                    contentAlignment = Alignment.Center
                                ) {
                                    Text(
                                        text = if (sosActive) "🚨" else "D",
                                        color = Color.White,
                                        fontSize = 28.sp,
                                        fontWeight = FontWeight.Black
                                    )
                                }

                                Spacer(modifier = Modifier.height(16.dp))

                                if (sosActive) {
                                    Text("🚨 Emergency Action Mode", color = Color(0xFFEF4444), fontWeight = FontWeight.Black, fontSize = 20.sp)
                                    Spacer(modifier = Modifier.height(8.dp))
                                    Text("Escalation sequence triggered in Sector 62. Tracking user feedback.", color = Color(0xFF687280), fontSize = 12.sp, textAlign = TextAlign.Center)

