                                    Spacer(modifier = Modifier.height(8.dp))
                                    Text("Ask me anything — products, fast code, PDF layouts, or courier tracks.", color = Color(0xFF687280), fontSize = 12.sp, textAlign = TextAlign.Center)
                                }

