                                                .background(Color(0xFF222222), RoundedCornerShape(16.dp))
                                                .border(1.dp, Color(0xFF2C2C2C), RoundedCornerShape(16.dp))
                                                .padding(horizontal = 10.dp, vertical = 4.dp)
