                                    modifier = Modifier.fillMaxWidth().padding(horizontal = 8.dp)
                                ) {
                                    Column(modifier = Modifier.padding(12.dp)) {
                                        OutlinedTextField(
                                            value = chatMessageInput,
                                            onValueChange = { chatMessageInput = it },
                                            placeholder = {
                                                Text(
                                                    text = if (sosActive) "Describe what's happening — I will help you step by step..." else "Ask about products, write code, analyze PDFs, describe images...",
                                                    color = Color(0xFF687280),
                                                    fontSize = 12.sp
                                                )
                                            },
                                            modifier = Modifier.fillMaxWidth().height(80.dp).testTag("ai_msg_input"),
                                            textStyle = TextStyle(color = Color.White, fontSize = 13.sp),
                                            colors = OutlinedTextFieldDefaults.colors(
                                                focusedBorderColor = Color.Transparent,
                                                unfocusedBorderColor = Color.Transparent,
                                                focusedContainerColor = Color.Transparent,
                                                unfocusedContainerColor = Color.Transparent
