                                                modifier = Modifier
                                                    .size(32.dp)
                                                    .background(if (chatMessageInput.isNotBlank()) Color(0xFFF97316) else Color(0xFF2C2C2C), CircleShape)
                                                    .testTag("send_ai_btn")
