                                ) {
                                    pills.forEach { (label, prompt) ->
                                        Box(
                                            modifier = Modifier
                                                .background(if (sosActive) Color(0xFF2A0D0D) else Color(0xFF242424), RoundedCornerShape(16.dp))
                                                .border(1.dp, if (sosActive) Color(0xFF7F1D1D) else Color(0xFF333333), RoundedCornerShape(16.dp))
                                                .clickable { performSend(prompt) }
                                                .padding(horizontal = 10.dp, vertical = 6.dp)
                                        ) {
                                            Text(label, color = if (sosActive) Color(0xFFF87171) else Color(0xFF9CA3AF), fontSize = 10.sp, fontWeight = FontWeight.SemiBold)
                                        }
                                    }
                                }
