@Composable
fun ProfileScreen(onBack: () -> Unit, modifier: Modifier = Modifier) {
    var subScreen by remember { mutableStateOf("Main") }

    // Address sub-screen state
    val addresses = remember { mutableStateListOf("Home — Flat 402, Royal Palms, Sector 62, Noida, UP 201301", "Office — Sector 62 Corporate Hub, Tower C, Noida 201301") }
    var newAddressInput by remember { mutableStateOf("") }

    // Card state
    val paymentCards = remember { mutableStateListOf("HDFC Bank •••• 4242 (Visa)", "SBI Debit •••• 8891 (Mastercard)") }
    var newCardNumber by remember { mutableStateOf("") }
    var newCardHolder by remember { mutableStateOf("") }

    val context = LocalContext.current

    if (subScreen.trim() == "Partners") {
        PartnersHomeScreen(onBack = { subScreen = "Main" })
    } else {
        Column(modifier = modifier.fillMaxSize().background(lightBg)) {
            Box(
                modifier = Modifier
