class ConnectCommentsMapProxy : Map<String, List<ConnectNewsComment>> {
    override val entries: Set<Map.Entry<String, List<ConnectNewsComment>>>
        get() = ConnectCommentsManager.allComments.entries.filter { it.key.startsWith("news_article_") }.map { entry ->
            object : Map.Entry<String, List<ConnectNewsComment>> {
                override val key: String = entry.key.removePrefix("news_article_")
                override val value: List<ConnectNewsComment> = entry.value
            }
        }.toSet()

    override val keys: Set<String>
        get() = ConnectCommentsManager.allComments.keys.filter { it.startsWith("news_article_") }.map { it.removePrefix("news_article_") }.toSet()

    override val size: Int
        get() = entries.size

    override val values: Collection<List<ConnectNewsComment>>
        get() = entries.map { it.value }

    override fun isEmpty(): Boolean = entries.isEmpty()

    override fun containsKey(key: String): Boolean = ConnectCommentsManager.allComments.containsKey("news_article_$key")

    override fun containsValue(value: List<ConnectNewsComment>): Boolean = values.contains(value)

    override fun get(key: String): List<ConnectNewsComment>? {
        return ConnectCommentsManager.getComments("news_article", key).filter { it.parentCommentId == null }
    }
}

@Composable
fun GroupsSubTabContent(
    chats: MutableList<ConnectChat>,
    groupsSearchQuery: String,
    groupFilterTab: String,
    setGroupFilterTab: (String) -> Unit,
    onPreviewGroup: (String) -> Unit,
    onOpenChat: (String) -> Unit,
    personalCity: String,
    tealPrimary: Color
) {
    val context = LocalContext.current
    Column(Modifier.fillMaxSize()) {
        // Inner tabs: My Groups | Discover
        TabRow(
            selectedTabIndex = if (groupFilterTab == "MY") 0 else 1,
            containerColor = Color.White,
            contentColor = tealPrimary
        ) {
            Tab(selected = groupFilterTab == "MY", onClick = { setGroupFilterTab("MY") }) {
                Row(modifier = Modifier.padding(12.dp), verticalAlignment = Alignment.CenterVertically) {
                    Text("👥 My Groups", fontWeight = FontWeight.Bold, fontSize = 13.sp)
                }
            }
            Tab(selected = groupFilterTab == "DISCOVER", onClick = { setGroupFilterTab("DISCOVER") }) {
                Row(modifier = Modifier.padding(12.dp), verticalAlignment = Alignment.CenterVertically) {
                    Text("📍 Discover Near You", fontWeight = FontWeight.Bold, fontSize = 13.sp)
                }
            }
        }

        if (groupFilterTab == "MY") {
            // "My Groups" lists colony groups + regular groups user has joined
            val myGroups = chats.filter {
                it.isGroup && it.joined && (groupsSearchQuery.isBlank() || it.name.contains(groupsSearchQuery, true))
            }
            if (myGroups.isEmpty()) {
                Column(
                    modifier = Modifier.fillMaxSize().padding(32.dp),
                    verticalArrangement = Arrangement.Center,
                    horizontalAlignment = Alignment.CenterHorizontally
                ) {
                    Text("No Groups Joined", fontWeight = FontWeight.Bold, fontSize = 16.sp, color = Color(0xFF687280))
                    Spacer(Modifier.height(8.dp))
                    Text("Tap \"Discover Near You\" to find and join local colony forums or interest groups!", textAlign = TextAlign.Center, fontSize = 12.sp, color = Color(0xFF9CA3AF))
                }
            } else {
                LazyColumn(modifier = Modifier.fillMaxSize()) {
                    items(myGroups) { group ->
                        Row(
                            modifier = Modifier
                                .fillMaxWidth()
                                .clickable { onOpenChat(group.id) }
                                .padding(14.dp)
                                .testTag("joined_group_${group.id}"),
                            verticalAlignment = Alignment.CenterVertically
                        ) {
                            Box(
                                modifier = Modifier.size(46.dp).background(Color(0xFFE2E8F0), CircleShape),
                                contentAlignment = Alignment.Center
                            ) {
                                Text(group.avatarEmoji, fontSize = 22.sp)
                            }
                            Spacer(Modifier.width(12.dp))
                            Column(Modifier.weight(1f)) {
                                Row(verticalAlignment = Alignment.CenterVertically) {
                                    Text(group.name, fontWeight = FontWeight.Bold, fontSize = 14.sp)
                                    if (group.isColonyGroup) {
                                        Spacer(Modifier.width(6.dp))
                                        Box(
                                            modifier = Modifier
                                                .background(tealPrimary.copy(alpha = 0.12f), RoundedCornerShape(8.dp))
                                                .padding(horizontal = 6.dp, vertical = 2.dp)
                                        ) {
                                            Text("📍 Colony", fontSize = 8.sp, color = tealPrimary, fontWeight = FontWeight.Bold)
                                        }
                                    }
                                }
                                Text("${group.membersCount} members", fontSize = 11.sp, color = Color(0xFF687280))
                                Spacer(Modifier.height(2.dp))
                                Text(group.lastMessage, fontSize = 12.sp, color = Color(0xFF687280), maxLines = 1, overflow = TextOverflow.Ellipsis)
                            }
                            Icon(Icons.Default.KeyboardArrowRight, contentDescription = "Open", tint = Color(0xFF9CA3AF))
                        }
                        Divider(color = Color(0xFFF1F5F9))
                    }
                }
            }
        } else {
            // DISCOVER TAB
            val cleanQuery = groupsSearchQuery.trim()
            
            // "Groups near you" section (Colony groups with matching saved locality, not joined)
            val groupsNearYou = chats.filter {
                it.isGroup && !it.joined && it.isColonyGroup &&
                (cleanQuery.isEmpty() || it.name.contains(cleanQuery, true) || it.description.contains(cleanQuery, true))
            }
            
            // "Other groups in [City]" section (Wider interest interest groups, not joined)
            val otherGroups = chats.filter {
                it.isGroup && !it.joined && !it.isColonyGroup &&
                (cleanQuery.isEmpty() || it.name.contains(cleanQuery, true) || it.description.contains(cleanQuery, true))
            }

            LazyColumn(
                modifier = Modifier.fillMaxSize().padding(12.dp),
                verticalArrangement = Arrangement.spacedBy(16.dp)
            ) {
                if (groupsNearYou.isNotEmpty()) {
                    item {
                        Text(
                            "📍 COLONY GROUPS NEAR YOU (Sector 62)",
                            fontWeight = FontWeight.Bold,
                            fontSize = 11.sp,
                            color = tealPrimary,
                            modifier = Modifier.padding(bottom = 6.dp)
                        )
                    }
                    items(groupsNearYou) { group ->
                        DiscoverGroupCard(
                            group = group,
                            onPreview = { onPreviewGroup(group.id) },
                            onJoin = {
                                if (group.requiresApproval) {
                                    val idx = chats.indexOfFirst { it.id == group.id }
                                    if (idx != -1) {
                                        chats[idx] = chats[idx].copy(requestedToJoin = true)
                                    }
                                    Toast.makeText(context, "Approval Request Sent ✉️!", Toast.LENGTH_LONG).show()
                                } else {
                                    val idx = chats.indexOfFirst { it.id == group.id }
                                    if (idx != -1) {
                                        chats[idx] = chats[idx].copy(joined = true)
                                    }
                                    Toast.makeText(context, "Hello Neighbor! Joined ${group.name} 🏙️", Toast.LENGTH_LONG).show()
                                }
                            },
                            tealPrimary = tealPrimary
                        )
                    }
                }

                if (otherGroups.isNotEmpty()) {
                    item {
                        Text(
                            "🌐 WIDER INTEREST GROUPS IN NOIDA",
                            fontWeight = FontWeight.Bold,
                            fontSize = 11.sp,
                            color = Color(0xFF687280),
                            modifier = Modifier.padding(top = 8.dp, bottom = 6.dp)
                        )
                    }
                    items(otherGroups) { group ->
                        DiscoverGroupCard(
                            group = group,
                            onPreview = { onPreviewGroup(group.id) },
                            onJoin = {
                                val idx = chats.indexOfFirst { it.id == group.id }
                                if (idx != -1) {
                                    chats[idx] = chats[idx].copy(joined = true)
                                }
                                Toast.makeText(context, "Joined ${group.name} Success!", Toast.LENGTH_LONG).show()
                            },
                            tealPrimary = tealPrimary
                        )
                    }
                }

                if (groupsNearYou.isEmpty() && otherGroups.isEmpty()) {
                    item {
                        Column(
                            modifier = Modifier.fillMaxWidth().padding(48.dp),
                            horizontalAlignment = Alignment.CenterHorizontally
                        ) {
                            Text("No match found for \"$cleanQuery\"", fontWeight = FontWeight.Bold, color = Color(0xFF687280), fontSize = 14.sp)
                            Spacer(modifier = Modifier.height(8.dp))
                            Text("Try searching with broader keywords like 'Sector', 'Noida' or 'Residents'.", fontSize = 11.sp, color = Color(0xFF9CA3AF), textAlign = TextAlign.Center)
                        }
                    }
                }
            }
        }
    }
}

