@Composable
fun ColonyGroupPollBubble(
    msg: ConnectMessage,
    context: Context,
    tealPrimary: Color
) {
    val votesMap = ConnectChatManager.pollVotes[msg.id] ?: mapOf("Yes" to 10, "No" to 5)
    val myVote = ConnectChatManager.myPollVotes[msg.id]

    val totalVotes = votesMap.values.sum().coerceAtLeast(1)

    Card(
        colors = CardDefaults.cardColors(containerColor = Color(0xFFECFDF5)),
        modifier = Modifier
            .widthIn(max = 280.dp)
            .padding(4.dp)
            .testTag("poll_card_${msg.id}"),
        border = BorderStroke(1.dp, tealPrimary.copy(alpha = 0.25f))
    ) {
        Column(Modifier.padding(12.dp)) {
            Row(verticalAlignment = Alignment.CenterVertically) {
                Text("📊", fontSize = 16.sp)
                Spacer(Modifier.width(6.dp))
                Column {
                    Text(msg.senderName, fontWeight = FontWeight.Bold, fontSize = 11.sp, color = tealPrimary)
                    Text("LIVE COLONY POLL", fontWeight = FontWeight.Bold, fontSize = 9.sp, color = Color(0xFF687280))
                }
            }
            Spacer(Modifier.height(8.dp))
            Text(msg.text, fontWeight = FontWeight.Bold, fontSize = 13.sp, color = Color.Black)
            Spacer(modifier = Modifier.height(8.dp))

            Column(verticalArrangement = Arrangement.spacedBy(8.dp)) {
                votesMap.forEach { (option, count) ->
                    val isVotedForThis = option == myVote
                    val pct = (count.toFloat() / totalVotes * 100).toInt()

                    Box(
                        modifier = Modifier
                            .fillMaxWidth()
                            .height(38.dp)
                            .clip(RoundedCornerShape(8.dp))
                            .border(
                                width = if (isVotedForThis) 2.dp else 1.dp,
                                color = if (isVotedForThis) tealPrimary else Color(0xFFCBD5E1),
                                shape = RoundedCornerShape(8.dp)
                            )
                            .clickable {
                                val currentMap = ConnectChatManager.pollVotes[msg.id]?.toMutableMap() ?: mutableMapOf()
                                val existingVote = ConnectChatManager.myPollVotes[msg.id]
                                
                                if (existingVote == option) {
                                    // Remove vote
                                    currentMap[option] = (currentMap[option] ?: 1).minus(1).coerceAtLeast(0)
                                    ConnectChatManager.myPollVotes.remove(msg.id)
                                    Toast.makeText(context, "Vote retracted!", Toast.LENGTH_SHORT).show()
                                } else {
                                    // Switch vote: decrement old option if any
                                    if (existingVote != null) {
                                        currentMap[existingVote] = (currentMap[existingVote] ?: 1).minus(1).coerceAtLeast(0)
                                    }
                                    currentMap[option] = (currentMap[option] ?: 0).plus(1)
                                    ConnectChatManager.myPollVotes[msg.id] = option
                                    Toast.makeText(context, "Voted: $option! 📊", Toast.LENGTH_SHORT).show()
                                }
                                ConnectChatManager.pollVotes[msg.id] = currentMap
                            }
                    ) {
                        // Horizontal bar chart visual
                        Box(
                            modifier = Modifier
                                .fillMaxHeight()
                                .fillMaxWidth(count.toFloat() / totalVotes)
                                .background(if (isVotedForThis) tealPrimary.copy(alpha = 0.22f) else Color(0xFF9CA3AF).copy(alpha = 0.3f))
                        )
                        
                        // Text overlays
                        Row(
                            modifier = Modifier
                                .fillMaxSize()
                                .padding(horizontal = 10.dp),
                            horizontalArrangement = Arrangement.SpaceBetween,
                            verticalAlignment = Alignment.CenterVertically
                        ) {
                            Row(verticalAlignment = Alignment.CenterVertically) {
                                if (isVotedForThis) {
                                    Text("🎯", fontSize = 11.sp, modifier = Modifier.padding(end = 4.dp))
                                }
                                Text(
                                    option,
                                    fontSize = 11.sp,
                                    fontWeight = if (isVotedForThis) FontWeight.Bold else FontWeight.Normal,
                                    color = Color.Black,
                                    maxLines = 1,
                                    overflow = TextOverflow.Ellipsis
                                )
                            }
                            Text(
                                "$count ($pct%)",
                                fontSize = 11.sp,
                                fontWeight = FontWeight.Bold,
                                color = if (isVotedForThis) tealPrimary else Color.DarkGray
                            )
                        }
                    }
                }
            }
            Spacer(Modifier.height(8.dp))
            Row(modifier = Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.SpaceBetween) {
                Text("$totalVotes total votes", fontSize = 9.sp, color = Color(0xFF687280))
                Text(msg.timestamp, fontSize = 8.sp, color = Color(0xFF687280))
            }
        }
    }
}

@Composable
fun CommentSection(
    targetType: String,
    targetId: String,
    modifier: Modifier = Modifier
) {
    val tealPrimary = Color(0xFF1FAE7A)
    val slateContent = Color(0xFF1E293B)
    val graySub = Color(0xFF64748B)

    val context = LocalContext.current
    val sharedPrefs = remember(context) { context.getSharedPreferences("crowmix_connect_prefs", Context.MODE_PRIVATE) }
    
    val activeProfileType = sharedPrefs.getString("connect_active_profile_type", "PERSONAL") ?: "PERSONAL"
    val personalName = sharedPrefs.getString("connect_personal_name", "Aman Sharma") ?: "Aman Sharma"
    val personalAvatar = sharedPrefs.getString("connect_personal_avatar", "🤠") ?: "🤠"
    val businessName = sharedPrefs.getString("connect_business_name", "Noida Fresh Hub") ?: "Noida Fresh Hub"
    val businessLogo = sharedPrefs.getString("connect_business_logo", "🍕") ?: "🍕"

    val userName = if (activeProfileType == "PERSONAL") personalName else businessName
    val userAvatar = if (activeProfileType == "PERSONAL") personalAvatar else businessLogo

    var commentText by remember { mutableStateOf("") }
    var replyingTo by remember { mutableStateOf<ConnectNewsComment?>(null) }
    var sortBy by remember { mutableStateOf("Most Relevant") }
    var showSortMenu by remember { mutableStateOf(false) }

    val expandedReplies = remember { mutableStateMapOf<String, Boolean>() }

    var showContextMenuForComment by remember { mutableStateOf<ConnectNewsComment?>(null) }
    var showEditDialogForComment by remember { mutableStateOf<ConnectNewsComment?>(null) }
    var editCommentText by remember { mutableStateOf("") }

    val comments = ConnectCommentsManager.getComments(targetType, targetId)
    val topLevelComments = comments.filter { it.parentCommentId == null }

    val sortedTopLevelComments = remember(comments, sortBy) {
        when (sortBy) {
            "Newest" -> topLevelComments.sortedByDescending { it.id }
            else -> topLevelComments.sortedByDescending { it.likesCount }
        }
    }

    val flaggedWords = listOf("spam", "abuse", "fake", "idiot", "hate", "scam", "cheat", "stupid", "fraud", "crap")

    var showMentionsDropdown by remember { mutableStateOf(false) }
    val contactsList = remember {
        ConnectChatManager.contacts.map { it.name.replace(" 🤠", "").replace(" 👩‍💻", "").replace(" 🏢", "").trim() }
    }
    val previousCommenters = remember(comments) {
        comments.map { it.authorName }.distinct()
    }
    val allMentionCandidates = remember(contactsList, previousCommenters) {
        (contactsList + previousCommenters).distinct().filter { it.isNotBlank() }
    }
    
    val mentionQuery = remember(commentText) {
        val lastIdx = commentText.lastIndexOf('@')
        if (lastIdx != -1 && lastIdx >= commentText.length - 15 && !commentText.substring(lastIdx).contains(' ')) {
            commentText.substring(lastIdx + 1)
        } else {
            null
        }
    }
    
    val filteredMentions = remember(mentionQuery, allMentionCandidates) {
        if (mentionQuery != null) {
            allMentionCandidates.filter { it.contains(mentionQuery, ignoreCase = true) }
        } else {
            emptyList()
        }
    }

    LaunchedEffect(mentionQuery, filteredMentions) {
        showMentionsDropdown = mentionQuery != null && filteredMentions.isNotEmpty()
    }

    Column(modifier = modifier.fillMaxWidth()) {
        Row(
            modifier = Modifier
                .fillMaxWidth()
                .padding(vertical = 12.dp),
            horizontalArrangement = Arrangement.SpaceBetween,
            verticalAlignment = Alignment.CenterVertically
        ) {
            Text(
                "${comments.size} comments",
                fontWeight = FontWeight.Bold,
                fontSize = 14.sp,
                color = slateContent
            )

            Box {
                Row(
                    modifier = Modifier.clickable { showSortMenu = true },
                    verticalAlignment = Alignment.CenterVertically
                ) {
                    Text(
                        sortBy,
                        color = Color(0xFF687280),
                        fontSize = 12.sp,
                        fontWeight = FontWeight.Medium
                    )
                    Spacer(modifier = Modifier.width(4.dp))
                    Icon(
                        Icons.Default.ArrowDropDown,
                        contentDescription = "Sort Options",
                        tint = Color(0xFF687280),
                        modifier = Modifier.size(16.dp)
                    )
                }

                DropdownMenu(
                    expanded = showSortMenu,
                    onDismissRequest = { showSortMenu = false },
                    modifier = Modifier.background(Color.White)
                ) {
                    DropdownMenuItem(
                        text = { Text("Most Relevant", fontSize = 13.sp) },
                        onClick = {
                            sortBy = "Most Relevant"
                            showSortMenu = false
                        }
                    )
                    DropdownMenuItem(
                        text = { Text("Newest", fontSize = 13.sp) },
                        onClick = {
                            sortBy = "Newest"
                            showSortMenu = false
                        }
                    )
                }
            }
        }

        Divider(color = Color(0xFFF1F5F9))
        Spacer(modifier = Modifier.height(16.dp))

        if (sortedTopLevelComments.isEmpty()) {
            Column(
                modifier = Modifier
                    .fillMaxWidth()
                    .padding(vertical = 32.dp),
                horizontalAlignment = Alignment.CenterHorizontally
            ) {
                Text("💬", fontSize = 36.sp, modifier = Modifier.padding(bottom = 8.dp))
                Text(
                    "No comments yet. Be the first to comment!",
                    color = Color(0xFF687280),
                    fontSize = 13.sp,
                    textAlign = TextAlign.Center
                )
            }
        } else {
            Column(
                modifier = Modifier.fillMaxWidth(),
                verticalArrangement = Arrangement.spacedBy(16.dp)
            ) {
                sortedTopLevelComments.forEach { comment ->
                    val isFlagged = ConnectCommentsManager.reportedComments.contains(comment.id)
                    val replies = comments.filter { it.parentCommentId == comment.id }
                    val hasReplies = replies.isNotEmpty()
                    val repliesAreExpanded = expandedReplies[comment.id] == true

                    Row(
                        modifier = Modifier.fillMaxWidth(),
                        horizontalArrangement = Arrangement.spacedBy(10.dp)
                    ) {
                        Box(
                            modifier = Modifier
                                .size(32.dp)
                                .background(Color(0xFFF1F5F9), CircleShape),
                            contentAlignment = Alignment.Center
                        ) {
                            Text(comment.authorAvatarEmoji, fontSize = 16.sp)
                        }

                        Column(modifier = Modifier.weight(1f)) {
                            Box(
                                modifier = Modifier
                                    .fillMaxWidth()
                                    .pointerInput(comment.id) {
                                        detectTapGestures(
                                            onDoubleTap = {
                                                val nextState = !comment.likedByMe
                                                val offset = if (nextState) 1 else -1
                                                ConnectCommentsManager.updateComment(
                                                    targetType,
                                                    targetId,
                                                    comment.copy(
                                                        likedByMe = nextState,
                                                        likesCount = (comment.likesCount + offset).coerceAtLeast(0)
                                                    )
                                                )
                                                Toast.makeText(context, if (nextState) "Liked comment ❤️" else "Unliked comment", Toast.LENGTH_SHORT).show()
                                            },
                                            onLongPress = {
                                                showContextMenuForComment = comment
                                            }
                                        )
                                    }
                            ) {
                                if (isFlagged) {
                                    Text(
                                        text = "⚠️ This comment is flagged for community safety review.",
                                        fontSize = 13.sp,
                                        color = Color.Red,
                                        fontStyle = androidx.compose.ui.text.font.FontStyle.Italic
                                    )
                                } else {
                                    Text(
                                        text = buildAnnotatedString {
                                            withStyle(style = SpanStyle(fontWeight = FontWeight.Bold, fontSize = 13.sp, color = slateContent)) {
                                                append(comment.authorName)
                                            }
                                            append("  ")
                                            withStyle(style = SpanStyle(fontSize = 13.sp, color = slateContent)) {
                                                append(comment.text)
                                            }
                                        },
                                        lineHeight = 18.sp
                                    )
                                }
                            }

                            Spacer(modifier = Modifier.height(8.dp))

                            Row(
                                verticalAlignment = Alignment.CenterVertically,
                                horizontalArrangement = Arrangement.spacedBy(12.dp)
                            ) {
                                Text(comment.timeAgo, fontSize = 11.sp, color = Color(0xFF687280))
                                
                                if (!isFlagged) {
                                    Text(
                                        "Reply",
                                        fontSize = 11.sp,
                                        fontWeight = FontWeight.Bold,
                                        color = Color(0xFF687280),
                                        modifier = Modifier.clickable {
                                            replyingTo = comment
                                            commentText = "@${comment.authorName} "
                                        }
                                    )
                                }

                                if (comment.likesCount > 0) {
                                    Text(
                                        "${comment.likesCount} liked",
                                        fontSize = 11.sp,
                                        color = Color(0xFF687280)
                                    )
                                }
                            }

                            if (hasReplies) {
                                Spacer(modifier = Modifier.height(8.dp))
                                Row(
                                    modifier = Modifier
                                        .clickable {
                                            expandedReplies[comment.id] = !repliesAreExpanded
                                        }
                                        .padding(vertical = 4.dp),
                                    verticalAlignment = Alignment.CenterVertically
                                ) {
                                    Box(
                                        modifier = Modifier
                                            .width(16.dp)
                                            .height(1.dp)
                                            .background(Color(0xFF9CA3AF))
                                    )
                                    Spacer(modifier = Modifier.width(6.dp))
                                    Text(
                                        if (repliesAreExpanded) "Hide replies" else "View ${replies.size} replies",
                                        fontSize = 11.sp,
                                        fontWeight = FontWeight.Bold,
                                        color = Color(0xFF687280)
                                    )
                                }
                            }

                            if (hasReplies && repliesAreExpanded) {
                                Spacer(modifier = Modifier.height(8.dp))
                                Column(
                                    verticalArrangement = Arrangement.spacedBy(12.dp),
                                    modifier = Modifier.padding(start = 24.dp)
                                ) {
                                    replies.forEach { reply ->
                                        val replyFlagged = ConnectCommentsManager.reportedComments.contains(reply.id)
                                        Row(
                                            modifier = Modifier.fillMaxWidth(),
                                            horizontalArrangement = Arrangement.spacedBy(8.dp)
                                        ) {
                                            Box(
                                                modifier = Modifier
                                                    .size(24.dp)
                                                    .background(Color(0xFFF1F5F9), CircleShape),
                                                contentAlignment = Alignment.Center
                                            ) {
                                                Text(reply.authorAvatarEmoji, fontSize = 12.sp)
                                            }

                                            Column(modifier = Modifier.weight(1f)) {
                                                Box(
                                                    modifier = Modifier
                                                        .fillMaxWidth()
                                                        .pointerInput(reply.id) {
                                                            detectTapGestures(
                                                                onDoubleTap = {
                                                                    val nextState = !reply.likedByMe
                                                                    val offset = if (nextState) 1 else -1
                                                                    ConnectCommentsManager.updateComment(
                                                                        targetType,
                                                                        targetId,
                                                                        reply.copy(
                                                                            likedByMe = nextState,
                                                                            likesCount = (reply.likesCount + offset).coerceAtLeast(0)
                                                                        )
                                                                    )
                                                                },
                                                                onLongPress = {
                                                                    showContextMenuForComment = reply
                                                                }
                                                            )
                                                        }
                                                ) {
                                                    if (replyFlagged) {
                                                        Text(
                                                            text = "⚠️ Flagged comment.",
                                                            fontSize = 12.sp,
                                                            color = Color.Red,
                                                            fontStyle = androidx.compose.ui.text.font.FontStyle.Italic
                                                        )
                                                    } else {
                                                        Text(
                                                            text = buildAnnotatedString {
                                                                withStyle(style = SpanStyle(fontWeight = FontWeight.Bold, fontSize = 12.sp, color = slateContent)) {
                                                                    append(reply.authorName)
                                                                }
                                                                append("  ")
                                                                withStyle(style = SpanStyle(fontSize = 12.sp, color = slateContent)) {
                                                                    append(reply.text)
                                                                }
                                                            },
                                                            lineHeight = 16.sp
                                                        )
                                                    }
                                                }

                                                Spacer(modifier = Modifier.height(2.dp))

                                                Row(
                                                    verticalAlignment = Alignment.CenterVertically,
                                                    horizontalArrangement = Arrangement.spacedBy(10.dp)
                                                ) {
                                                    Text(reply.timeAgo, fontSize = 10.sp, color = Color(0xFF687280))
                                                    
                                                    if (reply.likesCount > 0) {
                                                        Text(
                                                            "${reply.likesCount} liked",
                                                            fontSize = 10.sp,
                                                            color = Color(0xFF687280)
                                                        )
                                                    }
                                                }
                                            }

                                            if (!replyFlagged) {
                                                IconButton(
                                                    onClick = {
                                                        val nextState = !reply.likedByMe
                                                        val offset = if (nextState) 1 else -1
                                                        ConnectCommentsManager.updateComment(
                                                            targetType,
                                                            targetId,
                                                            reply.copy(
                                                                likedByMe = nextState,
                                                                likesCount = (reply.likesCount + offset).coerceAtLeast(0)
                                                            )
                                                        )
                                                    },
                                                    modifier = Modifier.size(24.dp)
                                                ) {
                                                    Text(
                                                        if (reply.likedByMe) "❤️" else "🖤",
                                                        fontSize = 11.sp
                                                    )
                                                }
                                            }
                                        }
                                    }
                                }
                            }
                        }

                        if (!isFlagged) {
                            IconButton(
                                onClick = {
                                    val nextState = !comment.likedByMe
                                    val offset = if (nextState) 1 else -1
                                    ConnectCommentsManager.updateComment(
                                        targetType,
                                        targetId,
                                        comment.copy(
                                            likedByMe = nextState,
                                            likesCount = (comment.likesCount + offset).coerceAtLeast(0)
                                        )
                                    )
                                },
                                modifier = Modifier.size(28.dp)
                            ) {
                                Text(
                                    if (comment.likedByMe) "❤️" else "🖤",
                                    fontSize = 13.sp
                                )
                            }
                        }
                    }
                }
            }
        }

        Spacer(modifier = Modifier.height(16.dp))

        Column(
            modifier = Modifier
                .fillMaxWidth()
                .background(Color.White)
        ) {
            if (replyingTo != null) {
                Row(
                    modifier = Modifier
                        .fillMaxWidth()
                        .background(Color(0xFFF1F5F9))
                        .padding(horizontal = 12.dp, vertical = 6.dp),
                    horizontalArrangement = Arrangement.SpaceBetween,
                    verticalAlignment = Alignment.CenterVertically
                ) {
                    Text(
                        "Replying to @${replyingTo?.authorName}",
                        fontSize = 11.sp,
                        fontWeight = FontWeight.Bold,
                        color = tealPrimary
                    )
                    IconButton(
                        onClick = { replyingTo = null },
                        modifier = Modifier.size(16.dp)
                    ) {
                        Icon(
                            Icons.Default.Clear,
                            contentDescription = "Cancel reply",
                            modifier = Modifier.size(12.dp),
                            tint = Color(0xFF687280)
                        )
                    }
                }
            }

            if (showMentionsDropdown) {
                Card(
                    modifier = Modifier
                        .fillMaxWidth()
                        .padding(bottom = 6.dp),
                    colors = CardDefaults.cardColors(containerColor = Color.White),
                    elevation = CardDefaults.cardElevation(defaultElevation = 4.dp),
                    shape = RoundedCornerShape(8.dp)
                ) {
                    LazyRow(
                        modifier = Modifier
                            .fillMaxWidth()
                            .padding(8.dp),
                        horizontalArrangement = Arrangement.spacedBy(8.dp)
                    ) {
                        items(filteredMentions) { candidate ->
                            Surface(
                                shape = RoundedCornerShape(16.dp),
                                color = tealPrimary.copy(alpha = 0.1f),
                                border = BorderStroke(1.dp, tealPrimary.copy(alpha = 0.3f)),
                                modifier = Modifier.clickable {
                                    val lastIdx = commentText.lastIndexOf('@')
                                    if (lastIdx != -1) {
                                        commentText = commentText.substring(0, lastIdx + 1) + candidate + " "
                                    }
                                    showMentionsDropdown = false
                                }
                            ) {
                                Text(
                                    text = "@$candidate",
                                    fontSize = 11.sp,
                                    fontWeight = FontWeight.Bold,
                                    color = tealPrimary,
                                    modifier = Modifier.padding(horizontal = 10.dp, vertical = 6.dp)
                                )
                            }
                        }
                    }
                }
            }

            Row(
                modifier = Modifier
                    .fillMaxWidth()
                    .padding(vertical = 4.dp),
                horizontalArrangement = Arrangement.SpaceEvenly
            ) {
                listOf("❤️", "🙌", "😂", "🔥", "👏", "😢", "😍", "👍").forEach { emoji ->
                    Text(
                        text = emoji,
                        fontSize = 20.sp,
                        modifier = Modifier
                            .clickable {
                                commentText += emoji
                            }
                            .padding(4.dp)
                    )
                }
            }

            Row(
                modifier = Modifier
                    .fillMaxWidth()
                    .padding(vertical = 4.dp),
                verticalAlignment = Alignment.CenterVertically
            ) {
                Box(
                    modifier = Modifier
                        .size(36.dp)
                        .background(Color(0xFFE2E8F0), CircleShape),
                    contentAlignment = Alignment.Center
                ) {
                    Text(userAvatar, fontSize = 18.sp)
                }

                Spacer(modifier = Modifier.width(10.dp))

                OutlinedTextField(
                    value = commentText,
                    onValueChange = { commentText = it },
                    placeholder = { Text("Add a comment...", fontSize = 13.sp) },
                    modifier = Modifier
                        .weight(1f)
                        .testTag("news_comment_input_box"),
                    singleLine = true,
                    shape = RoundedCornerShape(24.dp),
                    colors = OutlinedTextFieldDefaults.colors(
                        focusedBorderColor = tealPrimary,
                        unfocusedBorderColor = Color(0xFFCBD5E1)
                    )
                )

                Spacer(modifier = Modifier.width(8.dp))

                IconButton(
                    onClick = {
                        if (commentText.isNotBlank()) {
                            val isViolator = flaggedWords.any { commentText.contains(it, ignoreCase = true) }
                            if (isViolator) {
                                Toast.makeText(
                                    context,
                                    "This comment may violate community guidelines",
                                    Toast.LENGTH_LONG
                                ).show()
                            } else {
                                val brandNew = ConnectNewsComment(
                                    id = "c_${System.currentTimeMillis()}",
                                    authorName = userName,
                                    text = commentText,
                                    timeAgo = "Just now",
                                    authorAvatarEmoji = userAvatar,
                                    parentCommentId = replyingTo?.id
                                )

                                ConnectCommentsManager.addComment(targetType, targetId, brandNew)
                                if (replyingTo != null) {
                                    expandedReplies[replyingTo!!.id] = true
                                }
                                commentText = ""
                                replyingTo = null
                                Toast.makeText(context, "Comment posted!", Toast.LENGTH_SHORT).show()
                            }
                        }
                    },
                    modifier = Modifier
                        .size(40.dp)
                        .background(
                            if (commentText.isNotBlank()) tealPrimary else Color(0xFFF1F5F9),
                            CircleShape
                        )
                        .testTag("news_comment_submit_btn"),
                    enabled = commentText.isNotBlank()
                ) {
                    Text(
                        "✈️",
                        fontSize = 14.sp
                    )
                }
            }
        }
    }

    if (showContextMenuForComment != null) {
        val selectedComment = showContextMenuForComment!!
        val isOwnComment = selectedComment.authorName == userName
        
        AlertDialog(
            onDismissRequest = { showContextMenuForComment = null },
            title = { Text("Comment Options", fontWeight = FontWeight.Bold, fontSize = 16.sp, color = slateContent) },
            text = {
                Column(
                    modifier = Modifier.fillMaxWidth(),
                    verticalArrangement = Arrangement.spacedBy(12.dp)
                ) {
                    if (isOwnComment) {
                        Button(
                            onClick = {
                                editCommentText = selectedComment.text
                                showEditDialogForComment = selectedComment
                                showContextMenuForComment = null
                            },
                            colors = ButtonDefaults.buttonColors(containerColor = tealPrimary),
                            modifier = Modifier.fillMaxWidth()
                        ) {
                            Text("✏️ Edit Comment")
                        }

                        Button(
                            onClick = {
                                ConnectCommentsManager.deleteComment(targetType, targetId, selectedComment.id)
                                showContextMenuForComment = null
                                Toast.makeText(context, "Comment deleted", Toast.LENGTH_SHORT).show()
                            },
                            colors = ButtonDefaults.buttonColors(containerColor = Color.Red),
                            modifier = Modifier.fillMaxWidth()
                        ) {
                            Text("🗑️ Delete Comment")
                        }
                    } else {
                        Button(
                            onClick = {
                                ConnectCommentsManager.reportComment(selectedComment.id)
                                showContextMenuForComment = null
                                Toast.makeText(context, "Comment reported. Thank you!", Toast.LENGTH_LONG).show()
                            },
                            colors = ButtonDefaults.buttonColors(containerColor = Color(0xFFEA4335)),
                            modifier = Modifier.fillMaxWidth()
                        ) {
                            Text("⚠️ Report Comment")
                        }
                    }

                    Button(
                        onClick = {
                            val clipboard = context.getSystemService(Context.CLIPBOARD_SERVICE) as android.content.ClipboardManager
                            val clip = android.content.ClipData.newPlainText("Comment", selectedComment.text)
                            clipboard.setPrimaryClip(clip)
                            showContextMenuForComment = null
                            Toast.makeText(context, "Copied to clipboard", Toast.LENGTH_SHORT).show()
                        },
                        colors = ButtonDefaults.buttonColors(containerColor = Color(0xFF64748B)),
                        modifier = Modifier.fillMaxWidth()
                    ) {
                        Text("📋 Copy Comment Text")
                    }
                }
            },
            confirmButton = {
                TextButton(onClick = { showContextMenuForComment = null }) {
                    Text("Cancel", color = slateContent)
                }
            }
        )
    }

    if (showEditDialogForComment != null) {
        val selectedComment = showEditDialogForComment!!
        AlertDialog(
            onDismissRequest = { showEditDialogForComment = null },
            title = { Text("Edit Comment", fontWeight = FontWeight.Bold, fontSize = 16.sp, color = slateContent) },
            text = {
                OutlinedTextField(
                    value = editCommentText,
                    onValueChange = { editCommentText = it },
                    modifier = Modifier.fillMaxWidth(),
                    maxLines = 3
                )
            },
            confirmButton = {
                Button(
                    onClick = {
                        val isViolator = flaggedWords.any { editCommentText.contains(it, ignoreCase = true) }
                        if (isViolator) {
                            Toast.makeText(context, "This comment may violate community guidelines", Toast.LENGTH_LONG).show()
                        } else {
                            ConnectCommentsManager.updateComment(
                                targetType,
                                targetId,
                                selectedComment.copy(text = editCommentText)
                            )
                            showEditDialogForComment = null
                            Toast.makeText(context, "Comment updated", Toast.LENGTH_SHORT).show()
                        }
                    },
                    colors = ButtonDefaults.buttonColors(containerColor = tealPrimary)
                ) {
                    Text("Save")
                }
            },
            dismissButton = {
                TextButton(onClick = { showEditDialogForComment = null }) {
                    Text("Cancel", color = slateContent)
                }
            }
        )
    }
}

data class ConnectNewsItem(
    val id: String,
    val title: String,
    val category: String, // "City", "State", "National", "International"
    val locality: String,
    val summary: String,
    val content: String,
    val timeAgo: String,
    val initialLikes: Int,
    val source: String,
    val readTime: String,
    val bannerEmoji: String,
    val authorName: String,
    val gradientColors: List<Color>,
    val isNearMe: Boolean = false,
    val isBreaking: Boolean = false
)

// --- CROWMIX CONNECT MODULE 2 MODELS & MANAGER ---
data class ConnectChat(
    val id: String,
    val name: String,
    val avatarEmoji: String,
    val lastMessage: String,
    val timestamp: String,
    val unreadCount: Int = 0,
    val isGroup: Boolean = false,
    val isMuted: Boolean = false,
    val isPinned: Boolean = false,
    val contactPhone: String = "",
    val statusText: String = "",
    val city: String = "Noida",
    val locality: String = "",
    val groupAd: Boolean = false,
    val isColonyGroup: Boolean = false,
    val description: String = "",
    val membersCount: Int = 0,
    val joined: Boolean = true,
    val requiresApproval: Boolean = false,
    val requestedToJoin: Boolean = false,
    val mutualNeighborsCount: Int = 0,
    val landmarks: String = "",
    val rules: String = "",
    val announcementOnly: Boolean = false
)

enum class MessageStatus {
    SENT, DELIVERED, READ
}

data class ConnectMessage(
    val id: String,
    val conversationId: String,
    val senderId: String, // "me" or other
    val senderName: String,
    val senderAvatar: String,
    val text: String,
    val timestamp: String,
    val status: MessageStatus = MessageStatus.READ,
    val attachmentEmoji: String = "", 
    val replyToText: String? = null,
    val reactions: List<String> = emptyList()
)

data class ConnectStatus(
    val id: String,
    val name: String,
    val avatarEmoji: String,
    val emojiContent: String,
    val statusText: String,
    val timeAgo: String,
    var isViewed: Boolean = false,
    val isAd: Boolean = false,
    val adCTA: String = ""
)

data class CatalogProduct(
    val id: String,
    val name: String,
    val price: Double,
    val discountedPrice: Double? = null,
    val category: String,
    val description: String,
    val imageEmoji: String,
    val stockQty: Int? = null,
    val availableForOrder: Boolean = true,
    var isHidden: Boolean = false
)

data class BusinessAd(
    val id: String,
    val title: String,
    val emojiContent: String,
    val statusText: String,
    val linkProductId: String? = null,
    val durationType: String = "24h",
    var viewsCount: Int = 0,
    var tapsCount: Int = 0,
    val timestamp: String = "Just now"
)

data class BusinessReview(
    val authorName: String,
    val rating: Int,
    val text: String,
    val date: String
)

