@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun DeliveryActiveOrderScreen(
    order: DeliveryOrder,
    onDeliverSuccess: (DeliveryOrder) -> Unit,
    onBack: () -> Unit
) {
    val context = LocalContext.current
    var currentStep by remember { mutableStateOf(1) } // 1, 2, 3, 4
    var showDeliverSuccessDialog by remember { mutableStateOf(false) }

    if (showDeliverSuccessDialog) {
        AlertDialog(
            onDismissRequest = { /* forced action */ },
            title = { Text("Delivery Successful! 🎉", fontWeight = FontWeight.Black) },
            text = {
                Column {
                    Text("Superb work! You have successfully fulfilled shipment ${order.id}.")
                    Spacer(modifier = Modifier.height(8.dp))
                    Text(
                        text = "Estimated Earnings is now credited: ${order.estimatedEarnings}",
                        fontWeight = FontWeight.Bold,
                        color = Color(0xFF10B981)
                    )
                }
            },
            confirmButton = {
                Button(
                    onClick = {
                        showDeliverSuccessDialog = false
                        onDeliverSuccess(order)
                    },
                    colors = ButtonDefaults.buttonColors(containerColor = Color(0xFF14B8A6))
                ) {
                    Text("BACK TO PANEL")
                }
            }
        )
    }

    Scaffold(
        topBar = {
            TopAppBar(
                title = { Text("Active Delivery: ${order.id}", fontWeight = FontWeight.Bold, fontSize = 15.sp) },
                navigationIcon = {
                    IconButton(onClick = onBack) {
                        Icon(Icons.AutoMirrored.Filled.ArrowBack, contentDescription = "Exit view")
                    }
                },
                colors = TopAppBarDefaults.topAppBarColors(
                    containerColor = crowmixBlue,
                    titleContentColor = Color.White,
                    navigationIconContentColor = Color.White
                )
            )
        },
        containerColor = Color(0xFFF5F5F0)
    ) { innerPadding ->
        Column(
            modifier = Modifier
                .fillMaxSize()
                .padding(innerPadding)
                .verticalScroll(rememberScrollState())
                .padding(16.dp)
        ) {
            // Summary Card
            Card(
                modifier = Modifier.fillMaxWidth(),
                colors = CardDefaults.cardColors(containerColor = Color.White),
                shape = RoundedCornerShape(12.dp),
                elevation = CardDefaults.cardElevation(defaultElevation = 1.dp)
            ) {
                Column(modifier = Modifier.padding(16.dp)) {
                    Row(
                        modifier = Modifier.fillMaxWidth(),
                        horizontalArrangement = Arrangement.SpaceBetween,
                        verticalAlignment = Alignment.CenterVertically
                    ) {
                        Column {
                            Text("CUSTOMER DETAILS", fontSize = 10.sp, color = Color(0xFF687280), fontWeight = FontWeight.Bold)
                            Text(order.customerName, fontWeight = FontWeight.Bold, fontSize = 15.sp)
                        }
                        Box(
                            modifier = Modifier
                                .background(Color(0xFFF1F5F9), RoundedCornerShape(20.dp))
                                .padding(horizontal = 8.dp, vertical = 4.dp)
                        ) {
                            Text(order.phone, fontSize = 11.sp, fontWeight = FontWeight.SemiBold, color = Color.DarkGray)
                        }
                    }

                    Spacer(modifier = Modifier.height(8.dp))
                    Divider(color = Color(0xFFF1F5F9))
                    Spacer(modifier = Modifier.height(8.dp))

                    Text("🏬 PICKUP ADDRESS", fontSize = 10.sp, color = Color(0xFF0284C7), fontWeight = FontWeight.Bold)
                    Text(order.pickupAddress, fontSize = 12.sp, color = Color(0xFF1E293B))

                    Spacer(modifier = Modifier.height(8.dp))

                    Text("🏡 DELIVERY ADDRESS", fontSize = 10.sp, color = Color(0xFFEF4444), fontWeight = FontWeight.Bold)
                    Text(order.dropAddress, fontSize = 12.sp, color = Color(0xFF1E293B))

                    Spacer(modifier = Modifier.height(8.dp))
                    Divider(color = Color(0xFFF1F5F9))
                    Spacer(modifier = Modifier.height(8.dp))

                    // Items
                    Text("ITEMS ORDERED", fontSize = 10.sp, color = Color(0xFF687280), fontWeight = FontWeight.Bold)
                    order.itemsList.forEach { (item, price) ->
                        Row(
                            modifier = Modifier
                                .fillMaxWidth()
                                .padding(vertical = 2.dp),
                            horizontalArrangement = Arrangement.SpaceBetween
                        ) {
                            Text(item, fontSize = 11.sp, color = Color.DarkGray)
                            Text(price, fontSize = 11.sp, fontWeight = FontWeight.Bold)
                        }
                    }

                    Spacer(modifier = Modifier.height(8.dp))
                    Row(
                        modifier = Modifier.fillMaxWidth(),
                        horizontalArrangement = Arrangement.SpaceBetween
                    ) {
                        Text("Weight: ${order.weight}", fontSize = 11.sp, color = Color(0xFF687280))
                        Text("Total Amount: " + order.totalAmount, fontSize = 12.sp, fontWeight = FontWeight.Black, color = Color(0xFF1E293B))
                    }
                }
            }

            Spacer(modifier = Modifier.height(16.dp))

            // Interactive Map Label
            Text("📍 GOOGLE MAPS ROUTE ROUTING", fontSize = 12.sp, fontWeight = FontWeight.Bold, color = Color(0xFF687280))
            Spacer(modifier = Modifier.height(8.dp))

            // Interactive Map Composable
            InteractiveMapView(
                modifier = Modifier
                    .fillMaxWidth()
                    .height(220.dp)
            )

            Spacer(modifier = Modifier.height(16.dp))

            // Steps Buttons Title
            Text("⚙️ PROGRESS STEPS CONTROL", fontSize = 11.sp, fontWeight = FontWeight.Bold, color = Color(0xFF687280))
            Spacer(modifier = Modifier.height(8.dp))

            // Steps section column
            Column(
                modifier = Modifier.fillMaxWidth(),
                verticalArrangement = Arrangement.spacedBy(8.dp)
            ) {
                // Step 1: Picking up
                val step1Done = currentStep > 1
                val step1Enabled = currentStep == 1
                Button(
                    onClick = { currentStep = 2 },
                    enabled = step1Enabled,
                    colors = ButtonDefaults.buttonColors(
                        containerColor = if (step1Done) Color(0xFF10B981) else Color.White,
                        contentColor = if (step1Done) Color.White else Color(0xFF687280),
                        disabledContainerColor = if (step1Done) Color(0xFF10B981) else Color(0xFFE2E8F0),
                        disabledContentColor = if (step1Done) Color.White else Color(0xFF9CA3AF)
                    ),
                    modifier = Modifier.fillMaxWidth(),
                    shape = RoundedCornerShape(8.dp),
                    border = if (!step1Done) BorderStroke(1.dp, Color(0xFF687280)) else null
                ) {
                    Row(verticalAlignment = Alignment.CenterVertically) {
                        if (step1Done) Text("✓ ", fontWeight = FontWeight.Bold, color = Color.White)
                        Text("1. Picking up" + (if (step1Done) " (Completed)" else ""))
                    }
                }

                // Step 2: Out from shop
                val step2Done = currentStep > 2
                val step2Enabled = currentStep == 2
                Button(
                    onClick = { currentStep = 3 },
                    enabled = step2Enabled,
                    colors = ButtonDefaults.buttonColors(
                        containerColor = if (step2Done) Color(0xFF10B981) else Color.White,
                        contentColor = if (step2Done) Color.White else Color(0xFF687280),
                        disabledContainerColor = if (step2Done) Color(0xFF10B981) else Color(0xFFE2E8F0),
                        disabledContentColor = if (step2Done) Color.White else Color(0xFF9CA3AF)
                    ),
                    modifier = Modifier.fillMaxWidth(),
                    shape = RoundedCornerShape(8.dp),
                    border = if (!step2Done) BorderStroke(1.dp, Color(0xFF687280)) else null
                ) {
                    Row(verticalAlignment = Alignment.CenterVertically) {
                        if (step2Done) Text("✓ ", fontWeight = FontWeight.Bold, color = Color.White)
                        Text("2. Out from shop" + (if (step2Done) " (Completed)" else ""))
                    }
                }

                // Step 3: On the way
                val step3Done = currentStep > 3
                val step3Enabled = currentStep == 3
                Button(
                    onClick = { currentStep = 4 },
                    enabled = step3Enabled,
                    colors = ButtonDefaults.buttonColors(
                        containerColor = if (step3Done) Color(0xFF10B981) else Color.White,
                        contentColor = if (step3Done) Color.White else Color(0xFF687280),
                        disabledContainerColor = if (step3Done) Color(0xFF10B981) else Color(0xFFE2E8F0),
                        disabledContentColor = if (step3Done) Color.White else Color(0xFF9CA3AF)
                    ),
                    modifier = Modifier.fillMaxWidth(),
                    shape = RoundedCornerShape(8.dp),
                    border = if (!step3Done) BorderStroke(1.dp, Color(0xFF687280)) else null
                ) {
                    Row(verticalAlignment = Alignment.CenterVertically) {
                        if (step3Done) Text("✓ ", fontWeight = FontWeight.Bold, color = Color.White)
                        Text("3. On the way" + (if (step3Done) " (Completed)" else ""))
                    }
                }

                // Step 4: Delivered (teal filled)
                val step4Enabled = currentStep == 4
                Button(
                    onClick = {
                        showDeliverSuccessDialog = true
                    },
                    enabled = step4Enabled,
                    colors = ButtonDefaults.buttonColors(
                        containerColor = Color(0xFF14B8A6), // teal
                        contentColor = Color.White,
                        disabledContainerColor = Color(0xFF94A3B8),
                        disabledContentColor = Color.White.copy(alpha = 0.6f)
                    ),
                    modifier = Modifier.fillMaxWidth(),
                    shape = RoundedCornerShape(8.dp)
                ) {
                    Text("4. Delivered (Ready to Fulfill)", fontWeight = FontWeight.Bold)
                }
            }

            Spacer(modifier = Modifier.height(16.dp))
            Divider()
            Spacer(modifier = Modifier.height(16.dp))

            // Extra buttons row
            Row(
                modifier = Modifier.fillMaxWidth(),
                horizontalArrangement = Arrangement.spacedBy(16.dp)
            ) {
                OutlinedButton(
                    onClick = {
                        Toast.makeText(context, "Initiating call to customer ${order.phone}...", Toast.LENGTH_LONG).show()
                    },
                    modifier = Modifier.weight(1f),
                    border = BorderStroke(1.dp, Color(0xFF687280))
                ) {
                    Text("Call Customer", color = Color.DarkGray)
                }

                OutlinedButton(
                    onClick = {
                        Toast.makeText(context, "Issue logged. Support staff informed.", Toast.LENGTH_LONG).show()
                    },
                    modifier = Modifier.weight(1f),
                    border = BorderStroke(1.dp, Color.Red),
                    colors = ButtonDefaults.outlinedButtonColors(contentColor = Color.Red)
                ) {
                    Text("Report Issue")
                }
            }
        }
    }
}

// --------------------------------------------------------------------------
// MOCKED INTERACTIVE MAP
// --------------------------------------------------------------------------

@Composable
fun InteractiveMapView(modifier: Modifier = Modifier) {
    var offset by remember { mutableStateOf(androidx.compose.ui.geometry.Offset.Zero) }

    Box(
        modifier = modifier
            .background(Color(0xFFE2E8F0), RoundedCornerShape(12.dp))
            .pointerInput(Unit) {
                detectDragGestures { change, dragAmount ->
                    change.consume()
                    offset += dragAmount
                }
            }
            .clip(RoundedCornerShape(12.dp))
    ) {
        Canvas(modifier = Modifier.fillMaxSize()) {
            val width = size.width
            val height = size.height
            
            // Draw grid lines representing city roads block structure
            val stepVal = 44f
            val startX = (offset.x % stepVal)
            val startY = (offset.y % stepVal)

            var xPos = startX
            while (xPos < width) {
                drawLine(
                    color = Color.White,
                    start = androidx.compose.ui.geometry.Offset(xPos, 0f),
                    end = androidx.compose.ui.geometry.Offset(xPos, height),
                    strokeWidth = 3f
                )
                xPos += stepVal
            }

            var yPos = startY
            while (yPos < height) {
                drawLine(
                    color = Color.White,
                    start = androidx.compose.ui.geometry.Offset(0f, yPos),
                    end = androidx.compose.ui.geometry.Offset(width, yPos),
                    strokeWidth = 3f
                )
                yPos += stepVal
            }

            // Centralized markers
            val center = androidx.compose.ui.geometry.Offset(width / 2, height / 2)
            val pX = center.x - 120f + (offset.x * 0.4f)
            val pY = center.y + 40f + (offset.y * 0.4f)
            val dX = center.x + 120f + (offset.x * 0.4f)
            val dY = center.y - 80f + (offset.y * 0.4f)

            // Draw route polyline
            drawLine(
                color = Color(0xFF0EA5E9),
                start = androidx.compose.ui.geometry.Offset(pX, pY),
                end = androidx.compose.ui.geometry.Offset(dX, dY),
                strokeWidth = 6f
            )

            // Draw Pickup circular container
            drawCircle(
                color = Color(0xFF0284C7),
                radius = 12f,
                center = androidx.compose.ui.geometry.Offset(pX, pY)
            )
            // Draw Drop circular container
            drawCircle(
                color = Color(0xFFEF4444),
                radius = 12f,
                center = androidx.compose.ui.geometry.Offset(dX, dY)
            )
        }

        // Floating address tag overlays
        Box(
            modifier = Modifier
                .align(Alignment.Center)
                .offset(x = (-45).dp, y = 20.dp)
                .background(Color(0xFF0284C7), RoundedCornerShape(4.dp))
                .padding(horizontal = 4.dp, vertical = 2.dp)
        ) {
            Text("🏬 Shop", color = Color.White, fontSize = 8.sp, fontWeight = FontWeight.Bold)
        }

        Box(
            modifier = Modifier
                .align(Alignment.Center)
                .offset(x = 55.dp, y = (-35).dp)
                .background(Color(0xFFEF4444), RoundedCornerShape(4.dp))
                .padding(horizontal = 4.dp, vertical = 2.dp)
        ) {
            Text("🏠 Home", color = Color.White, fontSize = 8.sp, fontWeight = FontWeight.Bold)
        }

        // Compass / GPS indicators
        Box(
            modifier = Modifier
                .align(Alignment.TopEnd)
                .padding(8.dp)
                .background(Color.White.copy(alpha = 0.9f), CircleShape)
                .size(28.dp),
            contentAlignment = Alignment.Center
        ) {
            Text("🧭", fontSize = 12.sp)
        }
    }
}

