@Composable
fun OrderHistoryTabContent(
    acceptedHistory: List<Pair<String, String>>,
    onHistoryItemClick: (String) -> Unit
) {
    var selectedHistoryTab by remember { mutableStateOf("Accepted") } // Accepted, Declined, Total

    Column(
        modifier = Modifier
            .fillMaxSize()
            .padding(16.dp)
    ) {
        // Sub-tabs switcher row
        Row(
            modifier = Modifier
                .fillMaxWidth()
                .clip(RoundedCornerShape(8.dp))
                .background(Color(0xFFE2E8F0)),
            horizontalArrangement = Arrangement.SpaceBetween
        ) {
            listOf("Accepted", "Declined", "Total").forEach { tabLabel ->
                val isSelected = selectedHistoryTab == tabLabel
                Box(
                    modifier = Modifier
                        .weight(1f)
                        .clickable { selectedHistoryTab = tabLabel }
                        .background(if (isSelected) crowmixBlue else Color.Transparent)
                        .padding(vertical = 10.dp),
                    contentAlignment = Alignment.Center
                ) {
                    Text(
                        text = tabLabel,
                        fontWeight = if (isSelected) FontWeight.Bold else FontWeight.Medium,
                        color = if (isSelected) Color.White else Color.DarkGray,
                        fontSize = 12.sp
