@Composable
fun TaxiOffReasonDialog(
    title: String,
    subtitle: String,
    onDismiss: () -> Unit,
    onConfirmOffline: (String) -> Unit
) {
    var selectedReason by remember { mutableStateOf("No driver available") }
    var customReason by remember { mutableStateOf("") }
    val reasons = listOf("No driver available", "Break time", "Vehicle service", "Area restricted")

    AlertDialog(
        onDismissRequest = onDismiss,
        title = { Text(title, fontWeight = FontWeight.Bold) },
        text = {
            Column(modifier = Modifier.fillMaxWidth()) {
                Text(subtitle, fontSize = 12.sp, color = Color(0xFF687280))
                Spacer(modifier = Modifier.height(16.dp))
                reasons.forEach { r ->
                    Row(
                        modifier = Modifier
                            .fillMaxWidth()
                            .clickable { selectedReason = r }
                            .padding(vertical = 6.dp),
                        verticalAlignment = Alignment.CenterVertically
                    ) {
                        RadioButton(selected = (selectedReason == r), onClick = { selectedReason = r })
                        Spacer(modifier = Modifier.width(8.dp))
                        Text(r, fontSize = 13.sp)
                    }
                }
                Row(
                    modifier = Modifier
                        .fillMaxWidth()
                        .clickable { selectedReason = "Other" }
                        .padding(vertical = 6.dp),
                    verticalAlignment = Alignment.CenterVertically
                ) {
                    RadioButton(selected = (selectedReason == "Other"), onClick = { selectedReason = "Other" })
                    Spacer(modifier = Modifier.width(8.dp))
                    Text("Other Reason", fontSize = 13.sp)
                }
                if (selectedReason == "Other") {
                    Spacer(modifier = Modifier.height(8.dp))
                    OutlinedTextField(
                        value = customReason,
                        onValueChange = { customReason = it },
                        label = { Text("Enter offline reason...") },
                        singleLine = true,
                        modifier = Modifier.fillMaxWidth()
                    )
                }
            }
        },
        confirmButton = {
            Button(
                onClick = {
                    val res = if (selectedReason == "Other" && customReason.isNotEmpty()) customReason else selectedReason
                    onConfirmOffline(res)
                },
                colors = ButtonDefaults.buttonColors(containerColor = crowmixBlue)
            ) {
                Text("Confirm")
            }
        },
        dismissButton = {
            TextButton(onClick = onDismiss) { Text("Cancel", color = Color(0xFF687280)) }
        }
    )
}

@Composable
fun TaxiInteractiveMapView(
    modifier: Modifier = Modifier,
    pickupLabel: String,
    dropLabel: String
) {
    var offset by remember { mutableStateOf(androidx.compose.ui.geometry.Offset.Zero) }
    Box(
        modifier = modifier
            .background(Color(0xFFE2E8F0), RoundedCornerShape(12.dp))
            .pointerInput(Unit) {
                detectDragGestures { change, dragAmount ->
                    change.consume()
                    offset += dragAmount
                }
            }
            .clip(RoundedCornerShape(12.dp))
    ) {
        Canvas(modifier = Modifier.fillMaxSize()) {
            val w = size.width
            val h = size.height
            val stepVal = 44f
            val startX = (offset.x % stepVal)
            val startY = (offset.y % stepVal)
            var xPos = startX
            while (xPos < w) {
                drawLine(Color.White, androidx.compose.ui.geometry.Offset(xPos, 0f), androidx.compose.ui.geometry.Offset(xPos, h), 3f)
                xPos += stepVal
            }
            var yPos = startY
            while (yPos < h) {
                drawLine(Color.White, androidx.compose.ui.geometry.Offset(0f, yPos), androidx.compose.ui.geometry.Offset(w, yPos), 3f)
                yPos += stepVal
            }
            val center = androidx.compose.ui.geometry.Offset(w / 2, h / 2)
            val pX = center.x - 100f + (offset.x * 0.4f)
            val pY = center.y + 30f + (offset.y * 0.4f)
            val dX = center.x + 100f + (offset.x * 0.4f)
            val dY = center.y - 60f + (offset.y * 0.4f)
            drawLine(Color(0xFF0EA5E9), androidx.compose.ui.geometry.Offset(pX, pY), androidx.compose.ui.geometry.Offset(dX, dY), 6f)
            drawCircle(Color(0xFF0284C7), 12f, androidx.compose.ui.geometry.Offset(pX, pY))
            drawCircle(Color(0xFFEF4444), 12f, androidx.compose.ui.geometry.Offset(dX, dY))
        }
        Box(
            modifier = Modifier
                .align(Alignment.Center)
                .offset(x = (-40).dp, y = 15.dp)
                .background(Color(0xFF0284C7), RoundedCornerShape(4.dp))
                .padding(horizontal = 4.dp, vertical = 2.dp)
        ) {
            Text("📍 $pickupLabel", color = Color.White, fontSize = 8.sp, fontWeight = FontWeight.Bold)
        }
        Box(
            modifier = Modifier
                .align(Alignment.Center)
                .offset(x = 55.dp, y = (-25).dp)
                .background(Color(0xFFEF4444), RoundedCornerShape(4.dp))
                .padding(horizontal = 4.dp, vertical = 2.dp)
        ) {
            Text("🏁 $dropLabel", color = Color.White, fontSize = 8.sp, fontWeight = FontWeight.Bold)
        }
        Box(
            modifier = Modifier
                .align(Alignment.TopEnd)
                .padding(8.dp)
                .background(Color.White.copy(alpha = 0.9f), CircleShape)
                .size(28.dp),
            contentAlignment = Alignment.Center
        ) {
            Text("🧭", fontSize = 12.sp)
        }
    }
}

@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun TaxiPanelScreen(
    onSignOut: () -> Unit
) {
    var isOnline by remember { mutableStateOf(true) }
    var isNotifOn by remember { mutableStateOf(true) }
    var selectedTab by remember { mutableStateOf("Orders") }
    val drawerState = rememberDrawerState(initialValue = DrawerValue.Closed)
    val scope = rememberCoroutineScope()
    val context = LocalContext.current

    var showOfflineDialogReason by remember { mutableStateOf(false) }
    var showNotifDialogReason by remember { mutableStateOf(false) }
    var offlineReason by remember { mutableStateOf("No driver available") }

    var activeIncomingRide by remember { mutableStateOf<TaxiRide?>(null) }
    var activeRideInProgress by remember { mutableStateOf<TaxiRide?>(null) }

    var taxiRidesList by remember {
        mutableStateOf(
            listOf(
                TaxiRide("RIDE-881", "Rahul Sharma", "+91 98XXX XXXXX", "Koregaon Park", "Viman Nagar", "4.1 km", "₹120", "Standard Taxi", "Pending Request", Color(0xFFEA580C)),
                TaxiRide("RIDE-879", "Simran Jeet", "+91 98XXX XXXXX", "Camp", "Swargate", "2.8 km", "₹80", "Standard Taxi", "Pending Request", Color(0xFF0284C7))
            )
        )
    }

    var taxiHistoryAccepted by remember {
        mutableStateOf(
            listOf(
                TaxiRide("RIDE-870", "Sneha Patil", "+91 98XXX XXXXX", "Camp", "Swargate", "2.8 km", "₹80", "Standard Taxi", "Completed", Color(0xFF16A34A))
            )
        )
    }

    if (showOfflineDialogReason) {
        TaxiOffReasonDialog(
            title = "Going offline?",
            subtitle = "Select a reason so customers are Informed",
            onDismiss = { showOfflineDialogReason = false },
            onConfirmOffline = { r ->
                offlineReason = r
                isOnline = false
                showOfflineDialogReason = false
            }
        )
    }

    if (showNotifDialogReason) {
        TaxiOffReasonDialog(
            title = "Turn off Notifications?",
            subtitle = "Select a reason to disable new ride alert sound",
            onDismiss = { showNotifDialogReason = false },
            onConfirmOffline = { r ->
                isNotifOn = false
                showNotifDialogReason = false
                Toast.makeText(context, "Notifications muted: $r", Toast.LENGTH_SHORT).show()
            }
        )
    }

    if (activeIncomingRide != null) {
        TaxiIncomingRideScreen(
            ride = activeIncomingRide!!,
            onDecline = { activeIncomingRide = null },
            onAccept = { r ->
                activeIncomingRide = null
                activeRideInProgress = r
            }
        )
    } else if (activeRideInProgress != null) {
        TaxiRideStartScreen(
            ride = activeRideInProgress!!,
            onBack = { activeRideInProgress = null },
            onRideComplete = { r ->
                taxiRidesList = taxiRidesList.filter { it.id != r.id }
                taxiHistoryAccepted = listOf(r.copy(status = "Completed", statusColor = Color(0xFF16A34A))) + taxiHistoryAccepted
                activeRideInProgress = null
            }
        )
    } else {
        ModalNavigationDrawer(
            drawerState = drawerState,
            drawerContent = {
                ModalDrawerSheet {
                    Spacer(modifier = Modifier.height(16.dp))
                    Row(
                        modifier = Modifier.padding(horizontal = 20.dp, vertical = 12.dp),
                        verticalAlignment = Alignment.CenterVertically
                    ) {
                        Box(
                            modifier = Modifier
                                .size(48.dp)
                                .clip(CircleShape)
                                .background(Color(0xFFFEF9C3)),
                            contentAlignment = Alignment.Center
                        ) { Text("🚖", fontSize = 24.sp) }
                        Spacer(modifier = Modifier.width(16.dp))
                        Column {
                            Text("Tanmay Desai", fontWeight = FontWeight.Bold, fontSize = 16.sp, color = Color(0xFF0F172A))
                            Text("Taxi Partner | TX-8821", fontSize = 11.sp, color = Color(0xFF687280))
                        }
                    }
                    Divider(modifier = Modifier.padding(vertical = 8.dp))
                    val items = listOf("Orders" to Icons.Filled.LocalTaxi, "Order History" to Icons.Filled.History, "Payments" to Icons.Filled.Payment, "My Profile" to Icons.Filled.Person)
                    items.forEach { (tab, icon) ->
                        NavigationDrawerItem(
                            label = { Text(tab, fontWeight = FontWeight.Bold) },
                            selected = selectedTab == tab,
                            onClick = {
                                selectedTab = tab
                                scope.launch { drawerState.close() }
                            },
                            icon = { Icon(icon, tab) },
                            modifier = Modifier.padding(horizontal = 12.dp, vertical = 4.dp)
                        )
                    }
                    Spacer(modifier = Modifier.height(16.dp))
                    Divider(modifier = Modifier.padding(horizontal = 24.dp))
                    Spacer(modifier = Modifier.height(16.dp))
                    NavigationDrawerItem(
                        label = { Text("Sign Out", color = Color.Red, fontWeight = FontWeight.Bold) },
                        selected = false,
                        onClick = {
                            scope.launch { drawerState.close() }
                            onSignOut()
                        },
                        icon = { Icon(Icons.Filled.ExitToApp, "Sign Out", tint = Color.Red) },
                        modifier = Modifier.padding(horizontal = 12.dp)
                    )
                }
            }
        ) {
            Scaffold(
                topBar = {
                    TopAppBar(
                        title = { Text("Taxi Panel", fontSize = 16.sp, fontWeight = FontWeight.Black) },
                        navigationIcon = {
                            IconButton(onClick = { scope.launch { drawerState.open() } }) {
                                Icon(Icons.Filled.Menu, "Toggle Drawer")
                            }
                        },
                        actions = {
                            Button(
                                onClick = {
                                    if (isNotifOn) showNotifDialogReason = true else isNotifOn = true
                                },
                                colors = ButtonDefaults.buttonColors(
                                    containerColor = if (isNotifOn) Color(0xFF10B981) else Color(0xFF687280)
                                ),
                                contentPadding = PaddingValues(horizontal = 10.dp),
                                modifier = Modifier
                                    .padding(end = 12.dp)
                                    .height(32.dp)
                                    .testTag("taxi_notif_toggle_btn")
                            ) {
                                Icon(
                                    imageVector = if (isNotifOn) Icons.Filled.Notifications else Icons.Filled.NotificationsOff,
                                    contentDescription = null,
                                    tint = Color.White,
                                    modifier = Modifier.size(16.dp)
                                )
                                Spacer(modifier = Modifier.width(4.dp))
                                Text(if (isNotifOn) "Notif ON" else "Notif OFF", fontSize = 11.sp, fontWeight = FontWeight.Bold)
                            }
                        },
                        colors = TopAppBarDefaults.topAppBarColors(
                            containerColor = crowmixBlue,
                            titleContentColor = Color.White,
                            navigationIconContentColor = Color.White
                        )
                    )
                },
                containerColor = Color(0xFFF1F5F9)
            ) { innerPadding ->
                Column(
                    modifier = Modifier
                        .fillMaxSize()
                        .padding(innerPadding)
                ) {
                    val barColor = if (isOnline) Color(0xFF10B981) else Color(0xFFEF4444)
                    val barText = if (isOnline) "Online - Accepting rides" else "Offline - $offlineReason"
                    Box(
                        modifier = Modifier
                            .fillMaxWidth()
                            .background(barColor)
                            .padding(vertical = 6.dp),
                        contentAlignment = Alignment.Center
                    ) {
                        Text(barText, color = Color.White, fontSize = 12.sp, fontWeight = FontWeight.Bold)
                    }

                    when (selectedTab) {
                        "Orders" -> {
                            LazyColumn(
                                modifier = Modifier
                                    .fillMaxSize()
                                    .padding(16.dp),
                                verticalArrangement = Arrangement.spacedBy(16.dp)
                            ) {
                                item {
                                    Card(
                                        modifier = Modifier.fillMaxWidth(),
                                        colors = CardDefaults.cardColors(containerColor = Color.White),
                                        shape = RoundedCornerShape(12.dp)
                                    ) {
                                        Row(
                                            modifier = Modifier
                                                .fillMaxWidth()
                                                .padding(14.dp),
                                            verticalAlignment = Alignment.CenterVertically,
                                            horizontalArrangement = Arrangement.SpaceBetween
                                        ) {
                                            Row(verticalAlignment = Alignment.CenterVertically) {
                                                Icon(Icons.Filled.LocalTaxi, null, tint = if (isOnline) Color(0xFFEAB308) else Color(0xFF687280))
                                                Spacer(modifier = Modifier.width(8.dp))
                                                Text("Panel Status", fontSize = 14.sp, fontWeight = FontWeight.Bold)
                                            }
                                            Switch(
                                                checked = isOnline,
                                                onCheckedChange = { checked ->
                                                    if (checked) isOnline = true else showOfflineDialogReason = true
                                                },
                                                modifier = Modifier.testTag("taxi_panel_status_switch")
                                            )
                                        }
                                    }
                                }
                                item {
                                    Row(
                                        modifier = Modifier.fillMaxWidth(),
                                        horizontalArrangement = Arrangement.spacedBy(12.dp)
                                    ) {
                                        Card(
                                            modifier = Modifier.weight(1f),
                                            colors = CardDefaults.cardColors(containerColor = Color.White)
                                        ) {
                                            Column(modifier = Modifier.padding(16.dp)) {
                                                Text("Rides today", fontSize = 11.sp, color = Color(0xFF687280), fontWeight = FontWeight.SemiBold)
                                                Spacer(modifier = Modifier.height(8.dp))
                                                Text("9", fontSize = 24.sp, fontWeight = FontWeight.Black)
                                            }
                                        }
                                        Card(
                                            modifier = Modifier.weight(1f),
                                            colors = CardDefaults.cardColors(containerColor = Color.White)
                                        ) {
                                            Column(modifier = Modifier.padding(16.dp)) {
                                                Text("Earnings", fontSize = 11.sp, color = Color(0xFF687280), fontWeight = FontWeight.SemiBold)
                                                Spacer(modifier = Modifier.height(8.dp))
                                                Text("₹2,180", fontSize = 24.sp, fontWeight = FontWeight.Black, color = Color(0xFF10B981))
                                            }
                                        }
                                    }
                                }
                                item {
                                    Text("Pending ride requests", fontWeight = FontWeight.Bold, fontSize = 15.sp, color = Color(0xFF0F172A))
                                }
                                if (!isOnline) {
                                    item {
                                        Box(modifier = Modifier.fillMaxWidth().padding(32.dp), contentAlignment = Alignment.Center) {
                                            Text("You are offline. Toggle status online to view requests.", color = Color(0xFF687280), fontSize = 13.sp)
                                        }
                                    }
                                } else if (taxiRidesList.isEmpty()) {
                                    item {
                                        Box(modifier = Modifier.fillMaxWidth().padding(32.dp), contentAlignment = Alignment.Center) {
                                            Text("No requests right now.", color = Color(0xFF687280), fontSize = 13.sp)
                                        }
                                    }
                                } else {
                                    items(taxiRidesList) { ride ->
                                        Card(
                                            modifier = Modifier
                                                .fillMaxWidth()
                                                .clickable { activeIncomingRide = ride }
                                                .testTag("taxi_ride_card_${ride.id}"),
                                            colors = CardDefaults.cardColors(containerColor = Color.White),
                                            shape = RoundedCornerShape(12.dp)
                                        ) {
                                            Row(
                                                modifier = Modifier.padding(16.dp),
                                                horizontalArrangement = Arrangement.SpaceBetween,
                                                verticalAlignment = Alignment.CenterVertically
                                            ) {
                                                Column {
                                                    Text("${ride.id} | ${ride.pickup} ➔ ${ride.drop}", fontWeight = FontWeight.Bold, fontSize = 14.sp)
                                                    Text("${ride.distance} | ${ride.cabType} | ${ride.fare}", fontSize = 12.sp, color = Color(0xFF687280))
                                                }
                                                Icon(Icons.Filled.ChevronRight, "View")
                                            }
                                        }
                                    }
                                }
                            }
                        }
                        "Order History" -> {
                            TaxiOrderHistoryTabContent(taxiHistoryAccepted)
                        }
                        "Payments" -> {
                            TaxiPaymentsTabContent()
                        }
                        "My Profile" -> {
                            TaxiProfileTabContent(onSignOut)
                        }
                    }
                }
            }
        }
    }
}

@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun TaxiIncomingRideScreen(
    ride: TaxiRide,
    onDecline: () -> Unit,
    onAccept: (TaxiRide) -> Unit
) {
    var timeLeft by remember { mutableStateOf(30) }
    val context = LocalContext.current

    LaunchedEffect(timeLeft) {
        if (timeLeft > 0) {
            delay(1000L)
            timeLeft--
        } else {
            Toast.makeText(context, "Order timed out", Toast.LENGTH_SHORT).show()
            onDecline()
        }
    }

    Scaffold(
        topBar = {
            TopAppBar(
                title = { Text("New Ride Request!", fontWeight = FontWeight.Bold) },
                colors = TopAppBarDefaults.topAppBarColors(containerColor = crowmixBlue, titleContentColor = Color.White)
            )
        }
    ) { innerPadding ->
        Column(
            modifier = Modifier
                .fillMaxSize()
                .padding(innerPadding)
                .padding(24.dp),
            horizontalAlignment = Alignment.CenterHorizontally,
            verticalArrangement = Arrangement.SpaceBetween
        ) {
            Column(horizontalAlignment = Alignment.CenterHorizontally, modifier = Modifier.fillMaxWidth()) {
                Spacer(modifier = Modifier.height(16.dp))
                Box(contentAlignment = Alignment.Center, modifier = Modifier.size(100.dp)) {
                    CircularProgressIndicator(
                        progress = { timeLeft / 30f },
                        modifier = Modifier.fillMaxSize(),
                        color = Color(0xFF0D9488),
                        strokeWidth = 6.dp
                    )
                    Text("$timeLeft", fontSize = 28.sp, fontWeight = FontWeight.Black, color = Color(0xFF0D9488))
                }
                Spacer(modifier = Modifier.height(24.dp))
                Card(
                    modifier = Modifier.fillMaxWidth(),
                    colors = CardDefaults.cardColors(containerColor = Color.White)
                ) {
                    Column(modifier = Modifier.padding(16.dp)) {
                        Text("Customer: ${ride.customerName} (${ride.phone})", fontWeight = FontWeight.Bold, fontSize = 15.sp)
                        Spacer(modifier = Modifier.height(8.dp))
                        Text("Pickup: ${ride.pickup}", fontSize = 13.sp)
                        Text("Drop: ${ride.drop}", fontSize = 13.sp)
                        Text("Distance: ${ride.distance}", fontSize = 13.sp)
                        Text("Fare: ${ride.fare}", fontSize = 15.sp, fontWeight = FontWeight.Bold, color = Color(0xFF0D9488))
                        Text("Cab Type: ${ride.cabType}", fontSize = 13.sp)
                    }
                }
            }
            Row(modifier = Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.spacedBy(16.dp)) {
                OutlinedButton(
                    onClick = onDecline,
                    border = BorderStroke(1.5.dp, Color.Red),
                    colors = ButtonDefaults.outlinedButtonColors(contentColor = Color.Red),
                    modifier = Modifier.weight(1f).height(48.dp)
                ) { Text("Decline", fontWeight = FontWeight.Bold) }
                Button(
                    onClick = { onAccept(ride) },
                    colors = ButtonDefaults.buttonColors(containerColor = Color(0xFF0D9488)),
                    modifier = Modifier.weight(1f).height(48.dp)
                ) { Text("Accept", fontWeight = FontWeight.Bold) }
            }
        }
    }
}

@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun TaxiRideStartScreen(
    ride: TaxiRide,
    onBack: () -> Unit,
    onRideComplete: (TaxiRide) -> Unit
) {
    var codeInput by remember { mutableStateOf("") }
    var isVerified by remember { mutableStateOf(false) }
    var codeError by remember { mutableStateOf("") }
    var isReachedDestination by remember { mutableStateOf(false) }
    var showSuccessDialog by remember { mutableStateOf(false) }
    var paymentMode by remember { mutableStateOf("Cash") }
    val context = LocalContext.current

    if (showSuccessDialog) {
        AlertDialog(
            onDismissRequest = {},
            title = { Text("Ride Completed Successfully! 🏁") },
            text = { Text("Your ride earnings of ${ride.fare} have been added to your balance.") },
            confirmButton = {
                Button(
                    onClick = {
                        showSuccessDialog = false
                        onRideComplete(ride)
                    },
                    colors = ButtonDefaults.buttonColors(containerColor = crowmixBlue)
                ) { Text("OK") }
            }
        )
    }

    Scaffold(
        topBar = {
            TopAppBar(
                title = { Text("Ride Accepted", fontWeight = FontWeight.Bold) },
                navigationIcon = {
                    IconButton(onClick = onBack) {
                        Icon(Icons.AutoMirrored.Filled.ArrowBack, "Back")
                    }
                },
                colors = TopAppBarDefaults.topAppBarColors(containerColor = crowmixBlue, titleContentColor = Color.White, navigationIconContentColor = Color.White)
            )
        }
    ) { innerPadding ->
        Column(
            modifier = Modifier
                .fillMaxSize()
                .padding(innerPadding)
                .padding(16.dp)
                .verticalScroll(rememberScrollState()),
            verticalArrangement = Arrangement.spacedBy(16.dp)
        ) {
            Card(modifier = Modifier.fillMaxWidth(), colors = CardDefaults.cardColors(containerColor = Color.White)) {
                Column(modifier = Modifier.padding(16.dp)) {
                    Text(ride.customerName, fontWeight = FontWeight.Bold, fontSize = 16.sp)
                    Text(ride.phone, fontSize = 12.sp, color = Color(0xFF687280))
                    Divider(modifier = Modifier.padding(vertical = 8.dp))
                    Text("Pickup: ${ride.pickup}", fontSize = 13.sp)
                    Text("Drop: ${ride.drop}", fontSize = 13.sp)
                    Text("Distance: ${ride.distance} | Fare: ${ride.fare}", fontSize = 13.sp, fontWeight = FontWeight.Medium)
                    Text("Cab Type: ${ride.cabType}", fontSize = 13.sp, color = Color(0xFF687280))
                }
            }

            Card(
                modifier = Modifier.fillMaxWidth(),
                colors = CardDefaults.cardColors(containerColor = Color.White),
                border = BorderStroke(2.dp, if (isVerified) Color(0xFF10B981) else Color(0xFFF59E0B))
            ) {
                Column(modifier = Modifier.padding(16.dp)) {
                    Row(verticalAlignment = Alignment.CenterVertically) {
                        Icon(
                            imageVector = if (isVerified) Icons.Filled.CheckCircle else Icons.Filled.VerifiedUser,
                            contentDescription = null,
                            tint = if (isVerified) Color(0xFF10B981) else Color(0xFFF59E0B)
                        )
                        Spacer(modifier = Modifier.width(8.dp))
                        Text("Verify Customer Code", fontSize = 15.sp, fontWeight = FontWeight.Bold)
                    }
                    if (!isVerified) {
                        Spacer(modifier = Modifier.height(8.dp))
                        Text("Ask the customer for their 6-digit ride code. Enter it below to start the ride.", fontSize = 12.sp, color = Color(0xFF687280))
                        Spacer(modifier = Modifier.height(8.dp))
                        OutlinedTextField(
                            value = codeInput,
                            onValueChange = { if (it.length <= 6) { codeInput = it; codeError = "" } },
                            label = { Text("Enter customer's 6-digit code") },
                            singleLine = true,
                            isError = codeError.isNotEmpty(),
                            modifier = Modifier.fillMaxWidth().testTag("taxi_verify_code_input")
                        )
                        if (codeError.isNotEmpty()) {
                            Text(codeError, color = Color.Red, fontSize = 11.sp, modifier = Modifier.padding(top = 4.dp))
                        }
                        Spacer(modifier = Modifier.height(16.dp))
                        Button(
                            onClick = {
                                if (codeInput == "482910") {
                                    isVerified = true
                                    Toast.makeText(context, "Code Verified! Ride Started!", Toast.LENGTH_SHORT).show()
                                } else {
                                    codeError = "Invalid code. Ask customer to check the app."
                                }
                            },
                            enabled = codeInput.length == 6,
                            colors = ButtonDefaults.buttonColors(containerColor = Color(0xFF0D9488)),
                            modifier = Modifier.fillMaxWidth().testTag("taxi_start_ride_btn")
                        ) { Text("START RIDE", fontWeight = FontWeight.Bold) }
                    } else {
                        Spacer(modifier = Modifier.height(8.dp))
                        Text("✓ Code Verified! Ride In Progress.", color = Color(0xFF10B981), fontWeight = FontWeight.Bold, fontSize = 13.sp)
                    }
                }
            }

            if (isVerified) {
                Text("Map & Navigation", fontWeight = FontWeight.Bold, fontSize = 14.sp)
                TaxiInteractiveMapView(
                    modifier = Modifier.fillMaxWidth().height(220.dp),
                    pickupLabel = ride.pickup,
                    dropLabel = ride.drop
                )

                Button(
                    onClick = {
                        isReachedDestination = true
                        Toast.makeText(context, "Reached destination. Drop off passenger.", Toast.LENGTH_SHORT).show()
                    },
                    enabled = !isReachedDestination,
                    colors = ButtonDefaults.buttonColors(containerColor = if (isReachedDestination) Color(0xFF687280) else Color(0xFF0D9488)),
                    modifier = Modifier.fillMaxWidth().testTag("taxi_reached_destination_btn")
                ) { Text(if (isReachedDestination) "✓ Reached Destination" else "Reached Destination", fontWeight = FontWeight.Bold) }

                Button(
                    onClick = { showSuccessDialog = true },
                    enabled = isReachedDestination,
                    colors = ButtonDefaults.buttonColors(containerColor = Color(0xFF16A34A)),
                    modifier = Modifier.fillMaxWidth().testTag("taxi_complete_ride_btn")
                ) { Text("Complete Ride", fontWeight = FontWeight.Bold) }
            }

            Card(modifier = Modifier.fillMaxWidth(), colors = CardDefaults.cardColors(containerColor = Color.White)) {
                Row(
                    modifier = Modifier.padding(16.dp).fillMaxWidth(),
                    horizontalArrangement = Arrangement.SpaceBetween,
                    verticalAlignment = Alignment.CenterVertically
                ) {
                    Text("Payment Mode", fontSize = 13.sp, fontWeight = FontWeight.Bold)
                    Row(
                        modifier = Modifier
                            .clip(RoundedCornerShape(8.dp))
                            .background(Color(0xFFE2E8F0))
                            .padding(2.dp)
                    ) {
                        Box(
                            modifier = Modifier
                                .clip(RoundedCornerShape(6.dp))
                                .background(if (paymentMode == "Cash") crowmixBlue else Color.Transparent)
                                .clickable { paymentMode = "Cash" }
                                .padding(horizontal = 10.dp, vertical = 4.dp)
                        ) { Text("Cash", color = if (paymentMode == "Cash") Color.White else Color.Black, fontSize = 11.sp, fontWeight = FontWeight.Bold) }
                        Box(
                            modifier = Modifier
                                .clip(RoundedCornerShape(6.dp))
                                .background(if (paymentMode == "UPI") crowmixBlue else Color.Transparent)
                                .clickable { paymentMode = "UPI" }
                                .padding(horizontal = 10.dp, vertical = 4.dp)
                        ) { Text("UPI", color = if (paymentMode == "UPI") Color.White else Color.Black, fontSize = 11.sp, fontWeight = FontWeight.Bold) }
                    }
                }
            }
        }
    }
}

