    if (showSuccessDialog) {
        AlertDialog(
            onDismissRequest = {},
            title = { Text("Emergency Completed 🏁") },
            text = { Text("The emergency patient has been successfully delivered to ${emergency.drop}. The unit is now ready for the next call.") },
            confirmButton = {
                Button(
                    onClick = {
                        showSuccessDialog = false
                        onEmergencyComplete(emergency)
                    },
                    colors = ButtonDefaults.buttonColors(containerColor = Color.Red)
                ) { Text("OK") }
            }
        )
    }

    Scaffold(
        topBar = {
            TopAppBar(
                title = { Text("Active Emergency", fontWeight = FontWeight.Bold) },
                navigationIcon = {
                    IconButton(onClick = onBack) {
                        Icon(Icons.AutoMirrored.Filled.ArrowBack, "Back")
                    }
