                            Text(emergency.patientCondition, fontWeight = FontWeight.Bold, fontSize = 14.sp)
                        }
                        Text(currentSubStatus, color = Color.Red, fontWeight = FontWeight.Bold, fontSize = 12.sp)
                    }
