                }
            }
            Spacer(modifier = Modifier.height(24.dp))
        }
    }
}

@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun AmbulancePanelScreen(
    onSignOut: () -> Unit
) {
    var isOnline by remember { mutableStateOf(true) }
    var isNotifOn by remember { mutableStateOf(true) }
    var selectedTab by remember { mutableStateOf("Orders") }
    val drawerState = rememberDrawerState(initialValue = DrawerValue.Closed)
    val scope = rememberCoroutineScope()
    val context = LocalContext.current

    var showOfflineDialogReason by remember { mutableStateOf(false) }
    var showNotifDialogReason by remember { mutableStateOf(false) }
    var offlineReason by remember { mutableStateOf("No ambulance available") }

    var activeIncomingEmergency by remember { mutableStateOf<AmbulanceEmergency?>(null) }
    var activeEmergencyInProgress by remember { mutableStateOf<AmbulanceEmergency?>(null) }

    var ambulanceEmergenciesList by remember {
        mutableStateOf(
            listOf(
                AmbulanceEmergency(
                    id = "AMB-001",
                    patientName = "Ramesh Kumar",
                    phone = "+91 98XXX",
                    pickup = "Viman Nagar",
                    drop = "Ruby Hall Clinic",
                    distance = "2.1 km",
                    priority = "URGENT",
                    patientCondition = "Cardiac emergency",
                    status = "Emergency Pending",
                    statusColor = Color.Red
                ),
                AmbulanceEmergency(
                    id = "AMB-002",
                    patientName = "Suresh Patil",
                    phone = "+91 97XXX",
                    pickup = "Kharadi",
                    drop = "KEM Hospital",
                    distance = "5.4 km",
                    priority = "HIGH",
                    patientCondition = "Accident case",
                    status = "Emergency Pending",
                    statusColor = Color(0xFFF59E0B)
                )
            )
        )
    }

    var ambulanceHistoryAccepted by remember {
        mutableStateOf(
            listOf(
                AmbulanceEmergency(
                    id = "AMB-102",
                    patientName = "Priya Sharma",
                    phone = "+91 91122 33445",
                    pickup = "Kothrud",
                    drop = "Sahyadri Hospital",
                    distance = "3.2 km",
                    priority = "URGENT",
                    patientCondition = "Respiratory issue",
                    status = "Completed",
                    statusColor = Color(0xFF16A34A)
                )
            )
        )
    }

    if (showOfflineDialogReason) {
        AmbulanceOffReasonDialog(
            title = "Going offline?",
            subtitle = "Select a reason so central dispatch is informed",
            onDismiss = { showOfflineDialogReason = false },
            onConfirmOffline = { r ->
                offlineReason = r
                isOnline = false
                showOfflineDialogReason = false
            }
        )
    }

    if (showNotifDialogReason) {
        AmbulanceOffReasonDialog(
            title = "Disable dispatch alerts?",
            subtitle = "Select a reason to mute incoming sirens",
            onDismiss = { showNotifDialogReason = false },
            onConfirmOffline = { r ->
                isNotifOn = false
                showNotifDialogReason = false
                Toast.makeText(context, "Sirens silenced: $r", Toast.LENGTH_SHORT).show()
            }
        )
    }

    if (activeIncomingEmergency != null) {
        AmbulanceIncomingRideScreen(
            emergency = activeIncomingEmergency!!,
            onDecline = { activeIncomingEmergency = null },
            onAccept = { e ->
                activeIncomingEmergency = null
                activeEmergencyInProgress = e
            }
        )
    } else if (activeEmergencyInProgress != null) {
        AmbulanceActiveScreen(
            emergency = activeEmergencyInProgress!!,
            onBack = { activeEmergencyInProgress = null },
            onEmergencyComplete = { e ->
                ambulanceEmergenciesList = ambulanceEmergenciesList.filter { it.id != e.id }
                ambulanceHistoryAccepted = listOf(e.copy(status = "Completed", statusColor = Color(0xFF16A34A))) + ambulanceHistoryAccepted
                activeEmergencyInProgress = null
            }
        )
    } else {
        ModalNavigationDrawer(
            drawerState = drawerState,
            drawerContent = {
                ModalDrawerSheet {
                    Spacer(modifier = Modifier.height(16.dp))
                    Row(
                        modifier = Modifier.padding(horizontal = 20.dp, vertical = 12.dp),
                        verticalAlignment = Alignment.CenterVertically
                    ) {
                        Box(
                            modifier = Modifier
                                .size(48.dp)
                                .clip(CircleShape)
                                .background(Color(0xFFFEF2F2)),
                            contentAlignment = Alignment.Center
                        ) { Text("🚑", fontSize = 24.sp) }
                        Spacer(modifier = Modifier.width(16.dp))
                        Column {
                            Text("Rohan Deshmukh", fontWeight = FontWeight.Bold, fontSize = 16.sp, color = Color(0xFF0F172A))
                            Text("Emergency Lead | AMB-9112", fontSize = 11.sp, color = Color(0xFF687280))
                        }
                    }
                    Divider(modifier = Modifier.padding(vertical = 8.dp))
                    val items = listOf("Orders" to Icons.Filled.LocalHospital, "Order History" to Icons.Filled.History, "Payments" to Icons.Filled.Payment, "My Profile" to Icons.Filled.Person)
                    items.forEach { (tab, icon) ->
                        NavigationDrawerItem(
                            label = { Text(tab, fontWeight = FontWeight.Bold) },
                            selected = selectedTab == tab,
                            onClick = {
                                selectedTab = tab
                                scope.launch { drawerState.close() }
                            },
                            icon = { Icon(icon, tab) },
                            modifier = Modifier.padding(horizontal = 12.dp, vertical = 4.dp)
                        )
                    }
                    Spacer(modifier = Modifier.height(16.dp))
                    Divider(modifier = Modifier.padding(horizontal = 24.dp))
                    Spacer(modifier = Modifier.height(16.dp))
                    NavigationDrawerItem(
                        label = { Text("Sign Out", color = Color.Red, fontWeight = FontWeight.Bold) },
                        selected = false,
                        onClick = {
                            scope.launch { drawerState.close() }
                            onSignOut()
                        },
                        icon = { Icon(Icons.Filled.ExitToApp, "Sign Out", tint = Color.Red) },
                        modifier = Modifier.padding(horizontal = 12.dp)
                    )
                }
            }
        ) {
            Scaffold(
                topBar = {
                    TopAppBar(
                        title = { Text("Ambulance Panel", fontSize = 16.sp, fontWeight = FontWeight.Black) },
                        navigationIcon = {
                            IconButton(onClick = { scope.launch { drawerState.open() } }) {
                                Icon(Icons.Filled.Menu, "Toggle Drawer")
                            }
                        },
                        actions = {
                            Button(
                                onClick = {
                                    if (isNotifOn) showNotifDialogReason = true else isNotifOn = true
                                },
                                colors = ButtonDefaults.buttonColors(
                                    containerColor = if (isNotifOn) Color.Red else Color(0xFF687280)
                                ),
                                contentPadding = PaddingValues(horizontal = 10.dp),
                                modifier = Modifier
                                    .padding(end = 12.dp)
                                    .height(32.dp)
                                    .testTag("amb_notif_toggle_btn")
                            ) {
