                                                },
                                                modifier = Modifier.testTag("amb_panel_status_switch"),
                                                colors = SwitchDefaults.colors(checkedThumbColor = Color.Red, checkedTrackColor = Color.Red.copy(alpha = 0.5f))
                                            )
                                        }
                                    }
                                }
                                item {
                                    Row(
                                        modifier = Modifier.fillMaxWidth(),
                                        horizontalArrangement = Arrangement.spacedBy(12.dp)
                                    ) {
                                        Card(
                                            modifier = Modifier.weight(1f),
                                            colors = CardDefaults.cardColors(containerColor = Color.White)
                                        ) {
                                            Column(modifier = Modifier.padding(16.dp)) {
                                                Text("Calls today", fontSize = 11.sp, color = Color(0xFF687280), fontWeight = FontWeight.SemiBold)
                                                Spacer(modifier = Modifier.height(8.dp))
                                                Text("6", fontSize = 24.sp, fontWeight = FontWeight.Black)
                                            }
                                        }
                                        Card(
                                            modifier = Modifier.weight(1f),
                                            colors = CardDefaults.cardColors(containerColor = Color.White)
                                        ) {
                                            Column(modifier = Modifier.padding(16.dp)) {
                                                Text("Avg response", fontSize = 11.sp, color = Color(0xFF687280), fontWeight = FontWeight.SemiBold)
                                                Spacer(modifier = Modifier.height(8.dp))
                                                Text("4 min", fontSize = 24.sp, fontWeight = FontWeight.Black, color = Color.Red)
                                            }
                                        }
                                    }
                                }
                                item {
                                    Text("Pending emergency requests", fontWeight = FontWeight.Bold, fontSize = 15.sp, color = Color(0xFF0F172A))
                                }
