data class MedicineOrder(
    val id: String,
    val customerName: String,
    val phone: String,
    val medicines: String,
    val instruction: String,
    val total: Int,
    val status: String,
    val address: String = "123, Shanti Nagar, Lane 4, Pune",
    val distance: String = "1.2 km",
    val deliveryType: String = "Home delivery",
    val paymentType: String = "COD",
    val statusColor: Color = Color(0xFF687280)
)

@Composable
fun MedicineOffReasonDialog(
    title: String,
    subtitle: String,
    onDismiss: () -> Unit,
    onConfirm: (String) -> Unit
) {
    var selectedReason by remember { mutableStateOf("Break time") }
    var customReason by remember { mutableStateOf("") }
    val reasons = listOf("Break time", "Stock check in progress", "Closing soon", "Public holiday")

    AlertDialog(
        onDismissRequest = onDismiss,
        title = { Text(title, fontWeight = FontWeight.Bold) },
        text = {
            Column(modifier = Modifier.fillMaxWidth()) {
                Text(subtitle, fontSize = 12.sp, color = Color(0xFF687280))
                Spacer(modifier = Modifier.height(16.dp))
                reasons.forEach { r ->
                    Row(
                        modifier = Modifier
                            .fillMaxWidth()
                            .clickable { selectedReason = r }
                            .padding(vertical = 6.dp),
                        verticalAlignment = Alignment.CenterVertically
                    ) {
                        RadioButton(selected = (selectedReason == r), onClick = { selectedReason = r })
                        Spacer(modifier = Modifier.width(8.dp))
                        Text(r, fontSize = 13.sp)
                    }
                }
                Row(
                    modifier = Modifier
                        .fillMaxWidth()
                        .clickable { selectedReason = "Other" }
                        .padding(vertical = 6.dp),
                    verticalAlignment = Alignment.CenterVertically
                ) {
                    RadioButton(selected = (selectedReason == "Other"), onClick = { selectedReason = "Other" })
                    Spacer(modifier = Modifier.width(8.dp))
                    Text("Other", fontSize = 13.sp)
                }
                if (selectedReason == "Other") {
                    Spacer(modifier = Modifier.height(8.dp))
                    OutlinedTextField(
                        value = customReason,
                        onValueChange = { customReason = it },
                        label = { Text("Enter reason...") },
                        singleLine = true,
                        modifier = Modifier.fillMaxWidth()
                    )
                }
            }
        },
        confirmButton = {
            Button(
                onClick = {
                    val res = if (selectedReason == "Other" && customReason.isNotEmpty()) customReason else selectedReason
                    onConfirm(res)
                },
                colors = ButtonDefaults.buttonColors(containerColor = Color(0xFF16A34A))
            ) {
                Text("Confirm")
            }
        },
        dismissButton = {
            TextButton(onClick = onDismiss) { Text("Cancel", color = Color(0xFF687280)) }
        }
    )
}

@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun MedicineIncomingOrderScreen(
    order: MedicineOrder,
    onDecline: () -> Unit,
    onAccept: (MedicineOrder) -> Unit
) {
    var timeLeft by remember { mutableStateOf(30) }
    val context = LocalContext.current

    LaunchedEffect(timeLeft) {
        if (timeLeft > 0) {
            delay(1000L)
            timeLeft--
        } else {
            Toast.makeText(context, "Order timed out", Toast.LENGTH_SHORT).show()
            onDecline()
        }
    }

    Scaffold(
        topBar = {
            TopAppBar(
                title = { Text("New Medicine Order!", fontWeight = FontWeight.Bold) },
                colors = TopAppBarDefaults.topAppBarColors(containerColor = Color(0xFF16A34A), titleContentColor = Color.White)
            )
        }
    ) { innerPadding ->
        Column(
            modifier = Modifier
                .fillMaxSize()
                .padding(innerPadding)
                .padding(24.dp),
            horizontalAlignment = Alignment.CenterHorizontally,
            verticalArrangement = Arrangement.SpaceBetween
        ) {
            Column(horizontalAlignment = Alignment.CenterHorizontally, modifier = Modifier.fillMaxWidth()) {
                Spacer(modifier = Modifier.height(16.dp))
                Box(contentAlignment = Alignment.Center, modifier = Modifier.size(100.dp)) {
                    CircularProgressIndicator(
                        progress = { timeLeft / 30f },
                        modifier = Modifier.fillMaxSize(),
                        color = Color(0xFF16A34A),
                        strokeWidth = 6.dp
                    )
                    Text("$timeLeft", fontSize = 28.sp, fontWeight = FontWeight.Black, color = Color(0xFF16A34A))
                }
                Spacer(modifier = Modifier.height(24.dp))
                Card(
                    modifier = Modifier.fillMaxWidth(),
                    colors = CardDefaults.cardColors(containerColor = Color.White),
                    border = BorderStroke(1.5.dp, Color(0xFF16A34A)),
                    shape = RoundedCornerShape(12.dp)
                ) {
                    Column(modifier = Modifier.padding(16.dp)) {
                        Text("Customer Details:", fontSize = 12.sp, color = Color(0xFF687280), fontWeight = FontWeight.Bold)
                        Text(order.customerName, fontWeight = FontWeight.Bold, fontSize = 16.sp)
                        Text("Phone: ${order.phone}", fontSize = 14.sp)
                        Divider(modifier = Modifier.padding(vertical = 12.dp))
                        
                        Text("Prescription Items:", fontSize = 12.sp, color = Color(0xFF687280), fontWeight = FontWeight.Bold)
                        Text(order.medicines, fontWeight = FontWeight.Medium, fontSize = 14.sp)
                        Spacer(modifier = Modifier.height(8.dp))
                        Text("Instructions: ${order.instruction}", fontSize = 13.sp, color = Color.DarkGray)
                        Spacer(modifier = Modifier.height(8.dp))
                        Text("Total Price: ₹${order.total}", fontSize = 15.sp, fontWeight = FontWeight.Bold, color = Color(0xFF16A34A))
                        Spacer(modifier = Modifier.height(8.dp))
                        Text("Distance: ${order.distance} | Type: ${order.deliveryType}", fontSize = 13.sp, color = Color(0xFF687280))
                    }
                }
            }
            Row(modifier = Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.spacedBy(16.dp)) {
                OutlinedButton(
                    onClick = onDecline,
                    border = BorderStroke(1.5.dp, Color(0xFF16A34A)),
                    colors = ButtonDefaults.outlinedButtonColors(contentColor = Color(0xFF16A34A)),
                    modifier = Modifier.weight(1f).height(48.dp)
                ) { Text("Decline", fontWeight = FontWeight.Bold) }
                Button(
                    onClick = { onAccept(order) },
                    colors = ButtonDefaults.buttonColors(containerColor = Color(0xFF16A34A)),
                    modifier = Modifier.weight(1f).height(48.dp)
                ) { Text("Accept", fontWeight = FontWeight.Bold) }
            }
        }
    }
}

@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun MedicineOrderActiveScreen(
    order: MedicineOrder,
    onBack: () -> Unit,
    onOrderComplete: (MedicineOrder) -> Unit
) {
    var showSuccessDialog by remember { mutableStateOf(false) }
    var currentStep by remember { mutableStateOf(1) } // 1: Start Prep, 2: Ready Node, 3: Completed
    var markOutOfStockChecked by remember { mutableStateOf(false) }
    var selectedOutOfStockItem by remember { mutableStateOf<String?>(null) }
    val context = LocalContext.current

    val itemsInOrder = order.medicines.split(", ").map { it.trim() }

    if (showSuccessDialog) {
        AlertDialog(
            onDismissRequest = {},
            title = { Text("Order Completed 🏁") },
            text = { Text("The medicine prescription has been successfully processed and delivered/picked up. Returning to main panel.") },
            confirmButton = {
                Button(
                    onClick = {
                        showSuccessDialog = false
                        onOrderComplete(order)
                    },
                    colors = ButtonDefaults.buttonColors(containerColor = Color(0xFF16A34A))
                ) { Text("OK") }
            }
        )
    }

    Scaffold(
        topBar = {
            TopAppBar(
                title = { Text("Active Medicine Order", fontWeight = FontWeight.Bold) },
                navigationIcon = {
                    IconButton(onClick = onBack) {
                        Icon(Icons.AutoMirrored.Filled.ArrowBack, "Back")
                    }
                },
                colors = TopAppBarDefaults.topAppBarColors(containerColor = Color(0xFF16A34A), titleContentColor = Color.White, navigationIconContentColor = Color.White)
            )
        }
    ) { innerPadding ->
        Column(
            modifier = Modifier
                .fillMaxSize()
                .padding(innerPadding)
                .verticalScroll(rememberScrollState())
                .padding(16.dp),
            verticalArrangement = Arrangement.spacedBy(16.dp)
        ) {
            Card(
                modifier = Modifier.fillMaxWidth(),
                colors = CardDefaults.cardColors(containerColor = Color.White),
                border = BorderStroke(1.5.dp, Color(0xFF16A34A)),
                shape = RoundedCornerShape(12.dp)
            ) {
                Column(modifier = Modifier.padding(16.dp)) {
                    Row(
                        modifier = Modifier.fillMaxWidth(),
                        horizontalArrangement = Arrangement.SpaceBetween,
                        verticalAlignment = Alignment.CenterVertically
                    ) {
                        Text(order.id, fontWeight = FontWeight.Bold, fontSize = 16.sp, color = Color(0xFF16A34A))
                        Box(
                            modifier = Modifier
                                .background(Color(0xFFE0F2FE), RoundedCornerShape(4.dp))
                                .padding(horizontal = 8.dp, vertical = 2.dp)
                        ) {
                            Text(order.deliveryType, color = Color(0xFF0369A1), fontSize = 11.sp, fontWeight = FontWeight.Bold)
                        }
                    }
                    Spacer(modifier = Modifier.height(8.dp))
                    Text("Customer: ${order.customerName}", fontWeight = FontWeight.Bold, fontSize = 15.sp)
                    Text("Phone: ${order.phone}", fontSize = 13.sp, color = Color(0xFF687280))
                    Text("Address: ${order.address}", fontSize = 13.sp)
                    Divider(modifier = Modifier.padding(vertical = 12.dp))

                    Text("Prescription Items & Price Breakdown:", fontSize = 12.sp, color = Color(0xFF687280), fontWeight = FontWeight.Bold)
                    Spacer(modifier = Modifier.height(8.dp))
                    itemsInOrder.forEach { item ->
                        Row(
                            modifier = Modifier.fillMaxWidth(),
                            horizontalArrangement = Arrangement.SpaceBetween
                        ) {
                            Text("• $item", fontSize = 13.sp)
                            val price = if (item.contains("Paracetamol")) "₹60" else if (item.contains("Azithromycin")) "₹120" else "₹2640"
                            Text(price, fontSize = 13.sp, color = Color(0xFF687280))
                        }
                    }
                    Divider(modifier = Modifier.padding(vertical = 8.dp))
                    Row(
                        modifier = Modifier.fillMaxWidth(),
                        horizontalArrangement = Arrangement.SpaceBetween
                    ) {
                        Text("Total Amount:", fontWeight = FontWeight.Bold, fontSize = 15.sp)
                        Text("₹${order.total}", fontWeight = FontWeight.Bold, fontSize = 15.sp, color = Color(0xFF16A34A))
                    }
                    Spacer(modifier = Modifier.height(8.dp))
                    Text("Payment Method: ${order.paymentType}", fontSize = 12.sp, color = Color(0xFF687280), fontWeight = FontWeight.SemiBold)
                }
            }

            Card(
                modifier = Modifier.fillMaxWidth(),
                colors = CardDefaults.cardColors(containerColor = Color.White)
            ) {
                Column(modifier = Modifier.padding(16.dp), verticalArrangement = Arrangement.spacedBy(10.dp)) {
                    Text("Preparation Workflow Status", fontSize = 14.sp, fontWeight = FontWeight.Bold)
                    
                    OutlinedButton(
                        onClick = {
                            currentStep = 2
                            Toast.makeText(context, "Preparation started!", Toast.LENGTH_SHORT).show()
                        },
                        border = BorderStroke(1.5.dp, if (currentStep == 1) Color(0xFF16A34A) else Color(0xFF687280)),
                        colors = ButtonDefaults.outlinedButtonColors(
                            contentColor = if (currentStep == 1) Color(0xFF16A34A) else Color(0xFF687280)
                        ),
                        modifier = Modifier.fillMaxWidth().height(48.dp).testTag("med_start_prep_btn")
                    ) {
                        Text("1. Start Preparation", fontWeight = FontWeight.Bold)
                    }

                    Button(
                        onClick = {
                            if (currentStep < 2) {
                                Toast.makeText(context, "Please start preparation first", Toast.LENGTH_SHORT).show()
                            } else {
                                currentStep = 3
                                Toast.makeText(context, "Customer notified: Prescription ready!", Toast.LENGTH_SHORT).show()
                            }
                        },
                        colors = ButtonDefaults.buttonColors(
                            containerColor = if (currentStep == 2) Color(0xFF3B82F6) else Color(0xFF9CA3AF),
                            contentColor = Color.White
                        ),
                        modifier = Modifier.fillMaxWidth().height(48.dp).testTag("med_ready_notify_btn")
                    ) {
                        Text("2. Ready - Notify Customer", fontWeight = FontWeight.Bold)
                    }

                    Button(
                        onClick = {
                            if (currentStep < 3) {
                                Toast.makeText(context, "Please mark ready first", Toast.LENGTH_SHORT).show()
                            } else {
                                showSuccessDialog = true
                            }
                        },
                        colors = ButtonDefaults.buttonColors(
                            containerColor = if (currentStep == 3) Color(0xFF0D9488) else Color(0xFF9CA3AF),
                            contentColor = Color.White
                        ),
                        modifier = Modifier.fillMaxWidth().height(48.dp).testTag("med_dispatched_btn")
                    ) {
                        Text("3. Handed Over / Dispatched", fontWeight = FontWeight.Bold)
                    }
                }
            }

            Card(
                modifier = Modifier.fillMaxWidth(),
                colors = CardDefaults.cardColors(containerColor = Color.White)
            ) {
                Column(modifier = Modifier.padding(16.dp)) {
                    Row(
                        modifier = Modifier.fillMaxWidth(),
                        verticalAlignment = Alignment.CenterVertically
                    ) {
                        Checkbox(
                            checked = markOutOfStockChecked,
                            onCheckedChange = { 
                                markOutOfStockChecked = it
                                if (!it) selectedOutOfStockItem = null
                            },
                            modifier = Modifier.testTag("med_out_of_stock_checkbox")
                        )
                        Spacer(modifier = Modifier.width(8.dp))
                        Text("Mark any item out of stock", fontWeight = FontWeight.SemiBold, fontSize = 14.sp)
                    }

                    if (markOutOfStockChecked) {
                        Spacer(modifier = Modifier.height(16.dp))
                        Text("Select item to mark:", fontSize = 13.sp, color = Color(0xFF687280), fontWeight = FontWeight.Bold)
                        itemsInOrder.forEach { item ->
                            Row(
                                modifier = Modifier
                                    .fillMaxWidth()
                                    .clickable {
                                        selectedOutOfStockItem = item
                                        Toast.makeText(context, "Notified customer: $item is out of stock!", Toast.LENGTH_LONG).show()
                                    }
                                    .padding(vertical = 4.dp),
                                verticalAlignment = Alignment.CenterVertically
                            ) {
                                RadioButton(
                                    selected = (selectedOutOfStockItem == item),
                                    onClick = {
                                        selectedOutOfStockItem = item
                                        Toast.makeText(context, "Notified customer: $item is out of stock!", Toast.LENGTH_LONG).show()
                                    }
                                )
                                Spacer(modifier = Modifier.width(8.dp))
                                Text(item, fontSize = 13.sp)
                            }
                        }
                    }
                }
            }
        }
    }
}

@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun MedicineShopPanelScreen(
    onSignOut: () -> Unit
) {
    var isOnline by remember { mutableStateOf(true) }
    var isNotifOn by remember { mutableStateOf(true) }
    var selectedTab by remember { mutableStateOf("Orders") }
    val drawerState = rememberDrawerState(initialValue = DrawerValue.Closed)
    val scope = rememberCoroutineScope()
    val context = LocalContext.current

    var showOfflineDialogReason by remember { mutableStateOf(false) }
    var showNotifDialogReason by remember { mutableStateOf(false) }
    var offlineReason by remember { mutableStateOf("Break time") }

    var activeIncomingOrder by remember { mutableStateOf<MedicineOrder?>(null) }
    var activeOrderInProgress by remember { mutableStateOf<MedicineOrder?>(null) }

    var medicineOrdersList by remember {
        mutableStateOf(
            listOf(
                MedicineOrder(
                    id = "MED-221",
                    customerName = "Amir Shaikh",
                    phone = "+91 98XXX XXXXX",
                    medicines = "Paracetamol 500mg x 2, Azithromycin 250mg x 1",
                    instruction = "None",
                    total = 180,
                    status = "Awaiting Preparation",
                    statusColor = Color(0xFFF59E0B)
                ),
                MedicineOrder(
                    id = "MED-218",
                    customerName = "Pooja R.",
                    phone = "+91 97XXX XXXXX",
                    medicines = "Insulin 10ml x 2",
                    instruction = "Keep refrigerated",
                    total = 2640,
                    status = "Ready for Pickup",
                    statusColor = Color(0xFF3B82F6)
                )
            )
        )
    }

    var medicineHistoryAccepted by remember {
        mutableStateOf(
            listOf(
                MedicineOrder(
                    id = "MED-205",
                    customerName = "Karan Sharma",
                    phone = "+91 99887 76655",
                    medicines = "Loratadine 10mg x 10",
                    instruction = "None",
                    total = 420,
                    status = "Handed Over",
                    statusColor = Color(0xFF16A34A)
                )
            )
        )
    }

    if (showOfflineDialogReason) {
        MedicineOffReasonDialog(
            title = "Going offline?",
            subtitle = "Select a reason so central dispatch is informed",
            onDismiss = { showOfflineDialogReason = false },
            onConfirm = { r ->
                offlineReason = r
                isOnline = false
                showOfflineDialogReason = false
            }
        )
    }

    if (showNotifDialogReason) {
        MedicineOffReasonDialog(
            title = "Turn off Notifications?",
            subtitle = "Select a reason to mute incoming sirens",
            onDismiss = { showNotifDialogReason = false },
            onConfirm = { r ->
                isNotifOn = false
                showNotifDialogReason = false
                Toast.makeText(context, "Notifications muted: $r", Toast.LENGTH_SHORT).show()
            }
        )
    }

    if (activeIncomingOrder != null) {
        MedicineIncomingOrderScreen(
            order = activeIncomingOrder!!,
            onDecline = { activeIncomingOrder = null },
            onAccept = { o ->
                activeIncomingOrder = null
                activeOrderInProgress = o
            }
        )
    } else if (activeOrderInProgress != null) {
        MedicineOrderActiveScreen(
            order = activeOrderInProgress!!,
            onBack = { activeOrderInProgress = null },
            onOrderComplete = { o ->
                medicineOrdersList = medicineOrdersList.filter { it.id != o.id }
                medicineHistoryAccepted = listOf(o.copy(status = "Handed Over", statusColor = Color(0xFF16A34A))) + medicineHistoryAccepted
                activeOrderInProgress = null
            }
        )
    } else {
        ModalNavigationDrawer(
            drawerState = drawerState,
            drawerContent = {
                ModalDrawerSheet {
                    Spacer(modifier = Modifier.height(16.dp))
                    Row(
                        modifier = Modifier.padding(horizontal = 20.dp, vertical = 12.dp),
                        verticalAlignment = Alignment.CenterVertically
                    ) {
                        Box(
                            modifier = Modifier
                                .size(48.dp)
                                .clip(CircleShape)
                                .background(Color(0xFFF0FDF4)),
                            contentAlignment = Alignment.Center
                        ) { Text("💊", fontSize = 24.sp) }
                        Spacer(modifier = Modifier.width(16.dp))
                        Column {
                            Text("Aditya Kulkarni", fontWeight = FontWeight.Bold, fontSize = 16.sp, color = Color(0xFF0F172A))
                            Text("Licensed Pharmacist • PHA-781A", fontSize = 11.sp, color = Color(0xFF687280))
                        }
                    }
                    Divider(modifier = Modifier.padding(vertical = 8.dp))
                    val items = listOf(
                        "Orders" to Icons.Filled.LocalPharmacy,
                        "Order History" to Icons.Filled.History,
                        "Payments" to Icons.Filled.Payment,
                        "My Profile" to Icons.Filled.Person
                    )
                    items.forEach { (tab, icon) ->
                        NavigationDrawerItem(
                            label = { Text(tab, fontWeight = FontWeight.Bold) },
                            selected = selectedTab == tab,
                            onClick = {
                                selectedTab = tab
                                scope.launch { drawerState.close() }
                            },
                            icon = { Icon(icon, tab) },
                            modifier = Modifier.padding(horizontal = 12.dp, vertical = 4.dp)
                        )
                    }
                    Spacer(modifier = Modifier.height(16.dp))
                    Divider(modifier = Modifier.padding(horizontal = 24.dp))
                    Spacer(modifier = Modifier.height(16.dp))
                    NavigationDrawerItem(
                        label = { Text("Sign Out", color = Color.Red, fontWeight = FontWeight.Bold) },
                        selected = false,
                        onClick = {
                            scope.launch { drawerState.close() }
                            onSignOut()
                        },
                        icon = { Icon(Icons.Filled.ExitToApp, "Sign Out", tint = Color.Red) },
                        modifier = Modifier.padding(horizontal = 12.dp)
                    )
                }
            }
        ) {
            Scaffold(
                topBar = {
                    TopAppBar(
                        title = { Text("Medicine Shop Panel", fontSize = 16.sp, fontWeight = FontWeight.Black) },
                        navigationIcon = {
                            IconButton(onClick = { scope.launch { drawerState.open() } }) {
                                Icon(Icons.Filled.Menu, "Toggle Drawer")
                            }
                        },
                        actions = {
                            Button(
                                onClick = {
                                    if (isNotifOn) showNotifDialogReason = true else isNotifOn = true
                                },
                                colors = ButtonDefaults.buttonColors(
                                    containerColor = if (isNotifOn) Color(0xFF16A34A) else Color(0xFF687280)
                                ),
                                contentPadding = PaddingValues(horizontal = 10.dp),
                                modifier = Modifier
                                    .padding(end = 12.dp)
