data class HospitalDoctor(
    val id: String,
    val name: String,
    val specialization: String,
    val isOnline: Boolean,
    val statusText: String,
    val avatarColor: Color,
    val initials: String,
    val offlineReason: String = ""
)

data class HospitalAppointment(
    val id: String,
    val patientName: String,
    val age: Int,
    val gender: String,
    val bloodGroup: String = "B+",
    val phone: String = "+91 98XXX XXXXX",
    val email: String = "patient@example.com",
    val date: String = "Jun 12",
    val timeSlot: String,
    val doctorId: String,
    val reason: String,
    val status: String, // "Scheduled", "Checked In", "Completed", "Cancelled"
    val isTomorrow: Boolean = false,
    val insuranceInfo: String = "SBI General Medical Plan",
    val paymentStatus: String = "Paid",
    val amountPaid: Int = 500,
    val uploadedDocs: List<String> = listOf("ecg_scan_report.pdf", "lab_urine_test.pdf")
)

@Composable
fun HospitalReasonDialog(
    title: String,
    subtitle: String,
    reasons: List<String>,
    onDismiss: () -> Unit,
    onConfirm: (String) -> Unit
) {
    var selectedReason by remember { mutableStateOf(reasons.first()) }
    var customReason by remember { mutableStateOf("") }

    AlertDialog(
        onDismissRequest = onDismiss,
        title = { Text(title, fontWeight = FontWeight.Bold) },
        text = {
            Column(modifier = Modifier.fillMaxWidth()) {
                Text(subtitle, fontSize = 12.sp, color = Color(0xFF687280))
                Spacer(modifier = Modifier.height(16.dp))
                reasons.forEach { r ->
                    Row(
                        modifier = Modifier
                            .fillMaxWidth()
                            .clickable { selectedReason = r }
                            .padding(vertical = 5.dp),
                        verticalAlignment = Alignment.CenterVertically
                    ) {
                        RadioButton(selected = (selectedReason == r), onClick = { selectedReason = r })
                        Spacer(modifier = Modifier.width(8.dp))
                        Text(r, fontSize = 13.sp)
                    }
                }
                Row(
                    modifier = Modifier
                        .fillMaxWidth()
                        .clickable { selectedReason = "Other" }
                        .padding(vertical = 5.dp),
                    verticalAlignment = Alignment.CenterVertically
                ) {
                    RadioButton(selected = (selectedReason == "Other"), onClick = { selectedReason = "Other" })
                    Spacer(modifier = Modifier.width(8.dp))
                    Text("Other", fontSize = 13.sp)
                }
                if (selectedReason == "Other") {
                    Spacer(modifier = Modifier.height(8.dp))
                    OutlinedTextField(
                        value = customReason,
                        onValueChange = { customReason = it },
                        label = { Text("Enter reason...") },
                        singleLine = true,
                        modifier = Modifier.fillMaxWidth()
                    )
                }
            }
        },
        confirmButton = {
            Button(
                onClick = {
                    val res = if (selectedReason == "Other" && customReason.isNotEmpty()) customReason else selectedReason
                    onConfirm(res)
                },
                colors = ButtonDefaults.buttonColors(containerColor = Color(0xFFDC2626))
            ) { Text("Confirm") }
        },
        dismissButton = {
            TextButton(onClick = onDismiss) { Text("Cancel", color = Color(0xFF687280)) }
        }
    )
}

@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun HospitalIncomingRequestScreen(
    onDecline: () -> Unit,
    onAccept: (patientName: String, age: Int, gender: String, doctorId: String, timeSlot: String, reason: String, amount: Int) -> Unit
) {
    var timeLeft by remember { mutableStateOf(30) }
    val context = LocalContext.current

    LaunchedEffect(timeLeft) {
        if (timeLeft > 0) {
            delay(1000L)
            timeLeft--
        } else {
            Toast.makeText(context, "Request timed out", Toast.LENGTH_SHORT).show()
            onDecline()
        }
    }

    Scaffold(
        topBar = {
            TopAppBar(
                title = { Text("New Appointment Request!", fontWeight = FontWeight.Bold) },
                colors = TopAppBarDefaults.topAppBarColors(containerColor = Color(0xFFDC2626), titleContentColor = Color.White)
            )
        }
    ) { innerPadding ->
        Column(
            modifier = Modifier
                .fillMaxSize()
                .padding(innerPadding)
                .padding(24.dp),
            horizontalAlignment = Alignment.CenterHorizontally,
            verticalArrangement = Arrangement.SpaceBetween
        ) {
            Column(horizontalAlignment = Alignment.CenterHorizontally, modifier = Modifier.fillMaxWidth()) {
                Spacer(modifier = Modifier.height(16.dp))
                Box(contentAlignment = Alignment.Center, modifier = Modifier.size(100.dp)) {
                    CircularProgressIndicator(
                        progress = { timeLeft / 30f },
                        modifier = Modifier.fillMaxSize(),
                        color = Color(0xFFDC2626),
                        strokeWidth = 6.dp
                    )
                    Text("$timeLeft", fontSize = 28.sp, fontWeight = FontWeight.Black, color = Color(0xFFDC2626))
                }
                Spacer(modifier = Modifier.height(24.dp))
                Card(
                    modifier = Modifier.fillMaxWidth(),
                    colors = CardDefaults.cardColors(containerColor = Color.White),
                    border = BorderStroke(1.5.dp, Color(0xFFDC2626)),
                    shape = RoundedCornerShape(12.dp)
                ) {
                    Column(modifier = Modifier.padding(16.dp), verticalArrangement = Arrangement.spacedBy(8.dp)) {
                        Text("Patient Info:", fontSize = 11.sp, color = Color(0xFF687280), fontWeight = FontWeight.Bold)
                        Text("Aman Malhotra", fontWeight = FontWeight.Bold, fontSize = 16.sp)
                        Text("Age 35 | Male | Blood Group: A+", fontSize = 13.sp)
                        Divider()
                        
                        Text("Requested Consult:", fontSize = 11.sp, color = Color(0xFF687280), fontWeight = FontWeight.Bold)
                        Text("Dr. Mehta | Cardiology", fontWeight = FontWeight.Bold, fontSize = 14.sp)
                        Text("Time Slot: 04:30 PM (Today)", fontSize = 13.sp, color = Color.DarkGray)
                        Text("Symptoms/Reason: Shortness of breath & high BP", fontSize = 13.sp, color = Color.DarkGray)
                        Divider()
                        
                        Row(modifier = Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.SpaceBetween) {
                            Text("Payment Status: Paid", fontWeight = FontWeight.SemiBold, fontSize = 13.sp, color = Color(0xFF16A34A))
                            Text("Amount: ₹500", fontWeight = FontWeight.Bold, fontSize = 14.sp, color = Color(0xFFDC2626))
                        }
                    }
                }
            }
            Row(modifier = Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.spacedBy(16.dp)) {
                OutlinedButton(
                    onClick = onDecline,
                    border = BorderStroke(1.5.dp, Color(0xFFDC2626)),
                    colors = ButtonDefaults.outlinedButtonColors(contentColor = Color(0xFFDC2626)),
                    modifier = Modifier.weight(1f).height(48.dp).testTag("hosp_incoming_decline_btn")
                ) { Text("Decline", fontWeight = FontWeight.Bold) }
                Button(
                    onClick = {
                        onAccept("Aman Malhotra", 35, "M", "DOC-MEHTA", "04:30 PM", "Shortness of breath & high BP", 500)
                    },
                    colors = ButtonDefaults.buttonColors(containerColor = Color(0xFFDC2626)),
                    modifier = Modifier.weight(1f).height(48.dp).testTag("hosp_incoming_accept_btn")
                ) { Text("Accept", fontWeight = FontWeight.Bold) }
            }
        }
    }
}

@Composable
fun HospitalAppointmentDetailBottomSheet(
    appointment: HospitalAppointment,
    doctor: HospitalDoctor?,
    onDismiss: () -> Unit,
    onStatusChange: (String) -> Unit,
    modifier: Modifier = Modifier
) {
    val context = LocalContext.current
    Box(
        modifier = modifier
            .fillMaxSize()
            .background(Color.Black.copy(alpha = 0.5f))
            .clickable { onDismiss() }
    ) {
        Card(
            modifier = Modifier
                .align(Alignment.BottomCenter)
                .fillMaxWidth()
                .clickable(enabled = false) {},
            shape = RoundedCornerShape(topStart = 16.dp, topEnd = 16.dp),
            colors = CardDefaults.cardColors(containerColor = Color.White),
            border = BorderStroke(1.dp, Color(0xFFEFF1F4))
        ) {
            Column(
                modifier = Modifier
                    .padding(20.dp)
                    .verticalScroll(rememberScrollState()),
                verticalArrangement = Arrangement.spacedBy(12.dp)
            ) {
                Box(
                    modifier = Modifier
                        .size(40.dp, 4.dp)
                        .background(Color(0xFF9CA3AF), RoundedCornerShape(2.dp))
                        .align(Alignment.CenterHorizontally)
                )

                Row(
                    modifier = Modifier.fillMaxWidth(),
                    horizontalArrangement = Arrangement.SpaceBetween,
                    verticalAlignment = Alignment.CenterVertically
                ) {
                    Text("Appointment Ticket", fontSize = 16.sp, fontWeight = FontWeight.Black, color = Color(0xFF0F172A))
                    IconButton(onClick = onDismiss) { Text("✕", fontSize = 15.sp, fontWeight = FontWeight.Bold, color = Color(0xFF687280)) }
                }

                Row(
                    modifier = Modifier.fillMaxWidth(),
                    horizontalArrangement = Arrangement.SpaceBetween,
                    verticalAlignment = Alignment.Top
                ) {
                    Column {
                        Text(appointment.patientName, fontSize = 18.sp, fontWeight = FontWeight.Bold)
                        Text("Age ${appointment.age} | ${appointment.gender} | Blood: ${appointment.bloodGroup}", fontSize = 12.sp, color = Color(0xFF687280))
                    }
                    Box(
                        modifier = Modifier
                            .background(
                                when (appointment.status) {
                                    "Scheduled" -> Color(0xFFFEF3C7)
                                    "Checked In" -> Color(0xFFDBEAFE)
                                    "Completed" -> Color(0xFFD1FAE5)
                                    else -> Color(0xFFFEE2E2)
                                },
                                RoundedCornerShape(4.dp)
                            )
                            .padding(horizontal = 8.dp, vertical = 2.dp)
                    ) {
                        Text(
                            text = appointment.status,
                            color = when (appointment.status) {
                                "Scheduled" -> Color(0xFFD97706)
                                "Checked In" -> Color(0xFF2563EB)
                                "Completed" -> Color(0xFF059669)
                                else -> Color(0xFFDC2626)
                            },
                            fontSize = 11.sp,
                            fontWeight = FontWeight.Bold
                        )
                    }
                }

                Divider()

                Column(verticalArrangement = Arrangement.spacedBy(4.dp)) {
                    Row(modifier = Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.SpaceBetween) {
                        Text("Appointment ID", fontSize = 12.sp, color = Color(0xFF687280))
                        Text(appointment.id, fontSize = 12.sp, fontWeight = FontWeight.Bold)
                    }
                    Row(modifier = Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.SpaceBetween) {
                        Text("Phone / Email", fontSize = 12.sp, color = Color(0xFF687280))
                        Text("${appointment.phone}  |  ${appointment.email}", fontSize = 12.sp)
                    }
                    Row(modifier = Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.SpaceBetween) {
                        Text("Consultant", fontSize = 12.sp, color = Color(0xFF687280))
                        Text("${doctor?.name} (${doctor?.specialization})", fontSize = 12.sp, fontWeight = FontWeight.Bold)
                    }
                    Row(modifier = Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.SpaceBetween) {
                        Text("Booking Slot", fontSize = 12.sp, color = Color(0xFF687280))
                        Text("${appointment.date} @ ${appointment.timeSlot}", fontSize = 12.sp, fontWeight = FontWeight.Bold, color = Color(0xFFDC2626))
                    }
                }

                Divider()

                Column {
                    Text("Reason for Visit / Symptoms", fontSize = 11.sp, color = Color(0xFF687280), fontWeight = FontWeight.Bold)
                    Text(appointment.reason, fontSize = 13.sp, fontWeight = FontWeight.Medium)
                }

                Column {
                    Text("Uploaded Documents", fontSize = 11.sp, color = Color(0xFF687280), fontWeight = FontWeight.Bold)
                    appointment.uploadedDocs.forEach { file ->
                        Row(verticalAlignment = Alignment.CenterVertically) {
                            Text("📄", modifier = Modifier.padding(end = 4.dp), fontSize = 11.sp)
                            Text(file, fontSize = 12.sp, color = Color(0xFF2563EB))
                        }
                    }
                }

                Row(
                    modifier = Modifier.fillMaxWidth(),
                    horizontalArrangement = Arrangement.SpaceBetween,
                    verticalAlignment = Alignment.CenterVertically
                ) {
                    Column {
                        Text("Insurance Carrier", fontSize = 11.sp, color = Color(0xFF687280), fontWeight = FontWeight.Bold)
                        Text(appointment.insuranceInfo, fontSize = 12.sp)
                    }
                    Column(horizontalAlignment = Alignment.End) {
                        Text("Fee: ₹${appointment.amountPaid}", fontSize = 12.sp, fontWeight = FontWeight.Bold)
                        Text(appointment.paymentStatus, color = Color(0xFF15803D), fontSize = 11.sp, fontWeight = FontWeight.Bold)
                    }
                }

                Divider()

                Column(verticalArrangement = Arrangement.spacedBy(8.dp)) {
                    Row(modifier = Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.spacedBy(10.dp)) {
                        Button(
                            onClick = {
                                onStatusChange("Checked In")
                                Toast.makeText(context, "Patient marked Checked In!", Toast.LENGTH_SHORT).show()
                            },
                            colors = ButtonDefaults.buttonColors(containerColor = Color(0xFF3B82F6)),
                            shape = RoundedCornerShape(10.dp),
                            modifier = Modifier.weight(1f).height(46.dp).testTag("hosp_checkin_btn")
                        ) { Text("Mark Checked In", fontSize = 12.sp, fontWeight = FontWeight.Bold) }
                        
                        Button(
                            onClick = {
                                onStatusChange("Completed")
                                Toast.makeText(context, "Appointment completed!", Toast.LENGTH_SHORT).show()
                            },
                            colors = ButtonDefaults.buttonColors(containerColor = Color(0xFF0D9488)),
                            shape = RoundedCornerShape(10.dp),
                            modifier = Modifier.weight(1f).height(46.dp).testTag("hosp_complete_btn")
                        ) { Text("Mark Completed", fontSize = 12.sp, fontWeight = FontWeight.Bold) }
                    }

                    Row(modifier = Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.spacedBy(10.dp)) {
                        OutlinedButton(
                            onClick = {
                                onStatusChange("Cancelled")
                                Toast.makeText(context, "Appointment Cancelled!", Toast.LENGTH_SHORT).show()
                            },
                            border = BorderStroke(1.5.dp, Color.Red),
                            colors = ButtonDefaults.outlinedButtonColors(contentColor = Color.Red),
                            shape = RoundedCornerShape(10.dp),
                            modifier = Modifier.weight(1f).height(46.dp).testTag("hosp_cancel_btn")
                        ) { Text("Cancel Appointment", fontSize = 12.sp, fontWeight = FontWeight.Bold) }
                        
                        OutlinedButton(
                            onClick = {
                                Toast.makeText(context, "Dialing patient: ${appointment.phone}", Toast.LENGTH_LONG).show()
                            },
                            border = BorderStroke(1.5.dp, Color.DarkGray),
                            colors = ButtonDefaults.outlinedButtonColors(contentColor = Color.DarkGray),
                            shape = RoundedCornerShape(10.dp),
                            modifier = Modifier.weight(1f).height(46.dp).testTag("hosp_call_btn")
                        ) { Text("Call Patient", fontSize = 12.sp, fontWeight = FontWeight.Bold) }
                    }
                }
                Spacer(modifier = Modifier.height(16.dp))
            }
        }
    }
}

@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun HospitalPanelScreen(
    onSignOut: () -> Unit
) {
    var isOnline by remember { mutableStateOf(true) }
    var isNotifOn by remember { mutableStateOf(true) }
    var selectedTab by remember { mutableStateOf("Appointments") }
    var selectedSubTab by remember { mutableStateOf("Today") }
    
    val drawerState = rememberDrawerState(initialValue = DrawerValue.Closed)
    val scope = rememberCoroutineScope()
    val context = LocalContext.current

    var showOfflineDialogReason by remember { mutableStateOf(false) }
    var showNotifDialogReason by remember { mutableStateOf(false) }
    var offlineReason by remember { mutableStateOf("All doctors busy") }

    var showIncomingSimulator by remember { mutableStateOf(false) }
    var selectedAppointmentForDetail by remember { mutableStateOf<HospitalAppointment?>(null) }

    var doctorList by remember {
        mutableStateOf(
            listOf(
                HospitalDoctor("DOC-MEHTA", "Dr. Mehta", "Cardiology", true, "Available", Color(0xFFEF4444), "DM"),
                HospitalDoctor("DOC-SHARMA", "Dr. Sharma", "Orthopaedics", false, "OFFLINE", Color(0xFF3B82F6), "DS"),
                HospitalDoctor("DOC-PATEL", "Dr. Patel", "Dermatology", true, "On Break", Color(0xFF10B981), "DP"),
                HospitalDoctor("DOC-RAO", "Dr. Rao", "Neurology", true, "Available", Color(0xFF8B5CF6), "DR")
            )
        )
    }

    var activeDoctorForOfflineToggle by remember { mutableStateOf<HospitalDoctor?>(null) }

    var appointmentsList by remember {
        mutableStateOf(
            listOf(
                HospitalAppointment("APT-001", "Ramesh Kumar", 54, "M", "O+", "+91 98XXX XXXXX", "ramesh@gmail.com", "Jun 12", "10:00 AM", "DOC-MEHTA", "Chest pain", "Scheduled"),
                HospitalAppointment("APT-002", "Sunita Desai", 48, "F", "B-", "+91 97XXX XXXXX", "sunita@gmail.com", "Jun 12", "11:30 AM", "DOC-MEHTA", "Follow-up", "Scheduled"),
                HospitalAppointment("APT-003", "Vikas Shah", 61, "M", "A+", "+91 95XXX XXXXX", "vikas@gmail.com", "Jun 12", "02:00 PM", "DOC-MEHTA", "Palpitations", "Checked In"),
                HospitalAppointment("APT-004", "Amit Patil", 32, "M", "O+", "+91 91XXX XXXXX", "amit@gmail.com", "Jun 12", "09:00 AM", "DOC-SHARMA", "Knee pain", "Scheduled"),
                HospitalAppointment("APT-005", "Priya Mehta", 27, "F", "AB+", "+91 92XXX XXXXX", "priya@gmail.com", "Jun 12", "02:00 PM", "DOC-PATEL", "Rash", "Scheduled"),
                HospitalAppointment("APT-006", "Suresh L.", 45, "M", "B+", "+91 93XXX XXXXX", "suresh@gmail.com", "Jun 12", "03:30 PM", "DOC-RAO", "Migraine", "Scheduled"),

                HospitalAppointment("APT-010", "Anya Roy", 30, "F", "A-", "+91 94XXX XXXXX", "anya@gmail.com", "Jun 13", "10:00 AM", "DOC-MEHTA", "Routine checkup", "Scheduled", isTomorrow = true),
                HospitalAppointment("APT-011", "Rahul Verma", 40, "M", "O+", "+91 95XXX XXXXX", "rahul@gmail.com", "Jun 13", "11:00 AM", "DOC-MEHTA", "BP check", "Scheduled", isTomorrow = true),
                HospitalAppointment("APT-012", "Neha Sen", 25, "F", "O-", "+91 96XXX XXXXX", "neha@gmail.com", "Jun 13", "09:00 AM", "DOC-PATEL", "Acne advisory", "Scheduled", isTomorrow = true)
            )
        )
    }

    var expandedDoctorToday by remember { mutableStateOf(mapOf("DOC-MEHTA" to true, "DOC-SHARMA" to true, "DOC-PATEL" to true, "DOC-RAO" to true)) }
    var expandedDoctorTomorrow by remember { mutableStateOf(mapOf("DOC-MEHTA" to true, "DOC-PATEL" to true)) }

    if (showOfflineDialogReason) {
        HospitalReasonDialog(
            title = "Deactivate Hospital Panel?",
            subtitle = "Select reference offline reason:",
            reasons = listOf("All doctors busy", "Emergency cases only", "Closed today", "Equipment maintenance"),
            onDismiss = { showOfflineDialogReason = false },
            onConfirm = { r ->
                offlineReason = r
                isOnline = false
                showOfflineDialogReason = false
            }
        )
    }

    if (showNotifDialogReason) {
        HospitalReasonDialog(
            title = "Mute Sound Alerts?",
            subtitle = "Select alert muting reason:",
            reasons = listOf("All doctors busy", "Emergency cases only", "Closed today", "Equipment maintenance"),
            onDismiss = { showNotifDialogReason = false },
            onConfirm = { r ->
                isNotifOn = false
                showNotifDialogReason = false
                Toast.makeText(context, "Muted: $r", Toast.LENGTH_SHORT).show()
            }
        )
    }

    if (activeDoctorForOfflineToggle != null) {
        HospitalReasonDialog(
            title = "Deactivate ${activeDoctorForOfflineToggle!!.name}?",
            subtitle = "Select offline classification reason:",
            reasons = listOf("On leave", "Emergency", "Not available today"),
            onDismiss = { activeDoctorForOfflineToggle = null },
            onConfirm = { r ->
                val id = activeDoctorForOfflineToggle!!.id
                doctorList = doctorList.map {
                    if (it.id == id) it.copy(isOnline = false, statusText = "OFFLINE", offlineReason = r) else it
                }
                activeDoctorForOfflineToggle = null
                Toast.makeText(context, "Deactivated doctor successfully", Toast.LENGTH_SHORT).show()
            }
        )
    }

    if (showIncomingSimulator) {
        HospitalIncomingRequestScreen(
            onDecline = { showIncomingSimulator = false },
            onAccept = { name, age, gender, docId, slot, reason, amt ->
                val newApt = HospitalAppointment(
                    id = "HOSP-${(100..999).random()}",
                    patientName = name,
                    age = age,
                    gender = gender,
                    doctorId = docId,
                    timeSlot = slot,
                    reason = reason,
                    amountPaid = amt,
                    status = "Scheduled"
                )
                appointmentsList = appointmentsList + newApt
                showIncomingSimulator = false
                Toast.makeText(context, "Scheduled cleanly!", Toast.LENGTH_SHORT).show()
            }
        )
    } else {
        ModalNavigationDrawer(
            drawerState = drawerState,
            drawerContent = {
                ModalDrawerSheet {
                    Spacer(modifier = Modifier.height(16.dp))
                    Row(
                        modifier = Modifier.padding(horizontal = 20.dp, vertical = 12.dp),
                        verticalAlignment = Alignment.CenterVertically
                    ) {
                        Box(
                            modifier = Modifier
                                .size(44.dp)
                                .clip(CircleShape)
                                .background(Color(0xFFFEF2F2)),
                            contentAlignment = Alignment.Center
                        ) { Text("🏨", fontSize = 20.sp) }
                        Spacer(modifier = Modifier.width(12.dp))
                        Column {
                            Text("Ruby Hall Clinic", fontWeight = FontWeight.Bold, fontSize = 15.sp)
                            Text("Hospital Panel Center • HOSP-900", fontSize = 11.sp, color = Color(0xFF687280))
                        }
                    }
                    Divider(modifier = Modifier.padding(vertical = 8.dp))
                    listOf(
                        "Appointments" to Icons.Filled.LocalHospital,
                        "Hospital History" to Icons.Filled.History,
                        "Payments" to Icons.Filled.Payment,
                        "Hospital Profile" to Icons.Filled.Person
                    ).forEach { (tab, icon) ->
                        NavigationDrawerItem(
                            label = { Text(tab, fontWeight = FontWeight.Bold) },
                            selected = selectedTab == tab,
                            onClick = {
                                selectedTab = tab
                                scope.launch { drawerState.close() }
                            },
                            icon = { Icon(icon, tab) },
                            modifier = Modifier.padding(horizontal = 12.dp, vertical = 4.dp)
                        )
                    }
                    Spacer(modifier = Modifier.height(16.dp))
                    NavigationDrawerItem(
                        label = { Text("Sign Out", color = Color.Red, fontWeight = FontWeight.Bold) },
                        selected = false,
                        onClick = {
                            scope.launch { drawerState.close() }
                            onSignOut()
                        },
                        icon = { Icon(Icons.Filled.ExitToApp, "Sign Out", tint = Color.Red) },
                        modifier = Modifier.padding(horizontal = 12.dp)
                    )
                }
            }
        ) {
            Box(modifier = Modifier.fillMaxSize()) {
                Scaffold(
                    topBar = {
                        TopAppBar(
                            title = { Text("Hospital Panel", fontSize = 16.sp, fontWeight = FontWeight.Black) },
                            navigationIcon = {
                                IconButton(onClick = { scope.launch { drawerState.open() } }) {
                                    Icon(Icons.Filled.Menu, "Toggle Drawer")
                                }
                            },
                            actions = {
                                Button(
                                    onClick = {
                                        if (isNotifOn) showNotifDialogReason = true else isNotifOn = true
                                    },
                                    colors = ButtonDefaults.buttonColors(
                                        containerColor = if (isNotifOn) Color(0xFFDC2626) else Color(0xFF687280)
                                    ),
                                    contentPadding = PaddingValues(horizontal = 8.dp),
                                    modifier = Modifier
                                        .padding(end = 12.dp)
                                        .height(32.dp)
                                        .testTag("hosp_notif_toggle_btn")
                                ) {
                                    Icon(
                                        imageVector = if (isNotifOn) Icons.Filled.Notifications else Icons.Filled.NotificationsOff,
                                        contentDescription = null,
                                        tint = Color.White,
                                        modifier = Modifier.size(16.dp)
                                    )
                                    Spacer(modifier = Modifier.width(4.dp))
                                    Text(if (isNotifOn) "Alerts ON" else "Alerts OFF", fontSize = 11.sp, fontWeight = FontWeight.Bold)
                                }
                            },
                            colors = TopAppBarDefaults.topAppBarColors(
                                containerColor = Color(0xFFDC2626),
                                titleContentColor = Color.White,
                                navigationIconContentColor = Color.White
                            )
                        )
                    },
                    containerColor = Color(0xFFF8FAFC)
                ) { innerPadding ->
                    Column(
                        modifier = Modifier
                            .fillMaxSize()
                            .padding(innerPadding)
                    ) {
                        val barColor = if (isOnline) Color(0xFFDC2626) else Color(0xFF64748B)
                        val barText = if (isOnline) "Direct Consultation Live Queues" else "Hospital Offline - $offlineReason"
                        Box(
                            modifier = Modifier
                                .fillMaxWidth()
                                .background(barColor)
                                .padding(vertical = 6.dp),
                            contentAlignment = Alignment.Center
                        ) { Text(barText, color = Color.White, fontSize = 12.sp, fontWeight = FontWeight.Bold) }

                        when (selectedTab) {
                            "Appointments" -> {
                                Column(modifier = Modifier.fillMaxSize()) {
                                    TabRow(
                                        selectedTabIndex = when (selectedSubTab) {
                                            "Today" -> 0
                                            "Tomorrow" -> 1
                                            else -> 2
                                        },
                                        containerColor = Color.White,
                                        contentColor = Color(0xFFDC2626)
                                    ) {
                                        listOf("Today", "Tomorrow", "Doctors").forEach { sub ->
                                            Tab(
                                                selected = selectedSubTab == sub,
                                                onClick = { selectedSubTab = sub }
                                            ) { Text(sub, modifier = Modifier.padding(vertical = 12.dp), fontWeight = FontWeight.Bold, fontSize = 13.sp) }
                                        }
                                    }

                                    LazyColumn(
                                        modifier = Modifier
                                            .fillMaxSize()
                                            .padding(16.dp),
                                        verticalArrangement = Arrangement.spacedBy(16.dp)
                                    ) {
                                        if (selectedSubTab != "Doctors") {
                                            item {
                                                Card(
                                                    modifier = Modifier.fillMaxWidth(),
