                                                                Text("Tomorrow's appointments", fontSize = 11.sp, color = Color(0xFF687280))
                                                                Text("12", fontSize = 18.sp, fontWeight = FontWeight.Bold, color = Color(0xFF3B82F6))
                                                            }
                                                        }
                                                    }
                                                    Row(horizontalArrangement = Arrangement.spacedBy(8.dp)) {
                                                        Card(modifier = Modifier.weight(1f), colors = CardDefaults.cardColors(containerColor = Color.White)) {
                                                            Column(modifier = Modifier.padding(12.dp)) {
                                                                Text("Doctors available", fontSize = 11.sp, color = Color(0xFF687280))
                                                                Text("${doctorList.count { it.isOnline }}", fontSize = 18.sp, fontWeight = FontWeight.Bold, color = Color(0xFF16A34A))
                                                            }
                                                        }
                                                        Card(modifier = Modifier.weight(1f), colors = CardDefaults.cardColors(containerColor = Color.White)) {
                                                            Column(modifier = Modifier.padding(12.dp)) {
                                                                Text("Doctors offline", fontSize = 11.sp, color = Color(0xFF687280))
