                                                                            }
                                                                            Spacer(modifier = Modifier.width(10.dp))
                                                                            Column {
                                                                                Text(doc.name, fontWeight = FontWeight.Bold)
                                                                                Text(doc.specialization, fontSize = 11.sp, color = Color(0xFF687280))
                                                                            }
                                                                        }
                                                                        Row(verticalAlignment = Alignment.CenterVertically) {
                                                                            Text(if (doc.isOnline) doc.statusText else "OFFLINE", fontSize = 11.sp, fontWeight = FontWeight.Bold, color = if (doc.isOnline) Color(0xFF16A34A) else Color.Red)
