                                                                                checked = doc.isOnline,
                                                                                onCheckedChange = { if (it) { doctorList = doctorList.map { d -> if (d.id == doc.id) d.copy(isOnline = true, statusText = "Available") else d } } else { activeDoctorForOfflineToggle = doc } }
