                                                                    }

                                                                    if (!doc.isOnline) {
                                                                        Box(modifier = Modifier.fillMaxWidth().background(Color(0xFFFEF2F2)).padding(8.dp)) {
                                                                            Text("${doc.name} is currently offline. Patients will be notified.", fontSize = 12.sp, color = Color(0xFFDC2626), fontWeight = FontWeight.SemiBold)
                                                                        }
                                                                    }

                                                                    if (isExpanded) {
                                                                        Divider()
                                                                        if (filtered.isEmpty()) {
                                                                            Box(modifier = Modifier.fillMaxWidth().padding(12.dp), contentAlignment = Alignment.Center) {
                                                                                Text("No appointments scheduled", fontSize = 11.sp, color = Color(0xFF687280))
                                                                            }
                                                                        } else {
                                                                            filtered.forEach { appt ->
                                                                                Row(
                                                                                    modifier = Modifier
                                                                                        .fillMaxWidth()
                                                                                        .clickable { selectedAppointmentForDetail = appt }
                                                                                        .testTag("hosp_appoint_card_${appt.id}")
                                                                                        .padding(12.dp),
                                                                                    horizontalArrangement = Arrangement.SpaceBetween,
                                                                                    verticalAlignment = Alignment.CenterVertically
                                                                                ) {
                                                                                    Column(modifier = Modifier.weight(1f)) {
