                                                                                        Text("Age ${appt.age} • ${appt.id} • ${appt.reason}", fontSize = 11.sp, color = Color(0xFF687280))
                                                                                    }
                                                                                    Box(
                                                                                        modifier = Modifier
                                                                                            .background(
                                                                                                when (appt.status) {
                                                                                                    "Scheduled" -> Color(0xFFFEF3C7)
                                                                                                    "Checked In" -> Color(0xFFDBEAFE)
                                                                                                    "Completed" -> Color(0xFFD1FAE5)
                                                                                                    else -> Color(0xFFFEE2E2)
                                                                                                },
                                                                                                RoundedCornerShape(4.dp)
                                                                                            )
                                                                                            .padding(horizontal = 6.dp, vertical = 2.dp)
                                                                                    ) { Text(appt.status, fontSize = 10.sp, fontWeight = FontWeight.Bold) }
                                                                                }
                                                                                Divider()
                                                                            }
                                                                        }
                                                                    }
                                                                }
                                                            }
                                                        }
                                                    }
                                                }
                                            }
                                            "Tomorrow" -> {
                                                listOfNotNull(doctorList.find { it.id == "DOC-MEHTA" }, doctorList.find { it.id == "DOC-PATEL" }).forEach { doc ->
                                                    val filtered = appointmentsList.filter { it.isTomorrow && it.doctorId == doc.id }
                                                    val isExpanded = expandedDoctorTomorrow[doc.id] ?: true
                                                    item {
                                                        Card(modifier = Modifier.fillMaxWidth(), colors = CardDefaults.cardColors(containerColor = Color.White)) {
                                                            Column {
                                                                Row(
                                                                    modifier = Modifier
                                                                        .fillMaxWidth()
                                                                        .clickable { expandedDoctorTomorrow = expandedDoctorTomorrow + (doc.id to !isExpanded) }
                                                                        .padding(12.dp),
                                                                    horizontalArrangement = Arrangement.SpaceBetween,
                                                                    verticalAlignment = Alignment.CenterVertically
                                                                ) {
                                                                    Row(verticalAlignment = Alignment.CenterVertically) {
                                                                        Box(modifier = Modifier.size(36.dp).clip(CircleShape).background(doc.avatarColor), contentAlignment = Alignment.Center) {
                                                                            Text(doc.initials, color = Color.White, fontWeight = FontWeight.Bold, fontSize = 12.sp)
                                                                        }
                                                                        Spacer(modifier = Modifier.width(10.dp))
                                                                        Column {
                                                                            Text(doc.name, fontWeight = FontWeight.Bold)
                                                                            Text("${filtered.size} scheduled tomorrow", fontSize = 11.sp, color = Color(0xFF687280))
                                                                        }
                                                                    }
                                                                    Icon(if (isExpanded) Icons.Filled.ExpandLess else Icons.Filled.ExpandMore, null)
                                                                }
                                                                if (isExpanded) {
                                                                    Divider()
                                                                    filtered.forEach { appt ->
                                                                        Row(
                                                                            modifier = Modifier
                                                                                .fillMaxWidth()
                                                                                .clickable { selectedAppointmentForDetail = appt }
                                                                                .padding(12.dp)
                                                                        ) {
                                                                            Column {
                                                                                Text("${appt.timeSlot} | ${appt.patientName}", fontWeight = FontWeight.Bold, fontSize = 13.sp)
                                                                                Text("ID: ${appt.id} • Reason: ${appt.reason}", fontSize = 11.sp, color = Color(0xFF687280))
                                                                            }
                                                                        }
                                                                        Divider()
                                                                    }
                                                                }
                                                            }
                                                        }
                                                    }
                                                }
                                            }
                                            "Doctors" -> {
                                                doctorList.forEach { doc ->
                                                    item {
                                                        Card(modifier = Modifier.fillMaxWidth(), colors = CardDefaults.cardColors(containerColor = Color.White)) {
                                                            Row(modifier = Modifier.fillMaxWidth().padding(12.dp), horizontalArrangement = Arrangement.SpaceBetween, verticalAlignment = Alignment.CenterVertically) {
                                                                Row(verticalAlignment = Alignment.CenterVertically) {
                                                                    Box(modifier = Modifier.size(36.dp).clip(CircleShape).background(doc.avatarColor), contentAlignment = Alignment.Center) {
                                                                        Text(doc.initials, color = Color.White, fontWeight = FontWeight.Bold)
                                                                    }
                                                                    Spacer(modifier = Modifier.width(10.dp))
                                                                    Column {
                                                                        Text(doc.name, fontWeight = FontWeight.Bold)
                                                                        Text(doc.specialization, fontSize = 11.sp)
                                                                        if (!doc.isOnline && doc.offlineReason.isNotEmpty()) {
                                                                            Text("Offline: ${doc.offlineReason}", fontSize = 11.sp, color = Color.Red, fontWeight = FontWeight.Bold)
                                                                        }
                                                                    }
                                                                }
                                                                Row(verticalAlignment = Alignment.CenterVertically) {
                                                                    Text(if (doc.isOnline) "ONLINE" else "OFFLINE", fontSize = 10.sp, fontWeight = FontWeight.Black, color = if (doc.isOnline) Color(0xFF16A34A) else Color.Red)
                                                                    Spacer(modifier = Modifier.width(4.dp))
                                                                    Switch(
                                                                        checked = doc.isOnline,
                                                                        onCheckedChange = { if (it) { doctorList = doctorList.map { d -> if (d.id == doc.id) d.copy(isOnline = true, statusText = "Available") else d } } else { activeDoctorForOfflineToggle = doc } }
                                                                    )
                                                                }
                                                            }
                                                        }
                                                    }
                                                }
                                            }
                                        }
                                    }
                                }
                            }
                            "Hospital History" -> {
                                HospitalHistoryTabContent(appointmentsList)
                            }
                            "Payments" -> {
                                HospitalPaymentsTabContent()
                            }
                            "Hospital Profile" -> {
                                HospitalProfileTabContent(onSignOut)
                            }
                        }
                    }
                }

                if (selectedAppointmentForDetail != null) {
                    val appt = selectedAppointmentForDetail!!
                    HospitalAppointmentDetailBottomSheet(
                        appointment = appt,
                        doctor = doctorList.find { it.id == appt.doctorId },
                        onDismiss = { selectedAppointmentForDetail = null },
                        onStatusChange = { stat ->
                            appointmentsList = appointmentsList.map { if (it.id == appt.id) it.copy(status = stat) else it }
                            selectedAppointmentForDetail = selectedAppointmentForDetail?.copy(status = stat)
                        }
                    )
                }
            }
        }
    }
}

@Composable
fun HospitalHistoryTabContent(appointments: List<HospitalAppointment>) {
    var activeSubTab by remember { mutableStateOf("Treated") }
    Column(modifier = Modifier.fillMaxSize()) {
        TabRow(selectedTabIndex = if (activeSubTab == "Treated") 0 else 1, containerColor = Color.White, contentColor = Color(0xFFDC2626)) {
            Tab(selected = activeSubTab == "Treated", onClick = { activeSubTab = "Treated" }) { Text("Treated", modifier = Modifier.padding(12.dp), fontWeight = FontWeight.Bold) }
            Tab(selected = activeSubTab == "Cancelled", onClick = { activeSubTab = "Cancelled" }) { Text("Cancelled", modifier = Modifier.padding(12.dp), fontWeight = FontWeight.Bold) }
        }
        Spacer(modifier = Modifier.height(16.dp))
        val target = if (activeSubTab == "Treated") "Completed" else "Cancelled"
        val filtered = appointments.filter { it.status == target }
        if (filtered.isEmpty()) {
            Box(modifier = Modifier.fillMaxSize().padding(32.dp), contentAlignment = Alignment.Center) { Text("No historic tickets", color = Color(0xFF687280)) }
        } else {
            LazyColumn(modifier = Modifier.fillMaxSize().padding(horizontal = 16.dp), verticalArrangement = Arrangement.spacedBy(8.dp)) {
                items(filtered) { appt ->
                    Card(modifier = Modifier.fillMaxWidth(), colors = CardDefaults.cardColors(containerColor = Color.White)) {
                        Row(modifier = Modifier.padding(12.dp).fillMaxWidth(), horizontalArrangement = Arrangement.SpaceBetween) {
                            Column {
                                Text("${appt.id} | ${appt.patientName}", fontWeight = FontWeight.Bold)
                                Text("Fee: ₹${appt.amountPaid} • ${appt.timeSlot}", fontSize = 12.sp, color = Color(0xFF687280))
                            }
                        }
                    }
                }
            }
        }
    }
}

