// --------------------------------------------------------------------------
// RESTAURANT PANEL COGNITIVE EXPERIENCE
// --------------------------------------------------------------------------

data class RestaurantOrderItem(
    val name: String,
    val size: String, // "Full", "Half", "Quarter", "Regular", "Large", "Medium", "Small"
    val quantity: Int,
    val unitPrice: Int
)

data class RestaurantOrder(
    val id: String,
    val orderType: String, // "Dine-in" or "Delivery"
    val destination: String, // "Table 4" or "Crowmix App" or address
    val items: List<RestaurantOrderItem>,
    val specialInstruction: String?,
    val totalPrice: Int,
    val timeAgo: String,
    val status: String, // "Preparing", "Ready Waiting for Rider", "Served" etc.
    val customerName: String? = null,
    val customerPhone: String? = null,
    val customerNote: String? = null
)

data class RestaurantStaff(
    val name: String,
    val role: String,
    val isActive: Boolean
)

@Composable
fun RestaurantReasonDialog(
    title: String,
    reasons: List<String>,
    onDismiss: () -> Unit,
    onConfirm: (String) -> Unit
) {
    var selectedReason by remember { mutableStateOf(reasons.first()) }
    var customReason by remember { mutableStateOf("") }

    AlertDialog(
        onDismissRequest = onDismiss,
        title = { Text(title, fontWeight = FontWeight.Bold) },
        text = {
            Column {
                reasons.forEach { reason ->
                    Row(
                        modifier = Modifier
                            .fillMaxWidth()
                            .clickable { selectedReason = reason }
                            .padding(vertical = 6.dp),
                        verticalAlignment = Alignment.CenterVertically
                    ) {
                        RadioButton(
                            selected = (selectedReason == reason),
                            onClick = { selectedReason = reason }
                        )
                        Spacer(modifier = Modifier.width(8.dp))
                        Text(reason, fontSize = 14.sp)
                    }
                }
                Row(
                    modifier = Modifier
                        .fillMaxWidth()
                        .clickable { selectedReason = "Other" }
                        .padding(vertical = 6.dp),
                    verticalAlignment = Alignment.CenterVertically
                ) {
                    RadioButton(
                        selected = (selectedReason == "Other"),
                        onClick = { selectedReason = "Other" }
                    )
                    Spacer(modifier = Modifier.width(8.dp))
                    Text("Other", fontSize = 14.sp)
                }

                if (selectedReason == "Other") {
                    Spacer(modifier = Modifier.height(8.dp))
                    OutlinedTextField(
                        value = customReason,
                        onValueChange = { customReason = it },
                        placeholder = { Text("Specify other reason...") },
                        modifier = Modifier.fillMaxWidth(),
                        singleLine = true
                    )
                }
            }
        },
        confirmButton = {
            Button(
                onClick = {
                    val finalReason = if (selectedReason == "Other") {
                        if (customReason.isNotBlank()) customReason else "Other reason"
                    } else {
                        selectedReason
                    }
                    onConfirm(finalReason)
                },
                colors = ButtonDefaults.buttonColors(containerColor = Color(0xFFEA580C))
            ) {
                Text("OK")
            }
        },
        dismissButton = {
            TextButton(onClick = onDismiss) {
                Text("Cancel", color = Color(0xFF687280))
            }
        }
    )
}

@Composable
fun RestaurantIncomingTimerScreen(
    order: RestaurantOrder,
    onDecline: () -> Unit,
    onAccept: () -> Unit
) {
    var timeLeft by remember { mutableStateOf(30) }

    LaunchedEffect(key1 = timeLeft) {
        if (timeLeft > 0) {
            delay(1000L)
            timeLeft--
        } else {
            onDecline()
        }
    }

    Scaffold(
        topBar = {
            Box(
                modifier = Modifier
                    .fillMaxWidth()
                    .background(Color(0xFFEA580C))
                    .statusBarsPadding()
                    .padding(16.dp),
                contentAlignment = Alignment.Center
            ) {
                Text(
                    text = "New Order!",
                    color = Color.White,
                    fontWeight = FontWeight.Bold,
                    fontSize = 18.sp
                )
            }
        },
        containerColor = Color(0xFFF8FAFC)
    ) { innerPadding ->
        Column(
            modifier = Modifier
                .fillMaxSize()
                .padding(innerPadding)
                .padding(16.dp),
            verticalArrangement = Arrangement.SpaceBetween,
            horizontalAlignment = Alignment.CenterHorizontally
        ) {
            Column(
                horizontalAlignment = Alignment.CenterHorizontally,
                verticalArrangement = Arrangement.spacedBy(16.dp),
                modifier = Modifier.fillMaxWidth()
            ) {
                Spacer(modifier = Modifier.height(16.dp))
                Box(
                    contentAlignment = Alignment.Center,
                    modifier = Modifier.size(90.dp)
                ) {
                    CircularProgressIndicator(
                        progress = { timeLeft / 30f },
                        color = Color(0xFFEA580C),
                        trackColor = Color(0xFFFED7AA),
                        strokeWidth = 6.dp,
                        modifier = Modifier.fillMaxSize()
                    )
                    Text(
                        text = "${timeLeft}s",
                        fontWeight = FontWeight.Black,
                        fontSize = 24.sp,
                        color = Color(0xFFEA580C)
                    )
                }

                Text(
                    text = "Accept this order before timer runs out",
                    fontSize = 13.sp,
                    color = Color(0xFF687280)
                )

                Card(
                    modifier = Modifier.fillMaxWidth(),
                    shape = RoundedCornerShape(16.dp),
                    colors = CardDefaults.cardColors(containerColor = Color.White),
                    border = BorderStroke(1.dp, Color(0xFFE2E8F0))
                ) {
                    Column(
                        modifier = Modifier.padding(16.dp),
                        verticalArrangement = Arrangement.spacedBy(12.dp)
                    ) {
                        Row(
                            modifier = Modifier.fillMaxWidth(),
                            horizontalArrangement = Arrangement.SpaceBetween,
                            verticalAlignment = Alignment.CenterVertically
                        ) {
                            Box(
                                modifier = Modifier
                                    .background(Color(0xFFFFF7ED), RoundedCornerShape(6.dp))
                                    .padding(horizontal = 8.dp, vertical = 4.dp)
                            ) {
                                Text(
                                    text = order.orderType.uppercase(),
                                    color = Color(0xFFD97706),
                                    fontWeight = FontWeight.Bold,
                                    fontSize = 11.sp
                                )
                            }
                            Text(
                                text = order.id,
                                fontWeight = FontWeight.Black,
                                fontSize = 16.sp,
                                color = Color(0xFF1E293B)
                            )
                        }

                        Divider(color = Color(0xFFF1F5F9))

                        Column {
                            Text("ORDER TYPE & TABLE / ADDRESS", fontSize = 10.sp, color = Color(0xFF687280), fontWeight = FontWeight.Bold)
                            Text(order.destination, fontWeight = FontWeight.Bold, fontSize = 15.sp, color = Color(0xFF0F172A))
                        }

                        if (order.customerName != null) {
                            Row(
                                modifier = Modifier.fillMaxWidth(),
                                horizontalArrangement = Arrangement.SpaceBetween
                            ) {
                                Column {
                                    Text("CUSTOMER NAME", fontSize = 10.sp, color = Color(0xFF687280), fontWeight = FontWeight.Bold)
                                    Text(order.customerName, fontWeight = FontWeight.SemiBold, fontSize = 13.sp)
                                }
                                Column(horizontalAlignment = Alignment.End) {
                                    Text("PHONE", fontSize = 10.sp, color = Color(0xFF687280), fontWeight = FontWeight.Bold)
                                    Text(order.customerPhone ?: "N/A", fontWeight = FontWeight.Medium, fontSize = 13.sp)
                                }
                            }
                        }

                        Divider(color = Color(0xFFF1F5F9))

                        Column {
                            Text("ITEMS ORDERED", fontSize = 10.sp, color = Color(0xFF687280), fontWeight = FontWeight.Bold)
                            Spacer(modifier = Modifier.height(8.dp))
                            order.items.forEach { item ->
                                Row(
                                    modifier = Modifier.fillMaxWidth(),
                                    horizontalArrangement = Arrangement.SpaceBetween
                                ) {
                                    Text("${item.quantity}x ${item.name} (${item.size})", fontSize = 13.sp, color = Color(0xFF334155))
                                    Text("₹${item.unitPrice * item.quantity}", fontSize = 13.sp, fontWeight = FontWeight.Medium, color = Color(0xFF334155))
                                }
                            }
                        }

                        if (!order.specialInstruction.isNullOrEmpty()) {
                            Box(
                                modifier = Modifier
                                    .fillMaxWidth()
                                    .background(Color(0xFFFEF3C7), RoundedCornerShape(8.dp))
                                    .border(1.dp, Color(0xFFFCD34D), RoundedCornerShape(8.dp))
                                    .padding(10.dp)
                            ) {
                                Row(verticalAlignment = Alignment.CenterVertically) {
                                    Text("⚠️", fontSize = 14.sp)
                                    Spacer(modifier = Modifier.width(6.dp))
                                    Text(
                                        text = order.specialInstruction,
                                        color = Color(0xFF92400E),
                                        fontSize = 12.sp,
                                        fontWeight = FontWeight.SemiBold
                                    )
                                }
                            }
                        }

                        Divider(color = Color(0xFFF1F5F9))

                        Row(
                            modifier = Modifier.fillMaxWidth(),
                            horizontalArrangement = Arrangement.SpaceBetween,
                            verticalAlignment = Alignment.CenterVertically
                        ) {
                            Text("TOTAL AMOUNT", fontWeight = FontWeight.Bold, color = Color(0xFF687280), fontSize = 13.sp)
                            Text("₹${order.totalPrice}", fontWeight = FontWeight.Black, color = Color(0xFFEA580C), fontSize = 18.sp)
                        }
                    }
                }
            }

            Row(
                modifier = Modifier
                    .fillMaxWidth()
                    .navigationBarsPadding(),
                horizontalArrangement = Arrangement.spacedBy(16.dp)
            ) {
                OutlinedButton(
                    onClick = onDecline,
                    border = BorderStroke(1.5.dp, Color(0xFFEF4444)),
                    colors = ButtonDefaults.outlinedButtonColors(contentColor = Color(0xFFEF4444)),
                    shape = RoundedCornerShape(12.dp),
                    modifier = Modifier
                        .weight(1f)
                        .height(48.dp)
                        .testTag("rest_incoming_decline_btn")
                ) {
                    Text("Decline", fontWeight = FontWeight.Bold, fontSize = 15.sp)
                }

                Button(
                    onClick = onAccept,
                    colors = ButtonDefaults.buttonColors(containerColor = Color(0xFF16A34A)),
                    shape = RoundedCornerShape(12.dp),
                    modifier = Modifier
                        .weight(1f)
                        .height(48.dp)
                        .testTag("rest_incoming_accept_btn")
                ) {
                    Text("Accept", fontWeight = FontWeight.Bold, fontSize = 15.sp, color = Color.White)
                }
            }
        }
    }
}

@Composable
fun RestaurantOrderActiveScreen(
    order: RestaurantOrder,
    onBack: () -> Unit,
    onStatusTransition: (String) -> Unit
) {
    var isStaffSectionExpanded by remember { mutableStateOf(true) }
    var staffList by remember {
        mutableStateOf(
            listOf(
                RestaurantStaff("Chef Ramesh", "Head Kitchen", true),
                RestaurantStaff("Chef Priya", "Desserts & Tandoor", false)
            )
        )
    }

    Scaffold(
        topBar = {
            Box(
                modifier = Modifier
                    .fillMaxWidth()
                    .background(Color(0xFFEA580C))
                    .statusBarsPadding()
                    .padding(horizontal = 4.dp, vertical = 12.dp)
            ) {
                Row(
                    verticalAlignment = Alignment.CenterVertically,
                    modifier = Modifier.fillMaxWidth()
                ) {
                    IconButton(onClick = onBack) {
                        Icon(Icons.AutoMirrored.Filled.ArrowBack, contentDescription = "Back", tint = Color.White)
                    }
                    Text(
                        text = "Active Kitchen Ticket",
                        color = Color.White,
                        fontWeight = FontWeight.Bold,
                        fontSize = 16.sp
                    )
                }
            }
        },
        containerColor = Color(0xFFF8FAFC)
    ) { innerPadding ->
        Column(
            modifier = Modifier
                .fillMaxSize()
                .padding(innerPadding)
                .padding(16.dp)
                .verticalScroll(rememberScrollState()),
            verticalArrangement = Arrangement.spacedBy(16.dp)
        ) {
            Card(
                modifier = Modifier.fillMaxWidth(),
                colors = CardDefaults.cardColors(containerColor = Color.White),
                shape = RoundedCornerShape(12.dp),
                border = BorderStroke(1.dp, Color(0xFFE2E8F0))
            ) {
                Column(
                    modifier = Modifier.padding(16.dp),
                    verticalArrangement = Arrangement.spacedBy(12.dp)
                ) {
                    Row(
                        modifier = Modifier.fillMaxWidth(),
                        horizontalArrangement = Arrangement.SpaceBetween
                    ) {
                        Column {
                            Text(order.id, fontWeight = FontWeight.Black, fontSize = 20.sp, color = Color(0xFF1E293B))
                            Text(order.destination, fontSize = 13.sp, color = Color(0xFF687280), fontWeight = FontWeight.Medium)
                        }
                        Box(
                            modifier = Modifier
                                .background(Color(0xFFFFF7ED), RoundedCornerShape(6.dp))
                                .border(1.dp, Color(0xFFFED7AA), RoundedCornerShape(6.dp))
                                .padding(horizontal = 10.dp, vertical = 4.dp)
                        ) {
                            Text(
                                text = order.status.uppercase(),
                                color = Color(0xFFEA580C),
                                fontWeight = FontWeight.Black,
                                fontSize = 11.sp
                            )
                        }
                    }

                    Divider(color = Color(0xFFF1F5F9))

                    Text("ITEMS LIST", fontSize = 11.sp, color = Color(0xFF687280), fontWeight = FontWeight.Bold)
                    order.items.forEach { item ->
                        Row(
                            modifier = Modifier.fillMaxWidth(),
                            horizontalArrangement = Arrangement.SpaceBetween,
                            verticalAlignment = Alignment.CenterVertically
                        ) {
                            Column {
                                Text(item.name, fontWeight = FontWeight.Bold, fontSize = 14.sp)
                                Text("Size: ${item.size} | Qty: ${item.quantity}", fontSize = 12.sp, color = Color(0xFF687280))
                            }
                            Text("₹${item.unitPrice * item.quantity}", fontWeight = FontWeight.Bold, fontSize = 14.sp)
                        }
                    }

                    if (!order.specialInstruction.isNullOrEmpty()) {
                        Spacer(modifier = Modifier.height(8.dp))
                        Box(
                            modifier = Modifier
                                .fillMaxWidth()
                                .background(Color(0xFFFFFBEB), RoundedCornerShape(8.dp))
                                .border(1.dp, Color(0xFFFDE68A), RoundedCornerShape(8.dp))
                                .padding(12.dp)
                        ) {
                            Row(verticalAlignment = Alignment.Top) {
                                Text("⚠️", fontSize = 14.sp, modifier = Modifier.padding(top = 1.dp))
                                Spacer(modifier = Modifier.width(8.dp))
                                Column {
                                    Text("Cooking Instruction:", fontSize = 11.sp, color = Color(0xFFB45309), fontWeight = FontWeight.Bold)
                                    Text(order.specialInstruction, color = Color(0xFF92400E), fontSize = 13.sp, fontWeight = FontWeight.SemiBold)
                                }
                            }
                        }
                    }

                    if (!order.customerNote.isNullOrEmpty() || (order.customerName != null)) {
                        Spacer(modifier = Modifier.height(8.dp))
                        Column {
                            Text("CUSTOMER NOTE / DETAILS", fontSize = 10.sp, color = Color(0xFF687280), fontWeight = FontWeight.Bold)
                            Text(order.customerNote ?: "Please handle with care. Deliver hot.", fontSize = 12.sp, color = Color.DarkGray)
                        }
                    }

                    Divider(color = Color(0xFFF1F5F9))

                    Column(verticalArrangement = Arrangement.spacedBy(4.dp)) {
                        Row(modifier = Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.SpaceBetween) {
                            Text("Subtotal", fontSize = 13.sp, color = Color(0xFF687280))
                            Text("₹${order.totalPrice - 20}", fontSize = 13.sp)
                        }
                        Row(modifier = Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.SpaceBetween) {
                            Text("Packaging / GST", fontSize = 13.sp, color = Color(0xFF687280))
                            Text("₹20", fontSize = 13.sp)
                        }
                        Row(modifier = Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.SpaceBetween) {
                            Text("Total price breakdown", fontSize = 13.sp, fontWeight = FontWeight.Bold)
                            Text("₹${order.totalPrice}", fontSize = 14.sp, fontWeight = FontWeight.Black, color = Color(0xFFEA580C))
                        }
                    }
                }
            }

            Card(
                modifier = Modifier.fillMaxWidth(),
                colors = CardDefaults.cardColors(containerColor = Color.White),
                shape = RoundedCornerShape(12.dp),
                border = BorderStroke(1.dp, Color(0xFFE2E8F0))
            ) {
                Column(
                    modifier = Modifier.padding(16.dp),
                    verticalArrangement = Arrangement.spacedBy(10.dp)
                ) {
                    Text("KITCHEN QUEUE PROGRESS", fontSize = 11.sp, color = Color(0xFF687280), fontWeight = FontWeight.Bold)

                    OutlinedButton(
                        onClick = {
                            onStatusTransition("Cooking")
                        },
                        border = BorderStroke(1.5.dp, Color(0xFFEA580C)),
                        colors = ButtonDefaults.outlinedButtonColors(contentColor = Color(0xFFEA580C)),
                        shape = RoundedCornerShape(10.dp),
                        modifier = Modifier
                            .fillMaxWidth()
                            .height(48.dp)
                            .testTag("rest_start_cooking_btn")
                    ) {
                        Row(
                            verticalAlignment = Alignment.CenterVertically,
                            horizontalArrangement = Arrangement.Center
                        ) {
                            Text("🍳", fontSize = 14.sp)
                            Spacer(modifier = Modifier.width(6.dp))
                            Text("Start Cooking", fontWeight = FontWeight.Bold)
                        }
                    }

                    Button(
                        onClick = {
                            onStatusTransition("Ready Waiting for Rider")
                        },
                        colors = ButtonDefaults.buttonColors(containerColor = Color(0xFF3B82F6)),
                        shape = RoundedCornerShape(10.dp),
                        modifier = Modifier
                            .fillMaxWidth()
                            .height(48.dp)
                            .testTag("rest_ready_pack_btn")
                    ) {
                        Row(
                            verticalAlignment = Alignment.CenterVertically,
                            horizontalArrangement = Arrangement.Center
                        ) {
                            Text("📦", fontSize = 14.sp)
                            Spacer(modifier = Modifier.width(6.dp))
                            Text("Ready to Serve / Pack", fontWeight = FontWeight.Bold, color = Color.White)
                        }
                    }

                    Button(
                        onClick = {
                            onStatusTransition("Served")
                        },
                        colors = ButtonDefaults.buttonColors(containerColor = Color(0xFF0D9488)),
                        shape = RoundedCornerShape(10.dp),
                        modifier = Modifier
                            .fillMaxWidth()
                            .height(48.dp)
                            .testTag("rest_served_rider_btn")
                    ) {
                        Row(
                            verticalAlignment = Alignment.CenterVertically,
                            horizontalArrangement = Arrangement.Center
                        ) {
                            Text("✅", fontSize = 14.sp)
                            Spacer(modifier = Modifier.width(6.dp))
                            Text("Served Handed to Rider", fontWeight = FontWeight.Bold, color = Color.White)
                        }
                    }
                }
            }

            Card(
                modifier = Modifier.fillMaxWidth(),
                colors = CardDefaults.cardColors(containerColor = Color.White),
                shape = RoundedCornerShape(12.dp),
                border = BorderStroke(1.dp, Color(0xFFE2E8F0))
            ) {
                Column {
                    Row(
                        modifier = Modifier
                            .fillMaxWidth()
                            .clickable { isStaffSectionExpanded = !isStaffSectionExpanded }
                            .padding(16.dp),
                        horizontalArrangement = Arrangement.SpaceBetween,
                        verticalAlignment = Alignment.CenterVertically
                    ) {
                        Row(verticalAlignment = Alignment.CenterVertically) {
                            Text("🧑‍🍳", fontSize = 18.sp)
                            Spacer(modifier = Modifier.width(8.dp))
                            Text("Kitchen Staff Status", fontWeight = FontWeight.Bold, fontSize = 14.sp)
                        }
                        IconButton(
                            onClick = { isStaffSectionExpanded = !isStaffSectionExpanded },
                            modifier = Modifier.testTag("rest_staff_toggle_btn")
                        ) {
                            Icon(
                                imageVector = if (isStaffSectionExpanded) Icons.Filled.ExpandLess else Icons.Filled.ExpandMore,
                                contentDescription = "Toggle Staff"
                            )
                        }
                    }

                    if (isStaffSectionExpanded) {
                        Divider(color = Color(0xFFF1F5F9))
                        Column(modifier = Modifier.padding(16.dp), verticalArrangement = Arrangement.spacedBy(10.dp)) {
                            staffList.forEach { chef ->
                                Row(
                                    modifier = Modifier.fillMaxWidth(),
                                    horizontalArrangement = Arrangement.SpaceBetween,
                                    verticalAlignment = Alignment.CenterVertically
                                ) {
                                    Column {
                                        Text(chef.name, fontWeight = FontWeight.SemiBold, fontSize = 14.sp)
                                        Text(chef.role, fontSize = 12.sp, color = Color(0xFF687280))
                                    }
                                    Row(verticalAlignment = Alignment.CenterVertically) {
                                        Box(
                                            modifier = Modifier
                                                .size(8.dp)
                                                .background(if (chef.isActive) Color(0xFF16A34A) else Color(0xFFEF4444), CircleShape)
                                        )
                                        Spacer(modifier = Modifier.width(6.dp))
                                        Text(
                                            text = if (chef.isActive) "Active" else "On break",
                                            fontSize = 12.sp,
                                            fontWeight = FontWeight.Medium,
                                            color = if (chef.isActive) Color(0xFF16A34A) else Color(0xFFEF4444)
                                        )
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }
    }
}

@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun RestaurantPanelScreen(
    onSignOut: () -> Unit
) {
    var isOnline by remember { mutableStateOf(true) }
    var isNotifOn by remember { mutableStateOf(true) }
    var selectedTab by remember { mutableStateOf("Orders") }

    val drawerState = rememberDrawerState(initialValue = DrawerValue.Closed)
    val scope = rememberCoroutineScope()
    val context = LocalContext.current

    var showOfflineDialogReason by remember { mutableStateOf(false) }
    var showNotifDialogReason by remember { mutableStateOf(false) }
    var offlineReason by remember { mutableStateOf("Kitchen busy") }

    var showIncomingSimulator by remember { mutableStateOf(false) }
    var selectedOrderForDetail by remember { mutableStateOf<RestaurantOrder?>(null) }
    var incomingSimulatedOrder by remember { mutableStateOf<RestaurantOrder?>(null) }

    var ordersList by remember {
        mutableStateOf(
            listOf(
                RestaurantOrder(
                    id = "ORD-881",
                    orderType = "Dine-in",
                    destination = "Table 4 Dine In",
                    items = listOf(
                        RestaurantOrderItem("Chicken Biryani", "Full", 1, 220),
                        RestaurantOrderItem("Paneer Biryani", "Half", 1, 140),
                        RestaurantOrderItem("Lassi", "Regular", 1, 60)
                    ),
                    specialInstruction = "No onion in Paneer Biryani",
                    totalPrice = 420,
                    timeAgo = "12 min ago",
                    status = "Preparing",
                    customerName = "Rahul Roy",
                    customerPhone = "+91 98765 43210"
                ),
                RestaurantOrder(
                    id = "ORD-879",
                    orderType = "Delivery",
                    destination = "Delivery Crowmix App",
                    items = listOf(
                        RestaurantOrderItem("Margherita Pizza", "Large", 1, 280)
                    ),
                    specialInstruction = "Extra cheese",
                    totalPrice = 280,
                    timeAgo = "20 min ago",
                    status = "Ready Waiting for Rider",
                    customerName = "Ashish Mehta",
                    customerPhone = "+91 99112 23344"
                ),
                RestaurantOrder(
                    id = "ORD-877",
                    orderType = "Dine-in",
                    destination = "Table 2 Dine In",
                    items = listOf(
                        RestaurantOrderItem("Dal Makhani", "Full", 2, 180),
                        RestaurantOrderItem("Butter Naan", "x 3", 1, 60)
                    ),
                    specialInstruction = null,
                    totalPrice = 420,
                    timeAgo = "35 min ago",
                    status = "Served",
                    customerName = "Priyanka G.",
                    customerPhone = "+91 95555 12345"
                )
            )
        )
    }

    if (showOfflineDialogReason) {
        RestaurantReasonDialog(
            title = "Deactivate Restaurant Panel?",
            reasons = listOf("Kitchen busy", "Break time", "Closed today", "Staff shortage"),
            onDismiss = { showOfflineDialogReason = false },
            onConfirm = { reason ->
                offlineReason = reason
                isOnline = false
                showOfflineDialogReason = false
                Toast.makeText(context, "Panel mode Offline: $reason", Toast.LENGTH_SHORT).show()
            }
        )
    }

    if (showNotifDialogReason) {
        RestaurantReasonDialog(
            title = "Deactivate Alerts / Sound?",
            reasons = listOf("Kitchen busy", "Break time", "Closed today", "Staff shortage"),
            onDismiss = { showNotifDialogReason = false },
            onConfirm = { reason ->
                isNotifOn = false
                showNotifDialogReason = false
                Toast.makeText(context, "Muted sound: $reason", Toast.LENGTH_SHORT).show()
            }
        )
    }

    if (showIncomingSimulator && incomingSimulatedOrder != null) {
        RestaurantIncomingTimerScreen(
            order = incomingSimulatedOrder!!,
            onDecline = {
                showIncomingSimulator = false
                incomingSimulatedOrder = null
            },
            onAccept = {
                val acceptedOrder = incomingSimulatedOrder!!.copy(status = "Preparing")
                ordersList = listOf(acceptedOrder) + ordersList.filter { it.id != acceptedOrder.id }
                showIncomingSimulator = false
                selectedOrderForDetail = acceptedOrder
                incomingSimulatedOrder = null
                Toast.makeText(context, "Order added to kitchen schedule!", Toast.LENGTH_SHORT).show()
            }
        )
    } else if (selectedOrderForDetail != null) {
        RestaurantOrderActiveScreen(
            order = selectedOrderForDetail!!,
            onBack = { selectedOrderForDetail = null },
            onStatusTransition = { newStatus ->
                val ordId = selectedOrderForDetail!!.id
                ordersList = ordersList.map {
                    if (it.id == ordId) it.copy(status = newStatus) else it
                }
                selectedOrderForDetail = selectedOrderForDetail!!.copy(status = newStatus)
                Toast.makeText(context, "Order updated to $newStatus!", Toast.LENGTH_SHORT).show()
            }
        )
    } else {
        ModalNavigationDrawer(
            drawerState = drawerState,
            drawerContent = {
                ModalDrawerSheet {
                    Spacer(modifier = Modifier.height(16.dp))
                    Row(
                        modifier = Modifier.padding(horizontal = 20.dp, vertical = 12.dp),
                        verticalAlignment = Alignment.CenterVertically
                    ) {
                        Box(
                            modifier = Modifier
                                .size(44.dp)
                                .clip(CircleShape)
                                .background(Color(0xFFFFF7ED)),
                            contentAlignment = Alignment.Center
                        ) {
                            Text("🍕", fontSize = 20.sp)
                        }
                        Spacer(modifier = Modifier.width(12.dp))
                        Column {
                            Text("Flavor Junction", fontWeight = FontWeight.Bold, fontSize = 15.sp)
                            Text("Restaurant Panel Center • REST-500", fontSize = 11.sp, color = Color(0xFF687280))
                        }
                    }
                    Divider(modifier = Modifier.padding(vertical = 8.dp))
                    listOf(
                        "Orders" to Icons.Filled.Restaurant,
                        "Dine-in Tables" to Icons.Filled.Home,
                        "Earnings / Revenue" to Icons.Filled.Payment,
                        "Profile" to Icons.Filled.Person
                    ).forEach { (tab, icon) ->
                        NavigationDrawerItem(
                            label = { Text(tab, fontWeight = FontWeight.Bold) },
                            selected = selectedTab == tab,
                            onClick = {
                                selectedTab = tab
                                scope.launch { drawerState.close() }
                            },
                            icon = { Icon(icon, tab) },
                            modifier = Modifier.padding(horizontal = 12.dp, vertical = 4.dp)
                        )
                    }

                    Spacer(modifier = Modifier.height(16.dp))
                    NavigationDrawerItem(
                        label = { Text("Sign Out", color = Color.Red, fontWeight = FontWeight.Bold) },
                        selected = false,
                        onClick = {
                            scope.launch { drawerState.close() }
                            onSignOut()
                        },
                        icon = { Icon(Icons.Filled.ExitToApp, "Sign Out", tint = Color.Red) },
                        modifier = Modifier.padding(horizontal = 12.dp)
                    )
                }
            }
        ) {
            Scaffold(
                topBar = {
                    TopAppBar(
                        title = { Text("Restaurant Panel", fontSize = 16.sp, fontWeight = FontWeight.Black) },
                        navigationIcon = {
                            IconButton(onClick = { scope.launch { drawerState.open() } }) {
                                Icon(Icons.Filled.Menu, "Toggle Drawer")
                            }
                        },
                        actions = {
                            Button(
                                onClick = {
                                    if (isNotifOn) showNotifDialogReason = true else isNotifOn = true
                                },
                                colors = ButtonDefaults.buttonColors(
                                    containerColor = if (isNotifOn) Color(0xFFEA580C) else Color(0xFF687280)
                                ),
                                contentPadding = PaddingValues(horizontal = 8.dp),
                                modifier = Modifier
                                    .padding(end = 12.dp)
                                    .height(32.dp)
                                    .testTag("rest_notif_toggle_btn")
                            ) {
                                Icon(
                                    imageVector = if (isNotifOn) Icons.Filled.Notifications else Icons.Filled.NotificationsOff,
                                    contentDescription = null,
                                    tint = Color.White,
                                    modifier = Modifier.size(16.dp)
                                )
                                Spacer(modifier = Modifier.width(4.dp))
                                Text(if (isNotifOn) "Alerts ON" else "Alerts OFF", fontSize = 11.sp, fontWeight = FontWeight.Bold)
                            }
                        },
                        colors = TopAppBarDefaults.topAppBarColors(
                            containerColor = Color(0xFFEA580C),
                            titleContentColor = Color.White,
                            navigationIconContentColor = Color.White
                        )
                    )
                },
                containerColor = Color(0xFFF8FAFC)
            ) { innerPadding ->
                Column(
                    modifier = Modifier
                        .fillMaxSize()
                        .padding(innerPadding)
                ) {
                    val barColor = if (isOnline) Color(0xFFEA580C) else Color(0xFF64748B)
                    val barText = if (isOnline) "Live Orders Channel Open" else "Restaurant panel offline - $offlineReason"
                    Box(
                        modifier = Modifier
                            .fillMaxWidth()
                            .background(barColor)
                            .padding(vertical = 6.dp),
                        contentAlignment = Alignment.Center
                    ) {
                        Text(barText, color = Color.White, fontSize = 12.sp, fontWeight = FontWeight.Bold)
                    }

                    if (selectedTab == "Orders") {
                        LazyColumn(
                            modifier = Modifier
                                .fillMaxSize()
                                .padding(16.dp),
                            verticalArrangement = Arrangement.spacedBy(16.dp)
                        ) {
                            item {
                                Card(
                                    modifier = Modifier.fillMaxWidth(),
                                    colors = CardDefaults.cardColors(containerColor = Color.White),
                                    shape = RoundedCornerShape(12.dp),
                                    border = BorderStroke(1.dp, Color(0xFFE2E8F0))
                                ) {
                                    Row(
                                        modifier = Modifier
                                            .fillMaxWidth()
                                            .padding(14.dp),
                                        verticalAlignment = Alignment.CenterVertically,
                                        horizontalArrangement = Arrangement.SpaceBetween
                                    ) {
                                        Row(verticalAlignment = Alignment.CenterVertically) {
                                            Icon(Icons.Filled.Restaurant, null, tint = if (isOnline) Color(0xFFEA580C) else Color(0xFF687280))
                                            Spacer(modifier = Modifier.width(8.dp))
                                            Text("Channel Live Status", fontSize = 14.sp, fontWeight = FontWeight.Bold)
                                        }
                                        Switch(
                                            checked = isOnline,
                                            onCheckedChange = { checked ->
                                                if (!checked) {
                                                    showOfflineDialogReason = true
                                                } else {
                                                    isOnline = true
                                                    Toast.makeText(context, "Channel configured back Online!", Toast.LENGTH_SHORT).show()
                                                }
                                            },
                                            modifier = Modifier.testTag("rest_panel_status_switch"),
                                            colors = SwitchDefaults.colors(
                                                checkedThumbColor = Color(0xFFEA580C),
                                                checkedTrackColor = Color(0xFFFED7AA)
                                            )
                                        )
                                    }
                                }
                            }

                            item {
                                Column(verticalArrangement = Arrangement.spacedBy(8.dp)) {
                                    Row(horizontalArrangement = Arrangement.spacedBy(8.dp)) {
                                        Card(
                                            modifier = Modifier.weight(1f),
                                            colors = CardDefaults.cardColors(containerColor = Color.White),
                                            border = BorderStroke(1.dp, Color(0xFFE2E8F0))
                                        ) {
                                            Column(modifier = Modifier.padding(12.dp)) {
                                                Text("Active orders", fontSize = 11.sp, color = Color(0xFF687280), fontWeight = FontWeight.Bold)
                                                Spacer(modifier = Modifier.height(8.dp))
