                        ) {
                            Box(
                                modifier = Modifier
                                    .background(Color(0xFFF3E8FF), RoundedCornerShape(6.dp))
                                    .padding(horizontal = 8.dp, vertical = 4.dp)
                            ) {
                                Text(
                                    text = "SLEEPER CLASS",
