                            }
                            Text(
                                text = "Booking ID: BUS-7821",
                                fontWeight = FontWeight.Bold,
                                fontSize = 14.sp,
                                color = Color(0xFF1E293B)
                            )
                        }

                        HorizontalDivider(color = Color(0xFFF1F5F9))

                        // Passenger Information (full ticket info)
                        Column(verticalArrangement = Arrangement.spacedBy(6.dp)) {
                            Text("PASSENGER DETAILS", fontSize = 10.sp, color = Color(0xFF687280), fontWeight = FontWeight.Bold)
                            
                            Row(modifier = Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.SpaceBetween) {
                                Text("Name: Ramesh Kumar", fontWeight = FontWeight.SemiBold, fontSize = 13.sp)
                                Text("Age/Gender: 34 / Male", fontSize = 13.sp)
