                                    Text("OPERATIONAL ALERTS", fontSize = 11.sp, fontWeight = FontWeight.Bold, color = Color(0xFF687280))
                                    
                                    // Alert 1
                                    Card(
                                        colors = CardDefaults.cardColors(containerColor = Color(0xFFFFF1F2)),
