                                    }
                                    Spacer(modifier = Modifier.width(6.dp))
                                    Button(
                                        onClick = { showAddTripModal = true },
                                        colors = ButtonDefaults.buttonColors(containerColor = tealPrimary),
                                        contentPadding = PaddingValues(horizontal = 8.dp),
                                        modifier = Modifier.height(32.dp)
                                    ) {
                                        Icon(Icons.Default.Add, null, tint = Color.White, modifier = Modifier.size(12.dp))
                                        Spacer(modifier = Modifier.width(4.dp))
                                        Text("Add Trip", fontSize = 10.sp, color = Color.White)
                                    }
                                }
                            }

                            Spacer(modifier = Modifier.height(16.dp))

                            LazyColumn(verticalArrangement = Arrangement.spacedBy(10.dp)) {
                                items(routesList) { route ->
                                    val rDetails = routesDetailsMap[route.id]
                                    Card(
                                        modifier = Modifier.fillMaxWidth(),
                                        colors = CardDefaults.cardColors(containerColor = Color.White),
                                        border = BorderStroke(1.dp, Color(0xFFE2E8F0))
                                    ) {
                                        Column(modifier = Modifier.padding(12.dp)) {
                                            Row(
                                                modifier = Modifier.fillMaxWidth(),
                                                horizontalArrangement = Arrangement.SpaceBetween
                                            ) {
                                                Text(route.name, fontWeight = FontWeight.Black, fontSize = 14.sp, color = tealPrimary)
                                                Box(
                                                    modifier = Modifier.background(orangeAccent.copy(alpha = 0.1f)).padding(horizontal = 6.dp, vertical = 2.dp)
                                                ) {
                                                    Text(route.status, fontSize = 10.sp, fontWeight = FontWeight.Bold, color = orangeAccent)
                                                }
                                            }

                                            Spacer(modifier = Modifier.height(8.dp))
                                            
                                            Row(horizontalArrangement = Arrangement.spacedBy(16.dp)) {
                                                Text("🛣️ ${rDetails?.first ?: 150} KM", fontSize = 11.sp, color = Color(0xFF687280))
                                                Text("⏱️ ${(rDetails?.second ?: 180) / 60} Hrs ${reconstructMinutes(rDetails?.second ?: 180)} Min", fontSize = 11.sp, color = Color(0xFF687280))
                                                Text("🚌 Bus: ${route.busNumber}", fontSize = 11.sp, color = Color(0xFF687280))
                                            }

                                            Spacer(modifier = Modifier.height(8.dp))
                                            Text("Intermediate Stops:", fontSize = 10.sp, fontWeight = FontWeight.Bold, color = Color(0xFF687280))
                                            
                                            Row(
                                                modifier = Modifier.padding(top = 4.dp),
                                                horizontalArrangement = Arrangement.spacedBy(4.dp)
                                            ) {
                                                (rDetails?.third ?: listOf("Loading Stops")).forEach { stop ->
                                                    Box(
                                                        modifier = Modifier
                                                            .background(Color(0xFFF1F5F9), RoundedCornerShape(4.dp))
                                                            .padding(horizontal = 6.dp, vertical = 2.dp)
                                                    ) {
                                                        Text(stop, fontSize = 9.sp, color = Color.DarkGray)
                                                    }
                                                }
                                            }
                                        }
                                    }
                                }
                            }
                        }
                    }

                    "Buses" -> {
                        // SCREEN 3 & 9: BUS MANAGEMENT & STAFF DIRECTORY
                        var staffViewActive by remember { mutableStateOf(false) }

                        TabRow(
                            selectedTabIndex = if (staffViewActive) 1 else 0,
                            containerColor = Color.White,
                            contentColor = tealPrimary
                        ) {
                            Tab(selected = !staffViewActive, onClick = { staffViewActive = false }, text = { Text("Active Fleet Catalog") })
                            Tab(selected = staffViewActive, onClick = { staffViewActive = true }, text = { Text("Drivers & Crew Directory") })
                        }

                        Column(modifier = Modifier.weight(1f).padding(16.dp)) {
                            Row(
                                modifier = Modifier.fillMaxWidth(),
                                horizontalArrangement = Arrangement.SpaceBetween,
                                verticalAlignment = Alignment.CenterVertically
                            ) {
                                Text(
                                    text = if (staffViewActive) "MEMBERS DETAILS" else "FLEET ACTIVE BUSES",
                                    fontWeight = FontWeight.Bold,
                                    fontSize = 12.sp,
                                    color = Color(0xFF687280)
                                )

                                Button(
                                    onClick = {
                                        if (staffViewActive) {
                                            showAddStaffModal = true
                                        } else {
                                            showAddBusModal = true
                                        }
                                    },
                                    colors = ButtonDefaults.buttonColors(containerColor = tealPrimary),
                                    contentPadding = PaddingValues(horizontal = 8.dp),
                                    modifier = Modifier.height(32.dp)
                                ) {
                                    Icon(Icons.Default.Add, null, tint = Color.White, modifier = Modifier.size(12.dp))
                                    Spacer(modifier = Modifier.width(4.dp))
                                    Text(if (staffViewActive) "Add Member" else "Add Bus", fontSize = 10.sp, color = Color.White)
                                }
                            }

                            Spacer(modifier = Modifier.height(16.dp))

                            if (!staffViewActive) {
                                // Bus Catalog View
                                LazyColumn(verticalArrangement = Arrangement.spacedBy(10.dp)) {
                                    items(busesList) { bus ->
                                        Card(
                                            modifier = Modifier.fillMaxWidth(),
                                            colors = CardDefaults.cardColors(containerColor = Color.White),
                                            border = BorderStroke(1.dp, Color(0xFFE2E8F0))
                                        ) {
                                            Row(
                                                modifier = Modifier
                                                    .fillMaxWidth()
                                                    .padding(12.dp),
                                                horizontalArrangement = Arrangement.SpaceBetween,
                                                verticalAlignment = Alignment.CenterVertically
                                            ) {
                                                Column {
                                                    Row(verticalAlignment = Alignment.CenterVertically) {
                                                        Text("🚌", fontSize = 18.sp)
                                                        Spacer(modifier = Modifier.width(8.dp))
                                                        Text(bus.first, fontWeight = FontWeight.Bold, fontSize = 14.sp)
                                                    }
                                                    Text(bus.second, fontSize = 12.sp, color = Color(0xFF687280), modifier = Modifier.padding(top = 4.dp))
                                                }

                                                Row(verticalAlignment = Alignment.CenterVertically) {
                                                    val chipColor = when (bus.third) {
                                                        "Active" -> Color(0xFFECFDF5)
                                                        "On Route" -> Color(0xFFFFF7ED)
                                                        else -> Color(0xFFFEF2F2)
                                                    }
                                                    val textColor = when (bus.third) {
                                                        "Active" -> Color(0xFF047857)
                                                        "On Route" -> Color(0xFFC2410C)
                                                        else -> Color(0xFFB91C1C)
                                                    }
                                                    Box(
                                                        modifier = Modifier
                                                            .background(chipColor, RoundedCornerShape(6.dp))
                                                            .padding(horizontal = 8.dp, vertical = 4.dp)
                                                    ) {
                                                        Text(bus.third, fontSize = 11.sp, fontWeight = FontWeight.Bold, color = textColor)
                                                    }

                                                    Spacer(modifier = Modifier.width(8.dp))

                                                    IconButton(onClick = {
                                                        busesList.remove(bus)
                                                        Toast.makeText(context, "Bus deleted safely from platform catalog", Toast.LENGTH_SHORT).show()
                                                    }) {
                                                        Icon(Icons.Default.Delete, "Delete", tint = Color.Red, modifier = Modifier.size(16.dp))
                                                    }
                                                }
                                            }
                                        }
                                    }
                                }
                            } else {
                                // Staff Crew View
                                LazyColumn(verticalArrangement = Arrangement.spacedBy(10.dp)) {
                                    items(driversList) { crew ->
                                        Card(
                                            modifier = Modifier.fillMaxWidth(),
                                            colors = CardDefaults.cardColors(containerColor = Color.White),
                                            border = BorderStroke(1.dp, Color(0xFFE2E8F0))
                                        ) {
                                            Row(
                                                modifier = Modifier
                                                    .fillMaxWidth()
                                                    .padding(12.dp),
                                                verticalAlignment = Alignment.CenterVertically,
                                                horizontalArrangement = Arrangement.SpaceBetween
                                            ) {
                                                Row(verticalAlignment = Alignment.CenterVertically) {
                                                    Box(
                                                        modifier = Modifier
                                                            .size(40.dp)
                                                            .background(tealPrimary.copy(alpha = 0.1f), CircleShape),
                                                        contentAlignment = Alignment.Center
                                                    ) {
                                                        Text(crew.first.first().toString(), fontWeight = FontWeight.Bold, color = tealPrimary)
                                                    }
                                                    Spacer(modifier = Modifier.width(12.dp))
                                                    Column {
                                                        Text(crew.first, fontWeight = FontWeight.Bold, fontSize = 14.sp)
                                                        Text(crew.second, fontSize = 11.sp, color = orangeAccent, fontWeight = FontWeight.SemiBold)
                                                    }
                                                }
                                                Column(horizontalAlignment = Alignment.End) {
                                                    Text("License Code:", fontSize = 10.sp, color = Color(0xFF687280))
                                                    Text(crew.third, fontSize = 11.sp, fontWeight = FontWeight.Bold, color = Color.DarkGray)
                                                }
                                            }
                                        }
                                    }
                                }
                            }
                        }
                    }

                    "Bookings" -> {
                        // SCREEN 6 & 7: SEAT MAP & BOOKING MANAGEMENT
                        var isSeatingMapTab by remember { mutableStateOf(false) }

                        TabRow(
                            selectedTabIndex = if (isSeatingMapTab) 1 else 0,
                            containerColor = Color.White,
                            contentColor = tealPrimary
                        ) {
                            Tab(selected = !isSeatingMapTab, onClick = { isSeatingMapTab = false }, text = { Text("PNR Booking List") })
                            Tab(selected = isSeatingMapTab, onClick = { isSeatingMapTab = true }, text = { Text("Sleeper Seat Layout") })
                        }

                        if (!isSeatingMapTab) {
                            // SCREEN 7: BOOKING LIST WITH FILTERS & DETAILS
                            Column(modifier = Modifier.weight(1f).padding(16.dp)) {
                                OutlinedTextField(
                                    value = searchBookingQuery,
                                    onValueChange = { searchBookingQuery = it },
                                    placeholder = { Text("Search passenger name or PNR...") },
                                    modifier = Modifier.fillMaxWidth(),
                                    singleLine = true,
                                    leadingIcon = { Icon(Icons.Default.Search, null) }
                                )

                                Spacer(modifier = Modifier.height(16.dp))

                                LazyColumn(
                                    verticalArrangement = Arrangement.spacedBy(10.dp),
                                    modifier = Modifier.weight(1f)
                                ) {
                                    val filteredBookings = bookingsList.filter {
                                        it.name.contains(searchBookingQuery, ignoreCase = true) ||
                                        it.phone.contains(searchBookingQuery, ignoreCase = true)
                                    }
                                    items(filteredBookings) { booking ->
                                        Card(
                                            modifier = Modifier
                                                .fillMaxWidth()
                                                .clickable { selectedBookingForDetail = booking },
                                            colors = CardDefaults.cardColors(containerColor = Color.White),
                                            border = BorderStroke(1.dp, Color(0xFFE2E8F0))
                                        ) {
                                            Row(
                                                modifier = Modifier.padding(14.dp),
                                                horizontalArrangement = Arrangement.SpaceBetween,
                                                verticalAlignment = Alignment.CenterVertically
                                            ) {
                                                Column {
                                                    Text(booking.phone, fontWeight = FontWeight.Bold, fontSize = 13.sp, color = tealPrimary) // PNR
                                                    Text(booking.name, fontWeight = FontWeight.SemiBold, fontSize = 14.sp)
                                                    Text("Age/Gender: ${booking.ageGender} • Seat: ${booking.seatNumber}", fontSize = 11.sp, color = Color(0xFF687280))
                                                }
                                                Box(
                                                    modifier = Modifier
                                                        .background(
                                                            if (booking.paymentStatus == "Confirmed") Color(0xFFECFDF5) else Color(0xFFFEF2F2),
                                                            RoundedCornerShape(4.dp)
                                                        )
                                                        .padding(horizontal = 6.dp, vertical = 2.dp)
                                                ) {
                                                    Text(
                                                        booking.paymentStatus,
                                                        color = if (booking.paymentStatus == "Confirmed") Color(0xFF047857) else Color(0xFFBE123C),
                                                        fontSize = 11.sp,
                                                        fontWeight = FontWeight.Bold
                                                    )
                                                }
                                            }
                                        }
                                    }
                                }
                            }
                        } else {
                            // SCREEN 6: VISUAL BUS SEATING GRID
                            Column(
                                modifier = Modifier
                                    .weight(1f)
                                    .verticalScroll(rememberScrollState())
                                    .padding(16.dp)
                            ) {
                                Text("TRIP SELECTOR", fontSize = 11.sp, fontWeight = FontWeight.Bold, color = Color(0xFF687280))
                                
                                // Simple Selector Row
                                Row(
                                    modifier = Modifier
                                        .fillMaxWidth()
                                        .padding(vertical = 4.dp),
                                    horizontalArrangement = Arrangement.spacedBy(8.dp)
                                ) {
                                    routesList.forEach { route ->
                                        val isSel = selectedTripIdForSeatMap == route.id
                                        Box(
                                            modifier = Modifier
                                                .border(
                                                    1.dp,
                                                    if (isSel) tealPrimary else Color(0xFF9CA3AF),
                                                    RoundedCornerShape(8.dp)
                                                )
                                                .background(if (isSel) tealPrimary.copy(alpha = 0.1f) else Color.White)
                                                .clickable { selectedTripIdForSeatMap = route.id }
                                                .padding(horizontal = 10.dp, vertical = 6.dp)
                                        ) {
                                            Text(route.id, fontSize = 11.sp, fontWeight = FontWeight.Bold, color = if (isSel) tealPrimary else Color.DarkGray)
                                        }
                                    }
                                }

                                Spacer(modifier = Modifier.height(16.dp))

                                // Color Legend row
                                Row(
                                    modifier = Modifier.fillMaxWidth().padding(bottom = 12.dp),
                                    horizontalArrangement = Arrangement.SpaceBetween
                                ) {
                                    listOf(
                                        "Avail" to Color(0xFF22C55E),
                                        "Booked" to Color(0xFFEF4444),
                                        "Block" to Color(0xFFF59E0B),
                                        "Sel" to tealPrimary
                                    ).forEach { (lbl, col) ->
                                        Row(verticalAlignment = Alignment.CenterVertically) {
                                            Box(modifier = Modifier.size(10.dp).background(col, RoundedCornerShape(2.dp)))
                                            Spacer(modifier = Modifier.width(4.dp))
                                            Text(lbl, fontSize = 11.sp, fontWeight = FontWeight.Bold, color = Color(0xFF687280))
                                        }
                                    }
                                }

                                // Interactive Seating Layout representer
                                Card(
                                    colors = CardDefaults.cardColors(containerColor = Color.White),
                                    border = BorderStroke(1.dp, Color(0xFFE2E8F0)),
                                    modifier = Modifier.fillMaxWidth()
                                ) {
                                    Column(
                                        modifier = Modifier.padding(16.dp),
                                        horizontalAlignment = Alignment.CenterHorizontally
                                    ) {
                                        Text("🚍 STAGE FRONT / CABIN", fontSize = 11.sp, color = Color(0xFF687280), fontWeight = FontWeight.Bold)
                                        Spacer(modifier = Modifier.height(16.dp))

                                        // We simulate seats: L1..L12 on Left side, R1..R8 on Right side
                                        val leftRows = listOf("L1", "L2", "L3", "L4", "L5", "L6", "L7", "L8", "L9", "L10", "L11", "L12")
                                        val rightRows = listOf("R1", "R2", "R3", "R4", "R5", "R6", "R7", "R8", "R5", "R6", "R7", "R8") // align

                                        for (i in 0 until 4) {
                                            Row(
                                                modifier = Modifier.fillMaxWidth().padding(vertical = 4.dp),
                                                horizontalArrangement = Arrangement.SpaceEvenly
                                            ) {
                                                // Left 2 seats
                                                val sL1 = "L${i*2 + 1}"
                                                val sL2 = "L${i*2 + 2}"
                                                val statusL1 = seatsMapState[sL1] ?: "available"
                                                val statusL2 = seatsMapState[sL2] ?: "available"

                                                RenderSeatCell(sL1, statusL1) {
                                                    seatsMapState[sL1] = toggleSeatStatus(statusL1)
                                                }
                                                RenderSeatCell(sL2, statusL2) {
                                                    seatsMapState[sL2] = toggleSeatStatus(statusL2)
                                                }

                                                // Bus Aisle Corridor
                                                Box(modifier = Modifier.width(24.dp), contentAlignment = Alignment.Center) {
                                                    Text("🚶", fontSize = 12.sp)
                                                }

                                                // Right 2 seats
                                                val sR1 = "R${i*2 + 1}"
                                                val sR2 = "R${i*2 + 2}"
                                                val statusR1 = seatsMapState[sR1] ?: "available"
                                                val statusR2 = seatsMapState[sR2] ?: "available"

                                                RenderSeatCell(sR1, statusR1) {
                                                    seatsMapState[sR1] = toggleSeatStatus(statusR1)
                                                }
                                                RenderSeatCell(sR2, statusR2) {
                                                    seatsMapState[sR2] = toggleSeatStatus(statusR2)
                                                }
                                            }
                                        }

                                        Spacer(modifier = Modifier.height(16.dp))
                                        Text("Aggregate stats: Selected (Blue), Booked (Red), Held (Amber)", fontSize = 10.sp, color = Color(0xFF687280))
                                    }
                                }

                                Spacer(modifier = Modifier.height(8.dp))

                                Row(
                                    modifier = Modifier.fillMaxWidth(),
                                    horizontalArrangement = Arrangement.spacedBy(8.dp)
                                ) {
                                    Button(
                                        onClick = {
                                            seatsMapState.forEach { (k, v) ->
                                                if (v == "selected") seatsMapState[k] = "blocked"
                                            }
