                                            seatsMapState.forEach { (k, v) ->
                                                if (v == "selected") seatsMapState[k] = "available"
                                            }
                                            Toast.makeText(context, "Tickets declared available for app store", Toast.LENGTH_SHORT).show()
                                        },
                                        colors = ButtonDefaults.buttonColors(containerColor = tealPrimary),
                                        modifier = Modifier.weight(1f)
                                    ) {
                                        Text("Release/Sell", color = Color.White, fontWeight = FontWeight.Bold)
                                    }
                                }
                            }
                        }
                    }

                    "More" -> {
                        // SUB-NAV DRAWER GRID TABS FOR INTEGRATION REQUIREMENTS 8, 10, 11, 12
                        ScrollableTabRow(
                            selectedTabIndex = if (activeMoreTab == "Pricing") 0 else if (activeMoreTab == "Tracking") 1 else if (activeMoreTab == "Reports") 2 else 3,
                            containerColor = Color.White,
                            contentColor = tealPrimary,
                            edgePadding = 12.dp
                        ) {
                            Tab(selected = activeMoreTab == "Pricing", onClick = { activeMoreTab = "Pricing" }, text = { Text("⚡ Pricing Rule") })
                            Tab(selected = activeMoreTab == "Tracking", onClick = { activeMoreTab = "Tracking" }, text = { Text("📍 Live Tracking") })
                            Tab(selected = activeMoreTab == "Reports", onClick = { activeMoreTab = "Reports" }, text = { Text("📊 Ledger Reports") })
                            Tab(selected = activeMoreTab == "API", onClick = { activeMoreTab = "API" }, text = { Text("💻 Developer API") })
                        }

                        Column(
                            modifier = Modifier
                                .weight(1f)
                                .verticalScroll(rememberScrollState())
                                .padding(16.dp)
                        ) {
                            when (activeMoreTab) {
                                "Pricing" -> {
                                    // SCREEN 8: PRICING CONFIGURATION
                                    Text("DYNAMIC AUTOMATIC PRICING", fontWeight = FontWeight.Bold, fontSize = 14.sp)
                                    Text("Configure peak indicators based on Supabase algorithm", fontSize = 12.sp, color = Color(0xFF687280))

                                    Spacer(modifier = Modifier.height(16.dp))

                                    Card(
                                        colors = CardDefaults.cardColors(containerColor = Color.White),
                                        border = BorderStroke(1.dp, Color(0xFFE2E8F0)),
                                        modifier = Modifier.fillMaxWidth()
                                    ) {
                                        Column(modifier = Modifier.padding(14.dp)) {
