@Composable
fun RenderSeatCell(label: String, status: String, onClick: () -> Unit) {
    val col = when (status) {
        "booked" -> Color(0xFFEF4444)
        "blocked" -> Color(0xFFF59E0B)
        "selected" -> Color(0xFF059494)
        else -> Color(0xFF22C55E)
    }
    Box(
        modifier = Modifier
            .size(42.dp)
            .clip(RoundedCornerShape(6.dp))
            .background(col)
            .clickable { onClick() },
        contentAlignment = Alignment.Center
    ) {
        Text(label, color = Color.White, fontWeight = FontWeight.Black, fontSize = 11.sp)
    }
}

@Composable
fun RenderTimelineNode(station: String, desc: String, isPassed: Boolean, isLiveCurrent: Boolean = false) {
    Row(
        modifier = Modifier
            .fillMaxWidth()
            .padding(vertical = 4.dp),
        verticalAlignment = Alignment.CenterVertically
    ) {
        Box(
            modifier = Modifier
                .size(16.dp)
                .background(
                    if (isLiveCurrent) Color(0xFFFF6B35) else if (isPassed) Color(0xFF059494) else Color(0xFF9CA3AF),
                    CircleShape
                ),
            contentAlignment = Alignment.Center
        ) {
            if (isPassed && !isLiveCurrent) {
                Text("✓", color = Color.White, fontSize = 10.sp, fontWeight = FontWeight.Bold)
            }
        }
        Spacer(modifier = Modifier.width(12.dp))
        Column {
            Text(
                text = station,
                fontWeight = FontWeight.Bold,
                fontSize = 13.sp,
                color = if (isLiveCurrent) Color(0xFFFF6B35) else if (isPassed) Color(0xFF1E293B) else Color(0xFF687280)
            )
            Text(desc, fontSize = 11.sp, color = Color(0xFF687280))
        }
    }
}

private fun toggleSeatStatus(current: String): String {
    return when (current) {
        "available" -> "selected"
        "selected" -> "available"
        "blocked" -> "available"
        else -> "booked" // keeps booked
    }
}

private fun reconstructMinutes(timeInMinutes: Int): Int {
    return timeInMinutes % 60
}

