@Composable
fun CatalogScreen(
    onNavigate: (String) -> Unit,
    onEditProductId: (String) -> Unit
) {
    val context = LocalContext.current
    val tealPrimary = Color(0xFF1FAE7A)
    val slateContent = Color(0xFF1E293B)
    val graySub = Color(0xFF64748B)

    val products = ConnectChatManager.sellerProducts

    Scaffold(
        topBar = {
            Row(
                modifier = Modifier
                    .fillMaxWidth()
                    .background(tealPrimary)
                    .padding(horizontal = 8.dp, vertical = 12.dp),
                verticalAlignment = Alignment.CenterVertically
            ) {
                IconButton(onClick = { onNavigate("DASHBOARD") }) {
                    Icon(Icons.Default.ArrowBack, "Back", tint = Color.White)
                }
                Spacer(modifier = Modifier.width(8.dp))
                Text("Manage Catalog", color = Color.White, fontSize = 18.sp, fontWeight = FontWeight.Bold)
            }
        },
        floatingActionButton = {
            FloatingActionButton(
                onClick = { onNavigate("ADD_PRODUCT") },
                containerColor = tealPrimary,
                contentColor = Color.White,
                modifier = Modifier.testTag("add_product_fab")
            ) {
                Icon(Icons.Default.Add, "Add Product")
            }
        },
        content = { paddingValues ->
            Column(
                modifier = Modifier
                    .fillMaxSize()
                    .background(Color(0xFFF8FAFC))
                    .padding(paddingValues)
                    .padding(14.dp)
            ) {
                Text(
                    "Primary Catalog Products (${products.size})",
                    fontWeight = FontWeight.Bold,
                    fontSize = 14.sp,
                    color = slateContent,
                    modifier = Modifier.padding(bottom = 12.dp)
                )

                if (products.isEmpty()) {
                    Column(
                        modifier = Modifier.fillMaxSize(),
                        verticalArrangement = Arrangement.Center,
                        horizontalAlignment = Alignment.CenterHorizontally
                    ) {
                        Text("No products in your catalog yet.", color = graySub, fontSize = 13.sp)
                        TextButton(onClick = { onNavigate("ADD_PRODUCT") }) {
                            Text("Click here to add one ➕", color = tealPrimary)
                        }
                    }
                } else {
                    LazyVerticalGrid(
                        columns = GridCells.Fixed(2),
                        horizontalArrangement = Arrangement.spacedBy(10.dp),
                        verticalArrangement = Arrangement.spacedBy(10.dp),
                        modifier = Modifier.fillMaxSize()
                    ) {
                        items(products) { product ->
                            var isChecked by remember { mutableStateOf(!product.isHidden) }
                            Card(
                                modifier = Modifier
                                    .fillMaxWidth()
                                    .testTag("catalog_item_${product.id}"),
                                colors = CardDefaults.cardColors(containerColor = Color.White),
                                border = BorderStroke(1.dp, Color(0xFFE2E8F0))
                            ) {
                                Column(modifier = Modifier.padding(10.dp)) {
                                    // Visual preview box
                                    Box(
                                        modifier = Modifier
                                            .fillMaxWidth()
                                            .height(90.dp)
                                            .background(tealPrimary.copy(alpha = 0.05f), RoundedCornerShape(6.dp)),
                                        contentAlignment = Alignment.Center
                                    ) {
                                        Text(product.imageEmoji, fontSize = 42.sp)
                                    }
                                    Spacer(modifier = Modifier.height(8.dp))
                                    Text(
                                        product.name,
                                        fontWeight = FontWeight.Bold,
                                        fontSize = 12.sp,
                                        color = slateContent,
                                        maxLines = 1,
                                        overflow = TextOverflow.Ellipsis
                                    )
                                    Spacer(modifier = Modifier.height(2.dp))
                                    Row(verticalAlignment = Alignment.CenterVertically) {
                                        Text(
                                            "₹${product.price.toInt()}",
                                            fontWeight = FontWeight.Bold,
                                            fontSize = 13.sp,
                                            color = tealPrimary
                                        )
                                        if (product.discountedPrice != null) {
                                            Spacer(modifier = Modifier.width(6.dp))
                                            Text(
                                                "₹${product.discountedPrice.toInt()}",
                                                fontSize = 10.sp,
                                                color = graySub,
                                                textDecoration = TextDecoration.LineThrough
                                            )
                                        }
                                    }
                                    Spacer(modifier = Modifier.height(8.dp))
                                    Divider(color = Color(0xFFF1F5F9))
                                    Spacer(modifier = Modifier.height(8.dp))
                                    
                                    Row(
                                        modifier = Modifier.fillMaxWidth(),
                                        horizontalArrangement = Arrangement.SpaceBetween,
                                        verticalAlignment = Alignment.CenterVertically
                                    ) {
                                        Text(
                                            if (isChecked) "Active" else "Hidden",
                                            fontSize = 10.sp,
                                            color = if (isChecked) tealPrimary else graySub,
                                            fontWeight = FontWeight.Bold
                                        )
                                        Switch(
                                            checked = isChecked,
                                            onCheckedChange = {
                                                isChecked = it
                                                product.isHidden = !it
                                                Toast.makeText(context, "${product.name} visible status updated", Toast.LENGTH_SHORT).show()
                                            },
                                            modifier = Modifier.scale(0.7f).testTag("product_toggle_${product.id}")
                                        )
                                    }
                                    
                                    Row(
                                        modifier = Modifier.fillMaxWidth(),
                                        horizontalArrangement = Arrangement.SpaceBetween,
                                        verticalAlignment = Alignment.CenterVertically
                                    ) {
                                        IconButton(onClick = { onEditProductId(product.id); onNavigate("EDIT_PRODUCT") }, modifier = Modifier.size(32.dp)) {
                                            Icon(Icons.Default.Edit, "Edit", tint = graySub, modifier = Modifier.size(16.dp))
                                        }
                                        IconButton(onClick = {
                                            ConnectChatManager.sellerProducts.remove(product)
                                            Toast.makeText(context, "Product Deleted!", Toast.LENGTH_SHORT).show()
                                        }, modifier = Modifier.size(32.dp)) {
                                            Icon(Icons.Default.Delete, "Delete", tint = Color.Red, modifier = Modifier.size(16.dp))
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }
    )
}

@Composable
fun AddProductScreen(onNavigate: (String) -> Unit) {
    val context = LocalContext.current
    val tealPrimary = Color(0xFF1FAE7A)
    val slateContent = Color(0xFF1E293B)
    val graySub = Color(0xFF64748B)

    var pName by remember { mutableStateOf("") }
    var pPrice by remember { mutableStateOf("") }
    var pDiscount by remember { mutableStateOf("") }
    var pCategory by remember { mutableStateOf("General") }
    var pDesc by remember { mutableStateOf("") }
    var pStock by remember { mutableStateOf("") }
    var selectedImgIndex by remember { mutableStateOf(0) }
    
    val imgOptions = listOf("🧁", "🍕", "☕", "🍞", "🍦", "🥗", "🎂", "🍔", "🥤")

    Column(
        modifier = Modifier
            .fillMaxSize()
            .background(Color.White)
            .verticalScroll(rememberScrollState())
    ) {
        Row(
            modifier = Modifier
                .fillMaxWidth()
                .background(tealPrimary)
                .padding(horizontal = 8.dp, vertical = 12.dp),
            verticalAlignment = Alignment.CenterVertically
        ) {
            IconButton(onClick = { onNavigate("MY_CATALOG") }) {
                Icon(Icons.Default.ArrowBack, "Back", tint = Color.White)
            }
            Spacer(modifier = Modifier.width(8.dp))
            Text("Add New Product", color = Color.White, fontSize = 18.sp, fontWeight = FontWeight.Bold)
        }

        Column(modifier = Modifier.padding(16.dp), verticalArrangement = Arrangement.spacedBy(14.dp)) {
            Text("Pick Product Icon Picture 🌟", fontWeight = FontWeight.Medium, fontSize = 13.sp, color = slateContent)
            Row(
                modifier = Modifier.fillMaxWidth().horizontalScroll(rememberScrollState()),
                horizontalArrangement = Arrangement.spacedBy(8.dp)
            ) {
                imgOptions.forEachIndexed { idx, em ->
                    val isSel = selectedImgIndex == idx
                    Box(
                        modifier = Modifier
                            .size(45.dp)
                            .background(if (isSel) tealPrimary.copy(alpha = 0.15f) else Color(0xFFF1F5F9), RoundedCornerShape(8.dp))
                            .border(1.dp, if (isSel) tealPrimary else Color.Transparent, RoundedCornerShape(8.dp))
                            .clickable { selectedImgIndex = idx }
                            .testTag("add_product_emoji_$idx"),
                        contentAlignment = Alignment.Center
                    ) {
                        Text(em, fontSize = 24.sp)
                    }
                }
            }

            OutlinedTextField(
                value = pName,
                onValueChange = { pName = it },
                label = { Text("Product Name") },
                modifier = Modifier.fillMaxWidth().testTag("add_product_name")
            )

            Row(modifier = Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.spacedBy(10.dp)) {
                OutlinedTextField(
                    value = pPrice,
                    onValueChange = { pPrice = it },
                    label = { Text("Price (₹)") },
                    modifier = Modifier.weight(1f).testTag("add_product_price")
                )
                OutlinedTextField(
                    value = pDiscount,
                    onValueChange = { pDiscount = it },
                    label = { Text("Promo Price (₹)") },
                    modifier = Modifier.weight(1f).testTag("add_product_discount")
                )
            }

            OutlinedTextField(
                value = pCategory,
                onValueChange = { pCategory = it },
                label = { Text("Category / Tag") },
                modifier = Modifier.fillMaxWidth().testTag("add_product_category")
            )

            OutlinedTextField(
                value = pStock,
                onValueChange = { pStock = it },
                label = { Text("Stock Quantity (Optional)") },
                modifier = Modifier.fillMaxWidth().testTag("add_product_stock")
            )

            OutlinedTextField(
                value = pDesc,
                onValueChange = { pDesc = it },
                label = { Text("Product Description") },
                modifier = Modifier.fillMaxWidth().height(100.dp).testTag("add_product_desc")
            )

            Spacer(modifier = Modifier.height(8.dp))

            Button(
                onClick = {
                    if (pName.isBlank() || pPrice.isBlank()) {
                        Toast.makeText(context, "Please enter name and price", Toast.LENGTH_SHORT).show()
                    } else {
                        val priceVal = pPrice.toDoubleOrNull() ?: 0.0
                        val discVal = pDiscount.toDoubleOrNull()
                        val stockVal = pStock.toIntOrNull()
                        val uniqueId = "p_b_${System.currentTimeMillis()}"

                        ConnectChatManager.sellerProducts.add(
                            CatalogProduct(
                                id = uniqueId,
                                name = pName,
                                price = priceVal,
                                discountedPrice = discVal,
                                category = pCategory,
                                description = pDesc,
                                imageEmoji = imgOptions[selectedImgIndex],
                                stockQty = stockVal,
                                availableForOrder = true
                            )
                        )
                        Toast.makeText(context, "Product successfully saved!", Toast.LENGTH_SHORT).show()
                        onNavigate("MY_CATALOG")
                    }
                },
                colors = ButtonDefaults.buttonColors(containerColor = tealPrimary),
                modifier = Modifier.fillMaxWidth().height(50.dp).testTag("add_product_submit"),
                shape = RoundedCornerShape(10.dp)
            ) {
                Text("Save Product Details", color = Color.White, fontWeight = FontWeight.Bold, fontSize = 16.sp)
            }
        }
    }
}

@Composable
fun EditProductScreen(
    productId: String,
    onNavigate: (String) -> Unit
) {
    val context = LocalContext.current
    val tealPrimary = Color(0xFF1FAE7A)
    val slateContent = Color(0xFF1E293B)
    val graySub = Color(0xFF64748B)

    // Retrieve active product to prefill forms
    val product = ConnectChatManager.sellerProducts.find { it.id == productId }
    if (product == null) {
        onNavigate("MY_CATALOG")
        return
    }

    var pName by remember { mutableStateOf(product.name) }
    var pPrice by remember { mutableStateOf(product.price.toString()) }
    var pDiscount by remember { mutableStateOf(product.discountedPrice?.toString() ?: "") }
    var pCategory by remember { mutableStateOf(product.category) }
    var pDesc by remember { mutableStateOf(product.description) }
    var pStock by remember { mutableStateOf(product.stockQty?.toString() ?: "") }
    
    val imgOptions = listOf("🧁", "🍕", "☕", "🍞", "🍦", "🥗", "🎂", "🍔", "🥤")
    var selectedImgIndex by remember { mutableStateOf(imgOptions.indexOf(product.imageEmoji).coerceAtLeast(0)) }

    Column(
        modifier = Modifier
            .fillMaxSize()
            .background(Color.White)
            .verticalScroll(rememberScrollState())
    ) {
        Row(
            modifier = Modifier
                .fillMaxWidth()
                .background(tealPrimary)
                .padding(horizontal = 8.dp, vertical = 12.dp),
            verticalAlignment = Alignment.CenterVertically
        ) {
            IconButton(onClick = { onNavigate("MY_CATALOG") }) {
                Icon(Icons.Default.ArrowBack, "Back", tint = Color.White)
            }
            Spacer(modifier = Modifier.width(8.dp))
            Text("Edit Product Details", color = Color.White, fontSize = 18.sp, fontWeight = FontWeight.Bold)
        }

        Column(modifier = Modifier.padding(16.dp), verticalArrangement = Arrangement.spacedBy(14.dp)) {
            Text("Pick Product Icon Picture 🌟", fontWeight = FontWeight.Medium, fontSize = 13.sp, color = slateContent)
            Row(
                modifier = Modifier.fillMaxWidth().horizontalScroll(rememberScrollState()),
                horizontalArrangement = Arrangement.spacedBy(8.dp)
            ) {
                imgOptions.forEachIndexed { idx, em ->
                    val isSel = selectedImgIndex == idx
                    Box(
                        modifier = Modifier
                            .size(45.dp)
                            .background(if (isSel) tealPrimary.copy(alpha = 0.15f) else Color(0xFFF1F5F9), RoundedCornerShape(8.dp))
                            .border(1.dp, if (isSel) tealPrimary else Color.Transparent, RoundedCornerShape(8.dp))
                            .clickable { selectedImgIndex = idx }
                            .testTag("edit_product_emoji_$idx"),
                        contentAlignment = Alignment.Center
                    ) {
                        Text(em, fontSize = 24.sp)
                    }
                }
            }

            OutlinedTextField(
                value = pName,
                onValueChange = { pName = it },
                label = { Text("Product Name") },
                modifier = Modifier.fillMaxWidth().testTag("edit_product_name")
            )

            Row(modifier = Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.spacedBy(10.dp)) {
                OutlinedTextField(
                    value = pPrice,
                    onValueChange = { pPrice = it },
                    label = { Text("Price (₹)") },
                    modifier = Modifier.weight(1f).testTag("edit_product_price")
                )
                OutlinedTextField(
                    value = pDiscount,
                    onValueChange = { pDiscount = it },
                    label = { Text("Promo Price (₹)") },
                    modifier = Modifier.weight(1f).testTag("edit_product_discount")
                )
            }

            OutlinedTextField(
                value = pCategory,
                onValueChange = { pCategory = it },
                label = { Text("Category / Tag") },
                modifier = Modifier.fillMaxWidth().testTag("edit_product_category")
            )

            OutlinedTextField(
                value = pStock,
                onValueChange = { pStock = it },
                label = { Text("Stock Quantity (Optional)") },
                modifier = Modifier.fillMaxWidth().testTag("edit_product_stock")
            )

            OutlinedTextField(
                value = pDesc,
                onValueChange = { pDesc = it },
                label = { Text("Product Description") },
                modifier = Modifier.fillMaxWidth().height(100.dp).testTag("edit_product_desc")
            )

            Spacer(modifier = Modifier.height(8.dp))

            Button(
                onClick = {
                    if (pName.isBlank() || pPrice.isBlank()) {
                        Toast.makeText(context, "Please enter name and price", Toast.LENGTH_SHORT).show()
                    } else {
                        val priceVal = pPrice.toDoubleOrNull() ?: 0.0
                        val discVal = pDiscount.toDoubleOrNull()
                        val stockVal = pStock.toIntOrNull()

                        val index = ConnectChatManager.sellerProducts.indexOfFirst { it.id == productId }
                        if (index != -1) {
                            ConnectChatManager.sellerProducts[index] = CatalogProduct(
                                id = productId,
                                name = pName,
                                price = priceVal,
                                discountedPrice = discVal,
                                category = pCategory,
                                description = pDesc,
                                imageEmoji = imgOptions[selectedImgIndex],
                                stockQty = stockVal,
                                availableForOrder = true,
                                isHidden = product.isHidden
                            )
                        }
                        Toast.makeText(context, "Product successfully saved!", Toast.LENGTH_SHORT).show()
                        onNavigate("MY_CATALOG")
                    }
                },
                colors = ButtonDefaults.buttonColors(containerColor = tealPrimary),
                modifier = Modifier.fillMaxWidth().height(50.dp).testTag("edit_product_submit"),
                shape = RoundedCornerShape(10.dp)
            ) {
                Text("Save Changes", color = Color.White, fontWeight = FontWeight.Bold, fontSize = 16.sp)
            }
        }
    }
}

@Composable
fun BusinessStorefrontScreen(
    businessId: String,
    onNavigate: (String) -> Unit,
    onSelectDetailProductId: (String) -> Unit
) {
    val context = LocalContext.current
    val tealPrimary = Color(0xFF1FAE7A)
    val slateContent = Color(0xFF1E293B)
    val graySub = Color(0xFF64748B)

    // Since we only have 1 global active business in preferences, let's load it
    val sharedPrefs = remember(context) { context.getSharedPreferences("crowmix_prefs", android.content.Context.MODE_PRIVATE) }
    val businessName = sharedPrefs.getString("connect_business_name", "Noida Fresh Hub") ?: "Noida Fresh Hub"
    val businessLogo = sharedPrefs.getString("connect_business_logo", "🍕") ?: "🍕"
    val businessCategory = sharedPrefs.getString("connect_business_category", "Restaurant") ?: "Restaurant"
    val businessCity = sharedPrefs.getString("connect_business_city", "Noida") ?: "Noida"
    val businessLocality = sharedPrefs.getString("connect_business_locality", "Sector 62") ?: "Sector 62"
    val businessAddress = sharedPrefs.getString("connect_business_address", "Building B, Ground Floor, Sector 62, Noida") ?: "Building B, Ground Floor, Sector 62, Noida"
    val businessContact = sharedPrefs.getString("connect_business_contact", "+91 98765 43210") ?: "+91 98765 43210"

    var storefrontTab by remember { mutableStateOf("Catalog") } // "Catalog" | "About" | "Reviews"
    
    // Review dynamic rating
    val reviews = ConnectChatManager.businessReviews
    val avgScore = if (reviews.isEmpty()) 5.0 else reviews.map { it.rating }.average()

    Column(
        modifier = Modifier
            .fillMaxSize()
            .background(Color(0xFFF8FAFC))
    ) {
        // Linear gradient background representing the Cover Banner 🎨
        Box(
            modifier = Modifier
                .fillMaxWidth()
                .height(130.dp)
                .background(Brush.horizontalGradient(listOf(tealPrimary, Color(0xFF189366)))),
            contentAlignment = Alignment.TopStart
        ) {
            IconButton(onClick = { onNavigate("DASHBOARD") }, modifier = Modifier.padding(8.dp)) {
                Icon(Icons.Default.ArrowBack, "Back", tint = Color.White)
            }
        }

        // Profile details overlap block
        Column(
            modifier = Modifier
                .fillMaxWidth()
                .padding(horizontal = 16.dp),
            horizontalAlignment = Alignment.CenterHorizontally
        ) {
            Box(
                modifier = Modifier
                    .offset(y = (-45).dp)
                    .size(90.dp)
                    .background(Color.White, CircleShape)
                    .border(3.dp, Color.White, CircleShape)
                    .padding(2.dp)
                    .background(tealPrimary.copy(alpha = 0.1f), CircleShape),
                contentAlignment = Alignment.Center
            ) {
                Text(businessLogo, fontSize = 44.sp)
            }

            Column(
                modifier = Modifier
                    .offset(y = (-35).dp)
                    .fillMaxWidth(),
                horizontalAlignment = Alignment.CenterHorizontally
            ) {
                Text(businessName, fontWeight = FontWeight.Bold, fontSize = 21.sp, color = slateContent)
                Text("$businessCategory • Noida Local Partner 🏢", fontSize = 12.sp, color = graySub, fontWeight = FontWeight.Medium)
                Row(verticalAlignment = Alignment.CenterVertically, modifier = Modifier.padding(top = 4.dp)) {
                    Text("📍 $businessLocality, $businessCity", fontSize = 11.sp, color = graySub)
                    Text(" • ", color = graySub)
                    Text("⭐ ${"%.1f".format(avgScore)} (${reviews.size} reviews)", fontSize = 11.sp, fontWeight = FontWeight.Bold, color = Color(0xFFF59E0B))
                }
                
                Spacer(modifier = Modifier.height(16.dp))
                Row(horizontalArrangement = Arrangement.spacedBy(10.dp)) {
                    Button(
                        onClick = {
                            // Automatically start business chat conversation 💬
                            val nid = "chat_b_store"
                            val exist = ConnectChatManager.chats.firstOrNull { it.id == nid }
                            if (exist == null) {
                                ConnectChatManager.chats.add(0, ConnectChat(nid, businessName, businessLogo, "Interested in catalog", "Just now", isGroup = false, contactPhone = businessContact, locality = businessLocality))
                                ConnectChatManager.messages[nid] = mutableStateListOf(ConnectMessage("msg_b_1", nid, "me", "You", "🤓", "Hi $businessName! I saw your storefront and want to inquire.", "Just now"))
                            }
                            ConnectChatManager.selectedConversationId.value = nid
                            onNavigate("CHAT_CONVERSATION")
                        },
                        colors = ButtonDefaults.buttonColors(containerColor = tealPrimary),
                        shape = RoundedCornerShape(20.dp),
                        modifier = Modifier.testTag("storefront_chat_btn")
                    ) {
                        Text("💬 Message Seller", color = Color.White)
                    }
                    OutlinedButton(
                        onClick = {
                            val callUri = android.net.Uri.parse("tel:$businessContact")
                            val callIntent = Intent(Intent.ACTION_DIAL, callUri)
                            context.startActivity(callIntent)
                        },
                        shape = RoundedCornerShape(20.dp),
                        modifier = Modifier.testTag("storefront_call_btn")
                    ) {
                        Text("📞 Call Store", color = slateContent)
                    }
                }
            }
        }

        // Storefront Tab Row selection
        TabRow(
            selectedTabIndex = when (storefrontTab) { "Catalog" -> 0; "About" -> 1; else -> 2 },
            containerColor = Color.White,
            contentColor = tealPrimary,
            modifier = Modifier.offset(y = (-20).dp)
        ) {
            Tab(selected = storefrontTab == "Catalog", onClick = { storefrontTab = "Catalog" }) {
                Text("Catalog", modifier = Modifier.padding(10.dp), fontWeight = FontWeight.Bold, fontSize = 13.sp)
            }
            Tab(selected = storefrontTab == "About", onClick = { storefrontTab = "About" }) {
                Text("About Store", modifier = Modifier.padding(10.dp), fontWeight = FontWeight.Bold, fontSize = 13.sp)
            }
            Tab(selected = storefrontTab == "Reviews", onClick = { storefrontTab = "Reviews" }) {
                Text("Reviews (${reviews.size})", modifier = Modifier.padding(10.dp), fontWeight = FontWeight.Bold, fontSize = 13.sp)
            }
        }

        Column(
            modifier = Modifier
                .offset(y = (-20).dp)
                .weight(1f)
                .fillMaxWidth()
                .padding(horizontal = 14.dp, vertical = 6.dp)
        ) {
            when (storefrontTab) {
                "Catalog" -> {
                    // Grid of Products Catalog visible to client
                    val visibleProducts = ConnectChatManager.sellerProducts.filter { !it.isHidden }
                    if (visibleProducts.isEmpty()) {
                        Column(
                            modifier = Modifier.fillMaxSize(),
                            verticalArrangement = Arrangement.Center,
                            horizontalAlignment = Alignment.CenterHorizontally
                        ) {
                            Text("No products currently in seller catalog.", color = graySub, fontSize = 13.sp)
                        }
                    } else {
                        LazyVerticalGrid(
                            columns = GridCells.Fixed(2),
                            horizontalArrangement = Arrangement.spacedBy(10.dp),
                            verticalArrangement = Arrangement.spacedBy(10.dp),
                            modifier = Modifier.fillMaxSize()
                        ) {
                            items(visibleProducts) { prod ->
                                Card(
                                    modifier = Modifier
                                        .fillMaxWidth()
                                        .clickable { onSelectDetailProductId(prod.id); onNavigate("PRODUCT_DETAIL") }
                                        .testTag("store_product_${prod.id}"),
                                    colors = CardDefaults.cardColors(containerColor = Color.White),
                                    border = BorderStroke(1.dp, Color(0xFFE2E8F0))
                                ) {
                                    Column(modifier = Modifier.padding(12.dp)) {
                                        Box(
                                            modifier = Modifier
                                                .fillMaxWidth()
                                                .height(85.dp)
                                                .background(tealPrimary.copy(alpha = 0.05f), RoundedCornerShape(4.dp)),
                                            contentAlignment = Alignment.Center
                                        ) {
                                            Text(prod.imageEmoji, fontSize = 40.sp)
                                        }
                                        Spacer(modifier = Modifier.height(8.dp))
                                        Text(
                                            prod.name,
                                            fontWeight = FontWeight.Bold,
                                            fontSize = 12.sp,
                                            maxLines = 1,
                                            overflow = TextOverflow.Ellipsis,
                                            color = slateContent
                                        )
                                        Row(
                                            verticalAlignment = Alignment.CenterVertically,
                                            modifier = Modifier.padding(top = 2.dp)
                                        ) {
                                            Text("₹${prod.price.toInt()}", fontWeight = FontWeight.ExtraBold, color = Color(0xFF111827), fontSize = 16.sp)
                                            if (prod.discountedPrice != null) {
                                                Spacer(Modifier.width(4.dp))
                                                Text("₹${prod.discountedPrice.toInt()}", textDecoration = TextDecoration.LineThrough, fontSize = 9.sp, color = graySub)
                                            }
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
                "About" -> {
                    Column(
                        modifier = Modifier
                            .fillMaxSize()
                            .verticalScroll(rememberScrollState())
                            .background(Color.White, RoundedCornerShape(12.dp))
                            .padding(16.dp),
                        verticalArrangement = Arrangement.spacedBy(12.dp)
                    ) {
                        Text("Business Information", fontWeight = FontWeight.Bold, fontSize = 14.sp, color = slateContent)
                        Column(verticalArrangement = Arrangement.spacedBy(6.dp)) {
                            Text("Address 🏠", fontWeight = FontWeight.Bold, fontSize = 11.sp, color = graySub)
                            Text(businessAddress, fontSize = 13.sp, color = slateContent)
                        }
                        Column(verticalArrangement = Arrangement.spacedBy(6.dp)) {
                            Text("Contact Number 📞", fontWeight = FontWeight.Bold, fontSize = 11.sp, color = graySub)
                            Text(businessContact, fontSize = 13.sp, color = slateContent)
                        }
                        Column(verticalArrangement = Arrangement.spacedBy(6.dp)) {
                            Text("Opening Timings 🕒", fontWeight = FontWeight.Bold, fontSize = 11.sp, color = graySub)
                            Text("Everyday 8:00 AM - 10:00 PM • Fast delivery under 10m", fontSize = 13.sp, color = slateContent)
                        }
                    }
                }
                "Reviews" -> {
                    Column(modifier = Modifier.fillMaxSize()) {
                        // Quick Add Review form (If the user wants to add review)
                        var reviewText by remember { mutableStateOf("") }
                        var newRating by remember { mutableStateOf(5) }
                        Card(colors = CardDefaults.cardColors(containerColor = Color.White), modifier = Modifier.fillMaxWidth().padding(bottom = 10.dp)) {
                            Column(Modifier.padding(10.dp)) {
                                Text("Write a Store Review ✏️", fontWeight = FontWeight.Bold, fontSize = 12.sp, color = slateContent)
                                Row(Modifier.padding(vertical = 4.dp), horizontalArrangement = Arrangement.spacedBy(4.dp)) {
                                    (1..5).forEach { r ->
                                        Text(
                                            if (r <= newRating) "⭐" else "☆",
                                            modifier = Modifier.clickable { newRating = r },
                                            fontSize = 18.sp
                                        )
                                    }
                                }
                                Row(modifier = Modifier.fillMaxWidth(), verticalAlignment = Alignment.CenterVertically) {
                                    OutlinedTextField(
                                        value = reviewText,
                                        onValueChange = { reviewText = it },
                                        placeholder = { Text("How was your experience?", fontSize = 11.sp) },
                                        modifier = Modifier.weight(1f).testTag("dialog_new_review_input")
                                    )
                                    Spacer(modifier = Modifier.width(6.dp))
                                    IconButton(
                                        onClick = {
                                            if (reviewText.isNotBlank()) {
                                                ConnectChatManager.businessReviews.add(0, BusinessReview("Me (Current Customer)", newRating, reviewText, "Just now"))
                                                reviewText = ""
                                                Toast.makeText(context, "Review Published!", Toast.LENGTH_SHORT).show()
                                            }
                                        },
                                        modifier = Modifier.background(tealPrimary, RoundedCornerShape(8.dp)).testTag("submit_review_btn")
                                    ) {
                                        Icon(Icons.Default.Send, "Send", tint = Color.White)
                                    }
                                }
                            }
                        }

                        LazyColumn(modifier = Modifier.fillMaxSize()) {
                            items(reviews) { r ->
                                Card(
                                    modifier = Modifier.fillMaxWidth().padding(vertical = 4.dp),
                                    colors = CardDefaults.cardColors(containerColor = Color.White),
                                    border = BorderStroke(1.dp, Color(0xFFF1F5F9))
                                ) {
                                    Column(Modifier.padding(12.dp)) {
                                        Row(Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.SpaceBetween, verticalAlignment = Alignment.CenterVertically) {
                                            Text(r.authorName, fontWeight = FontWeight.Bold, fontSize = 12.sp, color = slateContent)
                                            Text(r.date, fontSize = 10.sp, color = graySub)
                                        }
                                        Row(Modifier.padding(vertical = 2.dp)) {
                                            repeat(r.rating) { Text("⭐", fontSize = 10.sp) }
                                        }
                                        Text(r.text, fontSize = 12.sp, color = slateContent)
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }
    }
}

@Composable
fun ProductDetailScreen(
    productId: String,
    viewModel: AppViewModel,
    onNavigate: (String) -> Unit
) {
    val context = LocalContext.current
    val tealPrimary = Color(0xFF1FAE7A)
    val slateContent = Color(0xFF1E293B)
    val graySub = Color(0xFF64748B)

    // Load seller item
    val product = ConnectChatManager.sellerProducts.find { it.id == productId }
    if (product == null) {
        onNavigate("DASHBOARD")
        return
    }

    Column(
        modifier = Modifier
            .fillMaxSize()
            .background(Color.White)
    ) {
        Row(
            modifier = Modifier
                .fillMaxWidth()
                .background(tealPrimary)
                .padding(horizontal = 8.dp, vertical = 12.dp),
            verticalAlignment = Alignment.CenterVertically
        ) {
            IconButton(onClick = { onNavigate("BUSINESS_STOREFRONT") }) {
                Icon(Icons.Default.ArrowBack, "Back", tint = Color.White)
            }
            Spacer(modifier = Modifier.width(8.dp))
            Text("Product Detail View", color = Color.White, fontSize = 18.sp, fontWeight = FontWeight.Bold)
        }

        Column(
            modifier = Modifier
                .weight(1f)
                .fillMaxWidth()
                .verticalScroll(rememberScrollState())
                .padding(16.dp),
            verticalArrangement = Arrangement.spacedBy(16.dp)
        ) {
            // Hero banner image representation 🎨
            Box(
                modifier = Modifier
                    .fillMaxWidth()
                    .height(200.dp)
                    .background(Brush.linearGradient(listOf(tealPrimary.copy(alpha = 0.1f), Color(0xFFECFDF5))), RoundedCornerShape(12.dp)),
                contentAlignment = Alignment.Center
            ) {
                Text(product.imageEmoji, fontSize = 80.sp)
            }

            Column(verticalArrangement = Arrangement.spacedBy(4.dp)) {
                Surface(
                    color = tealPrimary.copy(alpha = 0.12f),
                    shape = RoundedCornerShape(4.dp)
                ) {
                    Text(
                        product.category.uppercase(),
                        color = tealPrimary,
                        fontSize = 10.sp,
                        fontWeight = FontWeight.Bold,
                        modifier = Modifier.padding(horizontal = 8.dp, vertical = 4.dp)
                    )
                }
                Text(product.name, fontWeight = FontWeight.Bold, fontSize = 22.sp, color = slateContent)
                
                Row(verticalAlignment = Alignment.CenterVertically, modifier = Modifier.padding(vertical = 4.dp)) {
                    Text("₹${product.price.toInt()}", fontWeight = FontWeight.ExtraBold, color = Color(0xFF111827), fontSize = 16.sp)
                    if (product.discountedPrice != null) {
                        Spacer(modifier = Modifier.width(10.dp))
                        Text(
                            "₹${product.discountedPrice.toInt()}",
                            fontSize = 16.sp,
                            color = graySub,
                            textDecoration = TextDecoration.LineThrough
                        )
                    }
                }
            }

            Column(verticalArrangement = Arrangement.spacedBy(6.dp)) {
                Text("Stock Info", fontWeight = FontWeight.Bold, fontSize = 13.sp, color = slateContent)
                val isLow = (product.stockQty ?: 0) <= 5
                Text(
                    if (product.stockQty != null) "Only ${product.stockQty} left in stock!" else "In stock",
                    color = if (isLow) Color.Red else tealPrimary,
                    fontSize = 12.sp,
                    fontWeight = FontWeight.Medium
                )
            }

            Column(verticalArrangement = Arrangement.spacedBy(6.dp)) {
                Text("Product Specifications", fontWeight = FontWeight.Bold, fontSize = 13.sp, color = slateContent)
                Text(product.description, fontSize = 13.sp, color = slateContent, lineHeight = 18.sp)
            }

            Spacer(modifier = Modifier.weight(1f))

            Row(
                modifier = Modifier.fillMaxWidth(),
                horizontalArrangement = Arrangement.spacedBy(10.dp)
            ) {
                // Outlined Button: Inquire 💬
                OutlinedButton(
                    onClick = {
                        // Create inquiry chat with the seller
                        val nid = "chat_b_store"
                        val bContact = "+91 98765 43210"
                        val bLocality = "Sector 62"
                        val exist = ConnectChatManager.chats.firstOrNull { it.id == nid }
                        if (exist == null) {
                            ConnectChatManager.chats.add(0, ConnectChat(nid, "Noida Fresh Hub", "🍕", "Interested in ${product.name}", "Just now", isGroup = false, contactPhone = bContact, locality = bLocality))
                        }
                        // Send inquiry message
                        val msgList = ConnectChatManager.messages[nid] ?: mutableStateListOf()
                        msgList.add(ConnectMessage("msg_inq_${System.currentTimeMillis()}", nid, "me", "You", "🤓", "Hi! Is '${product.name}' available for order right now?", "Just now"))
                        ConnectChatManager.messages[nid] = msgList
                        
                        ConnectChatManager.selectedConversationId.value = nid
                        onNavigate("CHAT_CONVERSATION")
                    },
                    modifier = Modifier.weight(1f).height(50.dp).testTag("product_detail_message_seller_btn"),
                    shape = RoundedCornerShape(10.dp)
                ) {
                    Text("Message Seller", color = slateContent)
                }

                // Primary Button: Add to Cart 🛒 (Connects directly with the central shopping cart)
                Button(
                    onClick = {
                        // 1. Ensure the product is registered in AppViewModel's product inventory so that totals can calculate!
                        val alreadyRegistered = viewModel.products.any { it.id == product.id }
                        if (!alreadyRegistered) {
                            viewModel.products.add(
                                com.example.ProductItem(
                                    id = product.id,
                                    name = product.name,
                                    category = "veg", // map to general veggies so it checks out beautifully
                                    price = product.price,
                                    originalPrice = product.discountedPrice ?: product.price,
                                    qtyUnit = "1 unit",
                                    labelChar = product.imageEmoji,
                                    tintColorHex = 0xFFF8FAFC
                                )
                            )
                        }
                        // 2. Safely call central controller helper
                        viewModel.addToCart(product.id)
                        Toast.makeText(context, "${product.name} added to cart!", Toast.LENGTH_LONG).show()
                    },
                    colors = ButtonDefaults.buttonColors(containerColor = tealPrimary),
                    modifier = Modifier.weight(1.2f).height(50.dp).testTag("product_detail_add_to_cart_btn"),
                    shape = RoundedCornerShape(10.dp)
                ) {
                    Text("Add to Cart 🛒", color = Color.White, fontWeight = FontWeight.Bold)
                }
            }
        }
    }
}

@Composable
fun MyAdsScreen(
    onNavigate: (String) -> Unit
) {
    val context = LocalContext.current
    val tealPrimary = Color(0xFF1FAE7A)
    val slateContent = Color(0xFF1E293B)
    val graySub = Color(0xFF64748B)

    val ads = ConnectChatManager.businessAds

    Scaffold(
        topBar = {
            Row(
                modifier = Modifier
                    .fillMaxWidth()
                    .background(tealPrimary)
                    .padding(horizontal = 8.dp, vertical = 12.dp),
                verticalAlignment = Alignment.CenterVertically
            ) {
                IconButton(onClick = { onNavigate("DASHBOARD") }) {
                    Icon(Icons.Default.ArrowBack, "Back", tint = Color.White)
                }
                Spacer(modifier = Modifier.width(8.dp))
                Text("Business Status Ads", color = Color.White, fontSize = 18.sp, fontWeight = FontWeight.Bold)
            }
        },
        floatingActionButton = {
            FloatingActionButton(
                onClick = { onNavigate("CREATE_AD") },
                containerColor = tealPrimary,
                contentColor = Color.White,
                modifier = Modifier.testTag("create_ad_fab")
            ) {
                Icon(Icons.Default.Add, "New Ad")
            }
        },
        content = { paddingValues ->
            Column(
                modifier = Modifier
                    .fillMaxSize()
                    .background(Color(0xFFF8FAFC))
                    .padding(paddingValues)
                    .padding(14.dp)
            ) {
                Text(
                    "My Active Promotional Ads (${ads.size})",
                    fontWeight = FontWeight.Bold,
                    fontSize = 14.sp,
                    color = slateContent,
                    modifier = Modifier.padding(bottom = 12.dp)
                )

                if (ads.isEmpty()) {
                    Column(
                        modifier = Modifier.fillMaxSize(),
                        verticalArrangement = Arrangement.Center,
                        horizontalAlignment = Alignment.CenterHorizontally
                    ) {
                        Text("No active advertising campaigns yet.", color = graySub, fontSize = 13.sp)
                        TextButton(onClick = { onNavigate("CREATE_AD") }) {
                            Text("Click here to setup dynamic status ad 📢", color = tealPrimary)
                        }
                    }
                } else {
                    LazyColumn(
                        modifier = Modifier.fillMaxSize(),
                        verticalArrangement = Arrangement.spacedBy(10.dp)
                    ) {
                        items(ads) { ad ->
                            Card(
                                modifier = Modifier
                                    .fillMaxWidth()
                                    .testTag("ad_manage_card_${ad.id}"),
                                colors = CardDefaults.cardColors(containerColor = Color.White),
                                border = BorderStroke(1.dp, Color(0xFFE2E8F0))
                            ) {
                                Row(modifier = Modifier.padding(12.dp), verticalAlignment = Alignment.CenterVertically) {
                                    Box(
                                        modifier = Modifier
                                            .size(50.dp)
                                            .background(tealPrimary.copy(alpha = 0.05f), CircleShape),
                                        contentAlignment = Alignment.Center
                                    ) {
                                        Text(ad.emojiContent, fontSize = 28.sp)
                                    }
                                    Spacer(modifier = Modifier.width(12.dp))
                                    Column(modifier = Modifier.weight(1f)) {
                                        Text(ad.title, fontWeight = FontWeight.Bold, fontSize = 13.sp, color = slateContent)
                                        Text(ad.statusText, maxLines = 1, overflow = TextOverflow.Ellipsis, fontSize = 11.sp, color = graySub)
                                        Spacer(modifier = Modifier.height(8.dp))
                                        
                                        // Dynamic analytics indicators 📊
                                        Row(horizontalArrangement = Arrangement.spacedBy(10.dp)) {
                                            Text("👁️ ${ad.viewsCount} views", fontSize = 10.sp, color = tealPrimary, fontWeight = FontWeight.Bold)
                                            Text("🎯 ${ad.tapsCount} taps", fontSize = 10.sp, color = Color(0xFF3B82F6), fontWeight = FontWeight.Bold)
                                        }
                                    }
                                    
                                    IconButton(onClick = {
                                        ConnectChatManager.businessAds.remove(ad)
                                        Toast.makeText(context, "Campaign Paused & Deleted!", Toast.LENGTH_SHORT).show()
                                    }) {
                                        Icon(Icons.Default.Delete, "Delete Campaign", tint = Color.Red, modifier = Modifier.size(20.dp))
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }
    )
}

@Composable
fun CreateAdScreen(
    onNavigate: (String) -> Unit
) {
    val context = LocalContext.current
    val tealPrimary = Color(0xFF1FAE7A)
    val slateContent = Color(0xFF1E293B)
    val graySub = Color(0xFF64748B)

    var adTitle by remember { mutableStateOf("") }
    var adText by remember { mutableStateOf("") }
    var durationSelected by remember { mutableStateOf("24h") } // "24h" or "7d"
    var selectedProdId by remember { mutableStateOf<String?>(null) }
    
    // Paid boost toggle parameters 💰
    var applyPaidBoost by remember { mutableStateOf(false) }
    var boostBudgetSlider by remember { mutableStateOf(299f) } // default 299 in rupees

    val products = ConnectChatManager.sellerProducts
    val imgOptions = listOf("🧁", "🍕", "☕", "🍞", "🍦", "🥗", "🎂", "🍔", "🥤")
    var selectedImgIdx by remember { mutableStateOf(0) }

    Column(
        modifier = Modifier
            .fillMaxSize()
            .background(Color.White)
            .verticalScroll(rememberScrollState())
    ) {
        Row(
            modifier = Modifier
                .fillMaxWidth()
                .background(tealPrimary)
                .padding(horizontal = 8.dp, vertical = 12.dp),
            verticalAlignment = Alignment.CenterVertically
        ) {
            IconButton(onClick = { onNavigate("MY_ADS") }) {
                Icon(Icons.Default.ArrowBack, "Back", tint = Color.White)
            }
            Spacer(modifier = Modifier.width(8.dp))
            Text("Launch Business status Ad", color = Color.White, fontSize = 18.sp, fontWeight = FontWeight.Bold)
        }

        Column(modifier = Modifier.padding(16.dp), verticalArrangement = Arrangement.spacedBy(14.dp)) {
            Text("Select Promotion Visual Banner 📌", fontWeight = FontWeight.Bold, fontSize = 13.sp, color = slateContent)
            Row(
                modifier = Modifier.fillMaxWidth().horizontalScroll(rememberScrollState()),
                horizontalArrangement = Arrangement.spacedBy(8.dp)
            ) {
                imgOptions.forEachIndexed { index, opt ->
                    val isS = selectedImgIdx == index
                    Box(
                        modifier = Modifier
                            .size(45.dp)
                            .background(if (isS) tealPrimary.copy(alpha = 0.15f) else Color(0xFFF1F5F9), RoundedCornerShape(8.dp))
                            .border(1.dp, if (isS) tealPrimary else Color.Transparent, RoundedCornerShape(8.dp))
                            .clickable { selectedImgIdx = index }
                            .testTag("create_ad_emoji_$index"),
                        contentAlignment = Alignment.Center
                    ) {
                        Text(opt, fontSize = 24.sp)
                    }
                }
            }

            OutlinedTextField(
                value = adTitle,
                onValueChange = { adTitle = it },
                label = { Text("Ad Campaign Title") },
                modifier = Modifier.fillMaxWidth().testTag("create_ad_title_input")
            )

            OutlinedTextField(
                value = adText,
                onValueChange = { adText = it },
                label = { Text("Ad Description Caption") },
                modifier = Modifier.fillMaxWidth().height(80.dp).testTag("create_ad_description_input")
            )

            // Link with product selector
            Text("Link ad campaign to Product Catalog item (Optional)", fontWeight = FontWeight.Bold, fontSize = 13.sp, color = slateContent)
            if (products.isEmpty()) {
                Text("Register products in catalog to unlock Shop Now link tags.", fontSize = 11.sp, color = graySub)
            } else {
                Row(
                    modifier = Modifier.fillMaxWidth().horizontalScroll(rememberScrollState()),
                    horizontalArrangement = Arrangement.spacedBy(8.dp)
                ) {
                    products.forEach { prod ->
                        val isSelected = selectedProdId == prod.id
                        Card(
                            modifier = Modifier
                                .width(120.dp)
                                .clickable { selectedProdId = if (isSelected) null else prod.id }
                                .testTag("ad_product_link_${prod.id}"),
                            colors = CardDefaults.cardColors(containerColor = if (isSelected) tealPrimary.copy(alpha = 0.1f) else Color.White),
                            border = BorderStroke(1.dp, if (isSelected) tealPrimary else Color(0xFFE2E8F0))
                        ) {
                            Column(modifier = Modifier.padding(12.dp)) {
                                Text(prod.imageEmoji, fontSize = 20.sp)
                                Text(prod.name, fontSize = 11.sp, fontWeight = FontWeight.Bold, maxLines = 1, overflow = TextOverflow.Ellipsis)
                                Text("₹${prod.price.toInt()}", fontSize = 10.sp, color = tealPrimary)
                            }
                        }
                    }
                }
            }

            // Duration selection
            Text("Ad visibility Duration 🕒", fontWeight = FontWeight.Bold, fontSize = 13.sp, color = slateContent)
            Row(horizontalArrangement = Arrangement.spacedBy(12.dp)) {
                listOf("24h" to "24 Hours", "7d" to "7 Days").forEach { (tag, label) ->
                    val isSel = durationSelected == tag
                    Button(
                        onClick = { durationSelected = tag },
                        colors = ButtonDefaults.buttonColors(containerColor = if (isSel) tealPrimary else Color(0xFFE2E8F0), contentColor = if (isSel) Color.White else slateContent),
                        modifier = Modifier.weight(1f).testTag("duration_$tag")
                    ) {
                        Text(label, fontSize = 11.sp)
                    }
                }
            }

            // Paid boost booster campaign mechanism 🚀
            Card(
                colors = CardDefaults.cardColors(containerColor = Color(0xFFECFDF5)),
                border = BorderStroke(1.dp, tealPrimary.copy(alpha = 0.3f)),
                modifier = Modifier.fillMaxWidth()
            ) {
                Column(Modifier.padding(14.dp)) {
                    Row(
                        modifier = Modifier.fillMaxWidth(),
                        horizontalArrangement = Arrangement.SpaceBetween,
                        verticalAlignment = Alignment.CenterVertically
                    ) {
                        Column {
                            Text("🚀 Paid Ad Boost Campaign Check", fontWeight = FontWeight.Bold, fontSize = 12.sp, color = slateContent)
                            Text("Double views by broadcasting to nearby sectors", fontSize = 10.sp, color = graySub)
                        }
                        Switch(
                            checked = applyPaidBoost,
                            onCheckedChange = { applyPaidBoost = it },
                            modifier = Modifier.testTag("paid_boost_toggle")
                        )
                    }
                    if (applyPaidBoost) {
                        Spacer(modifier = Modifier.height(8.dp))
                        Text(
                            "Launch Budget: ₹${boostBudgetSlider.toInt()}",
                            fontWeight = FontWeight.Bold,
                            fontSize = 11.sp,
                            color = slateContent
                        )
                        Slider(
                            value = boostBudgetSlider,
                            onValueChange = { boostBudgetSlider = it },
                            valueRange = 99f..2990f,
                            modifier = Modifier.testTag("boost_budget_slider")
                        )
                        val estimatedViews = (boostBudgetSlider * 4.3).toInt()
                        Text(
                            "📢 Expected local views: ~$estimatedViews people in Noida Connect",
                            fontSize = 10.sp,
                            color = tealPrimary,
                            fontWeight = FontWeight.Bold
                        )
                    }
                }
            }

            Spacer(modifier = Modifier.height(8.dp))

            Button(
                onClick = {
                    if (adTitle.isBlank() || adText.isBlank()) {
                        Toast.makeText(context, "Please enter campaign title and caption!", Toast.LENGTH_SHORT).show()
                    } else {
                        val nid = "ad_cust_${System.currentTimeMillis()}"
                        // 1. Save locally to Noida Business Ads active registry
                        ConnectChatManager.businessAds.add(
                            0,
                            BusinessAd(
                                id = nid,
                                title = adTitle,
                                emojiContent = imgOptions[selectedImgIdx],
                                statusText = adText,
                                linkProductId = selectedProdId,
                                durationType = durationSelected,
                                viewsCount = 0,
                                tapsCount = 0
                            )
                        )
                        // 2. Also register inside the standard story statuses feed so that neighbours see it in Chat status bar!
                        ConnectChatManager.statuses.add(
                            0,
                            ConnectStatus(
                                id = nid,
                                name = "Promoted Ad",
                                avatarEmoji = imgOptions[selectedImgIdx],
                                emojiContent = imgOptions[selectedImgIdx],
                                statusText = adText,
                                timeAgo = "Sponsored",
                                isAd = true,
                                isViewed = false,
                                adCTA = if (selectedProdId != null) "Shop Linked Product 🛒" else "Visit Storefront 🏪"
                            )
                        )

                        Toast.makeText(context, "Promo Campaign launched successfully!", Toast.LENGTH_LONG).show()
                        onNavigate("MY_ADS")
                    }
                },
                colors = ButtonDefaults.buttonColors(containerColor = tealPrimary),
                modifier = Modifier.fillMaxWidth().height(50.dp).testTag("create_ad_submit_button"),
                shape = RoundedCornerShape(10.dp)
            ) {
                Text("Launch status Campaign", color = Color.White, fontWeight = FontWeight.Bold, fontSize = 15.sp)
            }
        }
    }
}

@Composable
fun BusinessInsightsScreen(
    onNavigate: (String) -> Unit
) {
    val context = LocalContext.current
    val tealPrimary = Color(0xFF1FAE7A)
    val slateContent = Color(0xFF1E293B)
    val graySub = Color(0xFF64748B)

    val productsCount = ConnectChatManager.sellerProducts.size
    val adsList = ConnectChatManager.businessAds
    val viewsCountTotal = adsList.sumOf { it.viewsCount }
    val tapsCountTotal = adsList.sumOf { it.tapsCount }

    val ctrRate = if (viewsCountTotal == 0) 0.0 else (tapsCountTotal.toDouble() / viewsCountTotal) * 100

    // Custom daily sales volumes 📊
    val salesArray = listOf(4, 7, 5, 9, 12, 8, 15) // units ordered per day (past 7 days)
    val labelDays = listOf("Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun")

    Column(
        modifier = Modifier
            .fillMaxSize()
            .background(Color(0xFFF8FAFC))
            .verticalScroll(rememberScrollState())
    ) {
        Row(
            modifier = Modifier
                .fillMaxWidth()
                .background(tealPrimary)
                .padding(horizontal = 8.dp, vertical = 12.dp),
            verticalAlignment = Alignment.CenterVertically
        ) {
            IconButton(onClick = { onNavigate("DASHBOARD") }) {
                Icon(Icons.Default.ArrowBack, "Back", tint = Color.White)
            }
            Spacer(modifier = Modifier.width(8.dp))
            Text("Business Insights & Charts", color = Color.White, fontSize = 18.sp, fontWeight = FontWeight.Bold)
        }

        Column(modifier = Modifier.padding(16.dp), verticalArrangement = Arrangement.spacedBy(16.dp)) {
            Text("Performance Metrics Overview", fontWeight = FontWeight.Bold, fontSize = 14.sp, color = slateContent)
            
            // Stats Row cards
            Row(modifier = Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.spacedBy(10.dp)) {
                Card(modifier = Modifier.weight(1f), colors = CardDefaults.cardColors(containerColor = Color.White)) {
                    Column(Modifier.padding(12.dp)) {
                        Text("Views 👁️", fontSize = 11.sp, color = graySub, fontWeight = FontWeight.Bold)
                        Text("$viewsCountTotal", fontSize = 24.sp, fontWeight = FontWeight.Bold, color = slateContent)
                        Text("Total ad exposures", fontSize = 9.sp, color = graySub)
                    }
                }
                Card(modifier = Modifier.weight(1f), colors = CardDefaults.cardColors(containerColor = Color.White)) {
                    Column(Modifier.padding(12.dp)) {
                        Text("Clicks 🎯", fontSize = 11.sp, color = graySub, fontWeight = FontWeight.Bold)
                        Text("$tapsCountTotal", fontSize = 24.sp, fontWeight = FontWeight.Bold, color = Color(0xFF3B82F6))
                        Text("Link shop visits", fontSize = 9.sp, color = graySub)
                    }
                }
            }

            Row(modifier = Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.spacedBy(10.dp)) {
                Card(modifier = Modifier.weight(1f), colors = CardDefaults.cardColors(containerColor = Color.White)) {
                    Column(Modifier.padding(12.dp)) {
                        Text("Engagement", fontSize = 11.sp, color = graySub, fontWeight = FontWeight.Bold)
                        Text("${"%.1f".format(ctrRate)}%", fontSize = 24.sp, fontWeight = FontWeight.Bold, color = Color(0xFF10B981))
                        Text("Average Click-Thru", fontSize = 9.sp, color = graySub)
                    }
                }
                Card(modifier = Modifier.weight(1f), colors = CardDefaults.cardColors(containerColor = Color.White)) {
                    Column(Modifier.padding(12.dp)) {
                        Text("Catalog Size", fontSize = 11.sp, color = graySub, fontWeight = FontWeight.Bold)
                        Text("$productsCount", fontSize = 24.sp, fontWeight = FontWeight.Bold, color = Color(0xFF8B5CF6))
                        Text("Products registered", fontSize = 9.sp, color = graySub)
                    }
                }
            }

            // Beautiful Canvas based Custom Line Chart 📈
            Card(
                colors = CardDefaults.cardColors(containerColor = Color.White),
                border = BorderStroke(1.dp, Color(0xFFE2E8F0)),
                modifier = Modifier.fillMaxWidth()
            ) {
                Column(Modifier.padding(16.dp)) {
                    Text("Daily Society Orders Summary", fontWeight = FontWeight.Bold, fontSize = 13.sp, color = slateContent)
                    Text("Total successful checkout items, past 7 days", fontSize = 10.sp, color = graySub)
                    
                    Spacer(modifier = Modifier.height(24.dp))
                    
                    Canvas(
                        modifier = Modifier
                            .fillMaxWidth()
                            .height(180.dp)
                            .testTag("analytics_line_chart")
                    ) {
                        val canvasWidth = size.width
                        val canvasHeight = size.height
                        
                        val maxSales = salesArray.maxOrNull() ?: 1
                        val pointCount = salesArray.size
                        
                        val paddingLeft = 32.dp.toPx()
                        val paddingBottom = 24.dp.toPx()
                        val paddingTop = 16.dp.toPx()
                        val paddingRight = 16.dp.toPx()
                        
                        val workableWidth = canvasWidth - paddingLeft - paddingRight
                        val workableHeight = canvasHeight - paddingTop - paddingBottom
                        
                        // Draw horizontal background gridlines 📊
                        val gridlines = 4
                        for (i in 0..gridlines) {
                            val ratio = i.toFloat() / gridlines
                            val y = workableHeight - ratio * workableHeight + paddingTop
                            drawLine(
                                color = Color(0xFFF1F5F9),
                                start = androidx.compose.ui.geometry.Offset(paddingLeft, y),
                                end = androidx.compose.ui.geometry.Offset(canvasWidth - paddingRight, y),
                                strokeWidth = 1.dp.toPx()
                            )
                        }

                        // Project and render the data lines 📈
                        val points = mutableListOf<androidx.compose.ui.geometry.Offset>()
                        for (idx in 0 until pointCount) {
                            val xRatio = idx.toFloat() / (pointCount - 1)
                            val x = paddingLeft + xRatio * workableWidth
                            
                            val yRatio = salesArray[idx].toFloat() / maxSales
                            val y = workableHeight - yRatio * workableHeight + paddingTop
                            points.add(androidx.compose.ui.geometry.Offset(x, y))
                        }

                        // Draw background gradient under line path
                        val fillPath = androidx.compose.ui.graphics.Path().apply {
                            moveTo(points[0].x, canvasHeight - paddingBottom)
                            points.forEach { pt -> lineTo(pt.x, pt.y) }
                            lineTo(points.last().x, canvasHeight - paddingBottom)
                            close()
                        }
                        drawPath(
                            path = fillPath,
                            brush = Brush.verticalGradient(
                                colors = listOf(tealPrimary.copy(alpha = 0.3f), Color.Transparent),
                                startY = paddingTop,
                                endY = canvasHeight - paddingBottom
                            )
                        )

                        // Connect line segment points
                        for (i in 0 until points.size - 1) {
                            drawLine(
                                color = tealPrimary,
                                start = points[i],
                                end = points[i+1],
                                strokeWidth = 3.dp.toPx()
                            )
                        }

                        // Render dots and markers on each point
                        points.forEach { pt ->
                            drawCircle(
                                color = tealPrimary,
                                radius = 4.dp.toPx(),
                                center = pt
                            )
                            drawCircle(
                                color = Color.White,
                                radius = 2.dp.toPx(),
                                center = pt
                            )
                        }
                    }
                    
                    // Render days of week indicators underneath the graph ☀️
                    Row(
                        modifier = Modifier
                            .fillMaxWidth()
                            .padding(start = 32.dp),
                        horizontalArrangement = Arrangement.SpaceBetween
                    ) {
                        labelDays.forEach { dayName ->
                            Text(dayName, fontSize = 10.sp, color = graySub, fontWeight = FontWeight.Bold)
                        }
                    }
                }
            }
        }
    }
}







